import ArrowLeftIcon from '../components/icons/ArrowLeftIcon';
import ChevronLeftIcon from '../components/icons/ChevronLeftIcon';
import ChevronRightIcon from '../components/icons/ChevronRightIcon';
import SparklesIcon from '../components/icons/SparklesIcon';
import PlusCircleIcon from '../components/icons/PlusCircleIcon';
import XMarkIcon from '../components/icons/XMarkIcon';
import CalendarRibbonAnimation from '../components/CalendarRibbonAnimation';

const MONTHS = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
const DAYS = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];

interface PersonalCalendarViewProps {
    userProfile: UserProfile;
    onClose: () => void;
}

const PersonalCalendarView: React.FC<PersonalCalendarViewProps> = ({ userProfile, onClose }) => {
    const [isAnimating, setIsAnimating] = useState(true);
    const [currentDate, setCurrentDate] = useState(new Date());
    const [notes, setNotes] = useLocalStorage<CalendarNote[]>(`sifra_calendar_notes_${userProfile.userId}`, []);
    const [selectedDate, setSelectedDate] = useState<string | null>(null);
    const [isNoteModalOpen, setIsNoteModalOpen] = useState(false);

    // Note Editor State
    const [editTitle, setEditTitle] = useState('');
    const [editContent, setEditContent] = useState('');
    const [editIsSpecial, setEditIsSpecial] = useState(false);

    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();

    const firstDayOfMonth = new Date(year, month, 1).getDay();
    const daysInMonth = new Date(year, month + 1, 0).getDate();

    const calendarDays = useMemo(() => {
        const d = [];
        for (let i = 0; i < firstDayOfMonth; i++) d.push(null);
        for (let i = 1; i <= daysInMonth; i++) d.push(i);
        return d;
    }, [year, month, firstDayOfMonth, daysInMonth]);

    const upcomingTasks = useMemo(() => {
        const today = new Date();
        today.setHours(0, 0, 0, 0);
        const threeDaysLater = new Date(today);
        threeDaysLater.setDate(today.getDate() + 3);

        return notes.filter(note => {
            const noteDate = new Date(note.date);
            return noteDate >= today && noteDate <= threeDaysLater;
        }).sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());
    }, [notes]);

    const handlePrevMonth = () => setCurrentDate(new Date(year, month - 1));
    const handleNextMonth = () => setCurrentDate(new Date(year, month + 1));

    const openNoteModal = (day: number) => {
        const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
        setSelectedDate(dateStr);
        const existingNote = notes.find(n => n.date === dateStr);
        if (existingNote) {
            setEditTitle(existingNote.title);
            setEditContent(existingNote.content);
            setEditIsSpecial(existingNote.isSpecial);
        } else {
            setEditTitle('');
            setEditContent('');
            setEditIsSpecial(false);
        }
        setIsNoteModalOpen(true);
    };

    const saveNote = () => {
        if (!selectedDate) return;
        const newNote: CalendarNote = {
            id: `cal-${Date.now()}`,
            date: selectedDate,
            title: editTitle.trim() || 'New Note',
            content: editContent.trim(),
            isSpecial: editIsSpecial
        };

        setNotes(prev => {
            const filtered = prev.filter(n => n.date !== selectedDate);
            if (newNote.title || newNote.content) {
                return [...filtered, newNote];
            }
            return filtered;
        });
        setIsNoteModalOpen(false);
    };

    if (isAnimating) return <CalendarRibbonAnimation onComplete={() => setIsAnimating(false)} />;

    return (
        <div className="h-full flex flex-col bg-[#05050A] text-white font-sans overflow-hidden">
            <header className="p-6 flex items-center justify-between border-b border-white/5 bg-black/40 backdrop-blur-md">
                <div className="flex items-center gap-4">
                    <button onClick={onClose} className="p-3 bg-white/5 rounded-2xl border border-white/10 hover:bg-white/10 transition-all">
                        <ArrowLeftIcon />
                    </button>
                    <h1 className="text-xl font-black tracking-tighter uppercase italic">Personal Calendar</h1>
                </div>
            </header>

            <main className="flex-1 overflow-y-auto p-6 pb-32 space-y-8 scroll-smooth">

                {/* YOUR TASKS SECTION */}
                <section className="space-y-4">
                    <div className="flex items-center justify-between px-2">
                         <h2 className="text-xs font-black text-pink-500 uppercase tracking-[0.4em]">Your Tasks</h2>
                         <span className="text-[9px] font-bold text-white/20 uppercase tracking-widest">Next 3 Days</span>
                    </div>

                    <div className="flex gap-4 overflow-x-auto pb-4 custom-scrollbar">
                        {upcomingTasks.length > 0 ? upcomingTasks.map(task => (
                            <motion.div 
                                key={task.id}
                                initial={{ opacity: 0, x: 20 }}
                                animate={{ opacity: 1, x: 0 }}
                                className="min-w-[240px] p-5 rounded-[2rem] bg-gradient-to-br from-indigo-900/40 to-black border border-white/10 relative overflow-hidden"
                            >
                                <div className="absolute top-0 right-0 p-3">
                                    <div className="w-2 h-2 rounded-full bg-pink-500 animate-pulse" />
                                </div>
                                <p className="text-[10px] font-black text-white/30 uppercase tracking-widest mb-1">{task.date}</p>
                                <h3 className="text-lg font-bold text-white truncate leading-tight">{task.title}</h3>
                                <p className="text-xs text-white/50 mt-1 line-clamp-1">{task.content || 'No description'}</p>
                            </motion.div>
