                </section>

                {/* CALENDAR ENGINE */}
                <section className="bg-white/5 rounded-[2.5rem] border border-white/10 p-6 shadow-2xl">
                    <div className="flex items-center justify-between mb-8 px-2">
                        <h2 className="text-2xl font-black italic tracking-tighter uppercase">{MONTHS[month]} <span className="text-pink-500">{year}</span></h2>
                        <div className="flex gap-2">
                            <button onClick={handlePrevMonth} className="p-3 bg-white/5 rounded-xl border border-white/10 hover:bg-white/10"><ChevronLeftIcon className="w-4 h-4" /></button>
                            <button onClick={handleNextMonth} className="p-3 bg-white/5 rounded-xl border border-white/10 hover:bg-white/10"><ChevronRightIcon className="w-4 h-4" /></button>
                        </div>
                    </div>

                    <div className="grid grid-cols-7 gap-2 mb-4">
                        {DAYS.map(d => (
                            <div key={d} className="text-center text-[10px] font-black text-white/20 uppercase tracking-widest py-2">{d}</div>
                        ))}
                    </div>

                    <div className="grid grid-cols-7 gap-3">
                        {calendarDays.map((day, i) => {
                            const dateStr = day ? `${year}-${String(month + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}` : null;
                            const hasNote = dateStr && notes.some(n => n.date === dateStr);
                            const note = dateStr ? notes.find(n => n.date === dateStr) : null;
                            const isToday = day && new Date().toDateString() === new Date(year, month, day).toDateString();

                            return (
                                <motion.button
                                    key={i}
                                    whileTap={{ scale: 0.9 }}
                                    disabled={!day}
                                    onClick={() => day && openNoteModal(day)}
                                    className={`aspect-square rounded-2xl flex flex-col items-center justify-center relative transition-all border ${
                                        !day ? 'opacity-0 pointer-events-none' : 
                                        isToday ? 'bg-pink-500 border-pink-400 shadow-[0_0_20px_rgba(236,72,153,0.4)]' :
                                        hasNote ? 'bg-white/10 border-white/20' : 'bg-white/5 border-white/5 hover:bg-white/10'
                                    }`}
                                >
                                    <span className={`text-sm font-black ${isToday ? 'text-white' : hasNote ? 'text-pink-400' : 'text-white/60'}`}>{day}</span>
                                    {hasNote && !isToday && <div className="absolute bottom-2 w-1 h-1 rounded-full bg-pink-500" />}
                                    {note?.isSpecial && <SparklesIcon className="absolute top-1 right-1 w-2.5 h-2.5 text-yellow-400 opacity-50" />}
                                </motion.button>
                            );
                        })}
                    </div>
                </section>

                <div className="text-center text-[9px] font-black text-white/10 uppercase tracking-[0.5em] pt-10">
                    S-Calendar Node v1.4 • Encrypted
                </div>
            </main>

            {/* NOTE MODAL */}
            <AnimatePresence>
                {isNoteModalOpen && (
                    <motion.div 
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                        exit={{ opacity: 0 }}
                        className="fixed inset-0 z-[600] flex items-center justify-center p-6 bg-black/90 backdrop-blur-xl"
                    >
                        <motion.div 
                            initial={{ scale: 0.9, y: 50 }}
                            animate={{ scale: 1, y: 0 }}
                            className="w-full max-w-md bg-zinc-900 border border-white/10 rounded-[3rem] p-8 shadow-2xl relative"
                        >
                            <button onClick={() => setIsNoteModalOpen(false)} className="absolute top-6 right-6 p-2 bg-white/5 rounded-full"><XMarkIcon className="w-5 h-5 text-white/40" /></button>

                            <div className="space-y-6">
                                <div>
                                    <p className="text-[10px] font-black text-pink-500 uppercase tracking-widest mb-1">Editing Date</p>
                                    <h3 className="text-2xl font-black text-white italic">{selectedDate}</h3>
                                </div>

                                <div className="space-y-4">
                                    <input 
                                        placeholder="Note Title"
                                        value={editTitle}
                                        onChange={e => setEditTitle(e.target.value)}
                                        className="w-full bg-white/5 border border-white/10 p-5 rounded-2xl text-lg font-bold outline-none focus:border-pink-500 transition-all"
                                    />
                                    <textarea 
                                        placeholder="Add your thoughts or task details..."
                                        value={editContent}
                                        onChange={e => setEditContent(e.target.value)}
                                        className="w-full h-32 bg-white/5 border border-white/10 p-5 rounded-2xl text-sm font-medium outline-none focus:border-pink-500 transition-all resize-none"
                                    />
                                    <button 
                                        onClick={() => setEditIsSpecial(!editIsSpecial)}
                                        className={`w-full p-4 rounded-2xl border transition-all flex items-center justify-between px-6 ${editIsSpecial ? 'bg-yellow-500/10 border-yellow-500/50 text-yellow-500' : 'bg-white/5 border-white/10 text-white/40'}`}
                                    >
                                        <span className="text-xs font-black uppercase tracking-widest">Mark as Special Day</span>
                                        <SparklesIcon className={`w-5 h-5 ${editIsSpecial ? 'opacity-100' : 'opacity-20'}`} />
                                    </button>
                                </div>

                                <button 
                                    onClick={saveNote}
                                    className="w-full py-5 bg-pink-500 rounded-2xl font-black text-white uppercase tracking-widest shadow-[0_15px_40px_rgba(236,72,153,0.3)] hover:scale-[1.02] active:scale-95 transition-all"
                                >
                                    Save Memory Link
                                </button>
                            </div>
                        </motion.div>
                    </motion.div>
                )}
            </AnimatePresence>

            <style>{`
                .custom-scrollbar::-webkit-scrollbar { height: 2px; }
                .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
                .custom-scrollbar::-webkit-scrollbar-thumb { background: rgba(255,255,255,0.1); border-radius: 10px; }
            `}</style>
        </div>
    );
};

