import React, { useState, useMemo, useEffect } from 'react';
import { UserProfile, CalendarNote, View } from '../types';
import { motion, AnimatePresence, LayoutGroup } from 'framer-motion';
import { useLocalStorage } from '../hooks/useLocalStorage';
import ArrowLeftIcon from '../components/icons/ArrowLeftIcon';
import ChevronLeftIcon from '../components/icons/ChevronLeftIcon';
import ChevronRightIcon from '../components/icons/ChevronRightIcon';
import SparklesIcon from '../components/icons/SparklesIcon';
import XMarkIcon from '../components/icons/XMarkIcon';
import CalendarRibbonAnimation from '../components/CalendarRibbonAnimation';
import TrashIcon from '../components/icons/TrashIcon';

const MONTHS = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
const DAYS = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];

interface PersonalCalendarViewProps {
    userProfile: UserProfile;
    onClose: () => void;
}

const PersonalCalendarView: React.FC<PersonalCalendarViewProps> = ({ userProfile, onClose }) => {
    const [isAnimating, setIsAnimating] = useState(true);
    const [currentDate, setCurrentDate] = useState(new Date());
    const [notes, setNotes] = useLocalStorage<CalendarNote[]>(`sifra_calendar_notes_${userProfile.userId}`, []);
    const [focusedDate, setFocusedDate] = useState<string | null>(null);

    // Editor State
    const [editTitle, setEditTitle] = useState('');
    const [editContent, setEditContent] = useState('');
    const [editIsSpecial, setEditIsSpecial] = useState(false);

    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();

    const firstDayOfMonth = new Date(year, month, 1).getDay();
    const daysInMonth = new Date(year, month + 1, 0).getDate();

    const calendarDays = useMemo(() => {
        const d = [];
        for (let i = 0; i < firstDayOfMonth; i++) d.push(null);
        for (let i = 1; i <= daysInMonth; i++) d.push(i);
        return d;
    }, [year, month, firstDayOfMonth, daysInMonth]);

    const handlePrevMonth = () => setCurrentDate(new Date(year, month - 1));
    const handleNextMonth = () => setCurrentDate(new Date(year, month + 1));

    const openDateFocus = (day: number) => {
        const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
        const existingNote = notes.find(n => n.date === dateStr);
        if (existingNote) {
            setEditTitle(existingNote.title);
            setEditContent(existingNote.content);
            setEditIsSpecial(existingNote.isSpecial);
        } else {
            setEditTitle('');
            setEditContent('');
            setEditIsSpecial(false);
        }
        setFocusedDate(dateStr);
    };

    const saveNote = () => {
        if (!focusedDate) return;
        const newNote: CalendarNote = {
            id: `cal-${Date.now()}`,
            date: focusedDate,
            title: editTitle.trim() || 'Untitled Note',
            content: editContent.trim(),
            isSpecial: editIsSpecial
        };

        setNotes(prev => {
            const filtered = prev.filter(n => n.date !== focusedDate);
            if (newNote.title || newNote.content) return [...filtered, newNote];
            return filtered;
        });
        setFocusedDate(null);
    };

    const deleteNote = () => {
        setNotes(prev => prev.filter(n => n.date !== focusedDate));
        setFocusedDate(null);
    };

    if (isAnimating) return <CalendarRibbonAnimation onComplete={() => setIsAnimating(false)} />;

    return (
        <LayoutGroup>
            <div className="h-full flex flex-col bg-[#08090F] text-white font-sans overflow-hidden select-none">
                {/* Header: Pro Aesthetics */}
                <header className="px-8 py-6 flex items-center justify-between border-b border-white/5 bg-black/40 backdrop-blur-2xl z-40">
                    <div className="flex items-center gap-6">
                        <motion.button 
                            whileTap={{ scale: 0.9 }}
                            onClick={onClose} 
                            className="p-3 bg-white/5 rounded-2xl border border-white/10 hover:bg-white/10 transition-all shadow-xl"
                        >
                            <ArrowLeftIcon />
                        </motion.button>
                        <div>
                            <h1 className="text-2xl font-black tracking-tighter uppercase italic leading-none">Personal Calendar</h1>
                            <p className="text-[10px] font-black text-pink-500 uppercase tracking-[0.4em] mt-1.5 flex items-center gap-2">
                                <span className="w-1.5 h-1.5 rounded-full bg-pink-500 animate-pulse" /> Sifra Memory Matrix
                            </p>
                        </div>
                    </div>
                    <div className="flex flex-col items-end">
                        <span className="text-[9px] font-bold text-white/30 uppercase tracking-widest">Protocol</span>
                        <span className="text-xs font-black text-white/80">PRO-LEVEL V2.4</span>
                    </div>
                </header>

                <main className="flex-1 overflow-y-auto p-8 space-y-10 relative scroll-smooth">
                    {/* Month Navigator: Ultra Clean */}
                    <div className="flex items-center justify-between px-2">
                        <motion.h2 
                            key={month}
                            initial={{ x: -20, opacity: 0 }} animate={{ x: 0, opacity: 1 }}
                            className="text-4xl font-black italic tracking-tighter uppercase"
                        >
                            {MONTHS[month]} <span className="text-pink-500">{year}</span>
                        </motion.h2>
                        <div className="flex gap-3">
                            <button onClick={handlePrevMonth} className="p-4 bg-white/5 rounded-2xl border border-white/10 hover:bg-white/10 transition-all"><ChevronLeftIcon className="w-5 h-5" /></button>
                            <button onClick={handleNextMonth} className="p-4 bg-white/5 rounded-2xl border border-white/10 hover:bg-white/10 transition-all"><ChevronRightIcon className="w-5 h-5" /></button>
                        </div>
                    </div>

                    {/* Pro Calendar Grid */}
                    <div className="bg-white/[0.02] border border-white/5 rounded-[3rem] p-8 shadow-2xl backdrop-blur-3xl">
                        <div className="grid grid-cols-7 gap-4 mb-6">
                            {DAYS.map(d => (
                                <div key={d} className="text-center text-[10px] font-black text-white/20 uppercase tracking-[0.3em]">{d}</div>
                            ))}
                        </div>

                        <div className="grid grid-cols-7 gap-4">
                            {calendarDays.map((day, i) => {
                                const dateStr = day ? `${year}-${String(month + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}` : null;
                                const note = dateStr ? notes.find(n => n.date === dateStr) : null;
                                const isToday = day && new Date().toDateString() === new Date(year, month, day).toDateString();

                                return (
                                    <motion.button
                                        key={i}
                                        layoutId={dateStr || `empty-${i}`}
                                        whileHover={day ? { y: -4, backgroundColor: 'rgba(255,255,255,0.08)' } : {}}
                                        whileTap={day ? { scale: 0.95 } : {}}
                                        disabled={!day}
                                        onClick={() => day && openDateFocus(day)}
                                        className={`aspect-square rounded-3xl flex flex-col items-center justify-center relative transition-all border ${
                                            !day ? 'opacity-0 pointer-events-none' : 
                                            isToday ? 'bg-pink-600 border-pink-400 shadow-[0_0_30px_rgba(236,72,153,0.3)]' :
                                            note ? 'bg-white/10 border-white/20' : 'bg-white/[0.03] border-white/5'
                                        }`}
                                    >
                                        <span className={`text-base font-black ${isToday ? 'text-white' : note ? 'text-pink-400' : 'text-white/40'}`}>{day}</span>
                                        {note && !isToday && <div className="absolute bottom-3 w-1.5 h-1.5 rounded-full bg-pink-500 shadow-[0_0_10px_#ff2a6d]" />}
                                        {note?.isSpecial && <SparklesIcon className="absolute top-2 right-2 w-3 h-3 text-yellow-400 opacity-70" />}
                                    </motion.button>
                                );
                            })}
                        </div>
                    </div>

                    {/* Upcoming Tasks Ticker */}
                    <div className="px-2">
                        <h3 className="text-xs font-black text-white/30 uppercase tracking-[0.5em] mb-6 flex items-center gap-4">
                            Recent Synchronizations <div className="h-[1px] flex-1 bg-white/5" />
                        </h3>
                        <div className="space-y-4">
                            {notes.slice(-3).map(n => (
                                <div key={n.id} className="p-6 rounded-[2rem] bg-white/5 border border-white/5 flex justify-between items-center group hover:bg-white/10 transition-all">
                                    <div className="flex items-center gap-5">
                                        <div className="w-12 h-12 rounded-2xl bg-pink-500/20 flex items-center justify-center text-pink-400 font-black">
                                            {n.date.split('-')[2]}
                                        </div>
                                        <div>
                                            <h4 className="font-bold text-white text-sm uppercase italic">{n.title}</h4>
                                            <p className="text-[10px] text-white/40 font-medium uppercase tracking-widest mt-0.5">{n.date}</p>
                                        </div>
                                    </div>
                                    <div className="opacity-0 group-hover:opacity-100 transition-opacity">
                                        <ChevronRightIcon className="text-white/20" />
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>

                    <div className="text-center text-[8px] font-black text-white/10 uppercase tracking-[0.6em] pt-12 pb-20">
                        Secure Neural Ledger v3.0 • End-to-End Encrypted
                    </div>
                </main>

                {/* FULL SCREEN DATE FOCUS MODE */}
                <AnimatePresence>
                    {focusedDate && (
                        <motion.div 
                            initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
                            className="fixed inset-0 z-[100] bg-black/95 backdrop-blur-3xl p-8 flex items-center justify-center"
                        >
                            <motion.div 
                                layoutId={focusedDate}
                                className="w-full max-w-2xl bg-[#0D0D16] border border-white/10 rounded-[4rem] p-10 shadow-[0_40px_100px_rgba(0,0,0,0.8)] relative overflow-hidden"
                            >
                                {/* Background Glow */}
                                <div className="absolute -top-20 -right-20 w-64 h-64 bg-pink-500/10 blur-[80px] rounded-full" />

                                <div className="flex justify-between items-start mb-12 relative z-10">
                                    <div>
                                        <p className="text-[11px] font-black text-pink-500 uppercase tracking-[0.4em] mb-2">Memory Focal Point</p>
                                        <h3 className="text-4xl font-black text-white italic tracking-tighter uppercase">{focusedDate}</h3>
                                    </div>
                                    <div className="flex gap-4">
                                        <button onClick={deleteNote} className="p-4 bg-red-500/10 text-red-500 rounded-3xl border border-red-500/20 hover:bg-red-500/20 transition-all"><TrashIcon className="w-6 h-6" /></button>
                                        <button onClick={() => setFocusedDate(null)} className="p-4 bg-white/5 rounded-3xl border border-white/10 hover:bg-white/10"><XMarkIcon className="w-6 h-6 text-white/60" /></button>
                                    </div>
                                </div>

                                <div className="space-y-6 relative z-10">
                                    <div className="space-y-2">
                                        <label className="text-[9px] font-black text-white/30 uppercase tracking-widest ml-4">Title</label>
                                        <input 
                                            value={editTitle}
                                            onChange={e => setEditTitle(e.target.value)}
                                            placeholder="Enter context title..."
                                            className="w-full bg-white/5 border border-white/10 p-7 rounded-[2rem] text-2xl font-black uppercase italic outline-none focus:border-pink-500/50 transition-all placeholder:text-white/10"
                                        />
                                    </div>

                                    <div className="space-y-2">
                                        <label className="text-[9px] font-black text-white/30 uppercase tracking-widest ml-4">Detailed Insights</label>
                                        <textarea 
                                            value={editContent}
                                            onChange={e => setEditContent(e.target.value)}
                                            placeholder="What happens on this date?"
                                            className="w-full h-48 bg-white/5 border border-white/10 p-7 rounded-[2.5rem] text-lg font-medium outline-none focus:border-pink-500/50 transition-all resize-none placeholder:text-white/10"
                                        />
                                    </div>

                                    <div className="flex items-center gap-6">
                                        <button 
                                            onClick={() => setEditIsSpecial(!editIsSpecial)}
                                            className={`flex-1 p-6 rounded-[2rem] border transition-all flex items-center justify-between px-8 ${editIsSpecial ? 'bg-yellow-500/10 border-yellow-500/50 text-yellow-500' : 'bg-white/5 border-white/10 text-white/20'}`}
                                        >
                                            <span className="text-[10px] font-black uppercase tracking-widest">Mark Special</span>
                                            <SparklesIcon className={`w-6 h-6 ${editIsSpecial ? 'opacity-100 animate-pulse' : 'opacity-20'}`} />
                                        </button>
                                        <button 
                                            onClick={saveNote}
                                            className="flex-[1.5] py-6 bg-white text-black rounded-[2rem] font-black uppercase tracking-[0.2em] shadow-2xl active:scale-95 transition-all"
                                        >
                                            Commit to Matrix
                                        </button>
                                    </div>
                                </div>
                            </motion.div>
                        </motion.div>
                    )}
                </AnimatePresence>
            </div>
        </LayoutGroup>
    );
};

