    neutral: 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-2.mp3'
};

const App: React.FC = () => {
    const [allUsers, setAllUsers] = useLocalStorage<UserProfile[]>('sifra_all_users', []);
    const [currentUser, setCurrentUser] = useLocalStorage<UserProfile | null>('sifra_current_user', null);

    const [appFlow, setAppFlow] = useState<AppFlow>(AppFlow.SPLASH);
    const [currentView, setCurrentView] = useState<View>(View.HOME);
    const [activeDiaryEntryId, setActiveDiaryEntryId] = useState<string | null>(null);

    const [chatHistory, setChatHistory] = useLocalStorage<Message[]>(`sifra_chat_history_${currentUser?.userId || ''}`, []);
    const [sifraVoice, setSifraVoice] = useLocalStorage<string>(`sifra_voice_${currentUser?.userId || ''}`, 'Kore');

    const [isLoading, setIsLoading] = useState(false);
    const [isSidebarOpen, setIsSidebarOpen] = useState(false);
    const [isProfileModalOpen, setIsProfileModalOpen] = useState(false);
    const [isVersionSelectorOpen, setIsVersionSelectorOpen] = useState(false);
    const [isQueenLockdown, setIsQueenLockdown] = useState(false);
    const [theme, setTheme] = useState<Theme>(THEMES[0]);
    const [showAdminPanel, setShowAdminPanel] = useState(false);
    const [currentMood, setCurrentMood] = useState<Mood>('neutral');
    const [currentlyPlayingAudioId, setCurrentlyPlayingAudioId] = useState<string | null>(null);

    // Freehand Wake Word detection
    const [isWakeWordActive, setIsWakeWordActive] = useState(false);
    const recognitionRef = useRef<any>(null);

    const handleSplashComplete = useCallback(() => {
        if (currentUser) {
            setAppFlow(AppFlow.MAIN_APP);
            setCurrentView(View.HOME);
        } else {
            setAppFlow(AppFlow.LOGIN);
        }
    }, [currentUser]);

    const chatRef = useRef<Chat | null>(null);
    const chatContainerRef = useRef<HTMLDivElement>(null);
    const headerPressTimer = useRef<number | null>(null);
    const audioContextRef = useRef<AudioContext | null>(null);
    const audioSourceRef = useRef<AudioBufferSourceNode | null>(null);
    const bgMusicRef = useRef<HTMLAudioElement | null>(null);

    useEffect(() => {
        const handlePopState = (event: PopStateEvent) => {
            if (event.state && typeof event.state.view === 'number') {
                setCurrentView(event.state.view);
            } else {
                setCurrentView(View.HOME);
            }
        };
        window.addEventListener('popstate', handlePopState);
        return () => window.removeEventListener('popstate', handlePopState);
    }, []);

    const handleNavigation = (view: View, params: any = null) => {
        if (view === View.DIARY_EDITOR) setActiveDiaryEntryId(params?.entryId || null);
        window.history.pushState({ view }, '', '');
        setCurrentView(view);
    };

    const handleBack = () => window.history.back();

    const handleLoginSuccess = (user: UserProfile) => {
        setCurrentUser(user);
        setAppFlow(AppFlow.MAIN_APP);
        setCurrentView(View.HOME);
        window.history.replaceState({ view: View.HOME }, '', '');
    };

    const handleLogout = () => {
        setCurrentUser(null);
        setChatHistory([]);
        setAppFlow(AppFlow.LOGIN);
        setCurrentView(View.HOME);
    };

    const handleClearAllData = () => {
        if (window.confirm('Delete ALL data?')) {
            localStorage.clear();
            window.location.reload();
        }
    };

    const handleNewChat = () => {
        setChatHistory([]);
        chatRef.current = null;
        handleNavigation(View.CHAT);
    };

    const handleUserProfileChange = (newProfile: UserProfile) => {
        setCurrentUser(newProfile);
        setAllUsers(users => users.map(u => u.userId === newProfile.userId ? newProfile : u));
    };

    useEffect(() => {
        if (currentUser) {
            const userTheme = THEMES.find(t => t.id === currentUser.themeId) || THEMES[0];
            setTheme(userTheme);
        }
    }, [currentUser]);

    // --- Global Freehand Wake Word Detection ---
    const speakAcknowledgement = useCallback(async () => {
        const text = "উমম বলো?";
        try {
            const audioData = await generateSpeech(text, sifraVoice);
            if (audioData) {
                const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
                const buffer = await decodeAudioData(decode(audioData), audioContext, 24000, 1);
                const source = audioContext.createBufferSource();
                source.buffer = buffer;
                source.connect(audioContext.destination);
                source.start();
            }
        } catch (e) {}
    }, [sifraVoice]);

    useEffect(() => {
        if (appFlow !== AppFlow.MAIN_APP || !currentUser) return;

        const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
        if (!SpeechRecognition) return;

        const startRecognition = () => {
            if (recognitionRef.current) return;

            const recognition = new SpeechRecognition();
            recognition.continuous = true;
            recognition.interimResults = true;
            recognition.lang = 'en-US';

            recognition.onresult = (event: any) => {
                const transcript = Array.from(event.results)
                    .map((result: any) => result[0])
                    .map((result: any) => result.transcript.toLowerCase())
                    .join('');

                if (transcript.includes('oi sifra') || transcript.includes('hey listen')) {
                    speakAcknowledgement();
                    recognition.stop();
                    recognitionRef.current = null;
                    // Trigger Voice Assistant
                    handleNavigation(View.GALAXY_VOICE);
                }
            };

            recognition.onend = () => {
                recognitionRef.current = null;
                // Restart automatically to keep "Always Listening" feel
                setTimeout(startRecognition, 1000);
            };

            recognitionRef.current = recognition;
            recognition.start();
        };

        startRecognition();
        return () => {
            if (recognitionRef.current) recognitionRef.current.stop();
        };
    }, [appFlow, currentUser, speakAcknowledgement]);

    // --- Audio Playback Logic ---
    const playAudio = useCallback(async (text: string, messageId: string) => {
        if (audioSourceRef.current) audioSourceRef.current.stop();
        setCurrentlyPlayingAudioId(messageId);
        try {
            if (!audioContextRef.current) {
                audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
            }
            const audioData = await generateSpeech(text, sifraVoice);
            if (audioData && audioContextRef.current) {
                const audioBuffer = await decodeAudioData(decode(audioData), audioContextRef.current, 24000, 1);
                const source = audioContextRef.current.createBufferSource();
                source.buffer = audioBuffer;
                source.connect(audioContextRef.current.destination);
                source.start();
                audioSourceRef.current = source;
                source.onended = () => { if (audioSourceRef.current === source) setCurrentlyPlayingAudioId(null); };
            }
        } catch (error) { setCurrentlyPlayingAudioId(null); }
    }, [sifraVoice]);

    const handleSendMessage = async (text: string, imageData?: { data: string, mimeType: string }) => {
        if ((!text.trim() && !imageData) || isLoading || !currentUser) return;
        const parts = [];
        if (text.trim()) parts.push({ text });
        if (imageData) parts.push({ inlineData: imageData });
        const userMessage: Message = { messageId: `msg-user-${Date.now()}`, role: Role.USER, parts };
        const currentChatHistory = [...chatHistory, userMessage];
        setChatHistory(currentChatHistory);
        setIsLoading(true);
        if (currentUser.moodAmbienceEnabled && text.trim()) detectMood(text).then(setCurrentMood);

        try {
            const systemInstruction = `You are SIFRA, a female AI assistant. Tone: Soft, polite, intelligent. Creator: Rizwan RR. 
            If the user asks to save something in the calendar (e.g. "Select date X as text Y"), confirm it nicely.`;

            if (!chatRef.current) {
                chatRef.current = ai.chats.create({ 
                    model: 'gemini-3-flash-preview', 
                    history: chatHistory.map(({role, parts}) => ({role, parts: parts.map(p => ({text: p.text}))})),
                    config: { systemInstruction } 
                });
            }
            const stream = await chatRef.current.sendMessageStream({ message: text.trim() || "Look at this image." });
            let fullText = '';
            const modelMessageId = `msg-model-${Date.now()}`;
            const placeholderMessage: Message = { messageId: modelMessageId, role: Role.MODEL, parts: [{ text: '' }] };
            setChatHistory([...currentChatHistory, placeholderMessage]);
            for await (const chunk of stream) {
                fullText += chunk.text || '';
                setChatHistory(prev => prev.map(msg => msg.messageId === modelMessageId ? { ...msg, parts: [{ text: fullText }] } : msg));
            }

            // --- Intelligence: Auto-Calendar Sync ---
            const lowerText = text.toLowerCase();
            if ((lowerText.includes('select') || lowerText.includes('save')) && (lowerText.includes('calendar') || lowerText.includes('date'))) {
                // Heuristic parsing for calendar sync
                const dateMatch = text.match(/(\d{1,2})[th|st|nd|rd]?\s+(january|february|march|april|may|june|july|august|september|october|november|december)/i);
                if (dateMatch) {
                    const day = dateMatch[1];
                    const monthName = dateMatch[2];
                    const monthIndex = MONTHS.indexOf(monthName.charAt(0).toUpperCase() + monthName.slice(1).toLowerCase());
                    const year = new Date().getFullYear();
                    const dateStr = `${year}-${String(monthIndex + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;

                    const newNote: CalendarNote = {
                        id: `ai-cal-${Date.now()}`,
                        date: dateStr,
                        title: 'Sifra Auto-Sync',
                        content: text,
                        isSpecial: true
                    };
                    const existingNotes = JSON.parse(localStorage.getItem(`sifra_calendar_notes_${currentUser.userId}`) || '[]');
                    localStorage.setItem(`sifra_calendar_notes_${currentUser.userId}`, JSON.stringify([...existingNotes, newNote]));
                }
            }

        } catch (error) {
            const errorMessage: Message = { messageId: `err-${Date.now()}`, role: Role.MODEL, parts: [{ text: "Error. Try again." }] };
            setChatHistory([...chatHistory, errorMessage]);
        } finally { setIsLoading(false); }
    };

    const renderMainView = () => {
        if (!currentUser) return null;
        const sifraAvatar = SIFRA_AVATARS.find(a => a.id === currentUser.sifraAvatarId) || SIFRA_AVATARS[0];
        switch (currentView) {
            case View.HOME: return <HomeView userProfile={currentUser} onNavigate={handleNavigation} />;
            case View.PROFILE: return <ProfileView userProfile={currentUser} onUserProfileChange={handleUserProfileChange} sifraVoice={sifraVoice} onSifraVoiceChange={setSifraVoice} onClose={handleBack} onNavigate={handleNavigation} onLogout={handleLogout} onClearAllData={handleClearAllData} />;
            case View.HISTORY: return <HistoryView chatHistory={chatHistory} setChatHistory={setChatHistory} onClose={handleBack} />;
            case View.TERMS: return <TermsView onClose={handleBack} showAcceptButton={false} onAccept={() => {}} />;
            case View.ABOUT: return <AboutView onClose={handleBack} />;
            case View.HOW_TO_USE: return <HowToUseView onClose={handleBack} />;
            case View.MOBILE_CONTROL: return <MobileControlView onClose={handleBack} />;
            case View.ACCOUNT_SWITCHER: return <AccountSwitcherView allUsers={allUsers} currentUser={currentUser} onSwitchUser={(id) => { const u = allUsers.find(x => x.userId === id); if(u) handleLoginSuccess(u); }} onAddNewUser={handleLogout} onClose={handleBack} />;
            case View.LIBRARY: return <LibraryView onClose={handleBack} onNavigate={handleNavigation} />;
            case View.TUTOR: return <TutorView userProfile={currentUser} onClose={handleBack} />;
            case View.TRAVEL_GUIDE: return <TravelGuideView userProfile={currentUser} onClose={handleBack} />;
            case View.SIFRA_SAVE: return <SifraSaveView userProfile={currentUser} onClose={handleBack} />;
            case View.MONER_DANA: return <MonerDanaView userProfile={currentUser} onClose={handleBack} onNavigate={handleNavigation} />;
            case View.DIARY_EDITOR: return <DiaryEditorView userProfile={currentUser} onClose={() => handleNavigation(View.MONER_DANA)} entryId={activeDiaryEntryId} />;
            case View.CALLS_SIFRA: return <CallsSifraView userProfile={currentUser} onClose={handleBack} />;
            case View.ADVANCED_SETTINGS: return <AdvancedSettingsView onNavigate={handleNavigation} onClose={handleBack} onNewChat={handleNewChat} onLogout={handleLogout} />;
            case View.VOICE_ASSISTANT: return <VoiceAssistantView userProfile={currentUser} onClose={handleBack} />;
            case View.GALAXY_VOICE: return <GalaxyVoiceView userProfile={currentUser} onClose={handleBack} />;
            case View.DUAL_MODE: return <DualModeView userProfile={currentUser} onUpdateProfile={handleUserProfileChange} onClose={handleBack} />;
            case View.SIFRA_PRO: return <SifraProView userProfile={currentUser} onUpdateProfile={handleUserProfileChange} onClose={handleBack} />;
            case View.SIFRA_PREMIUM_PLUS: return <SifraPremiumPlusView userProfile={currentUser} onClose={handleBack} />;
            case View.YOUR_CARD: return <YourCardView userProfile={currentUser} onClose={handleBack} />;
            case View.ACCOUNT_DETAILS: return <AccountDetailsView userProfile={currentUser} onClose={handleBack} onNavigate={handleNavigation} />;
            case View.MEET_SIFRA: return <MeetSifraView onClose={handleBack} />;
            case View.SIFRA_TOOLS: return <SifraToolsView userProfile={currentUser} onNavigate={handleNavigation} onClose={handleBack} />;
            case View.PERSONAL_CALENDAR: return <PersonalCalendarView userProfile={currentUser} onClose={handleBack} />;
            case View.CHAT:
            default:
                return (
                    <div className="h-full flex flex-col bg-white/50 backdrop-blur-md will-change-transform">
                        <header className="p-4 flex items-center justify-between border-b border-gray-100">
                             <div className="flex items-center gap-4">
                                <button onClick={handleBack} className="p-2 -ml-2 rounded-full hover:bg-black/5 transition-colors"><ArrowLeftIcon /></button>
                                <div><h1 className="text-lg font-bold text-gray-800">Sifra Chat</h1><p className="text-[10px] text-green-500 font-bold uppercase tracking-widest">Neural Link</p></div>
                             </div>
                             <Avatar src={sifraAvatar.url} isSifra />
                        </header>
                        <div ref={chatContainerRef} className="flex-1 overflow-y-auto space-y-4 p-4 scroll-smooth">
                            {chatHistory.map((msg, idx) => (
                                <ChatMessage key={msg.messageId || idx} message={msg} isPlayingAudio={currentlyPlayingAudioId === msg.messageId} onReplayAudio={playAudio} userAvatar={currentUser?.avatar || null} userName={currentUser?.name || null} sifraAvatarUrl={sifraAvatar.url} isLoading={isLoading} isLastMessage={idx === chatHistory.length - 1} />
                            ))}
                        </div>
                        <div className="p-4"><ChatInput onSendMessage={handleSendMessage} isLoading={isLoading} onVoiceClick={() => handleNavigation(View.GALAXY_VOICE)} /></div>
                    </div>
                );
        }
    };

    if (appFlow === AppFlow.SPLASH) return <SplashView onComplete={handleSplashComplete} />;
    if (appFlow === AppFlow.LOGIN) return <LoginView onLoginSuccess={handleLoginSuccess} />;

    return (
        <main className={`w-screen h-screen font-sans bg-gradient-to-br ${theme.gradient} flex flex-col overflow-hidden relative select-none`}>
             <AnimatePresence>
                {isQueenLockdown && <SifraQueenAnimation onComplete={() => setIsQueenLockdown(false)} />}
             </AnimatePresence>
             <motion.div 
                initial={false}
                animate={{ 
                    opacity: isQueenLockdown ? 0 : 1,
                    scale: isQueenLockdown ? 0.95 : 1,
                    y: isQueenLockdown ? 10 : 0
                }}
                transition={{ duration: 0.4, ease: "circOut" }}
                className="flex-1 flex flex-col will-change-transform h-full overflow-hidden"
                style={{ transform: 'translateZ(0)' }}
             >
                <div onMouseDown={() => headerPressTimer.current = window.setTimeout(() => setShowAdminPanel(true), 2000)} onMouseUp={() => clearTimeout(headerPressTimer.current)}>
                    {currentView === View.HOME && (
                        <Header userName={currentUser.nickname || currentUser.name} onProfileClick={() => setIsProfileModalOpen(true)} onMenuClick={() => setIsSidebarOpen(true)} onVersionClick={() => setIsVersionSelectorOpen(true)} onLogoClick={() => setIsQueenLockdown(true)} theme={theme} moodAmbienceEnabled={currentUser.moodAmbienceEnabled} currentMood={currentMood} />
                    )}
                </div>
                <Sidebar isOpen={isSidebarOpen} onClose={() => setIsSidebarOpen(false)} onNavigate={(v) => { handleNavigation(v); setIsSidebarOpen(false); }} onLogout={handleLogout} onNewChat={() => { handleNewChat(); setIsSidebarOpen(false); }} userProfile={currentUser!} />
                {showAdminPanel && <AdminView onClose={() => setShowAdminPanel(false)} currentUserProfile={currentUser!} />}
                {isProfileModalOpen && <ProfileModal userProfile={currentUser!} onClose={() => setIsProfileModalOpen(false)} onManageAccount={() => { setIsProfileModalOpen(false); handleNavigation(View.PROFILE); }} onLogout={handleLogout} onClearAllData={handleClearAllData} />}
                {isVersionSelectorOpen && <VersionSelector onClose={() => setIsVersionSelectorOpen(false)} onSelectFree={() => handleNavigation(View.CHAT)} onSelectQuantum={() => handleNavigation(View.DUAL_MODE)} onSelectPro={() => handleNavigation(View.SIFRA_PRO)} onSelectPremiumPlus={() => handleNavigation(View.SIFRA_PREMIUM_PLUS)} />}
                <div className="flex-1 overflow-hidden relative h-full">
                    {renderMainView()}
                </div>
             </motion.div>
        </main>
    );
};

const MONTHS = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];

export default App;

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { UserProfile, CalendarNote, View } from '../types';
import { motion, AnimatePresence, LayoutGroup } from 'framer-motion';
import { useLocalStorage } from '../hooks/useLocalStorage';
import ArrowLeftIcon from '../components/icons/ArrowLeftIcon';
import ChevronLeftIcon from '../components/icons/ChevronLeftIcon';
import ChevronRightIcon from '../components/icons/ChevronRightIcon';
import SparklesIcon from '../components/icons/SparklesIcon';
import XMarkIcon from '../components/icons/XMarkIcon';
import CalendarRibbonAnimation from '../components/CalendarRibbonAnimation';
import TrashIcon from '../components/icons/TrashIcon';
import BoltIcon from '../components/icons/BoltIcon';
import PlusCircleIcon from '../components/icons/PlusCircleIcon';

const MONTHS = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
const DAYS_SHORT = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];

interface PersonalCalendarViewProps {
    userProfile: UserProfile;
    onClose: () => void;
}

const PersonalCalendarView: React.FC<PersonalCalendarViewProps> = ({ userProfile, onClose }) => {
    const [isAnimating, setIsAnimating] = useState(true);
    const [currentDate, setCurrentDate] = useState(new Date());
    const [notes, setNotes] = useLocalStorage<CalendarNote[]>(`sifra_calendar_notes_${userProfile.userId}`, []);
    const [focusedDate, setFocusedDate] = useState<string | null>(null);

    // Editor State
    const [editTitle, setEditTitle] = useState('');
    const [editContent, setEditContent] = useState('');
    const [editIsSpecial, setEditIsSpecial] = useState(false);

    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();

    const daysInMonth = new Date(year, month + 1, 0).getDate();

    const weekStrip = useMemo(() => {
        const today = new Date();
        const start = new Date(today);
        start.setDate(today.getDate() - 3);
        const days = [];
        for (let i = 0; i < 7; i++) {
            const d = new Date(start);
            d.setDate(start.getDate() + i);
            days.push(d);
        }
        return days;
    }, []);

    const calendarDays = useMemo(() => {
        const d = [];
        for (let i = 1; i <= daysInMonth; i++) d.push(i);
        return d;
    }, [daysInMonth]);

    const handlePrevMonth = () => setCurrentDate(new Date(year, month - 1));
    const handleNextMonth = () => setCurrentDate(new Date(year, month + 1));

    const openDateFocus = (dateStr: string) => {
        const existingNote = notes.find(n => n.date === dateStr);
        if (existingNote) {
            setEditTitle(existingNote.title);
            setEditContent(existingNote.content);
            setEditIsSpecial(existingNote.isSpecial);
        } else {
            setEditTitle('');
            setEditContent('');
            setEditIsSpecial(false);
        }
        setFocusedDate(dateStr);
    };

    const saveNote = () => {
        if (!focusedDate) return;
        const newNote: CalendarNote = {
            id: `cal-${Date.now()}`,
            date: focusedDate,
            title: editTitle.trim() || 'Scheduled Event',
            content: editContent.trim(),
            isSpecial: editIsSpecial
        };

        setNotes(prev => {
            const filtered = prev.filter(n => n.date !== focusedDate);
            if (newNote.title || newNote.content) return [...filtered, newNote];
            return filtered;
        });
        setFocusedDate(null);
    };

    if (isAnimating) return <CalendarRibbonAnimation onComplete={() => setIsAnimating(false)} />;

    return (
        <LayoutGroup>
            <div className="h-full flex flex-col bg-[#01101b] text-white font-sans overflow-hidden select-none">
                {/* PRO HEADER - Deep Green/Dark Gradient inspired by image 1 */}
                <header className="pt-12 pb-6 px-8 bg-gradient-to-b from-[#0a2333] to-[#01101b] relative overflow-hidden">
                    <div className="absolute top-0 right-0 w-32 h-32 bg-[#ff5f6d]/10 blur-[60px] rounded-full" />
                    <div className="flex items-center justify-between relative z-10">
                        <button onClick={onClose} className="p-2 -ml-2 text-white/60 hover:text-white transition-colors">
                            <ArrowLeftIcon />
                        </button>
                        <h1 className="text-lg font-black tracking-tight uppercase">Intelligence Schedule</h1>
                        <button className="p-2 bg-white/5 rounded-xl border border-white/10">
                            <BoltIcon className="w-5 h-5 text-[#ff5f6d]" />
                        </button>
                    </div>

                    {/* Month Expansion inspired by image 2 */}
                    <div className="mt-8 flex items-end justify-between px-2">
                        <div>
                            <p className="text-[10px] font-black text-[#ff5f6d] uppercase tracking-[0.4em] mb-1">Active View</p>
                            <h2 className="text-3xl font-black italic tracking-tighter uppercase leading-none">
                                {MONTHS[month]} <span className="text-white/20">{year}</span>
                            </h2>
                        </div>
                        <div className="flex gap-2">
                            <button onClick={handlePrevMonth} className="p-2 hover:text-[#ff5f6d]"><ChevronLeftIcon className="w-5 h-5" /></button>
                            <button onClick={handleNextMonth} className="p-2 hover:text-[#ff5f6d]"><ChevronRightIcon className="w-5 h-5" /></button>
                        </div>
                    </div>
                </header>

                <main className="flex-1 overflow-y-auto relative scroll-smooth px-6 pt-6 pb-32 space-y-10">

                    {/* HORIZONTAL WEEK STRIP (Inspired by Gym Schedule Image) */}
                    <section className="space-y-4">
                        <div className="flex items-center justify-between px-2">
                             <h3 className="text-[11px] font-black text-white/30 uppercase tracking-[0.3em]">Timeline Sync</h3>
                             <button className="text-[10px] font-bold text-[#ff5f6d] uppercase tracking-widest">Full Grid</button>
                        </div>
                        <div className="flex gap-4 overflow-x-auto pb-4 no-scrollbar">
                            {weekStrip.map((date, i) => {
                                const isToday = date.toDateString() === new Date().toDateString();
                                const dStr = `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`;
                                const hasNote = notes.some(n => n.date === dStr);

                                return (
                                    <motion.button
                                        key={i}
                                        whileTap={{ scale: 0.95 }}
                                        onClick={() => openDateFocus(dStr)}
                                        className={`min-w-[70px] h-[90px] rounded-[1.8rem] flex flex-col items-center justify-center gap-1 transition-all border ${
                                            isToday ? 'bg-[#ff5f6d] border-[#ff5f6d] shadow-[0_15px_30px_rgba(255,95,109,0.3)]' : 
                                            hasNote ? 'bg-[#904394]/20 border-[#904394]/40' : 'bg-white/5 border-white/10'
                                        }`}
                                    >
                                        <span className={`text-[10px] font-bold uppercase tracking-widest ${isToday ? 'text-white/80' : 'text-white/40'}`}>
                                            {DAYS_SHORT[date.getDay()]}
                                        </span>
                                        <span className="text-xl font-black">{date.getDate()}</span>
                                        {hasNote && !isToday && <div className="w-1 h-1 rounded-full bg-[#ff5f6d]" />}
                                    </motion.button>
                                );
                            })}
                        </div>
                    </section>

                    {/* EVENT LIST - High Contrast Cards (Inspired by Sports Events Image) */}
                    <section className="space-y-6">
                        <div className="flex items-center justify-between px-2">
                            <h3 className="text-[11px] font-black text-white/30 uppercase tracking-[0.3em]">Sifra Observations</h3>
                            <span className="px-3 py-1 bg-white/5 rounded-full text-[9px] font-black text-white/50 uppercase tracking-widest border border-white/5">
                                {notes.length} Memories
                            </span>
                        </div>

                        <div className="space-y-4">
                            {notes.length > 0 ? notes.slice().reverse().map(note => (
                                <motion.button
                                    layoutId={`card-${note.date}`}
                                    key={note.id}
                                    onClick={() => openDateFocus(note.date)}
                                    className="w-full text-left p-6 rounded-[2.5rem] bg-white text-[#01101b] shadow-xl relative overflow-hidden group"
                                >
                                    {note.isSpecial && (
                                        <div className="absolute top-0 right-0 w-24 h-24 bg-[#ff5f6d]/10 rounded-full -mr-10 -mt-10 blur-2xl" />
                                    )}
                                    <div className="flex justify-between items-start mb-4">
                                        <div className="px-3 py-1 rounded-full bg-[#01101b]/5 text-[#01101b]/40 text-[9px] font-black uppercase tracking-widest border border-[#01101b]/10">
                                            {note.date}
                                        </div>
                                        {note.isSpecial && <SparklesIcon className="w-5 h-5 text-[#ff5f6d]" />}
                                    </div>
                                    <h4 className="text-xl font-black italic tracking-tighter uppercase leading-none mb-2 group-hover:text-[#ff5f6d] transition-colors">{note.title}</h4>
                                    <p className="text-sm font-medium text-[#01101b]/60 line-clamp-1">{note.content || 'Memory Sync Active...'}</p>
                                </motion.button>
                            )) : (
                                <div className="py-20 text-center border-2 border-dashed border-white/5 rounded-[3rem]">
                                    <PlusCircleIcon className="w-10 h-10 text-white/10 mx-auto mb-4" />
                                    <p className="text-xs font-black text-white/20 uppercase tracking-[0.2em]">Matrix is Empty</p>
                                </div>
                            )}
                        </div>
                    </section>

                    <div className="text-center text-[8px] font-black text-white/10 uppercase tracking-[0.6em] pt-10">
                        Pro-Level Encryption • Node 3.1
                    </div>
                </main>

                {/* FULL SCREEN FOCUSED EDITOR (Morping from card) */}
                <AnimatePresence>
                    {focusedDate && (
                        <motion.div 
                            initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
                            className="fixed inset-0 z-[100] bg-[#01101b] p-8 flex flex-col"
                        >
                            <header className="flex justify-between items-center mb-12">
                                <button onClick={() => setFocusedDate(null)} className="p-3 bg-white/5 rounded-2xl">
                                    <XMarkIcon className="w-6 h-6 text-white/40" />
                                </button>
                                <div className="text-center">
                                    <p className="text-[10px] font-black text-[#ff5f6d] uppercase tracking-[0.4em] mb-1">Refining Node</p>
                                    <h3 className="text-2xl font-black italic tracking-tighter uppercase leading-none">{focusedDate}</h3>
                                </div>
                                <button onClick={() => { setNotes(prev => prev.filter(n => n.date !== focusedDate)); setFocusedDate(null); }} className="p-3 bg-red-500/10 rounded-2xl">
                                    <TrashIcon className="w-6 h-6 text-red-500" />
                                </button>
                            </header>

                            <motion.div 
                                layoutId={`card-${focusedDate}`}
                                className="flex-1 bg-white rounded-[4rem] p-10 shadow-[0_40px_100px_rgba(0,0,0,0.5)] flex flex-col text-[#01101b]"
                            >
                                <div className="space-y-8 flex-1">
                                    <div className="space-y-2">
                                        <label className="text-[10px] font-black text-[#01101b]/30 uppercase tracking-widest ml-4">Module Title</label>
                                        <input 
                                            value={editTitle}
                                            onChange={e => setEditTitle(e.target.value)}
                                            placeholder="Enter Context..."
                                            className="w-full bg-transparent border-b-2 border-[#01101b]/5 p-2 text-3xl font-black italic uppercase outline-none focus:border-[#ff5f6d] transition-all"
                                        />
                                    </div>

                                    <div className="space-y-2">
                                        <label className="text-[10px] font-black text-[#01101b]/30 uppercase tracking-widest ml-4">Neural Data</label>
                                        <textarea 
                                            value={editContent}
                                            onChange={e => setEditContent(e.target.value)}
                                            placeholder="Sync thoughts for this date..."
                                            className="w-full h-40 bg-[#01101b]/5 rounded-[2.5rem] p-8 text-lg font-medium outline-none focus:ring-2 focus:ring-[#ff5f6d]/20 transition-all resize-none"
                                        />
                                    </div>

                                    <button 
                                        onClick={() => setEditIsSpecial(!editIsSpecial)}
                                        className={`w-full p-6 rounded-[2rem] border-2 flex items-center justify-between px-10 transition-all ${editIsSpecial ? 'bg-[#ff5f6d]/10 border-[#ff5f6d] text-[#ff5f6d]' : 'bg-transparent border-[#01101b]/5 text-[#01101b]/30'}`}
                                    >
                                        <span className="text-xs font-black uppercase tracking-widest">Mark as Special Day</span>
                                        <SparklesIcon className={`w-6 h-6 ${editIsSpecial ? 'opacity-100 animate-pulse' : 'opacity-20'}`} />
                                    </button>
                                </div>

                                <button 
                                    onClick={saveNote}
                                    className="w-full py-7 bg-[#01101b] text-white rounded-[2.5rem] font-black text-xl uppercase tracking-[0.2em] shadow-2xl hover:scale-[1.02] active:scale-95 transition-all mt-8"
                                >
                                    Commit to Matrix
                                </button>
                            </motion.div>
                        </motion.div>
                    )}
                </AnimatePresence>

                <style>{`
                    .no-scrollbar::-webkit-scrollbar { display: none; }
                    .no-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }
                `}</style>
            </div>
        </LayoutGroup>
    );
};

export default PersonalCalendarView;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GoogleGenAI, Chat } from '@google/genai';
import { AppFlow, View, UserProfile, Theme, THEMES, SIFRA_AVATARS, Message, Role, Mood, CalendarNote } from './types';
import { useLocalStorage } from './hooks/useLocalStorage';
import { AnimatePresence, motion } from 'framer-motion';

// Import Services & Utils
import { detectMood, generateSpeech } from './services/geminiService';
import { decode, decodeAudioData } from './utils/audioUtils';

// Import Views
import SplashView from './views/SplashView';
import LoginView from './views/LoginView';
import HomeView from './views/HomeView';
import ProfileView from './views/ProfileView';
import HistoryView from './views/HistoryView';
import TermsView from './views/TermsView';
import AboutView from './views/AboutView';
import HowToUseView from './views/HowToUseView';
import MobileControlView from './views/MobileControlView';
import AccountSwitcherView from './views/AccountSwitcherView';
import AdminView from './views/AdminView';
import LibraryView from './views/LibraryView';
import TutorView from './views/TutorView';
import TravelGuideView from './views/TravelGuideView';
import SifraSaveView from './views/SifraSaveView';
import MonerDanaView from './views/MonerDanaView';
import DiaryEditorView from './views/DiaryEditorView';
import CallsSifraView from './views/CallsSifraView';
import AdvancedSettingsView from './views/AdvancedSettingsView';
import VoiceAssistantView from './views/VoiceAssistantView';
import DualModeView from './views/DualModeView';
import SifraProView from './views/SifraProView';
import GalaxyVoiceView from './views/GalaxyVoiceView';
import SifraPremiumPlusView from './views/SifraPremiumPlusView';
import YourCardView from './views/YourCardView';
import AccountDetailsView from './views/AccountDetailsView';
import MeetSifraView from './views/MeetSifraView';
import SifraToolsView from './views/SifraToolsView';
import PersonalCalendarView from './views/PersonalCalendarView';

// Import Components
import Header from './components/Header';
import Sidebar from './components/Sidebar';
import ChatMessage from './components/ChatMessage';
import ChatInput from './components/ChatInput';
import ProfileModal from './components/ProfileModal';
import VersionSelector from './components/VersionSelector';
import ArrowLeftIcon from './components/icons/ArrowLeftIcon';
import Avatar from './components/Avatar';
import SifraQueenAnimation from './components/SifraQueenAnimation';

if (!process.env.API_KEY) {
    throw new Error("API_KEY environment variable is not set");
}
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const MOOD_MUSIC_MAP: Record<Mood, string> = {
    happy: 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-1.mp3',
    sad: 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-8.mp3',
    calm: 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-2.mp3',
    focused: 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-2.mp3',
    neutral: 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-2.mp3'
};

const App: React.FC = () => {
    const [allUsers, setAllUsers] = useLocalStorage<UserProfile[]>('sifra_all_users', []);
    const [currentUser, setCurrentUser] = useLocalStorage<UserProfile | null>('sifra_current_user', null);

    const [appFlow, setAppFlow] = useState<AppFlow>(AppFlow.SPLASH);
    const [currentView, setCurrentView] = useState<View>(View.HOME);
    const [activeDiaryEntryId, setActiveDiaryEntryId] = useState<string | null>(null);

    const [chatHistory, setChatHistory] = useLocalStorage<Message[]>(`sifra_chat_history_${currentUser?.userId || ''}`, []);
    const [sifraVoice, setSifraVoice] = useLocalStorage<string>(`sifra_voice_${currentUser?.userId || ''}`, 'Kore');

    const [isLoading, setIsLoading] = useState(false);
    const [isSidebarOpen, setIsSidebarOpen] = useState(false);
    const [isProfileModalOpen, setIsProfileModalOpen] = useState(false);
    const [isVersionSelectorOpen, setIsVersionSelectorOpen] = useState(false);
    const [isQueenLockdown, setIsQueenLockdown] = useState(false);
    const [theme, setTheme] = useState<Theme>(THEMES[0]);
    const [showAdminPanel, setShowAdminPanel] = useState(false);
    const [currentMood, setCurrentMood] = useState<Mood>('neutral');
    const [currentlyPlayingAudioId, setCurrentlyPlayingAudioId] = useState<string | null>(null);

    // Freehand Wake Word detection
    const recognitionRef = useRef<any>(null);

    const handleSplashComplete = useCallback(() => {
        if (currentUser) {
            setAppFlow(AppFlow.MAIN_APP);
            setCurrentView(View.HOME);
        } else {
            setAppFlow(AppFlow.LOGIN);
        }
    }, [currentUser]);

    const chatRef = useRef<Chat | null>(null);
    const chatContainerRef = useRef<HTMLDivElement>(null);
    const headerPressTimer = useRef<number | null>(null);
    const audioContextRef = useRef<AudioContext | null>(null);
    const audioSourceRef = useRef<AudioBufferSourceNode | null>(null);
    const bgMusicRef = useRef<HTMLAudioElement | null>(null);

    useEffect(() => {
        const handlePopState = (event: PopStateEvent) => {
            if (event.state && typeof event.state.view === 'number') {
                setCurrentView(event.state.view);
            } else {
                setCurrentView(View.HOME);
            }
        };
        window.addEventListener('popstate', handlePopState);
        return () => window.removeEventListener('popstate', handlePopState);
    }, []);

    const handleNavigation = (view: View, params: any = null) => {
        if (view === View.DIARY_EDITOR) setActiveDiaryEntryId(params?.entryId || null);
        window.history.pushState({ view }, '', '');
        setCurrentView(view);
    };

    const handleBack = () => window.history.back();

    const handleLoginSuccess = (user: UserProfile) => {
        setCurrentUser(user);
        setAppFlow(AppFlow.MAIN_APP);
        setCurrentView(View.HOME);
        window.history.replaceState({ view: View.HOME }, '', '');
    };

    const handleLogout = () => {
        setCurrentUser(null);
        setChatHistory([]);
        setAppFlow(AppFlow.LOGIN);
        setCurrentView(View.HOME);
    };

    const handleClearAllData = () => {
        if (window.confirm('Delete ALL data?')) {
            localStorage.clear();
            window.location.reload();
        }
    };

    const handleNewChat = () => {
        setChatHistory([]);
        chatRef.current = null;
        handleNavigation(View.CHAT);
    };

    const handleUserProfileChange = (newProfile: UserProfile) => {
        setCurrentUser(newProfile);
        setAllUsers(users => users.map(u => u.userId === newProfile.userId ? newProfile : u));
    };

    useEffect(() => {
        if (currentUser) {
            const userTheme = THEMES.find(t => t.id === currentUser.themeId) || THEMES[0];
            setTheme(userTheme);
        }
    }, [currentUser]);

    // --- Global Freehand Wake Word Detection Upgrade ---
    const speakAcknowledgement = useCallback(async () => {
        const text = "উম্ম বলো?";
        try {
            const audioData = await generateSpeech(text, sifraVoice);
            if (audioData) {
                const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
                const buffer = await decodeAudioData(decode(audioData), audioContext, 24000, 1);
                const source = audioContext.createBufferSource();
                source.buffer = buffer;
                source.connect(audioContext.destination);
                source.start();
            }
        } catch (e) {}
    }, [sifraVoice]);

    useEffect(() => {
        if (appFlow !== AppFlow.MAIN_APP || !currentUser) return;

        const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
        if (!SpeechRecognition) return;

        const startRecognition = () => {
            if (recognitionRef.current) return;

            const recognition = new SpeechRecognition();
            recognition.continuous = true;
            recognition.interimResults = true;
            recognition.lang = 'en-US';

            recognition.onresult = (event: any) => {
                const transcript = Array.from(event.results)
                    .map((result: any) => result[0])
                    .map((result: any) => result.transcript.toLowerCase())
                    .join('');

                if (transcript.includes('oi sifra') || transcript.includes('hey listen')) {
                    speakAcknowledgement();
                    recognition.stop();
                    recognitionRef.current = null;
                    handleNavigation(View.GALAXY_VOICE);
                }
            };

            recognition.onend = () => {
                recognitionRef.current = null;
                setTimeout(startRecognition, 1000);
            };

            recognitionRef.current = recognition;
            recognition.start();
        };

        startRecognition();
        return () => {
            if (recognitionRef.current) recognitionRef.current.stop();
        };
    }, [appFlow, currentUser, speakAcknowledgement]);

    // --- Audio Playback Logic ---
    const playAudio = useCallback(async (text: string, messageId: string) => {
        if (audioSourceRef.current) audioSourceRef.current.stop();
        setCurrentlyPlayingAudioId(messageId);
        try {
            if (!audioContextRef.current) {
                audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
            }
            const audioData = await generateSpeech(text, sifraVoice);
            if (audioData && audioContextRef.current) {
                const audioBuffer = await decodeAudioData(decode(audioData), audioContextRef.current, 24000, 1);
                const source = audioContextRef.current.createBufferSource();
                source.buffer = audioBuffer;
                source.connect(audioContextRef.current.destination);
                source.start();
                audioSourceRef.current = source;
                source.onended = () => { if (audioSourceRef.current === source) setCurrentlyPlayingAudioId(null); };
            }
        } catch (error) { setCurrentlyPlayingAudioId(null); }
    }, [sifraVoice]);

    const handleSendMessage = async (text: string, imageData?: { data: string, mimeType: string }) => {
        if ((!text.trim() && !imageData) || isLoading || !currentUser) return;
        const parts = [];
        if (text.trim()) parts.push({ text });
        if (imageData) parts.push({ inlineData: imageData });
        const userMessage: Message = { messageId: `msg-user-${Date.now()}`, role: Role.USER, parts };
        const currentChatHistory = [...chatHistory, userMessage];
        setChatHistory(currentChatHistory);
        setIsLoading(true);
        if (currentUser.moodAmbienceEnabled && text.trim()) detectMood(text).then(setCurrentMood);

        try {
            const systemInstruction = `You are SIFRA, a premium female AI assistant. Tone: High-end, soft, and extremely smart. 
            If the user mentions a date and an activity (e.g. "25th December as Big Day"), acknowledge you've saved it in their schedule.`;

            if (!chatRef.current) {
                chatRef.current = ai.chats.create({ 
                    model: 'gemini-3-flash-preview', 
                    history: chatHistory.map(({role, parts}) => ({role, parts: parts.map(p => ({text: p.text}))})),
                    config: { systemInstruction } 
                });
            }
            const stream = await chatRef.current.sendMessageStream({ message: text.trim() || "Look at this image." });
            let fullText = '';
            const modelMessageId = `msg-model-${Date.now()}`;
            const placeholderMessage: Message = { messageId: modelMessageId, role: Role.MODEL, parts: [{ text: '' }] };
            setChatHistory([...currentChatHistory, placeholderMessage]);
            for await (const chunk of stream) {
                fullText += chunk.text || '';
                setChatHistory(prev => prev.map(msg => msg.messageId === modelMessageId ? { ...msg, parts: [{ text: fullText }] } : msg));
            }

            // --- Intelligence: Pro Auto-Calendar Sync ---
            const lowerText = text.toLowerCase();
            if ((lowerText.includes('select') || lowerText.includes('save') || lowerText.includes('remember')) && (lowerText.includes('calendar') || lowerText.includes('date'))) {
                const dateMatch = text.match(/(\d{1,2})[th|st|nd|rd]?\s+(january|february|march|april|may|june|july|august|september|october|november|december)/i);
                if (dateMatch) {
                    const day = dateMatch[1];
                    const monthName = dateMatch[2];
                    const monthIndex = MONTHS.indexOf(monthName.charAt(0).toUpperCase() + monthName.slice(1).toLowerCase());
                    const year = new Date().getFullYear();
                    const dateStr = `${year}-${String(monthIndex + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;

                    const newNote: CalendarNote = {
                        id: `ai-cal-${Date.now()}`,
                        date: dateStr,
                        title: 'Auto-Synced Matrix Event',
                        content: text,
                        isSpecial: true
                    };
                    const existingNotes = JSON.parse(localStorage.getItem(`sifra_calendar_notes_${currentUser.userId}`) || '[]');
                    localStorage.setItem(`sifra_calendar_notes_${currentUser.userId}`, JSON.stringify([...existingNotes, newNote]));
                }
            }

        } catch (error) {
            const errorMessage: Message = { messageId: `err-${Date.now()}`, role: Role.MODEL, parts: [{ text: "Error. Try again." }] };
            setChatHistory([...chatHistory, errorMessage]);
        } finally { setIsLoading(false); }
    };

    const renderMainView = () => {
        if (!currentUser) return null;
        const sifraAvatar = SIFRA_AVATARS.find(a => a.id === currentUser.sifraAvatarId) || SIFRA_AVATARS[0];
        switch (currentView) {
            case View.HOME: return <HomeView userProfile={currentUser} onNavigate={handleNavigation} />;
            case View.PROFILE: return <ProfileView userProfile={currentUser} onUserProfileChange={handleUserProfileChange} sifraVoice={sifraVoice} onSifraVoiceChange={setSifraVoice} onClose={handleBack} onNavigate={handleNavigation} onLogout={handleLogout} onClearAllData={handleClearAllData} />;
            case View.HISTORY: return <HistoryView chatHistory={chatHistory} setChatHistory={setChatHistory} onClose={handleBack} />;
            case View.TERMS: return <TermsView onClose={handleBack} showAcceptButton={false} onAccept={() => {}} />;
            case View.ABOUT: return <AboutView onClose={handleBack} />;
            case View.HOW_TO_USE: return <HowToUseView onClose={handleBack} />;
            case View.MOBILE_CONTROL: return <MobileControlView onClose={handleBack} />;
            case View.ACCOUNT_SWITCHER: return <AccountSwitcherView allUsers={allUsers} currentUser={currentUser} onSwitchUser={(id) => { const u = allUsers.find(x => x.userId === id); if(u) handleLoginSuccess(u); }} onAddNewUser={handleLogout} onClose={handleBack} />;
            case View.LIBRARY: return <LibraryView onClose={handleBack} onNavigate={handleNavigation} />;
            case View.TUTOR: return <TutorView userProfile={currentUser} onClose={handleBack} />;
            case View.TRAVEL_GUIDE: return <TravelGuideView userProfile={currentUser} onClose={handleBack} />;
            case View.SIFRA_SAVE: return <SifraSaveView userProfile={currentUser} onClose={handleBack} />;
            case View.MONER_DANA: return <MonerDanaView userProfile={currentUser} onClose={handleBack} onNavigate={handleNavigation} />;
            case View.DIARY_EDITOR: return <DiaryEditorView userProfile={currentUser} onClose={() => handleNavigation(View.MONER_DANA)} entryId={activeDiaryEntryId} />;
            case View.CALLS_SIFRA: return <CallsSifraView userProfile={currentUser} onClose={handleBack} />;
            case View.ADVANCED_SETTINGS: return <AdvancedSettingsView onNavigate={handleNavigation} onClose={handleBack} onNewChat={handleNewChat} onLogout={handleLogout} />;
            case View.VOICE_ASSISTANT: return <VoiceAssistantView userProfile={currentUser} onClose={handleBack} />;
            case View.GALAXY_VOICE: return <GalaxyVoiceView userProfile={currentUser} onClose={handleBack} />;
            case View.DUAL_MODE: return <DualModeView userProfile={currentUser} onUpdateProfile={handleUserProfileChange} onClose={handleBack} />;
            case View.SIFRA_PRO: return <SifraProView userProfile={currentUser} onUpdateProfile={handleUserProfileChange} onClose={handleBack} />;
            case View.SIFRA_PREMIUM_PLUS: return <SifraPremiumPlusView userProfile={currentUser} onClose={handleBack} />;
            case View.YOUR_CARD: return <YourCardView userProfile={currentUser} onClose={handleBack} />;
            case View.ACCOUNT_DETAILS: return <AccountDetailsView userProfile={currentUser} onClose={handleBack} onNavigate={handleNavigation} />;
            case View.MEET_SIFRA: return <MeetSifraView onClose={handleBack} />;
            case View.SIFRA_TOOLS: return <SifraToolsView userProfile={currentUser} onNavigate={handleNavigation} onClose={handleBack} />;
            case View.PERSONAL_CALENDAR: return <PersonalCalendarView userProfile={currentUser} onClose={handleBack} />;
            case View.CHAT:
            default:
                return (
                    <div className="h-full flex flex-col bg-white/50 backdrop-blur-md will-change-transform">
                        <header className="p-4 flex items-center justify-between border-b border-gray-100">
                             <div className="flex items-center gap-4">
                                <button onClick={handleBack} className="p-2 -ml-2 rounded-full hover:bg-black/5 transition-colors"><ArrowLeftIcon /></button>
                                <div><h1 className="text-lg font-bold text-gray-800">Sifra Chat</h1><p className="text-[10px] text-green-500 font-bold uppercase tracking-widest">Neural Link</p></div>
                             </div>
                             <Avatar src={sifraAvatar.url} isSifra />
                        </header>
                        <div ref={chatContainerRef} className="flex-1 overflow-y-auto space-y-4 p-4 scroll-smooth">
                            {chatHistory.map((msg, idx) => (
                                <ChatMessage key={msg.messageId || idx} message={msg} isPlayingAudio={currentlyPlayingAudioId === msg.messageId} onReplayAudio={playAudio} userAvatar={currentUser?.avatar || null} userName={currentUser?.name || null} sifraAvatarUrl={sifraAvatar.url} isLoading={isLoading} isLastMessage={idx === chatHistory.length - 1} />
                            ))}
                        </div>
                        <div className="p-4"><ChatInput onSendMessage={handleSendMessage} isLoading={isLoading} onVoiceClick={() => handleNavigation(View.GALAXY_VOICE)} /></div>
                    </div>
                );
        }
    };

    if (appFlow === AppFlow.SPLASH) return <SplashView onComplete={handleSplashComplete} />;
    if (appFlow === AppFlow.LOGIN) return <LoginView onLoginSuccess={handleLoginSuccess} />;

    return (
        <main className={`w-screen h-screen font-sans bg-gradient-to-br ${theme.gradient} flex flex-col overflow-hidden relative select-none`}>
             <AnimatePresence>
                {isQueenLockdown && <SifraQueenAnimation onComplete={() => setIsQueenLockdown(false)} />}
             </AnimatePresence>
             <motion.div 
                initial={false}
                animate={{ 
                    opacity: isQueenLockdown ? 0 : 1,
                    scale: isQueenLockdown ? 0.95 : 1,
                    y: isQueenLockdown ? 10 : 0
                }}
                transition={{ duration: 0.4, ease: "circOut" }}
                className="flex-1 flex flex-col will-change-transform h-full overflow-hidden"
                style={{ transform: 'translateZ(0)' }}
             >
                <div onMouseDown={() => headerPressTimer.current = window.setTimeout(() => setShowAdminPanel(true), 2000)} onMouseUp={() => clearTimeout(headerPressTimer.current)}>
                    {currentView === View.HOME && (
                        <Header userName={currentUser.nickname || currentUser.name} onProfileClick={() => setIsProfileModalOpen(true)} onMenuClick={() => setIsSidebarOpen(true)} onVersionClick={() => setIsVersionSelectorOpen(true)} onLogoClick={() => setIsQueenLockdown(true)} theme={theme} moodAmbienceEnabled={currentUser.moodAmbienceEnabled} currentMood={currentMood} />
                    )}
                </div>
                <Sidebar isOpen={isSidebarOpen} onClose={() => setIsSidebarOpen(false)} onNavigate={(v) => { handleNavigation(v); setIsSidebarOpen(false); }} onLogout={handleLogout} onNewChat={() => { handleNewChat(); setIsSidebarOpen(false); }} userProfile={currentUser!} />
                {showAdminPanel && <AdminView onClose={() => setShowAdminPanel(false)} currentUserProfile={currentUser!} />}
                {isProfileModalOpen && <ProfileModal userProfile={currentUser!} onClose={() => setIsProfileModalOpen(false)} onManageAccount={() => { setIsProfileModalOpen(false); handleNavigation(View.PROFILE); }} onLogout={handleLogout} onClearAllData={handleClearAllData} />}
                {isVersionSelectorOpen && <VersionSelector onClose={() => setIsVersionSelectorOpen(false)} onSelectFree={() => handleNavigation(View.CHAT)} onSelectQuantum={() => handleNavigation(View.DUAL_MODE)} onSelectPro={() => handleNavigation(View.SIFRA_PRO)} onSelectPremiumPlus={() => handleNavigation(View.SIFRA_PREMIUM_PLUS)} />}
                <div className="flex-1 overflow-hidden relative h-full">
                    {renderMainView()}
                </div>
             </motion.div>
        </main>
    );
};

