    const [chatHistory, setChatHistory] = useLocalStorage<Message[]>(`sifra_chat_history_${currentUser?.userId || ''}`, []);
    const [sifraVoice, setSifraVoice] = useLocalStorage<string>(`sifra_voice_${currentUser?.userId || ''}`, 'Kore');

    const [isLoading, setIsLoading] = useState(false);
    const [isSidebarOpen, setIsSidebarOpen] = useState(false);
    const [isProfileModalOpen, setIsProfileModalOpen] = useState(false);
    const [isVersionSelectorOpen, setIsVersionSelectorOpen] = useState(false);
    const [isQueenLockdown, setIsQueenLockdown] = useState(false);
    const [theme, setTheme] = useState<Theme>(THEMES[0]);
    const [showAdminPanel, setShowAdminPanel] = useState(false);
    const [currentMood, setCurrentMood] = useState<Mood>('neutral');
    const [currentlyPlayingAudioId, setCurrentlyPlayingAudioId] = useState<string | null>(null);

    // PERSISTENT BACKGROUND LISTENER
    const recognitionRef = useRef<any>(null);
    const isVoiceViewActive = [View.GALAXY_VOICE, View.CALLS_SIFRA, View.VOICE_ASSISTANT, View.SIFRA_PREMIUM_PLUS].includes(currentView);

    const handleSplashComplete = useCallback(() => {
        if (currentUser) {
            setAppFlow(AppFlow.MAIN_APP);
            setCurrentView(View.HOME);
        } else {
            setAppFlow(AppFlow.LOGIN);
        }
    }, [currentUser]);

    const chatRef = useRef<Chat | null>(null);
    const audioContextRef = useRef<AudioContext | null>(null);
    const audioSourceRef = useRef<AudioBufferSourceNode | null>(null);

    useEffect(() => {
        const handlePopState = (event: PopStateEvent) => {
            if (event.state && typeof event.state.view === 'number') setCurrentView(event.state.view);
            else setCurrentView(View.HOME);
        };
        window.addEventListener('popstate', handlePopState);
        return () => window.removeEventListener('popstate', handlePopState);
    }, []);

    const handleNavigation = (view: View, params: any = null) => {
        if (view === View.DIARY_EDITOR) setActiveDiaryEntryId(params?.entryId || null);
        window.history.pushState({ view }, '', '');
        setCurrentView(view);
    };

    const handleBack = () => window.history.back();

    const handleLoginSuccess = (user: UserProfile) => {
        setCurrentUser(user);
        setAppFlow(AppFlow.MAIN_APP);
        setCurrentView(View.HOME);
        window.history.replaceState({ view: View.HOME }, '', '');
    };

    const handleLogout = () => {
        setCurrentUser(null);
        setChatHistory([]);
        setAppFlow(AppFlow.LOGIN);
        setCurrentView(View.HOME);
    };

    const handleUserProfileChange = (newProfile: UserProfile) => {
        setCurrentUser(newProfile);
        setAllUsers(users => users.map(u => u.userId === newProfile.userId ? newProfile : u));
    };

    useEffect(() => {
        if (currentUser) {
            const userTheme = THEMES.find(t => t.id === currentUser.themeId) || THEMES[0];
            setTheme(userTheme);
        }
    }, [currentUser]);

    // --- PRO WAKE WORD ACKNOWLEDGEMENT ---
    const speakAcknowledgement = useCallback(async () => {
        try {
            const audioData = await generateSpeech("উম্ম বলো?", sifraVoice);
            if (audioData) {
                const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
                const buffer = await decodeAudioData(decode(audioData), audioContext, 24000, 1);
                const source = audioContext.createBufferSource();
                source.buffer = buffer;
                source.connect(audioContext.destination);
                source.start();
            }
        } catch (e) {}
    }, [sifraVoice]);

    // --- STABLE BACKGROUND LISTENING (JARVIS STYLE) ---
    useEffect(() => {
        if (appFlow !== AppFlow.MAIN_APP || !currentUser) return;

        // Disable background listener if we are in an active voice view to prevent conflicts
        if (isVoiceViewActive) {
            if (recognitionRef.current) {
                recognitionRef.current.onend = null; // Prevent restart loop
                recognitionRef.current.stop();
                recognitionRef.current = null;
            }
            return;
        }

        const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
        if (!SpeechRecognition) return;

        const initRecognition = () => {
            if (recognitionRef.current) return;

            const recognition = new SpeechRecognition();
            recognition.continuous = true; 
            recognition.interimResults = true;
            recognition.lang = 'en-US';

            recognition.onresult = (event: any) => {
                const transcript = Array.from(event.results)
                    .map((result: any) => result[0].transcript.toLowerCase())
                    .join('');

                // Detect Wake Command
                if (transcript.includes('oi sifra') || transcript.includes('hey sifra') || transcript.includes('hey listen')) {
                    recognition.onend = null; // Disable restart before stop
                    recognition.stop();
                    recognitionRef.current = null;

                    speakAcknowledgement();
                    handleNavigation(View.GALAXY_VOICE);
                }
            };

            recognition.onend = () => {
                recognitionRef.current = null;
                // Only restart if we didn't transition to a voice view
                if (!isVoiceViewActive) {
                    setTimeout(initRecognition, 1000); 
                }
            };

            recognition.onerror = (e: any) => {
                console.warn("Speech Recognition Error:", e.error);
                if (e.error === 'not-allowed') return; // Don't loop if blocked
                recognitionRef.current = null;
            };

            recognitionRef.current = recognition;
            recognition.start();
        };

        initRecognition();
        return () => {
            if (recognitionRef.current) {
                recognitionRef.current.onend = null;
                recognitionRef.current.stop();
            }
        };
    }, [appFlow, currentUser, currentView, isVoiceViewActive, speakAcknowledgement]);

    // --- Audio Playback Logic ---
    const playAudio = useCallback(async (text: string, messageId: string) => {
        if (audioSourceRef.current) audioSourceRef.current.stop();
        setCurrentlyPlayingAudioId(messageId);
        try {
            if (!audioContextRef.current) {
                audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
            }
            const audioData = await generateSpeech(text, sifraVoice);
            if (audioData && audioContextRef.current) {
                const audioBuffer = await decodeAudioData(decode(audioData), audioContextRef.current, 24000, 1);
                const source = audioContextRef.current.createBufferSource();
                source.buffer = audioBuffer;
                source.connect(audioContextRef.current.destination);
                source.start();
                audioSourceRef.current = source;
                source.onended = () => { if (audioSourceRef.current === source) setCurrentlyPlayingAudioId(null); };
            }
        } catch (error) { setCurrentlyPlayingAudioId(null); }
    }, [sifraVoice]);

    const handleSendMessage = async (text: string, imageData?: { data: string, mimeType: string }) => {
        if ((!text.trim() && !imageData) || isLoading || !currentUser) return;
        const parts = [];
        if (text.trim()) parts.push({ text });
        if (imageData) parts.push({ inlineData: imageData });
        const userMessage: Message = { messageId: `msg-user-${Date.now()}`, role: Role.USER, parts };
        const currentChatHistory = [...chatHistory, userMessage];
        setChatHistory(currentChatHistory);
        setIsLoading(true);

        try {
            if (!chatRef.current) {
                chatRef.current = ai.chats.create({ 
                    model: 'gemini-3-flash-preview', 
                    history: chatHistory.map(({role, parts}) => ({role, parts: parts.map(p => ({text: p.text}))})),
                    config: { systemInstruction: "You are SIFRA AI. A professional assistant like Jarvis." } 
                });
            }
            const stream = await chatRef.current.sendMessageStream({ message: text.trim() || "Image" });
            let fullText = '';
            const modelMessageId = `msg-model-${Date.now()}`;
            setChatHistory([...currentChatHistory, { messageId: modelMessageId, role: Role.MODEL, parts: [{ text: '' }] }]);
            for await (const chunk of stream) {
                fullText += chunk.text || '';
                setChatHistory(prev => prev.map(msg => msg.messageId === modelMessageId ? { ...msg, parts: [{ text: fullText }] } : msg));
            }
        } catch (error) {
            setChatHistory([...chatHistory, { messageId: `err-${Date.now()}`, role: Role.MODEL, parts: [{ text: "Error." }] }]);
        } finally { setIsLoading(false); }
    };

    const renderMainView = () => {
        if (!currentUser) return null;
        const sifraAvatar = SIFRA_AVATARS.find(a => a.id === currentUser.sifraAvatarId) || SIFRA_AVATARS[0];
        switch (currentView) {
            case View.HOME: return <HomeView userProfile={currentUser} onNavigate={handleNavigation} />;
            case View.PROFILE: return <ProfileView userProfile={currentUser} onUserProfileChange={handleUserProfileChange} sifraVoice={sifraVoice} onSifraVoiceChange={setSifraVoice} onClose={handleBack} onNavigate={handleNavigation} onLogout={handleLogout} onClearAllData={() => {}} />;
            case View.HISTORY: return <HistoryView chatHistory={chatHistory} setChatHistory={setChatHistory} onClose={handleBack} />;
            case View.GALAXY_VOICE: return <GalaxyVoiceView userProfile={currentUser} onClose={handleBack} />;
            case View.SIFRA_TOOLS: return <SifraToolsView userProfile={currentUser} onNavigate={handleNavigation} onClose={handleBack} />;
            case View.PERSONAL_CALENDAR: return <PersonalCalendarView userProfile={currentUser} onClose={handleBack} />;
            case View.CHAT:
            default:
                return (
                    <div className="h-full flex flex-col bg-white">
                        <header className="p-4 flex items-center justify-between border-b border-gray-100">
                             <div className="flex items-center gap-4">
                                <button onClick={handleBack} className="p-2 -ml-2 rounded-full hover:bg-black/5"><ArrowLeftIcon /></button>
                                <h1 className="text-lg font-bold">Chat</h1>
                             </div>
                             <Avatar src={sifraAvatar.url} isSifra />
                        </header>
                        <div className="flex-1 overflow-y-auto space-y-4 p-4">
                            {chatHistory.map((msg, idx) => (
                                <ChatMessage key={msg.messageId || idx} message={msg} isPlayingAudio={currentlyPlayingAudioId === msg.messageId} onReplayAudio={playAudio} userAvatar={currentUser?.avatar || null} userName={currentUser?.name || null} sifraAvatarUrl={sifraAvatar.url} isLoading={isLoading} isLastMessage={idx === chatHistory.length - 1} />
                            ))}
                        </div>
                        <div className="p-4"><ChatInput onSendMessage={handleSendMessage} isLoading={isLoading} onVoiceClick={() => handleNavigation(View.GALAXY_VOICE)} /></div>
                    </div>
                );
        }
    };

    if (appFlow === AppFlow.SPLASH) return <SplashView onComplete={handleSplashComplete} />;
    if (appFlow === AppFlow.LOGIN) return <LoginView onLoginSuccess={handleLoginSuccess} />;

    return (
        <main className={`w-screen h-screen font-sans bg-gradient-to-br ${theme.gradient} flex flex-col overflow-hidden relative`}>
             <AnimatePresence>
                {isQueenLockdown && <SifraQueenAnimation onComplete={() => setIsQueenLockdown(false)} />}
             </AnimatePresence>
             <motion.div animate={{ opacity: isQueenLockdown ? 0 : 1 }} className="flex-1 flex flex-col h-full overflow-hidden">
                <Header userName={currentUser!.nickname || currentUser!.name} onProfileClick={() => setIsProfileModalOpen(true)} onMenuClick={() => setIsSidebarOpen(true)} onVersionClick={() => setIsVersionSelectorOpen(true)} onLogoClick={() => setIsQueenLockdown(true)} theme={theme} moodAmbienceEnabled={currentUser!.moodAmbienceEnabled} currentMood={currentMood} />
                <Sidebar isOpen={isSidebarOpen} onClose={() => setIsSidebarOpen(false)} onNavigate={(v) => { handleNavigation(v); setIsSidebarOpen(false); }} onLogout={handleLogout} onNewChat={() => { setChatHistory([]); setIsSidebarOpen(false); }} userProfile={currentUser!} />
                <div className="flex-1 overflow-hidden relative h-full">
                    {renderMainView()}
                </div>
             </motion.div>
        </main>
    );
};

export default App;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GoogleGenAI, LiveSession, Modality, LiveServerMessage, Blob } from '@google/genai';
import { motion, AnimatePresence } from 'framer-motion';
import { UserProfile } from '../types';
import { decode, decodeAudioData, encode } from '../utils/audioUtils';
import XMarkIcon from '../components/icons/XMarkIcon';
import ArrowLeftIcon from '../components/icons/ArrowLeftIcon';

if (!process.env.API_KEY) {
    throw new Error("API_KEY environment variable is not set");
}

const THEME = {
    bg: '#08090F', // Premium AMOLED Dark
    primary: '#FFFFFF',
    accent: '#3BB7FF',
    orbGlow: 'rgba(59, 183, 255, 0.4)',
};

const createBlob = (data: Float32Array): Blob => {
    const l = data.length;
    const int16 = new Int16Array(l);
    for (let i = 0; i < l; i++) {
        const s = Math.max(-1, Math.min(1, data[i]));
        int16[i] = s * 32767;
    }
    return {
        data: encode(new Uint8Array(int16.buffer)),
        mimeType: 'audio/pcm;rate=16000',
    };
};

type SessionState = 'idle' | 'connecting' | 'active' | 'error' | 'closing';

const GalaxyVoiceView: React.FC<{ userProfile: UserProfile; onClose: () => void; }> = ({ userProfile, onClose }) => {
    const [sessionState, setSessionState] = useState<SessionState>('idle');
    const [statusText, setStatusText] = useState('Listening...');
    const [isShipraSpeaking, setIsShipraSpeaking] = useState(false);

    const aiRef = useRef<GoogleGenAI | null>(null);
    const sessionPromiseRef = useRef<Promise<LiveSession> | null>(null);
    const streamRef = useRef<MediaStream | null>(null);
    const inputAudioContextRef = useRef<AudioContext | null>(null);
    const outputAudioContextRef = useRef<AudioContext | null>(null);
    const audioQueueRef = useRef(new Set<AudioBufferSourceNode>());
    const nextAudioStartTimeRef = useRef(0);
    const cleanedUpRef = useRef(false);
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const animationFrameRef = useRef<number>();
    const micEnergyRef = useRef(0);

    // Auto-timeout Logic (5 Seconds)
    const lastActivityRef = useRef<number>(Date.now());
    const silenceTimeoutRef = useRef<ReturnType<typeof setInterval> | null>(null);

    const cleanup = useCallback(() => {
        if (cleanedUpRef.current) return;
        cleanedUpRef.current = true;
        if (silenceTimeoutRef.current) clearInterval(silenceTimeoutRef.current);

        sessionPromiseRef.current?.then(session => session.close()).catch(console.error);
        sessionPromiseRef.current = null;

        if (streamRef.current) {
            streamRef.current.getTracks().forEach(track => track.stop());
            streamRef.current = null;
        }

        if (inputAudioContextRef.current && inputAudioContextRef.current.state !== 'closed') {
            inputAudioContextRef.current.close().catch(() => {});
        }
        inputAudioContextRef.current = null;

        if (outputAudioContextRef.current && outputAudioContextRef.current.state !== 'closed') {
            outputAudioContextRef.current.close().catch(() => {});
        }
        outputAudioContextRef.current = null;

        if (animationFrameRef.current) cancelAnimationFrame(animationFrameRef.current);
    }, []);

    const startSession = async () => {
        cleanup();
        cleanedUpRef.current = false;
        setSessionState('connecting');
        setStatusText('Initializing...');
        lastActivityRef.current = Date.now();

        try {
            streamRef.current = await navigator.mediaDevices.getUserMedia({ 
                audio: { echoCancellation: true, noiseSuppression: true, autoGainControl: true, sampleRate: 16000 } 
            });
        } catch (err) {
            setSessionState('error');
            setStatusText('Mic Blocked');
            return;
        }

        try {
            aiRef.current = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

            // JARVIS/SIRI LEVEL INSTRUCTIONS
            const systemInstruction = `
                You are SIFRA, a high-end personal AI assistant like Jarvis or Siri.
                User: ${userProfile.nickname || userProfile.name}.
                Tone: Smart, helpful, concise, and professional.

                CORE DIRECTIVES:
                1. You manage the user's "Personal Calendar" and "Memory Log."
                2. If the user asks to save something, acknowledge you've noted it for their tools.
                3. Reply instantly. Do not use filler words unless necessary for personality.
                4. Creator: Rizwan RR.
            `;

            sessionPromiseRef.current = aiRef.current.live.connect({
                model: 'gemini-2.5-flash-native-audio-preview-09-2025',
                callbacks: {
                    onopen: () => {
                        setSessionState('active');
                        setStatusText('Listening...');
                        if (!streamRef.current) return;
                        inputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
                        const ctx = inputAudioContextRef.current!;
                        const source = ctx.createMediaStreamSource(streamRef.current);
                        const processor = ctx.createScriptProcessor(2048, 1, 1);
                        source.connect(processor);
                        processor.connect(ctx.destination);

                        processor.onaudioprocess = (e) => {
                            const inputData = e.inputBuffer.getChannelData(0);
                            let sum = 0;
                            for (let i = 0; i < inputData.length; i++) sum += inputData[i] * inputData[i];
                            const energy = Math.sqrt(sum / inputData.length);
                            micEnergyRef.current = energy;

                            // Reset activity timer if user speaks (threshold 0.02)
                            if (energy > 0.02) lastActivityRef.current = Date.now();

                            sessionPromiseRef.current?.then(s => s.sendRealtimeInput({ media: createBlob(inputData) }));
                        };

                        // PRO ACTIVE WATCHDOG: Check for 5-second silence
                        silenceTimeoutRef.current = setInterval(() => {
                            const now = Date.now();
                            if (now - lastActivityRef.current > 5000 && !isShipraSpeaking) {
                                cleanup();
                                onClose();
                            }
                        }, 1000);
                    },
                    onmessage: async (msg: LiveServerMessage) => {
                        lastActivityRef.current = Date.now(); // Activity detected on msg
                        const audioData = msg.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
                        if (audioData) {
                            setIsShipraSpeaking(true);
                            setStatusText('Sifra is speaking...');
                            if (!outputAudioContextRef.current) {
                                outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
                            }
                            const ctx = outputAudioContextRef.current!;
                            const buffer = await decodeAudioData(decode(audioData), ctx, 24000, 1);
                            const source = ctx.createBufferSource();
                            source.buffer = buffer;
                            source.connect(ctx.destination);
                            const startTime = Math.max(ctx.currentTime, nextAudioStartTimeRef.current);
                            source.start(startTime);
                            nextAudioStartTimeRef.current = startTime + buffer.duration;
                            audioQueueRef.current.add(source);
                            source.onended = () => {
                                audioQueueRef.current.delete(source);
                                if (audioQueueRef.current.size === 0) {
                                    setIsShipraSpeaking(false);
                                    setStatusText('Listening...');
                                    lastActivityRef.current = Date.now(); // Start silence timer now
                                }
                            };
                        }
                    }
                },
                config: {
                    responseModalities: [Modality.AUDIO],
                    speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
                    systemInstruction
                }
            });
        } catch (e) { setSessionState('error'); }
    };

    useEffect(() => {
        startSession();
        return cleanup;
    }, []);

    // PREMIUM ORB ANIMATION
    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;
        canvas.width = window.innerWidth;
        canvas.height = window.innerHeight;
        const render = () => {
            ctx.fillStyle = THEME.bg;
            ctx.fillRect(0, 0, canvas.width, canvas.height);
            const cx = canvas.width / 2;
            const cy = canvas.height / 2 - 50;
            let energy = (isShipraSpeaking ? 0.3 : micEnergyRef.current) * 5;
            const time = Date.now() / 1000;
            const pulse = isShipraSpeaking ? Math.sin(time * 10) * 0.15 : Math.sin(time * 2) * 0.05;
            const radius = 80 * (1 + pulse + energy);

            // Glow
            const glowGradient = ctx.createRadialGradient(cx, cy, radius * 0.8, cx, cy, radius * 2.5);
            glowGradient.addColorStop(0, THEME.orbGlow);
            glowGradient.addColorStop(1, 'transparent');
            ctx.fillStyle = glowGradient;
            ctx.beginPath(); ctx.arc(cx, cy, radius * 2.5, 0, Math.PI * 2); ctx.fill();

            // Core Orb
            const orbGradient = ctx.createRadialGradient(cx - radius * 0.3, cy - radius * 0.3, radius * 0.1, cx, cy, radius);
            orbGradient.addColorStop(0, '#FFFFFF');
            orbGradient.addColorStop(1, '#1A1A1A');
            ctx.fillStyle = orbGradient;
            ctx.beginPath(); ctx.arc(cx, cy, radius, 0, Math.PI * 2); ctx.fill();

            animationFrameRef.current = requestAnimationFrame(render);
        };
        render();
    }, [sessionState, isShipraSpeaking]);

    return (
        <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 z-50 flex flex-col font-sans bg-[#08090F]">
            <canvas ref={canvasRef} className="absolute inset-0 w-full h-full" />
            <div className="relative z-10 flex items-center justify-between p-6">
                <button onClick={() => { cleanup(); onClose(); }} className="p-3 bg-white/5 rounded-2xl border border-white/10">
                    <ArrowLeftIcon className="w-6 h-6 text-white" />
                </button>
                <div className="text-center">
                    <span className="text-[10px] font-black tracking-[0.4em] text-white/40 uppercase">PRO-MATRIX</span>
                    <p className="text-xs text-blue-400 font-bold animate-pulse mt-1">{statusText}</p>
                </div>
                <div className="w-12" />
            </div>
            <div className="flex-1" />
            <div className="p-10 pb-16 flex flex-col items-center gap-6 relative z-10">
                <p className="text-[10px] font-black text-white/20 uppercase tracking-[0.2em]">Auto-off in 5s silence</p>
                <button onClick={() => { cleanup(); onClose(); }} className="w-20 h-20 bg-red-500 rounded-full flex items-center justify-center text-white shadow-xl shadow-red-500/20 active:scale-95 transition-transform">
                    <XMarkIcon className="w-8 h-8" />
                </button>
            </div>
        </motion.div>
    );
};

export default GalaxyVoiceView;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GoogleGenAI, Chat } from '@google/genai';
