const GlassAppIcon: React.FC<{ 
    icon: React.ReactNode, 
    label: string, 
    activeColor: string, 
    onClick?: () => void, 
    isLocked?: boolean,
    index: number 
}> = ({ icon, label, activeColor, onClick, isLocked, index }) => {
    const [isPressed, setIsPressed] = useState(false);

    return (
        <motion.button
            initial={{ opacity: 0, scale: 0.8, y: 30 }}
            animate={{ opacity: 1, scale: 1, y: 0 }}
            transition={{ 
                delay: index * 0.04, 
                ...SNAPPY_SPRING 
            }}
            onMouseDown={() => setIsPressed(true)}
            onMouseUp={() => setIsPressed(false)}
            onMouseLeave={() => setIsPressed(false)}
            onTouchStart={() => setIsPressed(true)}
            onTouchEnd={() => setIsPressed(false)}
            whileTap={{ scale: 0.92 }}
            onClick={isLocked ? undefined : onClick}
            className="flex flex-col items-center gap-4 group w-full outline-none py-2"
        >
            <div className={`relative w-24 h-24 sm:w-28 sm:h-28 rounded-[2.2rem] flex items-center justify-center transition-all duration-300 overflow-hidden border border-white/10 shadow-2xl backdrop-blur-3xl bg-white/5`}>

                {/* Dynamic Color Fill Animation */}
                <motion.div 
                    animate={{ 
                        opacity: isPressed && !isLocked ? 0.8 : 0,
                        scale: isPressed && !isLocked ? 1.5 : 0.5
                    }}
                    transition={{ duration: 0.2 }}
                    className={`absolute inset-0 rounded-full blur-2xl ${activeColor}`}
                />

