                {/* Icon Symbol */}
                <div className={`relative z-10 transition-all duration-200 ${isLocked ? 'text-white/10' : isPressed ? 'text-white scale-110' : 'text-white/60 group-hover:text-white'}`}>
                    {React.cloneElement(icon as React.ReactElement, { className: "w-10 h-10 sm:w-12 sm:h-12" })}
