                    </div>
                )}
            </div>

            <span className={`text-[11px] font-black tracking-[0.1em] text-center uppercase transition-colors duration-200 ${isLocked ? 'text-white/10' : isPressed ? 'text-white shadow-sm' : 'text-white/40 group-hover:text-white/80'}`}>
                {label}
            </span>
        </motion.button>
    );
};

