const MeetSifraAnimation = memo(() => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d', { alpha: true });
        if (!ctx) return;
        let animationFrameId: number;
        let time = 0;
        const render = () => {
            time += 0.015;
            const w = canvas.width;
            const h = canvas.height;
            ctx.clearRect(0, 0, w, h);
            const cx = w * 0.75;
            const cy = h / 2;
            for (let i = 0; i < 3; i++) {
                const r = (h * 0.2) + i * 15 + Math.sin(time + i) * 5;
                ctx.beginPath();
                ctx.arc(cx, cy, r, 0, Math.PI * 2);
                ctx.strokeStyle = `rgba(255, 42, 109, ${0.12 - i * 0.03})`;
                ctx.lineWidth = 2;
                ctx.stroke();
            }
            const coreR = (h * 0.12) + Math.sin(time * 2) * 4;
            const g = ctx.createRadialGradient(cx, cy, 0, cx, cy, coreR);
            g.addColorStop(0, 'rgba(255, 42, 109, 0.7)');
            g.addColorStop(1, 'rgba(255, 0, 85, 0)');
            ctx.beginPath(); ctx.arc(cx, cy, coreR, 0, Math.PI * 2);
            ctx.fillStyle = g; ctx.fill();
            animationFrameId = requestAnimationFrame(render);
        };
        render();
        return () => cancelAnimationFrame(animationFrameId);
    }, []);
    return <canvas ref={canvasRef} width={400} height={200} className="absolute inset-y-0 right-0 w-1/2 h-full pointer-events-none opacity-60" />;
});

