                            ))}
                        </motion.div>
                    )}
                </AnimatePresence>
            </div>

            <div className="flex gap-5 w-full lazy-render">
                <button onClick={() => onNavigate(View.ACCOUNT_DETAILS)} className="flex-1 h-24 rounded-[1.8rem] bg-white/20 backdrop-blur-md border border-white/30 flex flex-col items-center justify-center gap-3 shadow-sm active:scale-95 transition-all">
                    <UserIcon className="w-6 h-6 text-sky-600" /><span className="text-[9px] font-black text-gray-800 uppercase tracking-widest">Account</span>
                </button>
                <button onClick={() => onNavigate(View.YOUR_CARD)} className="flex-1 h-24 rounded-[1.8rem] bg-white/20 backdrop-blur-md border border-white/30 flex flex-col items-center justify-center gap-3 shadow-sm active:scale-95 transition-all">
                    <BookOpenIcon className="w-6 h-6 text-sky-600" /><span className="text-[9px] font-black text-gray-800 uppercase tracking-widest">Cards</span>
                </button>
            </div>
            <p className="text-[8px] font-black tracking-[0.5em] uppercase text-gray-400 text-center opacity-40 py-4">Sifra Hybrid Matrix v3.0</p>
        </div>
    );
};

