interface PersonalCalendarViewProps {
    userProfile: UserProfile;
    onClose: () => void;
}

const PersonalCalendarView: React.FC<PersonalCalendarViewProps> = ({ userProfile, onClose }) => {
    const [isAnimating, setIsAnimating] = useState(true);
    const [currentDate, setCurrentDate] = useState(new Date());
    const [viewMode, setViewMode] = useState<'monthly' | 'weekly'>('monthly');
    const [notes, setNotes] = useLocalStorage<CalendarNote[]>(`sifra_calendar_notes_${userProfile.userId}`, []);
    const [focusedDate, setFocusedDate] = useState<string | null>(null);

    // Editor State
    const [editTitle, setEditTitle] = useState('');
    const [editContent, setEditContent] = useState('');
    const [editTime, setEditTime] = useState('12:00');
    const [editIsSpecial, setEditIsSpecial] = useState(false);
    const [editColor, setEditColor] = useState(PRESET_COLORS[0].class);
    const [editReminder, setEditReminder] = useState(false);

    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();

    // Export Logic (.ics)
    const handleExportICS = useCallback(() => {
        let icsContent = "BEGIN:VCALENDAR\nVERSION:2.0\nPRODID:-//Sifra AI//Neural Calendar//EN\n";
        notes.forEach(note => {
            const dateClean = note.date.replace(/-/g, '');
            const timeClean = (note.time || '00:00').replace(/:/g, '') + '00';
            icsContent += "BEGIN:VEVENT\n";
            icsContent += `SUMMARY:${note.title}\n`;
            icsContent += `DTSTART:${dateClean}T${timeClean}\n`;
            icsContent += `DESCRIPTION:${note.content}\n`;
            icsContent += "END:VEVENT\n";
        });
        icsContent += "END:VCALENDAR";

        const blob = new Blob([icsContent], { type: 'text/calendar' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `sifra_matrix_export.ics`;
        a.click();
    }, [notes]);

    const handleDeviceSync = () => {
        if ('Notification' in window) {
            Notification.requestPermission().then(permission => {
                if (permission === 'granted') {
                    alert("✅ Neural Link Established. Device calendar symbols will now sync with Sifra Core.");
                }
            });
        } else {
            alert("This device does not support native notification sync.");
        }
    };

    const daysInMonth = new Date(year, month + 1, 0).getDate();

    const weekStrip = useMemo(() => {
        const start = new Date(currentDate);
        const day = start.getDay();
        start.setDate(start.getDate() - day);
        const days = [];
        for (let i = 0; i < 7; i++) {
            const d = new Date(start);
            d.setDate(start.getDate() + i);
            days.push(d);
        }
        return days;
    }, [currentDate]);

    const handlePrev = () => {
        if (viewMode === 'monthly') setCurrentDate(new Date(year, month - 1));
        else {
            const d = new Date(currentDate);
            d.setDate(d.getDate() - 7);
            setCurrentDate(d);
        }
    };

    const handleNext = () => {
        if (viewMode === 'monthly') setCurrentDate(new Date(year, month + 1));
        else {
            const d = new Date(currentDate);
            d.setDate(d.getDate() + 7);
            setCurrentDate(d);
        }
    };

    const openDateFocus = (dateStr: string) => {
        const existingNote = notes.find(n => n.date === dateStr);
        if (existingNote) {
            setEditTitle(existingNote.title);
            setEditContent(existingNote.content);
            setEditTime(existingNote.time || '12:00');
            setEditIsSpecial(existingNote.isSpecial);
            setEditColor(existingNote.color || PRESET_COLORS[0].class);
            setEditReminder(existingNote.reminderEnabled || false);
        } else {
            setEditTitle('');
            setEditContent('');
            setEditTime('12:00');
            setEditIsSpecial(false);
            setEditColor(PRESET_COLORS[0].class);
            setEditReminder(false);
        }
        setFocusedDate(dateStr);
    };

    const saveNote = () => {
        if (!focusedDate) return;
        const newNote: CalendarNote = {
            id: `cal-${Date.now()}`,
            date: focusedDate,
            time: editTime,
            title: editTitle.trim() || 'Scheduled Node',
            content: editContent.trim(),
            isSpecial: editIsSpecial,
            color: editColor,
            reminderEnabled: editReminder
        };

        setNotes(prev => {
            const filtered = prev.filter(n => n.date !== focusedDate);
            if (newNote.title || newNote.content) return [...filtered, newNote];
            return filtered;
        });
        setFocusedDate(null);
    };

    if (isAnimating) return <CalendarRibbonAnimation onComplete={() => setIsAnimating(false)} />;

    return (
        <LayoutGroup>
            <div className="h-full flex flex-col bg-[#01101b] text-white font-sans overflow-hidden select-none gpu-layer">

                {/* ADVANCED HEADER */}
                <header className="pt-12 pb-6 px-8 bg-gradient-to-b from-[#0a2333] to-[#01101b] relative overflow-hidden z-10">
                    <div className="absolute top-0 right-0 w-48 h-48 bg-[#ff5f6d]/5 blur-[80px] rounded-full" />
                    <div className="flex items-center justify-between relative z-10">
                        <button onClick={onClose} className="p-3 bg-white/5 rounded-2xl border border-white/5 active:scale-90 transition-transform">
                            <ArrowLeftIcon />
                        </button>
                        <div className="flex gap-1 p-1 bg-white/5 rounded-2xl border border-white/10">
                            <button 
                                onClick={() => setViewMode('monthly')}
                                className={`px-4 py-1.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${viewMode === 'monthly' ? 'bg-[#ff5f6d] text-white shadow-lg shadow-pink-500/20' : 'text-white/40'}`}
                            >
                                Month
                            </button>
                            <button 
                                onClick={() => setViewMode('weekly')}
                                className={`px-4 py-1.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${viewMode === 'weekly' ? 'bg-[#ff5f6d] text-white shadow-lg shadow-pink-500/20' : 'text-white/40'}`}
                            >
                                Week
                            </button>
                        </div>
                        <button onClick={handleExportICS} className="p-3 bg-white/5 rounded-2xl border border-white/5 active:scale-90">
                            <GlobeAltIcon className="w-5 h-5 text-sky-400" />
                        </button>
                    </div>

                    <div className="mt-8 flex items-end justify-between">
                        <div>
                            <p className="text-[10px] font-black text-[#ff5f6d] uppercase tracking-[0.4em] mb-1">Neural Timeline</p>
                            <h2 className="text-3xl font-black italic tracking-tighter uppercase leading-none">
                                {viewMode === 'monthly' ? MONTHS[month] : `Week of ${currentDate.getDate()}`} <span className="text-white/20">{year}</span>
                            </h2>
                        </div>
                        <div className="flex gap-1">
                            <button onClick={handlePrev} className="p-2 bg-white/5 rounded-xl hover:text-[#ff5f6d] transition-colors"><ChevronLeftIcon className="w-4 h-4" /></button>
                            <button onClick={handleNext} className="p-2 bg-white/5 rounded-xl hover:text-[#ff5f6d] transition-colors"><ChevronRightIcon className="w-4 h-4" /></button>
                        </div>
                    </div>
                </header>

                <main className="flex-1 premium-scroll relative px-6 pt-6 pb-40 space-y-10">

                    {/* VIEW SWITCHER CONTENT */}
                    <AnimatePresence mode="wait">
                        {viewMode === 'monthly' ? (
                            <motion.section 
                                key="monthly"
                                initial={{ opacity: 0, x: -20 }}
                                animate={{ opacity: 1, x: 0 }}
                                exit={{ opacity: 0, x: 20 }}
                                className="grid grid-cols-7 gap-2"
                            >
                                {DAYS_SHORT.map(d => (
                                    <div key={d} className="text-center text-[9px] font-black text-white/20 uppercase tracking-widest mb-2">{d}</div>
                                ))}
                                {[...Array(new Date(year, month, 1).getDay())].map((_, i) => <div key={`empty-${i}`} />)}
                                {calendarDays.map(day => {
                                    const dStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
                                    const note = notes.find(n => n.date === dStr);
                                    const isToday = new Date().toDateString() === new Date(year, month, day).toDateString();

                                    return (
                                        <button 
                                            key={day}
                                            onClick={() => openDateFocus(dStr)}
                                            className={`aspect-square rounded-2xl flex flex-col items-center justify-center relative transition-all border ${
                                                isToday ? 'bg-[#ff5f6d] border-[#ff5f6d] shadow-lg shadow-pink-500/20' : 
                                                note ? `${note.color || 'bg-white/10'} border-white/5` : 'bg-white/5 border-white/5'
                                            }`}
                                        >
                                            <span className={`text-xs font-black ${note && !isToday && note.color !== 'bg-white' ? 'text-white' : isToday ? 'text-white' : 'text-white/60'}`}>{day}</span>
                                            {note && !isToday && <div className="absolute bottom-1.5 w-1 h-1 rounded-full bg-white/40" />}
                                        </button>
                                    );
                                })}
                            </motion.section>
                        ) : (
                            <motion.section 
                                key="weekly"
                                initial={{ opacity: 0, x: 20 }}
                                animate={{ opacity: 1, x: 0 }}
                                exit={{ opacity: 0, x: -20 }}
                                className="space-y-4"
                            >
                                {weekStrip.map((date, i) => {
                                    const dStr = `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`;
                                    const note = notes.find(n => n.date === dStr);
                                    const isToday = date.toDateString() === new Date().toDateString();

                                    return (
                                        <button 
                                            key={i}
                                            onClick={() => openDateFocus(dStr)}
                                            className={`w-full p-6 rounded-[2.2rem] flex items-center justify-between border transition-all ${
                                                isToday ? 'bg-[#ff5f6d] border-[#ff5f6d] shadow-xl shadow-pink-500/10' : 
                                                note ? `${note.color || 'bg-white/10'} border-white/10` : 'bg-white/5 border-white/5'
                                            }`}
                                        >
                                            <div className="flex items-center gap-6">
                                                <div className="flex flex-col items-center">
                                                    <span className="text-[9px] font-black uppercase tracking-widest opacity-40">{DAYS_SHORT[date.getDay()]}</span>
                                                    <span className="text-xl font-black">{date.getDate()}</span>
                                                </div>
                                                <div className="h-8 w-[1px] bg-white/10" />
                                                <div className="text-left">
                                                    <h4 className={`text-sm font-black uppercase tracking-tight ${note ? 'text-white' : 'text-white/20'}`}>
