import React, { useState, useMemo, useCallback } from 'react';
import { UserProfile, CalendarNote } from '../types';
import { motion, AnimatePresence, LayoutGroup } from 'framer-motion';
import { useLocalStorage } from '../hooks/useLocalStorage';
import ArrowLeftIcon from '../components/icons/ArrowLeftIcon';
import ChevronLeftIcon from '../components/icons/ChevronLeftIcon';
import ChevronRightIcon from '../components/icons/ChevronRightIcon';
import SparklesIcon from '../components/icons/SparklesIcon';
import XMarkIcon from '../components/icons/XMarkIcon';
import CalendarRibbonAnimation from '../components/CalendarRibbonAnimation';
import TrashIcon from '../components/icons/TrashIcon';
import BoltIcon from '../components/icons/BoltIcon';
import PlusCircleIcon from '../components/icons/PlusCircleIcon';
import BellIcon from '../components/icons/BellIcon';
import GlobeAltIcon from '../components/icons/GlobeAltIcon';

const MONTHS = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
const DAYS_SHORT = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
const PRESET_COLORS = [
    { name: 'Neutral', class: 'bg-white', text: 'text-[#01101b]' },
    { name: 'Energy', class: 'bg-pink-500', text: 'text-white' },
    { name: 'Flow', class: 'bg-blue-500', text: 'text-white' },
    { name: 'Growth', class: 'bg-emerald-500', text: 'text-white' },
    { name: 'Focus', class: 'bg-amber-500', text: 'text-white' },
];

interface PersonalCalendarViewProps {
    userProfile: UserProfile;
    onClose: () => void;
}

const PersonalCalendarView: React.FC<PersonalCalendarViewProps> = ({ userProfile, onClose }) => {
    const [isAnimating, setIsAnimating] = useState(true);
    const [currentDate, setCurrentDate] = useState(new Date());
    const [viewMode, setViewMode] = useState<'monthly' | 'weekly'>('monthly');
    const [notes, setNotes] = useLocalStorage<CalendarNote[]>(`sifra_calendar_notes_${userProfile.userId}`, []);
    const [focusedDate, setFocusedDate] = useState<string | null>(null);

    // Editor State
    const [editTitle, setEditTitle] = useState('');
    const [editContent, setEditContent] = useState('');
    const [editTime, setEditTime] = useState('12:00');
    const [editIsSpecial, setEditIsSpecial] = useState(false);
    const [editColor, setEditColor] = useState(PRESET_COLORS[0].class);
    const [editReminder, setEditReminder] = useState(false);

    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();

    // Export Logic (.ics)
    const handleExportICS = useCallback(() => {
        let icsContent = "BEGIN:VCALENDAR\nVERSION:2.0\nPRODID:-//Sifra AI//Neural Calendar//EN\n";
        notes.forEach(note => {
            const dateClean = note.date.replace(/-/g, '');
            const timeClean = (note.time || '00:00').replace(/:/g, '') + '00';
            icsContent += "BEGIN:VEVENT\n";
            icsContent += `SUMMARY:${note.title}\n`;
            icsContent += `DTSTART:${dateClean}T${timeClean}\n`;
            icsContent += `DESCRIPTION:${note.content}\n`;
            icsContent += "END:VEVENT\n";
        });
        icsContent += "END:VCALENDAR";

        const blob = new Blob([icsContent], { type: 'text/calendar' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `sifra_matrix_export.ics`;
        a.click();
    }, [notes]);

    const handleDeviceSync = () => {
        if ('Notification' in window) {
            Notification.requestPermission().then(permission => {
                if (permission === 'granted') {
                    alert("✅ Neural Link Established. Device calendar symbols will now sync with Sifra Core.");
                }
            });
        } else {
            alert("This device does not support native notification sync.");
        }
    };

    const daysInMonth = new Date(year, month + 1, 0).getDate();

    // Fix: Defined calendarDays as an array from 1 to daysInMonth for rendering the monthly view grid.
    const calendarDays = useMemo(() => Array.from({ length: daysInMonth }, (_, i) => i + 1), [daysInMonth]);

    const weekStrip = useMemo(() => {
        const start = new Date(currentDate);
        const day = start.getDay();
        start.setDate(start.getDate() - day);
        const days = [];
        for (let i = 0; i < 7; i++) {
            const d = new Date(start);
            d.setDate(start.getDate() + i);
            days.push(d);
        }
        return days;
    }, [currentDate]);

    const handlePrev = () => {
        if (viewMode === 'monthly') setCurrentDate(new Date(year, month - 1));
        else {
            const d = new Date(currentDate);
            d.setDate(d.getDate() - 7);
            setCurrentDate(d);
        }
    };

    const handleNext = () => {
        if (viewMode === 'monthly') setCurrentDate(new Date(year, month + 1));
