            date: focusedDate,
            time: editTime,
            title: editTitle.trim() || 'Scheduled Node',
            content: editContent.trim(),
            isSpecial: editIsSpecial,
            color: editColor,
            reminderEnabled: editReminder
        };

        setNotes(prev => {
            const filtered = prev.filter(n => n.date !== focusedDate);
            if (newNote.title || newNote.content) return [...filtered, newNote];
            return filtered;
        });
        setFocusedDate(null);
    };

