                            >
                                Week
                            </button>
                        </div>
                        <button onClick={handleExportICS} className="p-3 bg-white/5 rounded-2xl border border-white/5 active:scale-90">
                            <GlobeAltIcon className="w-5 h-5 text-sky-400" />
                        </button>
                    </div>

