                                {viewMode === 'monthly' ? MONTHS[month] : `Week of ${currentDate.getDate()}`} <span className="text-white/20">{year}</span>
                            </h2>
                        </div>
                        <div className="flex gap-1">
                            <button onClick={handlePrev} className="p-2 bg-white/5 rounded-xl hover:text-[#ff5f6d] transition-colors"><ChevronLeftIcon className="w-4 h-4" /></button>
                            <button onClick={handleNext} className="p-2 bg-white/5 rounded-xl hover:text-[#ff5f6d] transition-colors"><ChevronRightIcon className="w-4 h-4" /></button>
                        </div>
                    </div>
                </header>

                <main className="flex-1 premium-scroll relative px-6 pt-6 pb-40 space-y-10">

                    {/* VIEW SWITCHER CONTENT */}
                    <AnimatePresence mode="wait">
                        {viewMode === 'monthly' ? (
                            <motion.section 
                                key="monthly"
                                initial={{ opacity: 0, x: -20 }}
                                animate={{ opacity: 1, x: 0 }}
                                exit={{ opacity: 0, x: 20 }}
                                className="grid grid-cols-7 gap-2"
                            >
                                {DAYS_SHORT.map(d => (
                                    <div key={d} className="text-center text-[9px] font-black text-white/20 uppercase tracking-widest mb-2">{d}</div>
                                ))}
                                {[...Array(new Date(year, month, 1).getDay())].map((_, i) => <div key={`empty-${i}`} />)}
                                {calendarDays.map(day => {
                                    const dStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
                                    const note = notes.find(n => n.date === dStr);
                                    const isToday = new Date().toDateString() === new Date(year, month, day).toDateString();

                                    return (
                                        <button 
                                            key={day}
                                            onClick={() => openDateFocus(dStr)}
                                            className={`aspect-square rounded-2xl flex flex-col items-center justify-center relative transition-all border ${
                                                isToday ? 'bg-[#ff5f6d] border-[#ff5f6d] shadow-lg shadow-pink-500/20' : 
                                                note ? `${note.color || 'bg-white/10'} border-white/5` : 'bg-white/5 border-white/5'
