                                                onClick={() => setEditReminder(!editReminder)}
                                                className={`w-full h-[60px] rounded-2xl flex items-center justify-center gap-2 transition-all ${editReminder ? 'bg-[#ff5f6d] text-white shadow-lg' : 'bg-black/5 text-black/40'}`}
                                            >
                                                <BellIcon className="w-5 h-5" />
                                                <span className="text-[10px] font-black uppercase">{editReminder ? 'ACTIVE' : 'OFFLINE'}</span>
                                            </button>
                                        </div>
                                    </div>

                                    <div className="space-y-1">
                                        <label className="text-[9px] font-black uppercase tracking-[0.2em] opacity-30 ml-2">Neural Data Payload</label>
                                        <textarea 
                                            value={editContent}
                                            onChange={e => setEditContent(e.target.value)}
                                            placeholder="Sync specific details into the matrix node..."
                                            className="w-full h-40 bg-black/5 rounded-[2.5rem] p-8 text-lg font-medium outline-none resize-none focus:ring-4 focus:ring-black/5 transition-all"
                                        />
                                    </div>

                                    <button 
                                        onClick={saveNote}
                                        className="w-full py-8 bg-[#01101b] text-white rounded-[2.5rem] font-black text-xl uppercase tracking-[0.3em] shadow-2xl active:scale-95 transition-all"
                                    >
                                        Commit Node
                                    </button>
                                </div>
                            </div>
                        </motion.div>
                    )}
                </AnimatePresence>

                <div className="fixed bottom-10 left-0 w-full flex flex-col items-center gap-2 z-[5] pointer-events-none opacity-20">
                    <div className="w-10 h-[1.5px] bg-white rounded-full" />
                    <span className="text-[6px] font-black text-white uppercase tracking-[1em]">Node S-Calendar v4.2</span>
                </div>
            </div>
        </LayoutGroup>
    );
};

