import React, { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { ClockStyleId } from '../types';

interface SifraClockProps {
    styleId: ClockStyleId;
    size?: 'sm' | 'md' | 'lg';
    onClick?: () => void;
}

const SifraClock: React.FC<SifraClockProps> = ({ styleId, size = 'md', onClick }) => {
    const [time, setTime] = useState(new Date());

    useEffect(() => {
        const timer = setInterval(() => setTime(new Date()), 1000);
        return () => clearInterval(timer);
    }, []);

    const hours = time.getHours();
    const minutes = time.getMinutes();
    const seconds = time.getSeconds();
    const dayName = time.toLocaleDateString('en-US', { weekday: 'long' });
    const dayNumeric = time.getDate();
    const monthName = time.toLocaleDateString('en-US', { month: 'short' }).toUpperCase();

    const hourDeg = (hours % 12) * 30 + minutes * 0.5;
    const minDeg = minutes * 6;
    const secDeg = seconds * 6;

    const sizeClass = size === 'sm' ? 'w-24 h-24' : size === 'md' ? 'w-32 h-32' : 'w-44 h-44';
    const containerBase = "relative rounded-[2.2rem] overflow-hidden flex items-center justify-center shadow-xl select-none transition-all";

    // STYLE 1: AURORA ANALOG (Left in reference)
    if (styleId === 'aurora-analog') {
        return (
            <div onClick={onClick} className={`${containerBase} ${sizeClass} bg-gradient-to-br from-indigo-400 via-blue-500 to-cyan-300`}>
                <div className="absolute inset-0 bg-white/5 backdrop-blur-[1px]" />
                <div className="absolute top-4 right-5 text-right">
                    <p className="text-[14px] font-black text-white leading-none">{hours.toString().padStart(2, '0')}</p>
                    <p className="text-[12px] font-bold text-white/40 leading-none">{minutes.toString().padStart(2, '0')}</p>
                </div>

                {/* Clock Face Markers */}
                <div className="absolute w-[80%] h-[80%]">
                    {[0, 90, 180, 270].map(deg => (
                        <div key={deg} className="absolute w-full h-full" style={{ transform: `rotate(${deg}deg)` }}>
                            <div className="w-1.5 h-[1px] bg-white/40 absolute left-0 top-1/2 -translate-y-1/2" />
                        </div>
                    ))}
                </div>

                {/* Hands */}
                <div className="relative w-full h-full flex items-center justify-center">
                    <motion.div style={{ rotate: hourDeg }} className="absolute w-[2px] h-8 bg-blue-900/60 rounded-full origin-bottom -translate-y-4" />
                    <motion.div style={{ rotate: minDeg }} className="absolute w-[1.5px] h-12 bg-white/80 rounded-full origin-bottom -translate-y-6" />
                    <div className="w-3 h-3 rounded-full bg-white shadow-md z-10 border border-white/20" />
                </div>

                <p className="absolute bottom-4 text-[6px] font-black text-white/50 uppercase tracking-[0.2em]">{dayName}</p>
            </div>
        );
    }

    // STYLE 2: MATRIX DIGITAL (Middle in reference)
    if (styleId === 'matrix-digital') {
        return (
            <div onClick={onClick} className={`${containerBase} ${sizeClass} bg-gradient-to-tr from-[#3b0a6b] via-[#2b6fc2] to-[#60a5fa]`}>
                <div className="flex gap-1 items-center justify-center p-4">
                    <div className="flex flex-col items-center">
                        <span className="text-4xl font-black text-white/80 tracking-tighter opacity-30 leading-none">{hours.toString().padStart(2, '0')}</span>
                        <span className="text-4xl font-black text-white tracking-tighter leading-none">{minutes.toString().padStart(2, '0')}</span>
                    </div>
                    <div className="w-[1px] h-12 bg-white/20 mx-2" />
                    <div className="flex flex-col items-start gap-1">
                        <span className="text-[6px] font-black text-blue-200 rotate-[-90deg] origin-left translate-x-2 translate-y-3">{dayName.toUpperCase()}</span>
                        <p className="text-[10px] font-black text-white tracking-tight leading-none mt-2">{dayNumeric}, {monthName}</p>
                    </div>
                </div>
            </div>
        );
    }

    // STYLE 3: ROMAN CLASSIC (Right in reference)
    return (
        <div onClick={onClick} className={`${containerBase} ${sizeClass} bg-white shadow-2xl`}>
            <div className="absolute inset-0 bg-gradient-to-tr from-cyan-50 via-white to-purple-50" />

            {/* Roman Marks */}
            <div className="absolute w-full h-full flex items-center justify-center">
                <span className="absolute top-3 text-[10px] font-black text-gray-800">XII</span>
                <span className="absolute right-3 text-[10px] font-black text-gray-800">III</span>
                <span className="absolute bottom-3 text-[10px] font-black text-gray-800">VI</span>
                <span className="absolute left-3 text-[10px] font-black text-gray-800">IX</span>
                {[30, 60, 120, 150, 210, 240, 300, 330].map(deg => (
                     <div key={deg} className="absolute w-[80%] h-[80%]" style={{ transform: `rotate(${deg}deg)` }}>
                        <div className="w-1.5 h-[0.5px] bg-gray-200 absolute right-0 top-1/2 -translate-y-1/2" />
                    </div>
                ))}
            </div>

            {/* Hands */}
            <div className="relative w-full h-full flex items-center justify-center">
                <motion.div style={{ rotate: hourDeg }} className="absolute w-1 h-6 bg-gray-300 rounded-full origin-bottom -translate-y-3" />
                <motion.div style={{ rotate: minDeg }} className="absolute w-1 h-10 bg-gray-800 rounded-full origin-bottom -translate-y-5" />
                <motion.div style={{ rotate: secDeg }} className="absolute w-[1px] h-12 bg-purple-500 rounded-full origin-bottom -translate-y-6" />
                <div className="w-1.5 h-1.5 rounded-full bg-purple-600 z-10" />
            </div>

            <div className="absolute opacity-5 text-[28px] font-black text-gray-900 pointer-events-none">
                {hours.toString().padStart(2, '0')}
            </div>
        </div>
    );
};

