// Ultra-snappy spring for 120Hz feel
const SNAPPY_SPRING = { type: "spring", stiffness: 750, damping: 45, mass: 0.8 };

const GlassAppIcon = memo(({ icon, label, activeColor, onClick, isLocked, index }: { 
    icon: React.ReactNode, 
    label: string, 
    activeColor: string, 
    onClick?: () => void, 
    isLocked?: boolean,
    index: number 
}) => {
    const [isPressed, setIsPressed] = useState(false);

    return (
        <motion.button
            initial={{ opacity: 0, scale: 0.9, y: 20 }}
            animate={{ opacity: 1, scale: 1, y: 0 }}
            transition={{ 
                delay: Math.min(index * 0.03, 0.2), // Stagger but cap it
                ...SNAPPY_SPRING 
            }}
            onMouseDown={() => setIsPressed(true)}
            onMouseUp={() => setIsPressed(false)}
            onMouseLeave={() => setIsPressed(false)}
            onTouchStart={() => setIsPressed(true)}
            onTouchEnd={() => setIsPressed(false)}
            whileTap={{ scale: 0.92 }}
            onClick={isLocked ? undefined : onClick}
            className="flex flex-col items-center gap-3 group w-full outline-none py-2 gpu-layer"
        >
            <div className={`relative w-24 h-24 sm:w-28 sm:h-28 rounded-[2.5rem] flex items-center justify-center transition-all duration-300 overflow-hidden border border-white/10 shadow-2xl backdrop-blur-2xl bg-white/5`}>

                {/* Hardware Accelerated Liquid Fill */}
                <motion.div 
                    animate={{ 
                        opacity: isPressed && !isLocked ? 1 : 0,
                        scale: isPressed && !isLocked ? 2 : 0.5
                    }}
                    transition={{ duration: 0.15, ease: "easeOut" }}
                    className={`absolute inset-0 rounded-full blur-2xl ${activeColor} pointer-events-none`}
                />

                <div className="absolute inset-0 bg-gradient-to-tr from-white/5 to-transparent opacity-20" />

                <div className={`relative z-10 transition-all duration-150 ${isLocked ? 'text-white/10' : isPressed ? 'text-white scale-110' : 'text-white/60 group-hover:text-white'}`}>
                    {React.cloneElement(icon as React.ReactElement, { className: "w-10 h-10 sm:w-12 sm:h-12" })}
                </div>

                {isLocked && (
                    <div className="absolute inset-0 flex items-center justify-center">
                        <BoltIcon className="w-5 h-5 text-white/5" />
                    </div>
                )}
            </div>

            <span className={`text-[10px] font-black tracking-[0.2em] text-center uppercase transition-all duration-200 ${isLocked ? 'text-white/10' : isPressed ? 'text-white translate-y-1' : 'text-white/30 group-hover:text-white/70'}`}>
                {label}
            </span>
        </motion.button>
    );
});

