const WorldMapSVG = memo(({ selectedCityId }: { selectedCityId?: string }) => (
    <svg viewBox="0 0 1000 500" className="w-full h-full opacity-40">
        <path fill="currentColor" className="text-white/20" d="M211,100 L250,110 L280,150 L300,200 L250,250 L200,220 Z M450,150 L500,160 L550,220 L520,280 L480,260 Z M700,120 L750,130 L800,180 L780,240 L720,220 Z M850,280 L900,290 L920,340 L880,380 L840,350 Z" />
        {/* Simple Red Dot / Vertical Line logic */}
        {selectedCityId === '3' && <line x1="180" y1="0" x2="180" y2="500" stroke="#FF5FAF" strokeWidth="2" />}
        {selectedCityId === '6' && <line x1="510" y1="0" x2="510" y2="500" stroke="#FF5FAF" strokeWidth="2" />}
    </svg>
));

const SifraClockView: React.FC<{ userProfile: UserProfile; onClose: () => void }> = ({ userProfile, onClose }) => {
    const [activeTab, setActiveTab] = useState<ClockTab>('clock');
    const [time, setTime] = useState(new Date());
    const [alarms, setAlarms] = useLocalStorage<AlarmNode[]>(`sifra_alarms_${userProfile.userId}`, []);
    const [is24h, setIs24h] = useLocalStorage('sifra_clock_24h', true);

    // World View Logic
    const [worldMode, setWorldMode] = useState<'list' | 'map'>('list');
    const [focusedCityId, setFocusedCityId] = useState<string>('3');

    useEffect(() => {
        const timer = setInterval(() => setTime(new Date()), 1000);
        return () => clearInterval(timer);
    }, []);

    const formatBigTime = (date: Date) => {
        const h = date.getHours();
        const m = date.getMinutes().toString().padStart(2, '0');
        const hh = is24h ? h.toString().padStart(2, '0') : ((h % 12) || 12).toString().padStart(2, '0');
        return { hh, mm: m };
    };

    const renderMainClock = () => {
        const { hh, mm } = formatBigTime(time);
        const day = time.toLocaleDateString('en-US', { weekday: 'short' });
        const dateStr = time.toLocaleDateString('en-US', { day: '2-digit', month: 'short' });

        return (
            <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="flex-1 flex flex-col p-10 justify-center gap-12">
                <div className="flex justify-between items-start">
                    <div className="w-10 h-10 rounded-2xl bg-white/5 border border-white/10 flex items-center justify-center">
                        <ClockIcon className="w-5 h-5 text-white/40" />
                    </div>
                    <div className="flex bg-white/5 rounded-full p-1 border border-white/10">
                        <button onClick={() => setIs24h(false)} className={`px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest transition-all ${!is24h ? 'bg-white text-black' : 'text-white/40'}`}>12h</button>
                        <button onClick={() => setIs24h(true)} className={`px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest transition-all ${is24h ? 'bg-white text-black' : 'text-white/40'}`}>24h</button>
                    </div>
                </div>

                <div className="flex flex-col">
                    <div className="text-[120px] font-black leading-none tracking-tighter text-white/90">
                        {hh}
                    </div>
                    <div className="text-[120px] font-black leading-none tracking-tighter text-white/90 ml-2">
                        {mm}
                    </div>
                </div>

                <div className="flex items-center gap-8">
                    <div className="text-left">
                        <p className="text-lg font-black text-white/80 tracking-tight">{day},</p>
                        <p className="text-lg font-black text-white/80 tracking-tight leading-none">{dateStr}</p>
                    </div>
                    <div className="h-10 w-[1px] bg-white/10" />
                    <div className="text-left">
                        <h2 className="text-4xl font-black text-white italic tracking-tighter uppercase leading-none">Los Angeles,</h2>
                        <p className="text-sm font-bold text-white/40 uppercase tracking-[0.2em] mt-2">California, USA</p>
                    </div>
                </div>

                <div className="mt-4 flex items-center gap-4">
                    <div className="flex items-center gap-2">
                        <BoltIcon className="w-4 h-4 text-orange-400" />
                        <span className="text-[10px] font-black text-white/40 uppercase tracking-widest">Sun ☀️ : 10h 06m</span>
                    </div>
                    <span className="text-[10px] font-black text-white/20 uppercase">07:12 - 17:17</span>
                </div>
            </motion.div>
        );
    };

    const renderWorldClock = () => (
        <div className="flex-1 flex flex-col overflow-hidden animate-fade-in">
            <header className="p-8 pb-4 flex justify-between items-center">
                 <div>
                    <h2 className="text-3xl font-black italic tracking-tighter uppercase text-white/90">World Time</h2>
                    <p className="text-[10px] font-black text-white/30 uppercase tracking-[0.4em] mt-1">Universal Neural Sync</p>
                 </div>
                 <button className="w-12 h-12 rounded-2xl bg-white/5 border border-white/10 flex items-center justify-center text-white/60 active:scale-90 transition-transform">
                    <PlusCircleIcon className="w-6 h-6" />
                 </button>
            </header>

            <div className="flex-1 premium-scroll p-8 pt-4 space-y-4">
                {worldMode === 'list' ? (
                    WORLD_CITIES.map(city => {
                        const isFocused = focusedCityId === city.id;
                        // Simulated local time logic
                        const cityTime = new Date(time.toLocaleString('en-US', { timeZone: city.timezone }));
                        const { hh, mm } = formatBigTime(cityTime);

                        return (
                            <button 
                                key={city.id} 
                                onClick={() => { setFocusedCityId(city.id); setWorldMode('map'); }}
                                className={`w-full p-6 rounded-[2.5rem] flex items-center justify-between border transition-all ${isFocused ? 'bg-white text-black border-transparent shadow-2xl' : 'bg-white/5 text-white border-white/5'}`}
                            >
                                <div className="text-left">
                                    <p className={`text-[10px] font-black uppercase tracking-widest ${isFocused ? 'opacity-40' : 'text-white/30'}`}>{city.offset}</p>
                                    <h4 className="text-lg font-black tracking-tight mt-1">{city.name}</h4>
                                </div>
                                <div className="flex items-center gap-2">
                                     <span className="text-3xl font-black tracking-tighter">{hh}:{mm}</span>
                                     <div className={`w-1.5 h-1.5 rounded-full ${cityTime.getHours() > 6 && cityTime.getHours() < 18 ? 'bg-orange-400' : 'bg-indigo-400'}`} />
                                </div>
                            </button>
                        )
                    })
                ) : (
                    <div className="h-full flex flex-col gap-6">
                        <div className="relative flex-1 bg-white/5 rounded-[3rem] border border-white/5 overflow-hidden">
                            <WorldMapSVG selectedCityId={focusedCityId} />

                            <div className="absolute bottom-10 left-10 right-10">
                                <motion.div 
                                    initial={{ y: 20, opacity: 0 }}
                                    animate={{ y: 0, opacity: 1 }}
                                    className="bg-black p-8 rounded-[2.5rem] flex items-center justify-between border border-white/10 shadow-2xl"
                                >
                                    <div className="text-left">
                                        <p className="text-[10px] font-black uppercase text-white/30 tracking-widest">{WORLD_CITIES.find(c => c.id === focusedCityId)?.offset}</p>
                                        <h4 className="text-2xl font-black text-white italic uppercase tracking-tighter">{WORLD_CITIES.find(c => c.id === focusedCityId)?.name}</h4>
                                    </div>
                                    <div className="flex items-center gap-3">
                                        <span className="text-4xl font-black text-white tracking-tighter">17:40</span>
                                        <div className="w-2 h-2 rounded-full bg-orange-400" />
                                    </div>
                                </motion.div>
                            </div>
                        </div>

                        {/* Timeline scrub area inspired by the image */}
                        <div className="h-20 w-full flex items-center justify-between px-4 border-t border-white/10 relative">
                            {[-1, 0, 1, 2].map(off => (
                                <div key={off} className="text-center">
                                    <p className={`text-[8px] font-black uppercase tracking-widest ${off === 1 ? 'text-white' : 'text-white/20'}`}>UTC {off >= 0 ? `+${off}` : off}</p>
                                    <div className={`w-1 h-1 rounded-full mx-auto mt-2 ${off === 1 ? 'bg-[#FF5FAF]' : 'bg-white/10'}`} />
                                </div>
                            ))}
                            <div className="absolute top-0 bottom-0 left-1/2 w-[1px] bg-white/5" />
                        </div>
                    </div>
                )}
            </div>
        </div>
    );

    return (
        <div className="fixed inset-0 z-[250] bg-black text-white flex flex-col font-sans overflow-hidden">
            {/* AMBIENT GLOW */}
            <div className="absolute top-[-10%] left-[-10%] w-[50%] h-[50%] bg-[#FF5FAF]/5 blur-[120px] pointer-events-none rounded-full" />
            <div className="absolute bottom-[-10%] right-[-10%] w-[50%] h-[50%] bg-blue-600/5 blur-[120px] pointer-events-none rounded-full" />

            <div className="relative z-10 flex-1 flex flex-col">
                <AnimatePresence mode="wait">
                    {activeTab === 'clock' && <div key="clock" className="h-full flex flex-col">{renderMainClock()}</div>}
                    {activeTab === 'world' && <div key="world" className="h-full flex flex-col">{renderWorldClock()}</div>}
                    {(activeTab === 'alarm' || activeTab === 'timer' || activeTab === 'stopwatch') && (
                        <div key="other" className="flex-1 flex flex-col items-center justify-center p-10 text-center opacity-40">
                             <BoltIcon className="w-12 h-12 mb-6" />
                             <h2 className="text-2xl font-black italic uppercase tracking-widest">Node Offline</h2>
                             <p className="text-xs font-bold uppercase tracking-[0.2em] mt-2">Module is currently undergoing neural calibration.</p>
                        </div>
                    )}
                </AnimatePresence>
            </div>

            {/* FLOATING PILL NAV */}
            <div className="h-32 flex items-center justify-center relative z-20 pb-10">
                <div className="bg-white/5 backdrop-blur-3xl border border-white/10 rounded-full flex items-center gap-1 p-1.5 shadow-[0_20px_50px_rgba(0,0,0,0.5)]">
                    <button 
                        onClick={() => setActiveTab('world')}
                        className={`w-14 h-14 rounded-full flex items-center justify-center transition-all ${activeTab === 'world' ? 'bg-white text-black' : 'text-white/40'}`}
                    >
                        <SearchIcon className="w-6 h-6" />
                    </button>
                    <button 
                        onClick={() => setActiveTab('clock')}
                        className={`w-14 h-14 rounded-full flex items-center justify-center transition-all ${activeTab === 'clock' ? 'bg-white text-black shadow-lg shadow-white/10' : 'text-white/40'}`}
                    >
                        <ClockIcon className="w-6 h-6" />
                    </button>
                    <button 
                        onClick={() => { if(activeTab==='world') setWorldMode(worldMode === 'list' ? 'map' : 'list'); else setActiveTab('world'); }}
