import React, { useState, useEffect, useRef, useMemo, memo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { UserProfile, View } from '../types';
import ArrowLeftIcon from '../components/icons/ArrowLeftIcon';
import XMarkIcon from '../components/icons/XMarkIcon';
import MicrophoneIcon from '../components/icons/MicrophoneIcon';
import CameraIcon from '../components/icons/CameraIcon';
import SendIcon from '../components/icons/SendIcon';
import CalculatorIcon from '../components/icons/CalculatorIcon';
import GlobeAltIcon from '../components/icons/GlobeAltIcon';
import SparklesIcon from '../components/icons/SparklesIcon';
import ClockIcon from '../components/icons/ClockIcon';
import BoltIcon from '../components/icons/BoltIcon';
import TrashIcon from '../components/icons/TrashIcon';
import SifraLogo from '../components/SifraLogo';
import { GoogleGenAI } from '@google/genai';

type CalcTab = 'calculator' | 'ai' | 'currency' | 'history';
type CalcMode = 'basic' | 'advanced' | 'easy';

const CURRENCIES = [
    { code: 'BDT', name: 'Bangladeshi Taka', symbol: '৳' },
    { code: 'INR', name: 'Indian Rupee', symbol: '₹' },
    { code: 'USD', name: 'US Dollar', symbol: '$' },
    { code: 'EUR', name: 'Euro', symbol: '€' },
    { code: 'GBP', name: 'British Pound', symbol: '£' },
    { code: 'SAR', name: 'Saudi Riyal', symbol: 'SR' }
];

const SifraCalculatorView: React.FC<{ userProfile: UserProfile; onClose: () => void }> = ({ userProfile, onClose }) => {
    const [activeTab, setActiveTab] = useState<CalcTab>('calculator');
    const [mode, setMode] = useState<CalcMode>('basic');
    const [input, setInput] = useState('');
    const [result, setResult] = useState('');
    const [history, setHistory] = useState<{ expression: string; res: string; date: string }[]>([]);

    // AI State
    const [aiQuery, setAiQuery] = useState('');
    const [aiResponse, setAiResponse] = useState<{ result: string, explanation: string } | null>(null);
    const [isAiLoading, setIsAiLoading] = useState(false);

    // Currency State
    const [curAmount, setCurAmount] = useState('1');
    const [fromCur, setFromCur] = useState('USD');
    const [toCur, setToCur] = useState('BDT');

    const handlePress = (val: string) => {
        if (val === 'AC') { setInput(''); setResult(''); return; }
        if (val === '⌫') { setInput(prev => prev.slice(0, -1)); return; }
        if (val === '=') {
            try {
                // Basic cleanup for math
                const evalStr = input.replace(/×/g, '*').replace(/÷/g, '/');
                const res = eval(evalStr).toString();
                setResult(res);
                setHistory([{ expression: input, res, date: new Date().toLocaleTimeString() }, ...history]);
            } catch (e) {
                setResult('Error');
            }
            return;
        }
        setInput(prev => prev + val);
    };

    const handleAiAsk = async () => {
        if (!aiQuery.trim()) return;
        setIsAiLoading(true);
        try {
            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
            const response = await ai.models.generateContent({
                model: 'gemini-3-flash-preview',
                contents: `Calculate this for a non-math user: "${aiQuery}". 
                Respond in JSON format: {"result": "the final number", "explanation": "step by step simple guide"}`
            });
            const data = JSON.parse(response.text);
            setAiResponse(data);
            setHistory([{ expression: aiQuery, res: data.result, date: new Date().toLocaleTimeString() }, ...history]);
        } catch (e) {
            setAiResponse({ result: 'Calculation Failed', explanation: 'Sifra matrix is currently unstable. Please try manual input.' });
        } finally {
            setIsAiLoading(false);
        }
    };

    const renderCalculator = () => {
        const buttons = mode === 'basic' 
            ? ['AC', '⌫', '%', '÷', '7', '8', '9', '×', '4', '5', '6', '−', '1', '2', '3', '+', '0', '.', '(', ')', '=']
            : ['AC', '⌫', 'sin', 'cos', 'tan', '7', '8', '9', '÷', '4', '5', '6', '×', '1', '2', '3', '−', '0', '.', 'π', '^', '(', ')', '+', '='];

        return (
            <div className="flex-1 flex flex-col p-6 gap-4">
                <div className="flex justify-between items-center mb-4">
                    <div className="flex bg-white/5 rounded-full p-1 border border-white/10">
                        {(['basic', 'advanced', 'easy'] as CalcMode[]).map(m => (
                            <button key={m} onClick={() => setMode(m)} className={`px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest transition-all ${mode === m ? 'bg-white text-black' : 'text-white/40'}`}>{m}</button>
                        ))}
                    </div>
                </div>

                <div className="flex-1 flex flex-col justify-end items-end p-6 bg-white/[0.02] rounded-[3rem] border border-white/5 min-h-[160px] mb-4">
                    <div className="text-xl text-white/40 font-mono tracking-tighter mb-2 break-all">{input || '0'}</div>
                    <div className="text-6xl font-black text-white font-mono tracking-tighter transition-all">{result || (input ? '' : '0')}</div>
                </div>

                <div className={`grid ${mode === 'advanced' ? 'grid-cols-5' : 'grid-cols-4'} gap-3`}>
                    {buttons.map(btn => (
                        <motion.button
                            key={btn}
                            whileTap={{ scale: 0.92 }}
                            onClick={() => handlePress(btn)}
                            className={`aspect-square rounded-[1.5rem] flex items-center justify-center text-lg font-bold transition-all ${
                                btn === '=' ? 'bg-[#4DA3FF] text-white shadow-[0_0_20px_rgba(77,163,255,0.4)]' :
                                ['÷', '×', '−', '+', 'sin', 'cos', 'tan'].includes(btn) ? 'bg-white/10 text-[#4DA3FF]' :
                                ['AC', '⌫'].includes(btn) ? 'bg-rose-500/20 text-rose-500' : 'bg-white/5 text-white/80 hover:bg-white/10'
                            }`}
                        >
                            {btn}
                        </motion.button>
                    ))}
                </div>
            </div>
        );
    };

    const renderAiTab = () => (
        <div className="flex-1 flex flex-col p-8 space-y-8 animate-fade-in">
            <div className="flex flex-col items-center gap-4 py-10">
                <div className="relative">
                    <motion.div animate={{ scale: [1, 1.1, 1], opacity: [0.3, 0.6, 0.3] }} transition={{ duration: 3, repeat: Infinity }} className="absolute inset-0 bg-[#8B5CF6]/20 blur-3xl rounded-full" />
                    <SifraLogo size="md" showText={false} />
                </div>
                <h2 className="text-2xl font-black italic uppercase tracking-tighter">Sifra AI Calc</h2>
                <p className="text-[10px] font-black text-white/30 uppercase tracking-[0.4em] text-center">Neural Equation Processor</p>
            </div>

            <div className="space-y-4">
                <textarea 
                    value={aiQuery}
                    onChange={e => setAiQuery(e.target.value)}
                    placeholder="Try: 'Calculate 20% discount on 1500'"
                    className="w-full h-32 bg-white/5 border border-white/10 rounded-3xl p-6 text-white outline-none focus:border-[#8B5CF6] transition-all resize-none font-medium"
                />
                <div className="flex gap-3">
                    <button className="flex-1 p-4 bg-white/5 rounded-2xl flex items-center justify-center gap-2 text-white/40"><MicrophoneIcon className="w-5 h-5" /> Voice</button>
                    <button className="flex-1 p-4 bg-white/5 rounded-2xl flex items-center justify-center gap-2 text-white/40"><CameraIcon className="w-5 h-5" /> Snap</button>
                    <button 
                        onClick={handleAiAsk}
                        disabled={isAiLoading || !aiQuery}
                        className="w-16 h-16 bg-[#8B5CF6] rounded-2xl flex items-center justify-center text-white shadow-xl disabled:opacity-30"
                    >
                        {isAiLoading ? <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" /> : <SendIcon />}
                    </button>
                </div>
            </div>

            <AnimatePresence>
                {aiResponse && (
                    <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="p-8 bg-[#8B5CF6]/10 border border-[#8B5CF6]/30 rounded-[2.5rem] space-y-4">
                        <div className="flex items-center gap-3">
                            <SparklesIcon className="w-5 h-5 text-[#8B5CF6]" />
                            <span className="text-[10px] font-black uppercase tracking-widest text-[#8B5CF6]">Intelligent Result</span>
                        </div>
                        <h3 className="text-4xl font-black text-white font-mono">{aiResponse.result}</h3>
                        <p className="text-sm text-white/60 leading-relaxed italic">"{aiResponse.explanation}"</p>
                    </motion.div>
                )}
            </AnimatePresence>
        </div>
    );

    const renderCurrency = () => (
        <div className="flex-1 flex flex-col p-8 space-y-8 animate-fade-in">
            <header className="flex justify-between items-center">
                <h2 className="text-3xl font-black italic tracking-tighter uppercase">World Exchange</h2>
                <GlobeAltIcon className="w-6 h-6 text-[#4DA3FF]" />
            </header>

            <div className="space-y-6">
                <div className="p-8 bg-white/5 rounded-[2.5rem] border border-white/5 space-y-6">
                    <div className="flex justify-between items-center">
                        <select value={fromCur} onChange={e => setFromCur(e.target.value)} className="bg-transparent text-2xl font-black text-white outline-none">
                            {CURRENCIES.map(c => <option key={c.code} value={c.code}>{c.code} {c.symbol}</option>)}
                        </select>
                        <input type="number" value={curAmount} onChange={e => setCurAmount(e.target.value)} className="text-right bg-transparent text-2xl font-black text-[#4DA3FF] outline-none w-1/2" />
                    </div>
                    <div className="h-[1px] bg-white/5" />
                    <div className="flex justify-between items-center">
                        <select value={toCur} onChange={e => setToCur(e.target.value)} className="bg-transparent text-2xl font-black text-white/40 outline-none">
                            {CURRENCIES.map(c => <option key={c.code} value={c.code}>{c.code} {c.symbol}</option>)}
                        </select>
                        <div className="text-right text-3xl font-black text-white">{(parseFloat(curAmount) * 119.5).toFixed(2)}</div>
                    </div>
                </div>

                <div className="grid grid-cols-2 gap-4">
                    {CURRENCIES.slice(0, 4).map(c => (
                        <div key={c.code} className="p-6 bg-white/[0.02] border border-white/5 rounded-3xl flex flex-col gap-1">
                            <span className="text-[10px] font-bold text-white/30 uppercase">{c.name}</span>
                            <div className="flex justify-between items-center">
                                <span className="text-lg font-black text-white">{c.code}</span>
                                <span className="text-xs text-[#4DA3FF]">1.00</span>
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        </div>
    );

    const renderHistory = () => (
        <div className="flex-1 flex flex-col p-8 space-y-6 animate-fade-in">
            <header className="flex justify-between items-center">
                <h2 className="text-3xl font-black italic tracking-tighter uppercase">History Log</h2>
                <button onClick={() => setHistory([])} className="text-rose-500/40 hover:text-rose-500 transition-colors"><TrashIcon className="w-5 h-5" /></button>
            </header>

            <div className="flex-1 premium-scroll space-y-4">
                {history.map((h, i) => (
                    <motion.div initial={{ opacity: 0, x: -10 }} animate={{ opacity: 1, x: 0 }} transition={{ delay: i * 0.05 }} key={i} className="p-6 bg-white/[0.03] border border-white/5 rounded-[2rem] flex justify-between items-center group hover:bg-white/[0.05] transition-all">
                        <div className="text-left">
                            <p className="text-[10px] text-white/30 font-bold uppercase mb-1">{h.date}</p>
                            <h4 className="text-sm font-medium text-white/60 truncate">{h.expression}</h4>
                        </div>
                        <div className="text-right">
                             <span className="text-xl font-black text-[#4DA3FF] font-mono">{h.res}</span>
                        </div>
                    </motion.div>
                ))}
                {history.length === 0 && (
                    <div className="p-20 text-center opacity-20 italic text-sm">No recorded sequences found in current session.</div>
                )}
            </div>
        </div>
    );

    return (
        <div className="fixed inset-0 z-[250] bg-[#0E0E11] text-white flex flex-col font-sans overflow-hidden">
            <div className="absolute top-[-10%] left-[-10%] w-[50%] h-[50%] bg-[#4DA3FF]/5 blur-[120px] pointer-events-none rounded-full" />
            <div className="absolute bottom-[-10%] right-[-10%] w-[50%] h-[50%] bg-[#8B5CF6]/5 blur-[120px] pointer-events-none rounded-full" />

            <header className="p-8 pb-4 flex items-center justify-between relative z-10">
                <button onClick={onClose} className="p-3 bg-white/5 rounded-2xl border border-white/5 active:scale-90 transition-transform">
                    <ArrowLeftIcon className="w-6 h-6" />
                </button>
                <div className="flex flex-col items-center">
                    <div className="flex items-center gap-2">
                        <SifraLogo size="sm" showText={false} />
                        <h2 className="text-sm font-black tracking-[0.2em] uppercase italic">Calculator</h2>
                    </div>
                </div>
                <div className="w-12" />
            </header>

            <main className="flex-1 flex flex-col relative z-10">
                <AnimatePresence mode="wait">
                    {activeTab === 'calculator' && <div key="calc" className="h-full flex flex-col">{renderCalculator()}</div>}
                    {activeTab === 'ai' && <div key="ai" className="h-full flex flex-col">{renderAiTab()}</div>}
                    {activeTab === 'currency' && <div key="cur" className="h-full flex flex-col">{renderCurrency()}</div>}
                    {activeTab === 'history' && <div key="hist" className="h-full flex flex-col">{renderHistory()}</div>}
                </AnimatePresence>
            </main>

            <div className="h-28 flex items-center justify-center relative z-20 pb-10 px-8">
                <div className="w-full bg-white/5 backdrop-blur-3xl border border-white/10 rounded-[2.5rem] flex items-center justify-between p-1.5 shadow-[0_20px_50px_rgba(0,0,0,0.5)]">
                    {[
                        { id: 'calculator', icon: <CalculatorIcon /> },
                        { id: 'ai', icon: <SparklesIcon /> },
                        { id: 'currency', icon: <GlobeAltIcon /> },
                        { id: 'history', icon: <ClockIcon /> }
                    ].map(tab => (
                        <button 
                            key={tab.id}
