                ))}
                {history.length === 0 && (
                    <div className="flex-1 flex flex-col items-center justify-center opacity-20 py-20">
                         <ClockIcon className="w-10 h-10 mb-2" />
                         <p className="italic text-xs uppercase tracking-widest font-black">Empty Matrix</p>
                    </div>
                )}
            </div>
        </div>
    );

    return (
        <div className="fixed inset-0 z-[250] bg-[#0E0E11] text-white flex flex-col font-sans overflow-hidden">
            {/* Ambient Animated Auras */}
            <div className="absolute top-[-5%] left-[-5%] w-[40%] h-[40%] bg-[#4DA3FF]/5 blur-[100px] pointer-events-none rounded-full animate-pulse" />
            <div className="absolute bottom-[-5%] right-[-5%] w-[40%] h-[40%] bg-[#8B5CF6]/5 blur-[100px] pointer-events-none rounded-full animate-pulse" />

            {/* Header: Compact and clean */}
            <header className="p-6 pb-2 flex items-center justify-between relative z-10">
                <button onClick={onClose} className="p-3 bg-white/5 rounded-2xl border border-white/5 active:scale-90 transition-transform">
                    <ArrowLeftIcon className="w-6 h-6" />
                </button>
                <div className="flex flex-col items-center">
                    <div className="flex items-center gap-2">
                        <SifraLogo size="sm" showText={false} />
                        <h2 className="text-xs font-black tracking-[0.2em] uppercase italic">Calculator</h2>
                    </div>
                </div>
                <div className="w-12" />
            </header>

            {/* Main Content: Flexible and Non-scrolling */}
            <main className="flex-1 relative z-10 overflow-hidden">
                <AnimatePresence mode="wait">
                    {activeTab === 'calculator' && <div key="calc" className="h-full">{renderCalculator()}</div>}
                    {activeTab === 'ai' && <div key="ai" className="h-full">{renderAiTab()}</div>}
                    {activeTab === 'currency' && <div key="cur" className="h-full">{renderCurrency()}</div>}
                    {activeTab === 'history' && <div key="hist" className="h-full">{renderHistory()}</div>}
