                <div className="w-full max-w-sm bg-white/5 backdrop-blur-3xl border border-white/10 rounded-[2.2rem] flex items-center justify-between p-1.5 shadow-2xl">
                    {[
                        { id: 'calculator', icon: <CalculatorIcon /> },
