                             <p className="text-xs font-bold uppercase tracking-[0.2em] mt-2">Calibration Required.</p>
                        </div>
                    )}
                </AnimatePresence>
            </div>

            <div className="h-28 flex items-center justify-center relative z-20 pb-8 px-6">
                <div className="bg-white/5 backdrop-blur-3xl border border-white/10 rounded-full flex items-center gap-1 p-1.5 shadow-[0_20px_50px_rgba(0,0,0,0.5)]">
                    <button 
                        onClick={() => setActiveTab('world')}
                        className={`w-12 h-12 rounded-full flex items-center justify-center transition-all ${activeTab === 'world' ? 'bg-white text-black' : 'text-white/40'}`}
                    >
                        <GlobeAltIcon className="w-5 h-5" />
                    </button>
                    <button 
                        onClick={() => setActiveTab('alarm')}
                        className={`w-12 h-12 rounded-full flex items-center justify-center transition-all ${activeTab === 'alarm' ? 'bg-white text-black' : 'text-white/40'}`}
                    >
                        <BellIcon className="w-5 h-5" />
                    </button>
                    <button 
                        onClick={() => setActiveTab('clock')}
                        className={`w-12 h-12 rounded-full flex items-center justify-center transition-all ${activeTab === 'clock' ? 'bg-white text-black shadow-lg shadow-white/10' : 'text-white/40'}`}
                    >
                        <ClockIcon className="w-5 h-5" />
                    </button>
                    <button 
                        onClick={() => setActiveTab('stopwatch')}
                        className={`w-12 h-12 rounded-full flex items-center justify-center transition-all ${activeTab === 'stopwatch' ? 'bg-white text-black' : 'text-white/40'}`}
                    >
                        <StopIcon className="w-5 h-5 fill-current" />
                    </button>
                    <button 
                        onClick={() => setActiveTab('timer')}
                        className={`w-12 h-12 rounded-full flex items-center justify-center transition-all ${activeTab === 'timer' ? 'bg-white text-black' : 'text-white/40'}`}
                    >
                        <SparklesIcon className="w-5 h-5" />
                    </button>
                </div>
            </div>

            <div className="fixed bottom-6 left-6">
                <button onClick={onClose} className="p-4 bg-white/5 border border-white/10 rounded-3xl text-white/60 hover:text-white transition-all active:scale-90">
                    <ArrowLeftIcon className="w-6 h-6" />
                </button>
            </div>
        </div>
    );
};

