                            </div>
                            <button 
                                onClick={() => setConfig({...config, intruderSelfie: !config.intruderSelfie})}
                                className={`w-12 h-6 rounded-full transition-all relative ${config.intruderSelfie ? 'bg-cyan-500' : 'bg-white/10'}`}
                            >
                                <div className={`absolute top-1 w-4 h-4 rounded-full bg-white transition-all ${config.intruderSelfie ? 'right-1' : 'left-1'}`} />
                            </button>
                        </div>

                        {['Change PIN', 'Auto-Lock Timeout', 'Fake Vault Mode', 'Encrypted Backup'].map(s => (
                            <button 
                                key={s} 
                                onClick={() => { setPinInput(''); setSubSetting(s); }}
                                className="w-full p-6 rounded-3xl bg-white/5 border border-white/5 flex items-center justify-between text-left hover:bg-white/10 transition-all"
                            >
                                <span className="text-sm font-bold text-gray-300">{s}</span>
                                <ChevronRightIcon className="w-4 h-4 text-gray-600" />
                            </button>
                        ))}

                        <div className="pt-8">
                             <button 
                                onClick={() => { if(confirm("Purge all vault data and reset Master PIN?")) setConfig({ ...config, pin: '' }); setView('setup'); }}
                                className="w-full p-6 rounded-3xl bg-rose-500/5 border border-rose-500/10 flex items-center justify-center gap-3 text-rose-500 font-black uppercase tracking-widest active:bg-rose-500/20 transition-all"
                            >
                                <TrashIcon className="w-5 h-5" /> Full Security Reset
                            </button>
                        </div>
                    </>
                )}
            </div>
        </motion.div>
    );

    return (
        <div className="fixed inset-0 z-[250] bg-[#0B0B0F] text-white flex flex-col font-sans overflow-hidden">
            <AnimatePresence mode="wait">
                {view === 'splash' && renderSplash()}
                {view === 'setup' && renderSetup()}
                {view === 'locked' && renderLock()}
                {view === 'dashboard' && renderDashboard()}
                {view === 'category' && renderCategoryView()}
                {view === 'settings' && renderSettings()}
            </AnimatePresence>

            <footer className="p-2 flex justify-center opacity-5 pointer-events-none absolute bottom-0 w-full">
                <p className="text-[6px] font-black uppercase tracking-[1.2em]">SIFRA VAULT PROTOCOL v2.0</p>
            </footer>
        </div>
    );
};

