                                    </div>
                                );
                        }
                    })()}
                </motion.div>
            </AnimatePresence>
        );
    };

    if (appFlow === AppFlow.SPLASH) return <SplashView onComplete={handleSplashComplete} />;
    if (appFlow === AppFlow.LOGIN) return <LoginView onLoginSuccess={handleLoginSuccess} />;

    return (
        <main className={`w-screen h-screen font-sans bg-gradient-to-br ${theme.gradient} flex flex-col overflow-hidden relative selection:bg-pink-500/20`}>
             <AnimatePresence>
                {isQueenLockdown && <SifraQueenAnimation onComplete={() => setIsQueenLockdown(false)} />}
             </AnimatePresence>
             <motion.div animate={{ opacity: isQueenLockdown ? 0 : 1 }} className="flex-1 flex flex-col h-full overflow-hidden gpu-layer">
                {/* Main app header only shown on non-fullscreen views */}
                {!isFullScreenActive && (
                    <Header 
                        userName={currentUser!.nickname || currentUser!.name} 
                        onProfileClick={() => handleNavigation(View.PROFILE)} 
                        onMenuClick={() => setIsSidebarOpen(true)} 
                        onLogoClick={() => setIsQueenLockdown(true)} 
                        theme={theme} 
                        moodAmbienceEnabled={currentUser!.moodAmbienceEnabled} 
                        currentMood={currentMood} 
                    />
                )}
                <Sidebar isOpen={isSidebarOpen} onClose={() => setIsSidebarOpen(false)} onNavigate={(v) => { handleNavigation(v); setIsSidebarOpen(false); }} onLogout={handleLogout} onNewChat={() => { setChatHistory([]); setIsSidebarOpen(false); }} userProfile={currentUser!} />
                <div className="flex-1 overflow-hidden relative h-full">
                    {renderMainView()}
                </div>
             </motion.div>
        </main>
    );
};

