interface Track {
    id: string;
    title: string;
    artist: string;
    duration: string;
    url: string;
    cover: string;
}

const CATEGORIES = ['All', 'Liked Songs', 'Playlists', 'Downloads'];

const SifraMusicView: React.FC<{ userProfile: UserProfile; onClose: () => void }> = ({ userProfile, onClose }) => {
    const [view, setView] = useState<'library' | 'player'>('library');
    const [activeCategory, setActiveCategory] = useState('All');
    const [tracks, setTracks] = useState<Track[]>([]);
    const [currentTrackIndex, setCurrentTrackIndex] = useState<number | null>(null);
    const [isPlaying, setIsPlaying] = useState(false);
    const [progress, setProgress] = useState(0);
    const [isSyncing, setIsSyncing] = useState(false);

    const audioRef = useRef<HTMLAudioElement | null>(null);
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const analyserRef = useRef<AnalyserNode | null>(null);
    const animationFrameRef = useRef<number>();

    // Initial setup for audio visualizer
    useEffect(() => {
        if (!audioRef.current) {
            audioRef.current = new Audio();
        }
        return () => {
            audioRef.current?.pause();
            if (animationFrameRef.current) cancelAnimationFrame(animationFrameRef.current);
        };
    }, []);

    useEffect(() => {
        if (isPlaying && currentTrackIndex !== null) {
            const updateProgress = () => {
                if (audioRef.current) {
                    setProgress((audioRef.current.currentTime / audioRef.current.duration) * 100);
                    animationFrameRef.current = requestAnimationFrame(updateProgress);
                }
            };
            updateProgress();
        } else {
            if (animationFrameRef.current) cancelAnimationFrame(animationFrameRef.current);
        }
    }, [isPlaying, currentTrackIndex]);

    const handleSync = async () => {
        setIsSyncing(true);
        try {
            // Web implementation using File Picker to simulate device access
            const input = document.createElement('input');
            input.type = 'file';
            input.accept = 'audio/*';
            input.multiple = true;
            input.onchange = (e: any) => {
                const files = e.target.files;
                const newTracks: Track[] = Array.from(files).map((file: any, i) => ({
                    id: `local-${Date.now()}-${i}`,
                    title: file.name.split('.')[0],
                    artist: 'Local Device',
                    duration: '0:00', // Actual duration metadata requires heavy parsing on web
                    url: URL.createObjectURL(file),
                    cover: `https://picsum.photos/seed/track-${i}/400`
                }));
                setTracks(prev => [...prev, ...newTracks]);
                setIsSyncing(false);
            };
            input.click();
        } catch (err) {
            alert('Failed to establish device link.');
            setIsSyncing(false);
        }
    };

    const playTrack = (index: number) => {
        setCurrentTrackIndex(index);
        const track = tracks[index];
        if (audioRef.current) {
            audioRef.current.src = track.url;
            audioRef.current.play();
            setIsPlaying(true);
        }
    };

    const togglePlay = () => {
        if (!audioRef.current) return;
        if (isPlaying) audioRef.current.pause();
        else audioRef.current.play();
        setIsPlaying(!isPlaying);
    };

    const currentTrack = currentTrackIndex !== null ? tracks[currentTrackIndex] : null;

    const renderLibrary = () => (
        <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex-1 flex flex-col p-6 space-y-8 overflow-hidden h-full">
            <header className="flex justify-between items-center">
                <div className="flex items-center gap-4">
                    <img src={userProfile.avatar || 'https://picsum.photos/seed/alex/100'} className="w-10 h-10 rounded-full border border-white/20" alt="" />
                    <h1 className="text-xl font-bold text-white tracking-tight">Hello, {userProfile.name?.split(' ')[0] || 'Explorer'}</h1>
                </div>
                <div className="flex gap-2">
                    <button className="p-2 bg-white/5 rounded-full"><SearchIcon className="w-5 h-5 text-white/60" /></button>
                    <button className="p-2 bg-white/5 rounded-full"><BellIcon className="w-5 h-5 text-white/60" /></button>
                </div>
            </header>

            <div className="flex gap-3 overflow-x-auto premium-scroll pb-2">
                {CATEGORIES.map(cat => (
                    <button 
                        key={cat} 
                        onClick={() => setActiveCategory(cat)}
                        className={`px-5 py-2.5 rounded-full text-[10px] font-black uppercase tracking-widest whitespace-nowrap transition-all ${activeCategory === cat ? 'bg-[#B45CFF] text-white' : 'bg-white/5 text-white/40'}`}
                    >
                        {cat}
                    </button>
                ))}
            </div>

            <section className="space-y-6">
                <h2 className="text-sm font-black uppercase tracking-[0.2em] text-white/40">For You</h2>
                <div className="relative w-full h-40 rounded-[2.5rem] overflow-hidden bg-gradient-to-br from-indigo-900 to-purple-800 p-8 flex items-center justify-between group">
                    <div className="relative z-10 space-y-2">
                        <h3 className="text-2xl font-black italic tracking-tighter leading-tight">Feel the <br/> Beat</h3>
                        <p className="text-[10px] text-white/60 font-bold max-w-[150px]">Explore trending tracks and hidden gems.</p>
                        <button className="px-5 py-2 bg-white/10 rounded-full text-[9px] font-black uppercase tracking-widest backdrop-blur-md">Start Listening</button>
                    </div>
                    <img src="https://picsum.photos/seed/music-hero/300" className="absolute top-0 right-0 w-1/2 h-full object-cover opacity-60 group-hover:scale-105 transition-transform duration-1000" alt="" />
                    <div className="absolute inset-0 bg-gradient-to-r from-purple-900 via-transparent to-transparent" />
                </div>
            </section>

            <section className="flex-1 flex flex-col space-y-6 overflow-hidden">
                <div className="flex justify-between items-center">
                    <h2 className="text-sm font-black uppercase tracking-[0.2em] text-white/40">Your Library</h2>
                    <button onClick={handleSync} disabled={isSyncing} className="flex items-center gap-2 text-[9px] font-black text-[#B45CFF] uppercase tracking-widest">
                        {isSyncing ? 'Syncing...' : 'Sync Device'} <BoltIcon className="w-3 h-3" />
                    </button>
                </div>
                <div className="flex-1 overflow-y-auto premium-scroll space-y-4 pb-20">
                    {tracks.length > 0 ? tracks.map((track, i) => (
                        <button 
                            key={track.id} 
                            onClick={() => { playTrack(i); setView('player'); }}
                            className="w-full flex items-center justify-between p-4 rounded-3xl bg-white/[0.03] border border-white/5 group hover:bg-white/5 transition-all"
                        >
                            <div className="flex items-center gap-4">
                                <img src={track.cover} className="w-12 h-12 rounded-2xl object-cover shadow-lg" alt="" />
                                <div className="text-left">
                                    <h4 className="text-sm font-bold text-white group-hover:text-[#B45CFF] transition-colors">{track.title}</h4>
                                    <p className="text-[10px] text-white/40 font-medium">{track.artist}</p>
                                </div>
                            </div>
                            <span className="text-[10px] font-mono text-white/20">{track.duration}</span>
                            <div className="w-10 h-10 rounded-full bg-white/5 flex items-center justify-center text-white/60">
                                <PlayIcon className="w-4 h-4 fill-current" />
                            </div>
                        </button>
                    )) : (
                        <div className="flex-1 flex flex-col items-center justify-center py-10 opacity-20 text-center space-y-4">
                            <MusicalNoteIcon className="w-16 h-16" />
                            <p className="text-sm font-black uppercase tracking-widest">Library Empty</p>
                            <p className="text-xs max-w-xs font-medium">Link your device node to sync your local audio frequency.</p>
                        </div>
                    )}
                </div>
            </section>
        </motion.div>
    );

    const renderPlayer = () => (
        <motion.div 
            initial={{ y: 100, opacity: 0 }} animate={{ y: 0, opacity: 1 }} 
            className="fixed inset-0 z-[300] flex flex-col bg-black text-white p-8"
        >
            <div className="absolute inset-0 bg-gradient-to-b from-purple-900/20 via-black to-black pointer-events-none" />

            <header className="flex justify-between items-center relative z-10 mb-12">
                <button onClick={() => setView('library')} className="p-3 bg-white/5 rounded-2xl"><ChevronDownIcon className="w-6 h-6" /></button>
                <div className="text-center">
                    <p className="text-[10px] font-black uppercase tracking-[0.4em] text-white/40">Now Playing</p>
                </div>
                <button className="p-3 bg-white/5 rounded-2xl"><GlobeAltIcon className="w-6 h-6 text-white/60" /></button>
            </header>

            <div className="flex-1 flex flex-col items-center justify-center space-y-12 relative z-10">
                {/* Reference Photo 1 Aesthetic - Glowing Circular Art */}
                <div className="relative w-72 h-72 group">
                    <motion.div 
                        animate={isPlaying ? { rotate: 360 } : {}}
                        transition={{ duration: 20, repeat: Infinity, ease: "linear" }}
                        className="absolute inset-0 rounded-full border-4 border-[#B45CFF]/20 shadow-[0_0_60px_rgba(180,92,255,0.2)]"
                    />
                    <div className="absolute inset-4 rounded-full overflow-hidden border-2 border-white/10 p-1">
                        <img 
                            src={currentTrack?.cover || 'https://picsum.photos/seed/default/600'} 
                            className="w-full h-full object-cover rounded-full shadow-2xl" 
                            alt="" 
                        />
                    </div>
                    {/* Floating progress marker */}
                    <svg className="absolute inset-0 w-full h-full rotate-[-90deg]">
                        <circle 
                            cx="144" cy="144" r="142" 
                            stroke="#B45CFF" strokeWidth="4" fill="none"
                            strokeDasharray="892"
                            strokeDashoffset={892 - (892 * progress) / 100}
                            className="transition-all duration-300"
                        />
                    </svg>
                </div>

                <div className="text-center space-y-2">
                    <h3 className="text-3xl font-black tracking-tight">{currentTrack?.title || 'Unknown Frequency'}</h3>
                    <p className="text-sm font-bold text-[#B45CFF] uppercase tracking-widest">{currentTrack?.artist || 'Unknown Artist'}</p>
                </div>

                {/* Waveform Visualization Placeholder (Reference Photo 2 Style) */}
                <div className="w-full h-20 flex items-center justify-center gap-1">
                    {[...Array(40)].map((_, i) => (
                        <motion.div 
                            key={i}
                            animate={isPlaying ? { 
                                height: [10, Math.random() * 60 + 10, 10],
                                opacity: [0.3, 0.8, 0.3]
                            } : { height: 4, opacity: 0.1 }}
                            transition={{ duration: 0.5, repeat: Infinity, delay: i * 0.05 }}
                            className="w-[3px] bg-[#B45CFF] rounded-full"
                        />
                    ))}
                </div>
            </div>

            <footer className="relative z-10 pb-12 space-y-10">
                <div className="flex justify-between items-center px-4">
                    <span className="text-[10px] font-mono text-white/40">1:27</span>
                    <span className="text-[10px] font-mono text-white/40">2:59</span>
                </div>

                <div className="flex items-center justify-between px-10">
                    <button className="text-white/40"><GlobeAltIcon className="w-5 h-5 rotate-90" /></button>
                    <div className="flex items-center gap-8">
                        <button className="text-white/60"><BoltIcon className="w-6 h-6 rotate-180" /></button>
                        <button 
                            onClick={togglePlay}
                            className="w-24 h-24 rounded-full bg-white text-black flex items-center justify-center shadow-[0_20px_50px_rgba(255,255,255,0.2)] active:scale-95 transition-all"
                        >
                            {isPlaying ? <PauseIcon className="w-10 h-10 fill-current" /> : <PlayIcon className="w-10 h-10 fill-current ml-2" />}
                        </button>
                        <button className="text-white/60"><BoltIcon className="w-6 h-6" /></button>
                    </div>
                    <button className="text-white/40"><HeartSparkleIcon className="w-5 h-5" /></button>
                </div>
            </footer>
        </motion.div>
    );

    return (
        <div className="fixed inset-0 z-[250] bg-[#0B0B0F] text-white flex flex-col font-sans overflow-hidden">
            {/* AMBIENT GLOW */}
            <div className="absolute top-[-10%] left-[-10%] w-[50%] h-[50%] bg-[#B45CFF]/10 blur-[120px] rounded-full pointer-events-none" />
            <div className="absolute bottom-[-10%] right-[-10%] w-[50%] h-[50%] bg-blue-600/5 blur-[120px] rounded-full pointer-events-none" />

            <div className="relative z-10 flex-1 flex flex-col h-full overflow-hidden">
                {renderLibrary()}
                <AnimatePresence>
                    {view === 'player' && renderPlayer()}
                </AnimatePresence>
            </div>

            {/* FLOATING MINI PLAYER */}
            <AnimatePresence>
                {currentTrack && view === 'library' && (
                    <motion.button 
                        initial={{ y: 100 }} animate={{ y: 0 }} exit={{ y: 100 }}
                        onClick={() => setView('player')}
                        className="fixed bottom-24 left-6 right-6 h-20 bg-white/10 backdrop-blur-3xl border border-white/10 rounded-[2.5rem] flex items-center justify-between px-6 z-[260] shadow-2xl"
                    >
                        <div className="flex items-center gap-4">
                            <div className="relative w-12 h-12 rounded-full overflow-hidden border border-white/20">
                                <img src={currentTrack.cover} className="w-full h-full object-cover" alt="" />
                                {isPlaying && (
                                    <div className="absolute inset-0 flex items-center justify-center bg-black/40">
                                        <div className="flex gap-0.5">
                                            {[1,2,3].map(i => <motion.div key={i} animate={{ height: [2, 10, 2] }} transition={{ duration: 0.5, repeat: Infinity, delay: i*0.1 }} className="w-1 bg-[#B45CFF] rounded-full" />)}
                                        </div>
                                    </div>
                                )}
                            </div>
                            <div className="text-left">
                                <h4 className="text-xs font-bold truncate max-w-[120px]">{currentTrack.title}</h4>
                                <p className="text-[8px] font-black uppercase text-[#B45CFF] tracking-widest">{currentTrack.artist}</p>
                            </div>
                        </div>
                        <button 
                            onClick={(e) => { e.stopPropagation(); togglePlay(); }}
                            className="w-12 h-12 rounded-full bg-white/5 flex items-center justify-center active:scale-90 transition-transform"
                        >
                            {isPlaying ? <PauseIcon className="w-5 h-5 fill-current" /> : <PlayIcon className="w-5 h-5 fill-current ml-1" />}
                        </button>
                    </motion.button>
                )}
            </AnimatePresence>

            <div className="fixed bottom-6 left-6 z-[270]">
                <button onClick={onClose} className="p-4 bg-white/5 border border-white/10 rounded-3xl text-white/60 hover:text-white transition-all active:scale-90 shadow-xl backdrop-blur-xl">
                    <ArrowLeftIcon className="w-6 h-6" />
                </button>
            </div>

            <style>{`
                .premium-scroll::-webkit-scrollbar { display: none; }
                .premium-scroll { -ms-overflow-style: none; scrollbar-width: none; }
            `}</style>
        </div>
    );
};

