import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { UserProfile } from '../types';
import { GoogleGenAI } from '@google/genai';
import ArrowLeftIcon from '../components/icons/ArrowLeftIcon';
import ArrowRightIcon from '../components/icons/ArrowRightIcon';
import XMarkIcon from '../components/icons/XMarkIcon';
import SearchIcon from '../components/icons/SearchIcon';
import GlobeAltIcon from '../components/icons/GlobeAltIcon';
import BoltIcon from '../components/icons/BoltIcon';
import PlusCircleIcon from '../components/icons/PlusCircleIcon';
import EllipsisVerticalIcon from '../components/icons/EllipsisVerticalIcon';
import HomeIcon from '../components/icons/HomeIcon';
import SifraLogo from '../components/SifraLogo';

interface SearchResult {
    title: string;
    uri: string;
    snippet?: string;
}

const SHORTCUTS = [
    { name: 'Google', icon: 'G', url: 'https://www.google.com', color: 'bg-blue-500' },
    { name: 'YouTube', icon: 'Y', url: 'https://www.youtube.com', color: 'bg-red-500' },
    { name: 'Facebook', icon: 'F', url: 'https://www.facebook.com', color: 'bg-blue-600' },
    { name: 'Sifra AI', icon: 'S', url: 'sifra://home', color: 'bg-pink-500' },
    { name: 'Wikipedia', icon: 'W', url: 'https://www.wikipedia.org', color: 'bg-gray-800' },
    { name: 'GitHub', icon: 'G', url: 'https://www.github.com', color: 'bg-slate-900' },
];

const SifraBrowserView: React.FC<{ userProfile: UserProfile; onClose: () => void }> = ({ userProfile, onClose }) => {
    const [query, setQuery] = useState('');
    const [url, setUrl] = useState('');
    const [isSearching, setIsSearching] = useState(false);
    const [results, setResults] = useState<SearchResult[]>([]);
    const [aiSummary, setAiSummary] = useState('');
    const [view, setView] = useState<'home' | 'results' | 'webview'>('home');

    const handleSearch = async (e?: React.FormEvent) => {
        if (e) e.preventDefault();
        if (!query.trim()) return;

        setIsSearching(true);
        setView('results');
        setUrl(query);

        try {
            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
            const response = await ai.models.generateContent({
                model: 'gemini-3-flash-preview',
                contents: query,
                config: {
                    tools: [{ googleSearch: {} }]
                }
            });

            const text = response.text || '';
            setAiSummary(text);

            // Extract grounding metadata if available
            const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
            const mappedResults: SearchResult[] = chunks
                .filter((c: any) => c.web)
                .map((c: any) => ({
                    title: c.web.title || 'Search Result',
                    uri: c.web.uri,
                    snippet: 'Real-time information retrieved via Sifra Neural Link.'
                }));

            setResults(mappedResults);
        } catch (err) {
            console.error("Browser Search Error:", err);
            setAiSummary("Sorry, I couldn't establish a neural link to the web matrix at this moment.");
        } finally {
            setIsSearching(false);
        }
    };

    const handleOpenUrl = (targetUrl: string) => {
        // Since we can't build a real full-featured browser sandbox,
        // we simulate "browsing" by opening in a new tab for real sites
        // or just staying in the UI for internal links.
        if (targetUrl.startsWith('http')) {
            window.open(targetUrl, '_blank');
        } else {
            setQuery(targetUrl);
            handleSearch();
        }
    };

    const renderHome = () => (
        <motion.div 
            initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }}
            className="flex-1 flex flex-col items-center pt-20 px-8 gap-12"
        >
            <div className="flex flex-col items-center gap-4">
                <SifraLogo size="xl" showText={true} />
                <div className="px-3 py-1 bg-blue-500/10 border border-blue-500/20 rounded-full">
                    <span className="text-[10px] font-black text-blue-500 uppercase tracking-widest">Powered by Sifra Matrix</span>
                </div>
            </div>

            <form onSubmit={handleSearch} className="w-full max-w-lg relative group">
                <div className="absolute inset-0 bg-white shadow-xl rounded-full -m-1 opacity-0 group-focus-within:opacity-100 transition-opacity duration-300 border border-gray-100" />
                <div className="relative flex items-center bg-[#F1F3F4] rounded-full px-6 py-4 border border-transparent group-focus-within:bg-white group-focus-within:border-gray-200 shadow-sm transition-all">
                    <SearchIcon className="w-5 h-5 text-gray-400 mr-4" />
                    <input 
                        type="text"
                        value={query}
                        onChange={e => setQuery(e.target.value)}
                        placeholder="Search with Sifra or enter URL"
                        className="flex-1 bg-transparent outline-none text-gray-800 font-medium"
                    />
                    <div className="flex gap-4">
                        <button type="button" className="text-gray-400"><BoltIcon className="w-5 h-5" /></button>
                    </div>
                </div>
            </form>

            <div className="grid grid-cols-4 sm:grid-cols-4 gap-6 w-full max-w-md">
                {SHORTCUTS.map(s => (
                    <button 
                        key={s.name} 
                        onClick={() => handleOpenUrl(s.url)}
                        className="flex flex-col items-center gap-2 group"
                    >
                        <div className={`w-14 h-14 rounded-full flex items-center justify-center text-white text-xl font-black shadow-md group-active:scale-90 transition-transform ${s.color}`}>
                            {s.icon}
                        </div>
                        <span className="text-[10px] font-bold text-gray-500 truncate w-full text-center">{s.name}</span>
                    </button>
                ))}
                <button className="flex flex-col items-center gap-2 group">
                    <div className="w-14 h-14 rounded-full bg-gray-100 flex items-center justify-center text-gray-400 border border-gray-200">
                        <PlusCircleIcon className="w-6 h-6" />
                    </div>
                    <span className="text-[10px] font-bold text-gray-500">Add</span>
                </button>
            </div>
        </motion.div>
    );

    const renderResults = () => (
        <div className="flex-1 flex flex-col bg-white overflow-y-auto premium-scroll">
            <div className="p-6 border-b border-gray-100 space-y-4">
                <div className="flex gap-2 text-xs text-gray-500 font-bold uppercase tracking-widest items-center">
                    <BoltIcon className="w-4 h-4 text-blue-500" />
                    <span>AI-Generated Intelligence Layer</span>
                </div>
                {isSearching ? (
                    <div className="space-y-3 animate-pulse">
                        <div className="h-4 bg-gray-100 rounded w-3/4" />
                        <div className="h-4 bg-gray-100 rounded w-1/2" />
                    </div>
                ) : (
                    <div className="p-5 bg-blue-50/50 border border-blue-100 rounded-3xl text-sm text-gray-800 leading-relaxed shadow-sm">
                        {aiSummary}
                    </div>
                )}
            </div>

            <div className="flex-1 p-6 space-y-8">
                {isSearching ? (
                    [...Array(3)].map((_, i) => (
                        <div key={i} className="space-y-3 animate-pulse">
                            <div className="h-4 bg-gray-100 rounded w-2/3" />
                            <div className="h-3 bg-gray-50 rounded w-full" />
                            <div className="h-3 bg-gray-50 rounded w-1/2" />
                        </div>
                    ))
                ) : (
                    results.map((res, i) => (
                        <div key={i} className="space-y-1 group">
                            <p className="text-[10px] text-gray-500 truncate">{res.uri}</p>
                            <button 
                                onClick={() => handleOpenUrl(res.uri)}
                                className="text-xl font-bold text-blue-600 hover:underline text-left block"
                            >
                                {res.title}
                            </button>
                            <p className="text-sm text-gray-600 line-clamp-2 leading-relaxed">{res.snippet}</p>
                        </div>
                    ))
                )}
            </div>
        </div>
    );

    return (
        <div className="fixed inset-0 z-[250] bg-[#FFFFFF] text-gray-800 flex flex-col font-sans overflow-hidden">
            {/* OMNIBOX / TOOLBAR */}
            <header className="p-4 border-b border-gray-100 bg-[#F8F9FA] flex flex-col gap-3">
                <div className="flex items-center justify-between gap-4">
                    <div className="flex gap-1">
                        <button onClick={onClose} className="p-2 text-gray-400 hover:text-gray-900 active:scale-90"><ArrowLeftIcon className="w-5 h-5" /></button>
                        <button className="p-2 text-gray-200 cursor-not-allowed"><ArrowRightIcon className="w-5 h-5" /></button>
                    </div>

                    <div className="flex-1 relative">
                        <div className={`absolute inset-y-0 left-4 flex items-center ${view === 'home' ? 'text-gray-400' : 'text-blue-500'}`}>
                            {view === 'home' ? <SearchIcon className="w-4 h-4" /> : <GlobeAltIcon className="w-4 h-4" />}
                        </div>
                        <input 
                            type="text"
                            value={url || query}
                            onChange={e => {
                                setQuery(e.target.value);
                                setUrl(e.target.value);
                            }}
                            onKeyDown={e => e.key === 'Enter' && handleSearch()}
                            className="w-full bg-[#E9EBEF] rounded-full py-2.5 pl-11 pr-4 text-sm font-medium outline-none focus:bg-white focus:ring-2 focus:ring-blue-500/20 border border-transparent focus:border-blue-500/50"
                        />
                    </div>

                    <div className="flex items-center gap-1">
                        <button className="relative p-2 text-gray-500">
                            <div className="w-5 h-5 border-2 border-gray-400 rounded-md flex items-center justify-center font-black text-[9px]">1</div>
                        </button>
                        <button className="p-2 text-gray-500"><EllipsisVerticalIcon className="w-5 h-5" /></button>
                    </div>
                </div>
            </header>

            {/* CONTENT AREA */}
            <main className="flex-1 flex flex-col overflow-hidden relative">
                <AnimatePresence mode="wait">
                    {view === 'home' ? renderHome() : renderResults()}
                </AnimatePresence>
            </main>

            {/* BOTTOM NAV BAR */}
            <footer className="p-4 bg-[#F8F9FA] border-t border-gray-200 flex justify-evenly items-center">
                <button onClick={() => setView('home')} className={`p-2 transition-colors ${view === 'home' ? 'text-blue-500' : 'text-gray-400'}`}>
                    <HomeIcon className="w-6 h-6" />
                </button>
                <button className="p-2 text-gray-400">
                    <SearchIcon className="w-6 h-6" />
                </button>
                <button onClick={() => setView('home')} className="p-2 text-gray-400">
                    <PlusCircleIcon className="w-6 h-6" />
                </button>
                <button className="p-2 text-gray-400">
                    <BoltIcon className="w-6 h-6" />
                </button>
                <button onClick={onClose} className="p-2 text-gray-400">
                    <XMarkIcon className="w-6 h-6" />
                </button>
            </footer>

            <style>{`
                .premium-scroll::-webkit-scrollbar { display: none; }
                .premium-scroll { -ms-overflow-style: none; scrollbar-width: none; }
            `}</style>
        </div>
    );
};

