import React, { useState, useMemo, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { UserProfile } from '../types';
import ArrowLeftIcon from '../components/icons/ArrowLeftIcon';
import SearchIcon from '../components/icons/SearchIcon';
import EllipsisVerticalIcon from '../components/icons/EllipsisVerticalIcon';
import FolderIcon from '../components/icons/FolderIcon';
import CameraIcon from '../components/icons/CameraIcon';
import VideoCameraIcon from '../components/icons/VideoCameraIcon';
import SpeakerWaveIcon from '../components/icons/SpeakerWaveIcon';
import DocumentTextIcon from '../components/icons/DocumentTextIcon';
import BoltIcon from '../components/icons/BoltIcon';
import ShieldCheckIcon from '../components/icons/ShieldCheckIcon';
import TrashIcon from '../components/icons/TrashIcon';
import SparklesIcon from '../components/icons/SparklesIcon';
import ShareIcon from '../components/icons/ShareIcon';
import XMarkIcon from '../components/icons/XMarkIcon';
import LockClosedIcon from '../components/icons/LockClosedIcon';
import PlusCircleIcon from '../components/icons/PlusCircleIcon';
import ChevronRightIcon from '../components/icons/ChevronRightIcon';
import PlayIcon from '../components/icons/PlayIcon';
import PauseIcon from '../components/icons/PauseIcon';
import SifraLogo from '../components/SifraLogo';

type FileTab = 'clean' | 'browse' | 'share';
type CategoryId = 'downloads' | 'images' | 'videos' | 'audio' | 'docs' | 'apps';

interface SifraFile {
    id: string;
    name: string;
    size: number;
    type: string;
    url: string;
    date: string;
    category: CategoryId;
}

const SifraFileView: React.FC<{ userProfile: UserProfile; onClose: () => void }> = ({ userProfile, onClose }) => {
    const [activeTab, setActiveTab] = useState<FileTab>('browse');
    const [selectedCategory, setSelectedCategory] = useState<CategoryId | null>(null);
    const [searchQuery, setSearchQuery] = useState('');
    const [isSyncing, setIsSyncing] = useState(false);
    const [files, setFiles] = useState<SifraFile[]>([]);
    const [storageInfo, setStorageInfo] = useState({ used: 0, total: 0, percent: 0 });

    // Feature States
    const [isCleaning, setIsCleaning] = useState(false);
    const [isSharing, setIsSharing] = useState(false);
    const [activeVideo, setActiveVideo] = useState<SifraFile | null>(null);

    // Fetch real device storage estimate
    useEffect(() => {
        if (navigator.storage && navigator.storage.estimate) {
            navigator.storage.estimate().then(estimate => {
                const used = (estimate.usage || 0) / (1024 ** 3);
                const total = (estimate.quota || 128 * (1024 ** 3)) / (1024 ** 3);
                setStorageInfo({
                    used: parseFloat(used.toFixed(2)),
                    total: Math.round(total),
                    percent: Math.round((used / total) * 100)
                });
            });
        }
    }, []);

    const handleSync = () => {
        setIsSyncing(true);
        const input = document.createElement('input');
        input.type = 'file';
        input.multiple = true;
        input.onchange = (e: any) => {
            const selectedFiles = Array.from(e.target.files) as File[];
            const mapped: SifraFile[] = selectedFiles.map(f => {
                let cat: CategoryId = 'docs';
                if (f.type.startsWith('image/')) cat = 'images';
                else if (f.type.startsWith('video/')) cat = 'videos';
                else if (f.type.startsWith('audio/')) cat = 'audio';

                return {
                    id: `file-${Math.random()}`,
                    name: f.name,
                    size: f.size,
                    type: f.type,
                    url: URL.createObjectURL(f),
                    date: new Date(f.lastModified).toLocaleDateString(),
                    category: cat
                };
            });
            setFiles(prev => [...prev, ...mapped]);
            setIsSyncing(false);
        };
        input.click();
    };

    const formatSize = (bytes: number) => {
        if (bytes === 0) return '0 Bytes';
        const k = 1024;
        const sizes = ['Bytes', 'KB', 'MB', 'GB'];
        const i = Math.floor(Math.log(bytes) / Math.log(k));
        return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
    };

    const categories = useMemo(() => {
        const getStats = (id: CategoryId) => {
            const filtered = files.filter(f => f.category === id);
            const size = filtered.reduce((acc, f) => acc + f.size, 0);
            return { count: filtered.length, size: formatSize(size) };
        };

        return [
            { id: 'images', name: 'Images', icon: <CameraIcon />, color: 'text-purple-500', ...getStats('images') },
            { id: 'videos', name: 'Videos', icon: <VideoCameraIcon />, color: 'text-rose-500', ...getStats('videos') },
            { id: 'audio', name: 'Audio', icon: <SpeakerWaveIcon />, color: 'text-orange-500', ...getStats('audio') },
            { id: 'docs', name: 'Documents', icon: <DocumentTextIcon />, color: 'text-indigo-500', ...getStats('docs') },
            { id: 'downloads', name: 'Downloads', icon: <FolderIcon />, color: 'text-blue-500', count: 0, size: '0 KB' },
            { id: 'apps', name: 'Apps', icon: <BoltIcon />, color: 'text-emerald-500', count: 0, size: '0 KB' },
        ];
    }, [files]);

    const renderClean = () => (
        <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex-1 flex flex-col p-6 space-y-6">
            <div className="p-8 rounded-[2.5rem] bg-gradient-to-br from-indigo-600 to-blue-500 text-white shadow-xl relative overflow-hidden">
                <div className="absolute top-0 right-0 w-32 h-32 bg-white/10 blur-3xl rounded-full translate-x-10 -translate-y-10" />
                <div className="relative z-10 flex flex-col items-center gap-4">
                    <motion.div 
                        animate={isCleaning ? { rotate: 360 } : {}}
                        transition={{ duration: 2, repeat: Infinity, ease: "linear" }}
                        className="w-20 h-20 rounded-full bg-white/20 flex items-center justify-center backdrop-blur-xl border border-white/30"
                    >
                        <SparklesIcon className="w-10 h-10 text-white" />
                    </motion.div>
                    <div className="text-center">
                        <h2 className="text-2xl font-black italic tracking-tighter uppercase">Sifra Clean</h2>
                        <p className="text-xs font-bold text-white/60 uppercase tracking-widest mt-1">
                            {isCleaning ? 'Optimizing Matrix...' : 'Freeing Neural Space'}
                        </p>
                    </div>
                    <div className="w-full bg-black/20 h-2 rounded-full overflow-hidden mt-2">
                        <motion.div initial={{ width: 0 }} animate={{ width: `${storageInfo.percent}%` }} className="h-full bg-white" />
                    </div>
                    <p className="text-sm font-bold">{storageInfo.used} GB used of {storageInfo.total} GB</p>
                </div>
            </div>

            <div className="space-y-4">
                <h3 className="text-xs font-black text-gray-400 uppercase tracking-[0.3em] px-2">Intelligence Recommendations</h3>

                <div className="p-6 rounded-[2rem] bg-white border border-gray-100 flex items-center justify-between shadow-sm group">
                    <div className="flex items-center gap-4">
                        <div className="w-12 h-12 rounded-2xl bg-rose-50 flex items-center justify-center text-rose-500">
                            <TrashIcon className="w-6 h-6" />
                        </div>
                        <div>
                            <h4 className="text-sm font-bold text-gray-800">Cache Nodes</h4>
                            <p className="text-xs text-gray-400">Temporary data taking 450 MB</p>
                        </div>
                    </div>
                    <button 
                        onClick={() => { setIsCleaning(true); setTimeout(() => { setIsCleaning(false); alert("Cache purged from neural system."); }, 2000); }}
                        className="px-4 py-2 bg-blue-50 text-blue-600 text-[10px] font-black uppercase rounded-full tracking-widest active:scale-95 transition-transform"
                    >
                        Clean
                    </button>
                </div>

                <div className="p-6 rounded-[2.5rem] bg-indigo-50/50 border border-indigo-100/50 flex flex-col items-center gap-4 text-center">
                    <div className="w-12 h-12 rounded-full bg-white flex items-center justify-center shadow-md">
                        <SifraLogo size="sm" showText={false} />
                    </div>
                    <div>
                        <h4 className="text-sm font-black text-indigo-900 uppercase">AI Recommendation</h4>
                        <p className="text-xs text-indigo-700/60 mt-1">Sifra identified duplicate media nodes in your storage matrix.</p>
                    </div>
                    <button className="w-full py-4 bg-indigo-600 text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-lg shadow-indigo-500/20">Review Duplicates</button>
                </div>
            </div>
        </motion.div>
    );

    const renderBrowse = () => (
        <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex-1 flex flex-col p-6 space-y-8">
            <div className="flex items-center justify-between px-2">
                <h3 className="text-xs font-black text-gray-400 uppercase tracking-[0.3em]">Categories</h3>
                <button onClick={handleSync} className="flex items-center gap-2 text-[10px] font-black text-blue-600 uppercase tracking-widest">
                    {isSyncing ? 'Syncing...' : 'Sync Device'} <BoltIcon className="w-3 h-3" />
                </button>
            </div>

            <div className="grid grid-cols-2 gap-4">
                {categories.map((cat) => (
                    <button 
                        key={cat.id}
                        onClick={() => setSelectedCategory(cat.id as CategoryId)}
                        className="flex items-center gap-4 p-5 rounded-[2rem] bg-white border border-gray-100 shadow-sm active:scale-95 transition-transform text-left group"
                    >
                        <div className={`w-12 h-12 rounded-2xl bg-gray-50 flex items-center justify-center transition-colors group-hover:bg-white group-hover:shadow-md ${cat.color}`}>
                            {React.cloneElement(cat.icon as React.ReactElement, { className: "w-6 h-6" })}
                        </div>
                        <div className="min-w-0">
                            <h4 className="text-sm font-bold text-gray-800 truncate">{cat.name}</h4>
                            <p className="text-[9px] font-black text-gray-400 uppercase tracking-tighter">{cat.count} files • {cat.size}</p>
                        </div>
                    </button>
                ))}
            </div>

            <section className="space-y-4">
                <h3 className="text-xs font-black text-gray-400 uppercase tracking-[0.3em] px-2">Storage Matrix</h3>
                <div className="p-6 rounded-[2.5rem] bg-white border border-gray-100 shadow-sm flex items-center justify-between">
                    <div className="flex items-center gap-5">
                        <div className="w-12 h-12 rounded-2xl bg-blue-50 flex items-center justify-center text-blue-600">
                            <FolderIcon className="w-6 h-6" />
                        </div>
                        <div>
                            <h4 className="text-sm font-bold text-gray-800">Local Memory</h4>
                            <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">{storageInfo.total - storageInfo.used} GB Free</p>
                        </div>
                    </div>
                    <div className="flex flex-col items-end gap-1">
                            <span className="text-[10px] font-black text-gray-800">{storageInfo.percent}%</span>
                            <div className="w-12 h-1 bg-gray-100 rounded-full overflow-hidden">
                            <motion.div initial={{ width: 0 }} animate={{ width: `${storageInfo.percent}%` }} className="h-full bg-blue-500" />
                            </div>
                    </div>
                </div>
            </section>
        </motion.div>
    );

    const renderShare = () => (
        <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex-1 flex flex-col items-center justify-center p-10 text-center gap-8">
            <div className="relative">
                <motion.div 
                    animate={isSharing ? { scale: [1, 2, 1], opacity: [0.2, 0.05, 0.2] } : { scale: [1, 1.5, 1], opacity: [0.1, 0.05, 0.1] }} 
                    transition={{ duration: isSharing ? 1.5 : 4, repeat: Infinity }}
                    className="absolute inset-[-40px] bg-blue-500 rounded-full blur-3xl" 
                />
                <div className="w-40 h-40 rounded-full bg-white shadow-2xl flex items-center justify-center relative border border-gray-100">
                    <ShareIcon className={`w-16 h-16 ${isSharing ? 'text-blue-600' : 'text-blue-500'}`} />
                </div>
            </div>
            <div className="space-y-2">
                <h2 className="text-2xl font-black italic tracking-tighter uppercase text-gray-900">Nearby Share</h2>
                <p className="text-sm text-gray-500 font-medium">
                    {isSharing ? 'Broadcasting Sifra Neural Frequency...' : 'Send files instantly using Sifra\'s encrypted local link.'}
                </p>
            </div>

            <div className="grid grid-cols-2 gap-4 w-full max-w-sm mt-8">
                <button 
                    onClick={() => setIsSharing(true)}
                    className={`flex flex-col items-center gap-4 p-8 rounded-[2.5rem] transition-all shadow-lg active:scale-95 ${isSharing ? 'bg-blue-800' : 'bg-blue-600'} text-white`}
                >
                    <ArrowUpTrayIcon className="w-8 h-8" />
                    <span className="text-[10px] font-black uppercase tracking-widest">{isSharing ? 'Broadcasting' : 'Send'}</span>
                </button>
                <button 
                    onClick={() => setIsSharing(true)}
                    className="flex flex-col items-center gap-4 p-8 rounded-[2.5rem] bg-white border border-gray-100 shadow-sm active:scale-95 transition-all"
                >
                    <ArrowDownTrayIcon className="w-8 h-8 text-blue-500" />
                    <span className="text-[10px] font-black uppercase tracking-widest text-gray-800">Receive</span>
                </button>
            </div>

            {isSharing && (
                <button onClick={() => setIsSharing(false)} className="text-[10px] font-black text-rose-500 uppercase tracking-[0.4em] mt-4">Stop Signal</button>
            )}
        </motion.div>
    );

    const renderFileBrowser = () => {
        const cat = categories.find(c => c.id === selectedCategory);
        const filteredFiles = files.filter(f => f.category === selectedCategory);

        return (
            <motion.div 
                initial={{ x: '100%' }} animate={{ x: 0 }} exit={{ x: '100%' }}
                className="fixed inset-0 z-[280] bg-white flex flex-col"
            >
                <header className="p-6 flex items-center justify-between border-b border-gray-100">
                    <div className="flex items-center gap-4">
                        <button onClick={() => setSelectedCategory(null)} className="p-2 hover:bg-gray-100 rounded-full transition-colors">
                            <ArrowLeftIcon className="w-6 h-6 text-gray-800" />
                        </button>
                        <h2 className="text-xl font-black text-gray-900 italic uppercase tracking-tighter">{cat?.name}</h2>
                    </div>
                    <div className="flex gap-2">
                        <button className="p-2 text-gray-400"><SearchIcon className="w-5 h-5" /></button>
                        <button className="p-2 text-gray-400"><EllipsisVerticalIcon className="w-5 h-5" /></button>
                    </div>
                </header>

                <div className="flex-1 overflow-y-auto premium-scroll p-6 space-y-4">
                    {filteredFiles.length > 0 ? filteredFiles.map((file) => (
                        <button 
                            key={file.id} 
                            onClick={() => { if(file.category === 'videos') setActiveVideo(file); }}
                            className="w-full flex items-center justify-between p-4 rounded-3xl bg-gray-50/50 hover:bg-gray-100 transition-colors group text-left"
                        >
                            <div className="flex items-center gap-4 min-w-0">
                                <div className={`w-12 h-12 rounded-2xl bg-white shadow-sm flex items-center justify-center shrink-0 ${cat?.color}`}>
                                    {file.category === 'images' ? (
                                        <img src={file.url} className="w-full h-full object-cover rounded-2xl" alt="" />
                                    ) : (
                                        React.cloneElement(cat?.icon as React.ReactElement, { className: "w-6 h-6" })
                                    )}
                                </div>
                                <div className="min-w-0">
                                    <h4 className="text-sm font-bold text-gray-800 truncate">{file.name}</h4>
                                    <p className="text-[10px] text-gray-400 font-medium">{file.date} • {formatSize(file.size)}</p>
                                </div>
                            </div>
                            <div className="flex items-center gap-2 shrink-0">
                                {file.category === 'videos' && <PlayIcon className="w-4 h-4 text-blue-500 opacity-0 group-hover:opacity-100 transition-opacity" />}
                                <button className="p-2 text-gray-300 group-hover:text-gray-900 transition-colors"><EllipsisVerticalIcon className="w-4 h-4" /></button>
                            </div>
                        </button>
                    )) : (
                        <div className="flex-1 flex flex-col items-center justify-center py-20 opacity-20 text-center space-y-4">
                            {cat && React.cloneElement(cat.icon as React.ReactElement, { className: "w-16 h-16" })}
                            <p className="text-sm font-black uppercase tracking-widest">No {cat?.name} Nodes</p>
                        </div>
                    )}
                </div>

                <div className="p-8 pb-12 flex justify-center">
                    <button onClick={handleSync} className="flex items-center gap-3 px-8 py-5 bg-slate-900 text-white rounded-3xl font-black uppercase tracking-[0.2em] shadow-2xl active:scale-95 transition-all">
                        <PlusCircleIcon className="w-5 h-5" /> Import Data
                    </button>
                </div>
            </motion.div>
        );
    };

    const renderVideoPlayer = () => (
        <motion.div 
            initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
            className="fixed inset-0 z-[400] bg-black flex flex-col"
        >
            <header className="p-6 flex items-center justify-between relative z-10">
                <button onClick={() => setActiveVideo(null)} className="p-3 bg-white/10 rounded-2xl backdrop-blur-xl text-white"><ArrowLeftIcon /></button>
                <div className="text-center">
                    <p className="text-[10px] font-black text-white/40 uppercase tracking-[0.4em] mb-1">Sifra Media Player</p>
                    <h3 className="text-sm font-bold text-white truncate max-w-[200px]">{activeVideo?.name}</h3>
                </div>
                <div className="w-12" />
            </header>

            <div className="flex-1 flex items-center justify-center bg-black">
                <video 
                    src={activeVideo?.url} 
                    controls 
                    autoPlay 
                    className="w-full max-h-[70vh] shadow-[0_0_100px_rgba(59,130,246,0.3)]"
                />
            </div>

            <footer className="p-10 flex flex-col items-center gap-6">
                <div className="flex items-center gap-4">
                    <SifraLogo size="sm" showText={false} />
                    <span className="text-[10px] font-black text-white/20 uppercase tracking-[1em]">Neural Playback Active</span>
                </div>
            </footer>
        </motion.div>
    );

    return (
        <div className="fixed inset-0 z-[250] bg-[#F8F9FA] text-gray-800 flex flex-col font-sans overflow-hidden">
            <header className="p-6 pb-2 flex flex-col gap-6 bg-white shadow-sm relative z-10">
                <div className="flex items-center justify-between">
                    <div className="flex items-center gap-4">
                        <SifraLogo size="sm" showText={false} />
                        <h1 className="text-2xl font-black italic tracking-tighter uppercase text-gray-900">Sifra File</h1>
                    </div>
                    <button onClick={onClose} className="p-2 bg-gray-100 rounded-full text-gray-400 active:scale-90 transition-transform"><XMarkIcon className="w-5 h-5" /></button>
                </div>

                <div className="relative">
                    <SearchIcon className="absolute left-5 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                    <input 
                        type="text" 
                        value={searchQuery}
                        onChange={e => setSearchQuery(e.target.value)}
                        placeholder="Search your neural storage..."
                        className="w-full bg-gray-100/80 rounded-2xl py-4 pl-12 pr-6 text-sm font-medium outline-none focus:bg-white focus:ring-2 focus:ring-blue-500/20 border border-transparent focus:border-blue-500/20 transition-all shadow-inner"
                    />
                </div>
            </header>

            <main className="flex-1 overflow-y-auto premium-scroll relative">
                <AnimatePresence mode="wait">
                    {activeTab === 'clean' && renderClean()}
                    {activeTab === 'browse' && renderBrowse()}
                    {activeTab === 'share' && renderShare()}
                </AnimatePresence>
            </main>

            <footer className="h-24 bg-white border-t border-gray-100 flex items-center justify-evenly px-6 pb-4 shrink-0">
