interface SifraClockProps {
    styleId: ClockStyleId;
    size?: 'sm' | 'md' | 'lg';
    onClick?: () => void;
}

const SifraClock: React.FC<SifraClockProps> = ({ size = 'md', onClick }) => {
    const [time, setTime] = useState(new Date());

    useEffect(() => {
        const timer = setInterval(() => setTime(new Date()), 1000);
        return () => clearInterval(timer);
    }, []);

    const hours = time.getHours();
    const minutes = time.getMinutes();
    const dayName = time.toLocaleDateString('en-US', { weekday: 'long' });
    const dayNumeric = time.getDate();
    const monthName = time.toLocaleDateString('en-US', { month: 'short' }).toUpperCase();

    const sizeClass = size === 'sm' ? 'w-24 h-24' : size === 'md' ? 'w-32 h-32' : 'w-44 h-44';
    const containerBase = "relative rounded-[2.2rem] overflow-hidden flex items-center justify-center shadow-xl select-none transition-all";

    // ONLY STYLE: MATRIX DIGITAL
    return (
        <div onClick={onClick} className={`${containerBase} ${sizeClass} bg-gradient-to-tr from-[#3b0a6b] via-[#2b6fc2] to-[#60a5fa]`}>
            <div className="flex gap-1 items-center justify-center p-4">
                <div className="flex flex-col items-center">
                    <span className="text-4xl font-black text-white/80 tracking-tighter opacity-30 leading-none">{hours.toString().padStart(2, '0')}</span>
                    <span className="text-4xl font-black text-white tracking-tighter leading-none">{minutes.toString().padStart(2, '0')}</span>
                </div>
                <div className="w-[1px] h-12 bg-white/20 mx-2" />
                <div className="flex flex-col items-start gap-1">
                    <span className="text-[6px] font-black text-blue-200 rotate-[-90deg] origin-left translate-x-2 translate-y-3">{dayName.toUpperCase()}</span>
                    <p className="text-[10px] font-black text-white tracking-tight leading-none mt-2">{dayNumeric}, {monthName}</p>
                </div>
            </div>
            {/* Blinking dot removed per request */}
        </div>
    );
};

