import React, { useState, useEffect, useRef, memo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { UserProfile, AlarmNode, WorldCity } from '../types';
import { useLocalStorage } from '../hooks/useLocalStorage';
import ArrowLeftIcon from '../components/icons/ArrowLeftIcon';
import PlusCircleIcon from '../components/icons/PlusCircleIcon';
import ClockIcon from '../components/icons/ClockIcon';
import GlobeAltIcon from '../components/icons/GlobeAltIcon';
import BellIcon from '../components/icons/BellIcon';
import XMarkIcon from '../components/icons/XMarkIcon';
import SifraClock from '../components/SifraClock';
import BoltIcon from '../components/icons/BoltIcon';
import PlayIcon from '../components/icons/PlayIcon';
import PauseIcon from '../components/icons/PauseIcon';
import StopIcon from '../components/icons/StopIcon';
import SparklesIcon from '../components/icons/SparklesIcon';
import TrashIcon from '../components/icons/TrashIcon';

type ClockTab = 'clock' | 'alarm' | 'world' | 'timer' | 'stopwatch';

const WORLD_CITIES: WorldCity[] = [
    { id: '1', name: 'Tokyo', region: 'Japan', timezone: 'Asia/Tokyo', offset: 'UTC+9' },
    { id: '2', name: 'Sydney', region: 'Australia', timezone: 'Australia/Sydney', offset: 'UTC+11' },
    { id: '3', name: 'Los Angeles', region: 'California, USA', timezone: 'America/Los_Angeles', offset: 'UTC-8' },
    { id: '4', name: 'New York', region: 'New York, USA', timezone: 'America/New_York', offset: 'UTC-5' },
    { id: '5', name: 'London', region: 'United Kingdom', timezone: 'Europe/London', offset: 'UTC+0' },
    { id: '6', name: 'Algiers', region: 'Algeria', timezone: 'Africa/Algiers', offset: 'UTC+1' },
];

const SifraClockView: React.FC<{ userProfile: UserProfile; onClose: () => void }> = ({ userProfile, onClose }) => {
    const [activeTab, setActiveTab] = useState<ClockTab>('clock');
    const [time, setTime] = useState(new Date());
    const [alarms, setAlarms] = useLocalStorage<AlarmNode[]>(`sifra_alarms_${userProfile.userId}`, []);
    const [is24h, setIs24h] = useLocalStorage('sifra_clock_24h', true);

    // Stopwatch State
    const [swTime, setSwTime] = useState(0);
    const [swRunning, setSwRunning] = useState(false);
    const [laps, setLaps] = useState<number[]>([]);
    const swTimerRef = useRef<number | null>(null);
    const swStartTimeRef = useRef<number>(0);

    useEffect(() => {
        const timer = setInterval(() => setTime(new Date()), 1000);
        return () => clearInterval(timer);
    }, []);

    useEffect(() => {
        if (swRunning) {
            swStartTimeRef.current = performance.now() - swTime;
            const step = (now: number) => {
                setSwTime(now - swStartTimeRef.current);
                swTimerRef.current = requestAnimationFrame(step);
            };
            swTimerRef.current = requestAnimationFrame(step);
        } else if (swTimerRef.current) {
            cancelAnimationFrame(swTimerRef.current);
        }
        return () => { if (swTimerRef.current) cancelAnimationFrame(swTimerRef.current); };
    }, [swRunning]);

    const formatStopwatch = (ms: number) => {
        const minutes = Math.floor(ms / 60000);
        const seconds = Math.floor((ms % 60000) / 1000);
        const centiseconds = Math.floor((ms % 1000) / 10);
        return {
            min: minutes.toString().padStart(2, '0'),
            sec: seconds.toString().padStart(2, '0'),
            ms: centiseconds.toString().padStart(2, '0')
        };
    };

    const renderMainClock = () => {
        const h = time.getHours();
        const mm = time.getMinutes().toString().padStart(2, '0');
        const hh = is24h ? h.toString().padStart(2, '0') : ((h % 12) || 12).toString().padStart(2, '0');
        const day = time.toLocaleDateString('en-US', { weekday: 'short' });
        const dateStr = time.toLocaleDateString('en-US', { day: '2-digit', month: 'short' });

        return (
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex-1 flex flex-col p-8 pt-12 gap-8">
                {/* PROMINENT DIGITAL CLOCK AT TOP */}
                <div className="flex justify-center">
                    <SifraClock styleId="matrix-digital" size="lg" />
                </div>

                <div className="h-[1px] bg-white/5 w-full my-4" />

                <div className="space-y-12 flex-1 flex flex-col justify-center px-4">
                    <div className="flex justify-between items-center">
                         <div>
                            <h2 className="text-5xl font-black text-white tracking-tighter leading-none">{hh}:{mm}</h2>
                            <p className="text-blue-400 font-black text-[10px] uppercase tracking-[0.4em] mt-2 italic">Neural Matrix Sync</p>
                         </div>
                         <div className="text-right">
                             <p className="text-lg font-black text-white/80">{day}</p>
                             <p className="text-sm font-bold text-white/40 uppercase tracking-widest">{dateStr}</p>
                         </div>
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                        <button onClick={() => setIs24h(!is24h)} className="p-6 rounded-[2rem] bg-white/5 border border-white/10 flex flex-col gap-2 text-left active:scale-95 transition-all">
                            <span className="text-[9px] font-black text-white/30 uppercase tracking-widest">Time Format</span>
                            <span className="text-sm font-black text-white uppercase">{is24h ? '24 Hours' : '12 Hours'}</span>
                        </button>
                        <button className="p-6 rounded-[2rem] bg-white/5 border border-white/10 flex flex-col gap-2 text-left active:scale-95 transition-all opacity-40">
                            <span className="text-[9px] font-black text-white/30 uppercase tracking-widest">Time Zone</span>
                            <span className="text-sm font-black text-white uppercase italic">Auto</span>
                        </button>
                    </div>
                </div>
            </motion.div>
        );
    };

    const renderStopwatch = () => {
        const { min, sec, ms } = formatStopwatch(swTime);
        return (
            <div className="flex-1 flex flex-col p-8 gap-10 animate-fade-in justify-center">
                <div className="text-center space-y-4">
                    <p className="text-[10px] font-black text-[#FF5FAF] uppercase tracking-[0.5em]">High-Precision Node</p>
                    <div className="flex justify-center items-baseline font-mono text-white/90">
                        <span className="text-[100px] font-black leading-none tracking-tighter">{min}</span>
                        <span className="text-4xl font-bold mx-1 opacity-40">:</span>
                        <span className="text-[100px] font-black leading-none tracking-tighter">{sec}</span>
                        <span className="text-4xl font-bold mx-1 opacity-40">.</span>
                        <span className="text-6xl font-black opacity-60 tracking-tighter">{ms}</span>
                    </div>
                </div>

                <div className="flex justify-center items-center gap-10">
                    <button 
                        onClick={() => swRunning ? setLaps([swTime, ...laps]) : setSwTime(0)}
                        className="w-20 h-20 rounded-full bg-white/5 border border-white/10 flex items-center justify-center text-white/60 active:scale-90 transition-all"
                    >
                        <span className="text-[10px] font-black uppercase">{swRunning ? 'Lap' : 'Reset'}</span>
                    </button>
                    <button 
                        onClick={() => setSwRunning(!swRunning)}
                        className={`w-28 h-28 rounded-full flex items-center justify-center shadow-2xl transition-all active:scale-95 ${swRunning ? 'bg-rose-500 text-white' : 'bg-blue-500 text-white'}`}
                    >
                        {swRunning ? <PauseIcon className="w-10 h-10 fill-current" /> : <PlayIcon className="w-10 h-10 fill-current ml-1" />}
                    </button>
                </div>
            </div>
        );
    };

    return (
        <div className="fixed inset-0 z-[250] bg-black text-white flex flex-col font-sans overflow-hidden">
            <div className="absolute top-[-10%] left-[-10%] w-[50%] h-[50%] bg-blue-600/5 blur-[120px] pointer-events-none rounded-full" />

            <header className="p-6 relative z-10 flex justify-between items-center">
                 <button onClick={onClose} className="p-3 bg-white/5 rounded-2xl border border-white/10"><ArrowLeftIcon className="w-6 h-6" /></button>
                 <span className="text-[10px] font-black tracking-[0.5em] text-white/20 uppercase italic">Sifra Chronos</span>
                 <div className="w-12" />
            </header>

            <main className="flex-1 relative z-10 flex flex-col overflow-hidden">
                <AnimatePresence mode="wait">
                    {activeTab === 'clock' && <div key="clock" className="h-full flex flex-col">{renderMainClock()}</div>}
                    {activeTab === 'stopwatch' && <div key="stopwatch" className="h-full flex flex-col">{renderStopwatch()}</div>}
                    {(activeTab === 'alarm' || activeTab === 'world' || activeTab === 'timer') && (
