import React, { useState, useEffect, useRef, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { UserProfile } from '../types';
import ArrowLeftIcon from '../components/icons/ArrowLeftIcon';
import XMarkIcon from '../components/icons/XMarkIcon';
import CameraIcon from '../components/icons/CameraIcon';
import SparklesIcon from '../components/icons/SparklesIcon';
import BoltIcon from '../components/icons/BoltIcon';
import SifraLogo from '../components/SifraLogo';

type CameraMode = 'PHOTO' | 'VIDEO' | 'PORTRAIT' | 'PRO' | 'DUAL';

const SifraCameraView: React.FC<{ userProfile: UserProfile; onClose: () => void }> = ({ userProfile, onClose }) => {
    const [mode, setMode] = useState<CameraMode>('PHOTO');
    const [isFrontCamera, setIsFrontCamera] = useState(false);
    const [isFlashActive, setIsFlashActive] = useState(false);
    const [isCapturing, setIsCapturing] = useState(false);
    const [lastCapture, setLastCapture] = useState<string | null>(null);
    const [permissionError, setPermissionError] = useState<string | null>(null);
    const [isActivating, setIsActivating] = useState(false);

    const videoRef = useRef<HTMLVideoElement>(null);
    const streamRef = useRef<MediaStream | null>(null);

    const stopStreams = useCallback(() => {
        if (streamRef.current) {
            streamRef.current.getTracks().forEach(t => t.stop());
            streamRef.current = null;
        }
    }, []);

    const startCamera = useCallback(async (isFront: boolean) => {
        stopStreams();
        setPermissionError(null);
        setIsActivating(true);

        try {
            // Lens optimization: Lighter constraints for better mobile compatibility
            const constraints = {
                video: {
                    facingMode: isFront ? 'user' : 'environment',
                },
                audio: mode === 'VIDEO'
            };

            const stream = await navigator.mediaDevices.getUserMedia(constraints);
            streamRef.current = stream;
            if (videoRef.current) {
                videoRef.current.srcObject = stream;
            }
        } catch (err: any) {
            console.error("Lens Initialization Error:", err);
            setPermissionError("Neural link to lens failed. Ensure permissions are granted in browser settings.");
        } finally {
            setIsActivating(false);
        }
    }, [mode, stopStreams]);

    useEffect(() => {
        startCamera(isFrontCamera);
        return () => stopStreams();
    }, [isFrontCamera, mode]);

    const capturePhoto = () => {
        if (!videoRef.current || isCapturing || !!permissionError) return;
        setIsCapturing(true);

        const canvas = document.createElement('canvas');
        canvas.width = videoRef.current.videoWidth;
        canvas.height = videoRef.current.videoHeight;
        const ctx = canvas.getContext('2d');
        if (ctx) {
            if (isFrontCamera) {
                ctx.translate(canvas.width, 0);
                ctx.scale(-1, 1);
            }
            ctx.drawImage(videoRef.current, 0, 0);
            setLastCapture(canvas.toDataURL('image/jpeg'));
        }

        new Audio('https://assets.mixkit.co/sfx/preview/mixkit-camera-shutter-click-1133.mp3').play().catch(() => {});
        setTimeout(() => setIsCapturing(false), 150);
    };

    return (
        <div className="fixed inset-0 z-[250] bg-black text-white flex flex-col font-sans overflow-hidden">
            <AnimatePresence>
                {permissionError && (
                    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="absolute inset-0 z-[100] bg-black/90 backdrop-blur-xl flex flex-col items-center justify-center p-10 text-center">
                        <div className="w-20 h-20 bg-rose-500/20 rounded-full flex items-center justify-center mb-8 border border-rose-500/50">
                            <XMarkIcon className="w-10 h-10 text-rose-500" />
                        </div>
                        <h2 className="text-xl font-black uppercase italic tracking-widest text-rose-400">Signal Blocked</h2>
                        <p className="text-sm text-white/60 mt-4 leading-relaxed max-w-xs">{permissionError}</p>
                        <button onClick={() => startCamera(isFrontCamera)} className="mt-10 px-10 py-5 bg-white text-black rounded-3xl font-black uppercase tracking-widest active:scale-95 transition-all">Retry Link</button>
                        <button onClick={onClose} className="mt-4 text-xs font-bold text-white/30 uppercase tracking-widest">Abort</button>
                    </motion.div>
                )}
            </AnimatePresence>

            <header className="absolute top-0 left-0 w-full p-6 flex items-center justify-between z-30 bg-gradient-to-b from-black/60 to-transparent">
                <button onClick={onClose} className="p-2 bg-white/10 rounded-full backdrop-blur-md border border-white/5"><XMarkIcon className="w-5 h-5" /></button>
                <div className="flex items-center gap-4 bg-white/10 backdrop-blur-md px-4 py-2 rounded-full border border-white/5">
                    <button onClick={() => setIsFlashActive(!isFlashActive)} className={`p-1 transition-all ${isFlashActive ? 'text-yellow-400' : 'text-white/40'}`}><BoltIcon className="w-4 h-4" /></button>
                    <div className="h-4 w-[1px] bg-white/10 mx-2" />
                    <span className="text-[9px] font-black uppercase tracking-widest text-white/80">{mode} MODE</span>
                </div>
                <button onClick={() => setIsFrontCamera(!isFrontCamera)} className="p-2 bg-white/10 rounded-full backdrop-blur-md border border-white/5">
                    <svg className="w-5 h-5 text-white/80" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" /></svg>
                </button>
            </header>

            <main className="flex-1 relative bg-[#050505] overflow-hidden">
                <video ref={videoRef} autoPlay playsInline className={`w-full h-full object-cover transition-all duration-700 ${isFrontCamera ? 'scale-x-[-1]' : ''} ${isCapturing ? 'brightness-150 scale-105' : 'brightness-100'}`} />
                {isActivating && <div className="absolute inset-0 flex items-center justify-center bg-black/40 backdrop-blur-sm"><div className="w-10 h-10 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin" /></div>}
            </main>

            <footer className="h-60 bg-black flex flex-col items-center justify-between pb-12 shrink-0 border-t border-white/5">
                <div className="w-full flex justify-center pt-6 pb-2 overflow-x-auto no-scrollbar">
                    <div className="flex gap-8 px-20">
                        {(['PHOTO', 'VIDEO', 'PORTRAIT', 'DUAL', 'PRO'] as CameraMode[]).map(m => (
                            <button key={m} onClick={() => setMode(m)} className={`text-[11px] font-black uppercase tracking-[0.2em] transition-all whitespace-nowrap ${mode === m ? 'text-indigo-400 scale-110' : 'text-white/30'}`}>{m}</button>
                        ))}
                    </div>
                </div>
                <div className="w-full flex items-center justify-between max-w-sm px-8">
                    <button className="w-14 h-14 rounded-2xl bg-white/5 border border-white/10 overflow-hidden">{lastCapture ? <img src={lastCapture} className="w-full h-full object-cover" /> : <div className="w-full h-full flex items-center justify-center opacity-20"><CameraIcon className="w-6 h-6" /></div>}</button>
                    <motion.button whileTap={{ scale: 0.9 }} onClick={capturePhoto} className="w-22 h-22 rounded-full border-[6px] border-white/20 flex items-center justify-center transition-all"><div className="w-16 h-16 rounded-full bg-white" /></motion.button>
                    <button className="w-14 h-14 rounded-2xl bg-indigo-500/10 border border-indigo-500/20 flex items-center justify-center text-indigo-400"><SparklesIcon className="w-6 h-6" /></button>
                </div>
            </footer>
        </div>
    );
};

