interface Track {
    id: string;
    title: string;
    artist: string;
    duration: string;
    url: string;
    cover: string;
}

const SifraMusicView: React.FC<{ userProfile: UserProfile; onClose: () => void }> = ({ userProfile, onClose }) => {
    const [view, setView] = useState<'library' | 'player'>('library');
    const [tracks, setTracks] = useState<Track[]>([]);
    const [currentTrackIndex, setCurrentTrackIndex] = useState<number | null>(null);
    const [isPlaying, setIsPlaying] = useState(false);
    const [progress, setProgress] = useState(0);
    const [currentTimeStr, setCurrentTimeStr] = useState('0:00');
    const [durationStr, setDurationStr] = useState('0:00');

    const audioRef = useRef<HTMLAudioElement | null>(null);

    useEffect(() => {
        if (!audioRef.current) audioRef.current = new Audio();
        const audio = audioRef.current;

        const updateProgress = () => {
            const current = audio.currentTime;
            const duration = audio.duration || 0;
            if (duration > 0) {
                setProgress((current / duration) * 100);
                setCurrentTimeStr(formatTime(current));
                setDurationStr(formatTime(duration));
            }
        };

        audio.addEventListener('timeupdate', updateProgress);
        return () => {
            audio.pause();
            audio.removeEventListener('timeupdate', updateProgress);
        };
    }, []);

    const formatTime = (s: number) => {
        const min = Math.floor(s / 60);
        const sec = Math.floor(s % 60);
        return `${min}:${sec.toString().padStart(2, '0')}`;
    };

    const handleSync = async () => {
        const input = document.createElement('input');
        input.type = 'file';
        input.accept = 'audio/*';
        input.multiple = true;
        input.onchange = (e: any) => {
            const files = Array.from(e.target.files) as File[];
            setTracks(files.map((f, i) => ({
                id: `local-${i}`,
                title: f.name.split('.')[0],
                artist: 'Local Device',
                duration: '...',
                url: URL.createObjectURL(f),
                cover: `https://picsum.photos/seed/track-${i}/400`
            })));
        };
        input.click();
    };

    const skip = (seconds: number) => {
        if (audioRef.current) audioRef.current.currentTime += seconds;
    };

    const handleSeek = (e: React.ChangeEvent<HTMLInputElement>) => {
        const seekTo = (parseFloat(e.target.value) / 100) * (audioRef.current?.duration || 0);
        if (audioRef.current) audioRef.current.currentTime = seekTo;
    };

    const currentTrack = currentTrackIndex !== null ? tracks[currentTrackIndex] : null;

    const renderPlayer = () => (
        <motion.div initial={{ y: 100, opacity: 0 }} animate={{ y: 0, opacity: 1 }} className="fixed inset-0 z-[300] flex flex-col bg-black text-white p-8">
            <header className="flex justify-between items-center mb-12">
                <button onClick={() => setView('library')} className="p-3 bg-white/5 rounded-2xl"><ChevronDownIcon className="w-6 h-6" /></button>
                <p className="text-[10px] font-black uppercase tracking-[0.4em] text-white/40">Sifra Node Player</p>
                <div className="w-12" />
            </header>

            <div className="flex-1 flex flex-col items-center justify-center space-y-12">
                <div className="relative w-72 h-72">
                    <motion.div animate={isPlaying ? { rotate: 360 } : {}} transition={{ duration: 20, repeat: Infinity, ease: "linear" }} className="absolute inset-0 rounded-full border-4 border-[#B45CFF]/20 shadow-[0_0_60px_rgba(180,92,255,0.2)]" />
                    <img src={currentTrack?.cover} className="absolute inset-4 rounded-full w-64 h-64 object-cover" />
                </div>
                <div className="text-center">
                    <h3 className="text-3xl font-black tracking-tight">{currentTrack?.title}</h3>
                    <p className="text-sm font-bold text-[#B45CFF] uppercase tracking-widest">{currentTrack?.artist}</p>
                </div>

                {/* SEEKABLE PROGRESS BAR */}
                <div className="w-full space-y-2">
                    <input type="range" min="0" max="100" value={progress} onChange={handleSeek} className="w-full h-1.5 bg-white/10 rounded-full appearance-none accent-[#B45CFF] cursor-pointer" />
                    <div className="flex justify-between text-[10px] font-mono text-white/40">
                        <span>{currentTimeStr}</span>
                        <span>{durationStr}</span>
                    </div>
                </div>
            </div>

            <footer className="pb-12 flex flex-col gap-10">
                <div className="flex items-center justify-center gap-10">
                    <button onClick={() => skip(-15)} className="text-white/40 active:text-white"><svg className="w-8 h-8" fill="currentColor" viewBox="0 0 24 24"><path d="M12.5 5.5V18.5L2 12L12.5 5.5ZM22 5.5V18.5L11.5 12L22 5.5Z"/></svg></button>
                    <button onClick={() => { if(isPlaying) audioRef.current?.pause(); else audioRef.current?.play(); setIsPlaying(!isPlaying); }} className="w-24 h-24 rounded-full bg-white text-black flex items-center justify-center shadow-xl active:scale-95 transition-all">
                        {isPlaying ? <PauseIcon className="w-10 h-10 fill-current" /> : <PlayIcon className="w-10 h-10 fill-current ml-2" />}
                    </button>
                    <button onClick={() => skip(15)} className="text-white/40 active:text-white"><svg className="w-8 h-8" fill="currentColor" viewBox="0 0 24 24"><path d="M11.5 5.5V18.5L22 12L11.5 5.5ZM2 5.5V18.5L12.5 12L2 5.5Z"/></svg></button>
                </div>
            </footer>
        </motion.div>
    );

    return (
        <div className="fixed inset-0 z-[250] bg-[#0B0B0F] text-white flex flex-col font-sans overflow-hidden">
            <div className="flex-1 flex flex-col p-6 space-y-8 overflow-hidden h-full">
                <header className="flex justify-between items-center">
                    <h1 className="text-xl font-bold">Music Library</h1>
                    <button onClick={handleSync} className="text-[10px] font-black text-[#B45CFF] uppercase tracking-widest">Sync Device</button>
                </header>
                <div className="flex-1 overflow-y-auto premium-scroll space-y-4">
                    {tracks.map((t, i) => (
                        <button key={i} onClick={() => { setCurrentTrackIndex(i); audioRef.current!.src = t.url; audioRef.current!.play(); setIsPlaying(true); setView('player'); }} className="w-full flex items-center justify-between p-4 rounded-3xl bg-white/[0.03] border border-white/5">
                            <div className="flex items-center gap-4 text-left">
                                <img src={t.cover} className="w-12 h-12 rounded-xl" />
                                <div><h4 className="text-sm font-bold truncate max-w-[150px]">{t.title}</h4><p className="text-[10px] opacity-40 uppercase tracking-widest">{t.artist}</p></div>
                            </div>
                            <PlayIcon className="w-4 h-4 opacity-40" />
                        </button>
                    ))}
                    {tracks.length === 0 && <div className="text-center py-20 opacity-20 italic">No tracks linked. Tap Sync.</div>}
                </div>
            </div>
            <AnimatePresence>{view === 'player' && renderPlayer()}</AnimatePresence>
            <div className="fixed bottom-6 left-6 z-[310]"><button onClick={onClose} className="p-4 bg-white/5 border border-white/10 rounded-3xl text-white/60"><ArrowLeftIcon className="w-6 h-6" /></button></div>
        </div>
    );
};

