                model: 'gemini-3-flash-preview',
                contents: query,
                config: { tools: [{ googleSearch: {} }] }
            });
            setAiSummary(response.text || '');
            const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
            setResults(chunks.filter((c: any) => c.web).map((c: any) => ({
                title: c.web.title || 'Information Hub',
                uri: c.web.uri,
                snippet: 'Neural link data retrieved successfully.'
