import React, { useState, useMemo, useCallback, useEffect, useRef } from 'react';
import { UserProfile, CalendarNote, EventType, Participant } from '../types';
import { motion, AnimatePresence, LayoutGroup } from 'framer-motion';
import { useLocalStorage } from '../hooks/useLocalStorage';
import { GoogleGenAI, Type } from '@google/genai';
import ArrowLeftIcon from '../components/icons/ArrowLeftIcon';
import ChevronLeftIcon from '../components/icons/ChevronLeftIcon';
import ChevronRightIcon from '../components/icons/ChevronRightIcon';
import SparklesIcon from '../components/icons/SparklesIcon';
import XMarkIcon from '../components/icons/XMarkIcon';
import TrashIcon from '../components/icons/TrashIcon';
import BoltIcon from '../components/icons/BoltIcon';
import PlusCircleIcon from '../components/icons/PlusCircleIcon';
import BellIcon from '../components/icons/BellIcon';
import GlobeAltIcon from '../components/icons/GlobeAltIcon';
import MapPinIcon from '../components/icons/MapPinIcon';
import VideoCameraIcon from '../components/icons/VideoCameraIcon';
import CalendarIcon from '../components/icons/CalendarIcon';
import HomeIcon from '../components/icons/HomeIcon';
import UserIcon from '../components/icons/UserIcon';
import CheckCircleIcon from '../components/icons/CheckCircleIcon';
import MicrophoneIcon from '../components/icons/MicrophoneIcon';
import EllipsisVerticalIcon from '../components/icons/EllipsisVerticalIcon';

const MONTHS = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
const DAYS_SHORT = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];

type CalendarViewMode = 'today' | 'day' | 'week' | 'month' | 'agenda' | 'tasks';

const PRESET_COLORS = [
    { name: 'Indigo', bg: 'bg-indigo-500', shadow: 'shadow-indigo-500/20' },
    { name: 'Rose', bg: 'bg-rose-500', shadow: 'shadow-rose-500/20' },
    { name: 'Emerald', bg: 'bg-emerald-500', shadow: 'shadow-emerald-500/20' },
    { name: 'Amber', bg: 'bg-amber-500', shadow: 'shadow-amber-500/20' },
    { name: 'Sky', bg: 'bg-sky-500', shadow: 'shadow-sky-500/20' },
];

const PersonalCalendarView: React.FC<{ userProfile: UserProfile; onClose: () => void }> = ({ userProfile, onClose }) => {
    const [viewMode, setViewMode] = useState<CalendarViewMode>('today');
    const [currentDate, setCurrentDate] = useState(new Date());
    const [events, setEvents] = useLocalStorage<CalendarNote[]>(`sifra_events_v2_${userProfile.userId}`, []);
    const [showCreate, setShowCreate] = useState(false);
    const [isParsing, setIsParsing] = useState(false);
    const [quickAddText, setQuickAddText] = useState('');

    // Form State
    const [editEvent, setEditEvent] = useState<Partial<CalendarNote> | null>(null);

    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();

    const formatDateStr = (date: Date) => date.toISOString().split('T')[0];
    const todayStr = formatDateStr(new Date());

    const filteredEvents = useMemo(() => {
        return events.sort((a, b) => a.time.localeCompare(b.time));
    }, [events]);

    const handleQuickAdd = async () => {
        if (!quickAddText.trim()) return;
        setIsParsing(true);
        try {
            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
            const response = await ai.models.generateContent({
                model: 'gemini-3-flash-preview',
                contents: `Extract event details from this text: "${quickAddText}". Provide as JSON. Context: Today is ${new Date().toDateString()}.`,
                config: {
                    responseMimeType: 'application/json',
                    responseSchema: {
                        type: Type.OBJECT,
                        properties: {
                            title: { type: Type.STRING },
                            date: { type: Type.STRING, description: "YYYY-MM-DD" },
                            time: { type: Type.STRING, description: "HH:mm" },
                            type: { type: Type.STRING, description: "event, task, or meet" },
                            location: { type: Type.STRING }
                        },
                        required: ['title', 'date', 'time', 'type']
                    }
                }
            });
            const data = JSON.parse(response.text);
            const newEvent: CalendarNote = {
                id: `evt-${Date.now()}`,
                date: data.date,
                time: data.time,
                title: data.title,
                content: '',
                type: data.type as EventType,
                isSpecial: false,
                location: data.location,
                color: PRESET_COLORS[Math.floor(Math.random() * PRESET_COLORS.length)].bg,
                participants: []
            };
            setEvents([...events, newEvent]);
            setQuickAddText('');
            alert('AI synchronized new event to your matrix.');
        } catch (e) {
            alert('Neural sync failed. Please use manual entry.');
        } finally {
            setIsParsing(false);
        }
    };

    const renderEventCard = (evt: CalendarNote) => (
        <motion.div 
            layout
            key={evt.id}
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            className="w-full relative group cursor-pointer"
            onClick={() => setEditEvent(evt)}
        >
            <div className="absolute inset-0 bg-white/5 rounded-[2rem] blur-xl opacity-0 group-hover:opacity-20 transition-opacity" />
            <div className="relative bg-white/[0.03] border border-white/10 backdrop-blur-xl rounded-[2rem] p-6 flex flex-col gap-4 group-hover:bg-white/[0.06] transition-all">
                <div className="flex justify-between items-start">
                    <div className="flex items-center gap-4">
                        <div className={`w-1.5 h-10 rounded-full ${evt.color || 'bg-indigo-500'}`} />
                        <div>
                            <p className="text-[10px] font-black text-white/30 uppercase tracking-[0.3em] mb-0.5">{evt.time} {evt.endTime ? `- ${evt.endTime}` : ''}</p>
                            <h4 className="text-lg font-bold text-white tracking-tight leading-tight">{evt.title}</h4>
                        </div>
                    </div>
                    <div className={`px-3 py-1 rounded-full text-[8px] font-black uppercase tracking-widest ${evt.type === 'meet' ? 'bg-indigo-500/20 text-indigo-400' : evt.type === 'task' ? 'bg-emerald-500/20 text-emerald-400' : 'bg-sky-500/20 text-sky-400'}`}>
                        {evt.type}
                    </div>
                </div>

                {evt.location && (
                    <div className="flex items-center gap-2 text-white/40">
                        <MapPinIcon className="w-3.5 h-3.5" />
                        <span className="text-xs font-medium truncate">{evt.location}</span>
                    </div>
                )}

                {evt.participants && evt.participants.length > 0 && (
                    <div className="flex items-center justify-between mt-2">
                        <div className="flex -space-x-3">
                            {evt.participants.slice(0, 3).map((p, i) => (
                                <div key={i} className="w-8 h-8 rounded-full border-2 border-[#0F1115] bg-slate-800 flex items-center justify-center text-[10px] font-bold overflow-hidden shadow-lg">
                                    {p.avatar ? <img src={p.avatar} className="w-full h-full object-cover" alt=""/> : p.name[0]}
                                </div>
                            ))}
                            {evt.participants.length > 3 && (
                                <div className="w-8 h-8 rounded-full border-2 border-[#0F1115] bg-white/5 flex items-center justify-center text-[8px] font-black text-white/40">
                                    +{evt.participants.length - 3}
                                </div>
                            )}
                        </div>
                        {evt.meetingLink && (
                            <button onClick={(e) => { e.stopPropagation(); window.open(evt.meetingLink, '_blank'); }} className="px-5 py-2.5 bg-indigo-600 rounded-2xl flex items-center gap-2 text-[10px] font-black uppercase tracking-widest shadow-lg shadow-indigo-500/20 active:scale-95 transition-all">
                                <VideoCameraIcon className="w-3.5 h-3.5" /> Join Link
                            </button>
                        )}
                    </div>
                )}
            </div>
        </motion.div>
    );

    const renderToday = () => {
        const todayEvents = filteredEvents.filter(e => e.date === todayStr);
        return (
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex-1 flex flex-col gap-10">
                <section className="relative px-2">
                    <div className="flex items-center justify-between mb-6">
                        <h2 className="text-3xl font-black italic tracking-tighter uppercase leading-none">Focus Today</h2>
                        <div className="flex flex-col items-end">
                            <span className="text-[10px] font-black text-[#ff5f6d] uppercase tracking-[0.3em]">{MONTHS[month]}</span>
                            <span className="text-xs font-bold text-white/20 uppercase tracking-widest">{year}</span>
                        </div>
                    </div>

                    <div className="p-8 rounded-[3rem] bg-gradient-to-br from-indigo-600 to-violet-800 shadow-2xl relative overflow-hidden group">
                        <div className="absolute top-0 right-0 w-32 h-32 bg-white/10 blur-3xl rounded-full translate-x-10 -translate-y-10" />
                        <div className="relative z-10">
                            <p className="text-[10px] font-black text-white/40 uppercase tracking-[0.5em] mb-2">Upcoming Node</p>
                            {todayEvents[0] ? (
                                <>
                                    <h3 className="text-4xl font-black text-white tracking-tighter mb-4 leading-tight">{todayEvents[0].title}</h3>
                                    <div className="flex items-center gap-4">
                                        <div className="px-4 py-2 bg-white/10 rounded-2xl backdrop-blur-md border border-white/10 text-xs font-bold">{todayEvents[0].time}</div>
                                        {todayEvents[0].location && <div className="flex items-center gap-2 text-white/60 text-xs"><MapPinIcon className="w-4 h-4" /> {todayEvents[0].location}</div>}
                                    </div>
                                </>
                            ) : (
                                <p className="text-xl font-bold text-white/60">No pending neural logs for today.</p>
                            )}
                        </div>
                    </div>
                </section>

                <section className="space-y-6">
                    <div className="flex items-center justify-between px-2">
                        <h3 className="text-[10px] font-black text-white/30 uppercase tracking-[0.4em]">Timeline Nodes</h3>
                        <span className="text-[9px] font-bold text-indigo-400 uppercase tracking-widest">{todayEvents.length} Active</span>
                    </div>
                    <div className="space-y-4">
                        {todayEvents.length > 0 ? todayEvents.map(renderEventCard) : (
                            <div className="py-20 text-center opacity-20 italic">Empty matrix for today.</div>
                        )}
                    </div>
                </section>
            </motion.div>
        );
    };

    const renderMonth = () => {
        const daysInMonth = new Date(year, month + 1, 0).getDate();
        const firstDay = new Date(year, month, 1).getDay();
        const days = Array.from({ length: daysInMonth }, (_, i) => i + 1);

        return (
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex-1 flex flex-col gap-8">
                <div className="grid grid-cols-7 gap-1">
                    {DAYS_SHORT.map(d => (
                        <div key={d} className="text-center text-[9px] font-black text-white/10 uppercase tracking-widest mb-2">{d}</div>
                    ))}
                    {[...Array(firstDay)].map((_, i) => <div key={`empty-${i}`} />)}
                    {days.map(day => {
                        const dStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
                        const dayEvents = events.filter(e => e.date === dStr);
                        const isToday = todayStr === dStr;

                        return (
                            <button 
                                key={day}
                                onClick={() => { setCurrentDate(new Date(year, month, day)); setViewMode('day'); }}
                                className={`aspect-square rounded-3xl flex flex-col items-center justify-center relative transition-all border ${
                                    isToday ? 'bg-indigo-600 border-indigo-500 shadow-[0_0_25px_rgba(99,102,241,0.4)]' : 
                                    dayEvents.length > 0 ? 'bg-white/5 border-white/5' : 'border-transparent hover:bg-white/[0.02]'
                                }`}
                            >
                                <span className={`text-sm font-black ${isToday ? 'text-white' : 'text-white/60'}`}>{day}</span>
                                <div className="flex gap-0.5 mt-1">
                                    {dayEvents.slice(0, 3).map((e, idx) => (
                                        <div key={idx} className={`w-1 h-1 rounded-full ${e.color?.replace('bg-', 'bg-opacity-100 bg-') || 'bg-indigo-400'}`} />
                                    ))}
                                </div>
                            </button>
                        );
                    })}
                </div>
            </motion.div>
        );
    };

    const renderDay = () => {
        const dStr = formatDateStr(currentDate);
        const dayEvents = filteredEvents.filter(e => e.date === dStr);
        const hours = Array.from({ length: 24 }, (_, i) => i);
        const currentHour = new Date().getHours();

        return (
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex-1 flex flex-col h-full overflow-hidden">
                <div className="flex-1 overflow-y-auto premium-scroll relative">
                    {hours.map(h => (
                        <div key={h} className="h-20 border-t border-white/[0.03] flex group">
                            <div className="w-16 flex-none flex justify-center pt-2">
                                <span className={`text-[10px] font-black uppercase tracking-tighter ${h === currentHour ? 'text-indigo-400' : 'text-white/20'}`}>
                                    {h.toString().padStart(2, '0')}:00
                                </span>
                            </div>
                            <div className="flex-1 relative">
                                {dayEvents.filter(e => parseInt(e.time.split(':')[0]) === h).map(evt => (
                                    <div 
                                        key={evt.id} 
                                        onClick={() => setEditEvent(evt)}
                                        className={`absolute top-2 left-2 right-2 p-3 rounded-2xl border border-white/10 backdrop-blur-md ${evt.color || 'bg-indigo-600/20'} cursor-pointer active:scale-95 transition-all`}
                                    >
                                        <h5 className="text-[10px] font-black text-white tracking-tight truncate">{evt.title}</h5>
                                        <p className="text-[8px] text-white/40 uppercase">{evt.time}</p>
                                    </div>
                                ))}
                                {h === currentHour && todayStr === dStr && (
                                    <motion.div 
                                        animate={{ opacity: [1, 0.4, 1] }}
                                        transition={{ duration: 2, repeat: Infinity }}
                                        className="absolute top-0 left-0 w-full h-[1px] bg-rose-500 z-10"
                                    >
                                        <div className="w-1.5 h-1.5 rounded-full bg-rose-500 absolute -left-0.5 -top-0.5 shadow-[0_0_8px_#f43f5e]" />
                                    </motion.div>
                                )}
                            </div>
                        </div>
                    ))}
                </div>
            </motion.div>
        );
    };

    return (
        <div className="fixed inset-0 z-[250] bg-[#0F1115] text-white flex flex-col font-sans overflow-hidden selection:bg-indigo-500/30">
            {/* AMBIENT AURAS */}
            <div className="absolute inset-0 pointer-events-none opacity-20">
                <div className="absolute top-0 left-0 w-full h-[50vh] bg-gradient-to-b from-indigo-600/40 to-transparent" />
            </div>

            {/* TOP NAVIGATION */}
            <header className="p-8 pb-4 relative z-[260] space-y-8 backdrop-blur-xl bg-[#0F1115]/80 border-b border-white/5">
                <div className="flex items-center justify-between">
                    <button onClick={onClose} className="p-3 bg-white/5 rounded-2xl border border-white/5 active:scale-90"><ArrowLeftIcon /></button>
                    <div className="flex items-center gap-3 p-1 bg-white/5 rounded-2xl border border-white/10">
                        {(['today', 'day', 'month', 'agenda'] as CalendarViewMode[]).map(m => (
                            <button 
                                key={m}
                                onClick={() => setViewMode(m)}
                                className={`px-4 py-1.5 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all ${viewMode === m ? 'bg-indigo-600 text-white shadow-lg' : 'text-gray-400 hover:text-white'}`}
                            >
                                {m}
                            </button>
                        ))}
                    </div>
                    <button onClick={() => setShowCreate(true)} className="p-3 bg-indigo-600 rounded-2xl shadow-xl shadow-indigo-600/20 active:scale-90"><PlusCircleIcon /></button>
                </div>

                <div className="relative group">
                    <div className={`absolute inset-y-0 left-5 flex items-center ${isParsing ? 'animate-spin' : ''}`}>
                        {isParsing ? <BoltIcon className="w-4 h-4 text-indigo-400" /> : <MicrophoneIcon className="w-4 h-4 text-gray-500" />}
                    </div>
                    <input 
                        type="text" 
                        value={quickAddText}
                        onChange={e => setQuickAddText(e.target.value)}
                        onKeyDown={e => e.key === 'Enter' && handleQuickAdd()}
                        placeholder="Neural Quick Sync: 'Meeting with Riya tomorrow at 4pm'"
                        className="w-full bg-white/5 border border-white/10 rounded-[1.8rem] py-5 pl-14 pr-10 text-sm font-medium outline-none focus:bg-white/10 focus:border-indigo-500 transition-all shadow-inner"
                    />
                    <button onClick={handleQuickAdd} className="absolute inset-y-0 right-5 flex items-center text-indigo-400 hover:text-white transition-colors">
                        <SparklesIcon className="w-5 h-5" />
                    </button>
                </div>
            </header>

            {/* MAIN CONTENT AREA */}
            <main className="flex-1 overflow-y-auto premium-scroll px-8 pt-8 relative z-10 pb-40">
                <AnimatePresence mode="wait">
                    {viewMode === 'today' && renderToday()}
                    {viewMode === 'month' && renderMonth()}
                    {viewMode === 'day' && renderDay()}
                    {viewMode === 'agenda' && (
                        <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="space-y-10">
                            {filteredEvents.length > 0 ? (
                                filteredEvents.reduce((acc: any[], evt) => {
                                    const last = acc[acc.length - 1];
                                    if (last && last.date === evt.date) last.items.push(evt);
                                    else acc.push({ date: evt.date, items: [evt] });
                                    return acc;
                                }, []).map((group, i) => (
                                    <div key={i} className="space-y-4">
                                        <h3 className="text-[10px] font-black text-indigo-400 uppercase tracking-[0.4em] px-2">{group.date === todayStr ? 'Today' : group.date}</h3>
                                        <div className="space-y-4">{group.items.map(renderEventCard)}</div>
                                    </div>
                                ))
                            ) : <div className="py-20 text-center opacity-20 italic">No events found in matrix.</div>}
                        </motion.div>
                    )}
                </AnimatePresence>
            </main>

            {/* BOTTOM BAR (NAV + HABITS) */}
            <footer className="fixed bottom-0 left-0 w-full h-32 bg-gradient-to-t from-black via-[#0F1115] to-transparent pointer-events-none z-[300]">
                <div className="absolute bottom-10 left-1/2 -translate-x-1/2 w-[90%] max-w-sm h-16 bg-white/[0.03] backdrop-blur-2xl border border-white/10 rounded-full flex items-center justify-evenly px-4 pointer-events-auto shadow-2xl">
                    <button onClick={() => setViewMode('today')} className={`p-2 rounded-full transition-all ${viewMode === 'today' ? 'bg-indigo-600 text-white shadow-xl' : 'text-white/20'}`}><HomeIcon className="w-6 h-6" /></button>
                    <button onClick={() => setViewMode('month')} className={`p-2 rounded-full transition-all ${viewMode === 'month' ? 'bg-indigo-600 text-white shadow-xl' : 'text-white/20'}`}><CalendarIcon className="w-6 h-6" /></button>
                    <button onClick={() => setViewMode('tasks')} className={`p-2 rounded-full transition-all ${viewMode === 'tasks' ? 'bg-indigo-600 text-white shadow-xl' : 'text-white/20'}`}><CheckCircleIcon className="w-6 h-6" /></button>
                    <button onClick={onClose} className="p-2 text-white/10"><UserIcon className="w-6 h-6" /></button>
                </div>
            </footer>

            {/* CREATE/EDIT MODAL (BOTTOM SHEET STYLE) */}
            <AnimatePresence>
                {(showCreate || editEvent) && (
                    <div className="fixed inset-0 z-[500] flex items-end justify-center p-0">
                        <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onClick={() => { setShowCreate(false); setEditEvent(null); }} className="absolute inset-0 bg-black/80 backdrop-blur-md" />
                        <motion.div 
                            initial={{ y: '100%' }} animate={{ y: 0 }} exit={{ y: '100%' }}
                            transition={{ type: "spring", damping: 25, stiffness: 200 }}
                            className="relative w-full max-w-lg bg-[#0F1115] border-t border-white/10 rounded-t-[3rem] p-8 flex flex-col gap-8 max-h-[90vh] overflow-y-auto premium-scroll"
                        >
                            <div className="flex items-center justify-between">
                                <h2 className="text-2xl font-black italic tracking-tighter uppercase">{editEvent ? 'Modify Node' : 'Initialize Node'}</h2>
                                <button onClick={() => { setShowCreate(false); setEditEvent(null); }} className="p-2 bg-white/5 rounded-full"><XMarkIcon className="w-6 h-6" /></button>
                            </div>

                            <div className="space-y-6">
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black text-white/30 uppercase tracking-widest ml-4">Title</label>
                                    <input 
                                        defaultValue={editEvent?.title}
                                        className="w-full bg-white/5 border border-white/10 rounded-[1.8rem] p-5 text-lg font-bold outline-none focus:border-indigo-500" 
                                        placeholder="Event Identification..." 
                                    />
                                </div>

                                <div className="grid grid-cols-2 gap-4">
                                    <div className="space-y-2">
                                        <label className="text-[10px] font-black text-white/30 uppercase tracking-widest ml-4">Date</label>
                                        <input type="date" defaultValue={editEvent?.date || todayStr} className="w-full bg-white/5 border border-white/10 rounded-[1.8rem] p-5 text-sm outline-none font-bold" />
                                    </div>
                                    <div className="space-y-2">
                                        <label className="text-[10px] font-black text-white/30 uppercase tracking-widest ml-4">Start Time</label>
                                        <input type="time" defaultValue={editEvent?.time || '12:00'} className="w-full bg-white/5 border border-white/10 rounded-[1.8rem] p-5 text-sm outline-none font-bold" />
                                    </div>
                                </div>

                                <div className="space-y-2">
                                    <label className="text-[10px] font-black text-white/30 uppercase tracking-widest ml-4">Category Color</label>
                                    <div className="flex gap-3 px-2">
                                        {PRESET_COLORS.map(c => (
                                            <button key={c.name} className={`w-8 h-8 rounded-full ${c.bg} border-2 border-white/10 hover:scale-110 transition-transform`} />
                                        ))}
                                    </div>
                                </div>

                                <button 
                                    onClick={() => { setShowCreate(false); setEditEvent(null); }}
                                    className="w-full py-6 bg-indigo-600 rounded-[2rem] font-black text-sm uppercase tracking-widest shadow-2xl shadow-indigo-600/20 active:scale-95 transition-all mt-6"
                                >
                                    Commit Synchronization
                                </button>

                                {editEvent && (
                                    <button 
                                        onClick={() => {
                                            setEvents(prev => prev.filter(e => e.id !== editEvent.id));
                                            setEditEvent(null);
                                        }}
                                        className="w-full py-6 bg-rose-500/10 border border-rose-500/20 text-rose-500 rounded-[2rem] font-black text-sm uppercase tracking-widest"
                                    >
                                        Purge Node
                                    </button>
                                )}
                            </div>
                        </motion.div>
                    </div>
                )}
            </AnimatePresence>

            <style>{`
                .premium-scroll::-webkit-scrollbar { display: none; }
                .premium-scroll { -ms-overflow-style: none; scrollbar-width: none; }
            `}</style>
        </div>
    );
};

export default PersonalCalendarView;

import React, { useState, useMemo, useCallback, useEffect, useRef } from 'react';
import { UserProfile, CalendarNote, EventType, Participant, EventStatus } from '../types';
import { motion, AnimatePresence, LayoutGroup } from 'framer-motion';
import { useLocalStorage } from '../hooks/useLocalStorage';
import { GoogleGenAI, Type } from '@google/genai';
import ArrowLeftIcon from '../components/icons/ArrowLeftIcon';
import ChevronLeftIcon from '../components/icons/ChevronLeftIcon';
import ChevronRightIcon from '../components/icons/ChevronRightIcon';
import SparklesIcon from '../components/icons/SparklesIcon';
import XMarkIcon from '../components/icons/XMarkIcon';
import TrashIcon from '../components/icons/TrashIcon';
import BoltIcon from '../components/icons/BoltIcon';
import PlusCircleIcon from '../components/icons/PlusCircleIcon';
import BellIcon from '../components/icons/BellIcon';
import GlobeAltIcon from '../components/icons/GlobeAltIcon';
import MapPinIcon from '../components/icons/MapPinIcon';
import VideoCameraIcon from '../components/icons/VideoCameraIcon';
import CalendarIcon from '../components/icons/CalendarIcon';
import HomeIcon from '../components/icons/HomeIcon';
import UserIcon from '../components/icons/UserIcon';
import CheckCircleIcon from '../components/icons/CheckCircleIcon';
