const MONTHS = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
const DAYS_SHORT = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];

type CalendarViewMode = 'today' | 'day' | 'week' | 'month' | 'agenda' | 'tasks';

const PRESET_COLORS = [
    { name: 'Indigo', bg: 'bg-indigo-500', shadow: 'shadow-indigo-500/20' },
    { name: 'Rose', bg: 'bg-rose-500', shadow: 'shadow-rose-500/20' },
    { name: 'Emerald', bg: 'bg-emerald-500', shadow: 'shadow-emerald-500/20' },
    { name: 'Amber', bg: 'bg-amber-500', shadow: 'shadow-amber-500/20' },
    { name: 'Sky', bg: 'bg-sky-500', shadow: 'shadow-sky-500/20' },
    { name: 'Purple', bg: 'bg-purple-500', shadow: 'shadow-purple-500/20' },
];

const PersonalCalendarView: React.FC<{ userProfile: UserProfile; onClose: () => void }> = ({ userProfile, onClose }) => {
    const [viewMode, setViewMode] = useState<CalendarViewMode>('today');
    const [currentDate, setCurrentDate] = useState(new Date());
    const [events, setEvents] = useLocalStorage<CalendarNote[]>(`sifra_events_v2_${userProfile.userId}`, []);
    const [showCreate, setShowCreate] = useState(false);
    const [isParsing, setIsParsing] = useState(false);
    const [quickAddText, setQuickAddText] = useState('');
    const [focusMode, setFocusMode] = useState(false);

    // Form State for advanced creation
    const [editEvent, setEditEvent] = useState<Partial<CalendarNote> | null>(null);
    const [isSaving, setIsSaving] = useState(false);

    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();

    const formatDateStr = (date: Date) => date.toISOString().split('T')[0];
    const todayStr = formatDateStr(new Date());

    const filteredEvents = useMemo(() => {
        let evs = [...events].sort((a, b) => a.time.localeCompare(b.time));
        if (focusMode) {
            // Only show 'meet' or 'special' in focus mode
            evs = evs.filter(e => e.type === 'meet' || e.isSpecial);
        }
        return evs;
    }, [events, focusMode]);

    const handleQuickAdd = async () => {
        if (!quickAddText.trim()) return;
        setIsParsing(true);
        try {
            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
            const response = await ai.models.generateContent({
                model: 'gemini-3-flash-preview',
                contents: `Extract event details from this text: "${quickAddText}". Provide as JSON. Context: Today is ${new Date().toDateString()}.`,
                config: {
                    responseMimeType: 'application/json',
                    responseSchema: {
                        type: Type.OBJECT,
                        properties: {
                            title: { type: Type.STRING },
                            date: { type: Type.STRING, description: "YYYY-MM-DD" },
                            time: { type: Type.STRING, description: "HH:mm" },
                            type: { type: Type.STRING, description: "event, task, or meet" },
                            location: { type: Type.STRING },
                            meetingLink: { type: Type.STRING }
                        },
                        required: ['title', 'date', 'time', 'type']
                    }
                }
            });
            const data = JSON.parse(response.text);
            const newEvent: CalendarNote = {
                id: `evt-${Date.now()}`,
                date: data.date,
                time: data.time,
                title: data.title,
                content: '',
                type: data.type as EventType,
                isSpecial: false,
                location: data.location,
                meetingLink: data.meetingLink,
                color: PRESET_COLORS[Math.floor(Math.random() * PRESET_COLORS.length)].bg,
                participants: []
            };
            setEvents([...events, newEvent]);
            setQuickAddText('');
        } catch (e) {
            alert('Neural sync failed. Please use manual entry.');
        } finally {
            setIsParsing(false);
        }
    };

    const handleSaveEvent = (e: React.FormEvent) => {
        e.preventDefault();
        const form = e.target as HTMLFormElement;
        const formData = new FormData(form);

        const newEvt: CalendarNote = {
            id: editEvent?.id || `evt-${Date.now()}`,
            title: formData.get('title') as string || 'Untitled Node',
            date: formData.get('date') as string,
            time: formData.get('time') as string,
            endTime: formData.get('endTime') as string || undefined,
            type: formData.get('type') as EventType,
            content: formData.get('description') as string,
            location: formData.get('location') as string || undefined,
            meetingLink: formData.get('meetingLink') as string || undefined,
            isSpecial: formData.get('isSpecial') === 'on',
            color: editEvent?.color || PRESET_COLORS[0].bg,
            participants: editEvent?.participants || [],
            repeat: (formData.get('repeat') as any) || 'none',
        };

        if (editEvent?.id) {
            setEvents(prev => prev.map(ev => ev.id === editEvent.id ? newEvt : ev));
        } else {
            setEvents(prev => [...prev, newEvt]);
        }

        setShowCreate(false);
        setEditEvent(null);
    };

    const renderEventCard = (evt: CalendarNote) => (
        <motion.div 
            layout
            key={evt.id}
            initial={{ opacity: 0, scale: 0.95 }}
            animate={{ opacity: 1, scale: 1 }}
            className="w-full relative group cursor-pointer"
            onClick={() => setEditEvent(evt)}
        >
            <div className="absolute inset-0 bg-white/5 rounded-[2rem] blur-xl opacity-0 group-hover:opacity-20 transition-opacity" />
            <div className="relative bg-white/[0.03] border border-white/10 backdrop-blur-3xl rounded-[2.5rem] p-6 flex flex-col gap-4 group-hover:bg-white/[0.06] transition-all shadow-2xl">
                <div className="flex justify-between items-start">
                    <div className="flex items-center gap-4">
                        <div className={`w-2 h-12 rounded-full ${evt.color || 'bg-indigo-500'} shadow-lg`} />
                        <div>
                            <p className="text-[10px] font-black text-white/40 uppercase tracking-[0.3em] mb-1">{evt.time} {evt.endTime ? `— ${evt.endTime}` : ''}</p>
                            <h4 className="text-xl font-bold text-white tracking-tight leading-tight">{evt.title}</h4>
                        </div>
                    </div>
                    <div className={`px-4 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest ${evt.type === 'meet' ? 'bg-indigo-500/30 text-indigo-400 border border-indigo-500/20' : evt.type === 'task' ? 'bg-emerald-500/30 text-emerald-400 border border-emerald-500/20' : 'bg-sky-500/30 text-sky-400 border border-sky-500/20'}`}>
                        {evt.type}
                    </div>
                </div>

                {(evt.location || evt.content) && (
                    <div className="space-y-2">
                        {evt.location && (
                            <div className="flex items-center gap-2 text-white/50 text-xs">
                                <MapPinIcon className="w-3.5 h-3.5" />
                                <span className="truncate">{evt.location}</span>
                                <div className="ml-auto flex items-center gap-1 text-[8px] bg-white/5 px-2 py-0.5 rounded-full">
                                    <CloudIcon className="w-2.5 h-2.5" /> 24°C
                                </div>
                            </div>
                        )}
                        {evt.content && <p className="text-xs text-white/30 line-clamp-1">{evt.content}</p>}
                    </div>
                )}

                <div className="flex items-center justify-between mt-2">
                    <div className="flex -space-x-3">
                        {/* Simulated participants if none exist for a "Meet" */}
                        {evt.type === 'meet' && (!evt.participants || evt.participants.length === 0) && (
                            <div className="w-8 h-8 rounded-full border-2 border-[#0F1115] bg-pink-500 flex items-center justify-center text-[10px] font-bold text-white shadow-lg">S</div>
                        )}
                        {evt.participants?.slice(0, 3).map((p, i) => (
                            <div key={i} className={`w-8 h-8 rounded-full border-2 border-[#0F1115] bg-slate-800 flex items-center justify-center text-[10px] font-bold overflow-hidden shadow-lg ${p.status === 'accepted' ? 'ring-2 ring-emerald-500/50' : p.status === 'rejected' ? 'ring-2 ring-rose-500/50' : 'ring-2 ring-amber-500/50'}`}>
                                {p.avatar ? <img src={p.avatar} className="w-full h-full object-cover" alt=""/> : p.name[0]}
                            </div>
                        ))}
                        {evt.participants && evt.participants.length > 3 && (
                            <div className="w-8 h-8 rounded-full border-2 border-[#0F1115] bg-white/5 flex items-center justify-center text-[8px] font-black text-white/40">
                                +{evt.participants.length - 3}
                            </div>
                        )}
                    </div>
                    {evt.meetingLink && (
                        <button onClick={(e) => { e.stopPropagation(); window.open(evt.meetingLink, '_blank'); }} className="px-6 py-3 bg-gradient-to-r from-indigo-600 to-blue-600 rounded-2xl flex items-center gap-2 text-[10px] font-black uppercase tracking-widest shadow-xl shadow-indigo-500/20 active:scale-95 transition-all">
                            <VideoCameraIcon className="w-4 h-4" /> Join Neural Meet
                        </button>
                    )}
                </div>
            </div>
        </motion.div>
    );

    const renderToday = () => {
        const todayEvents = filteredEvents.filter(e => e.date === todayStr);
        return (
            <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="flex-1 flex flex-col gap-12">
                <section className="relative px-2">
                    <div className="flex items-center justify-between mb-8">
                        <div>
                             <h2 className="text-4xl font-black italic tracking-tighter uppercase leading-none mb-1">Matrix Dashboard</h2>
                             <p className="text-[10px] font-black text-white/20 uppercase tracking-[0.4em]">Node Visualization Active</p>
                        </div>
                        <div className="flex flex-col items-end">
                            <span className="text-xs font-black text-[#ff5f6d] uppercase tracking-[0.3em]">{MONTHS[month]}</span>
                            <span className="text-lg font-black text-white/80 tracking-tighter">{year}</span>
                        </div>
                    </div>

                    <div className="p-10 rounded-[3.5rem] bg-gradient-to-br from-[#6366F1] to-[#A855F7] shadow-[0_20px_50px_rgba(99,102,241,0.3)] relative overflow-hidden group">
                        <div className="absolute top-0 right-0 w-48 h-48 bg-white/10 blur-[80px] rounded-full translate-x-20 -translate-y-20 group-hover:scale-110 transition-transform duration-1000" />
                        <div className="absolute bottom-0 left-0 w-32 h-32 bg-indigo-400/20 blur-[60px] rounded-full -translate-x-10 translate-y-10" />
                        <div className="relative z-10">
                            <div className="flex items-center gap-2 mb-4">
                                <SparklesIcon className="w-4 h-4 text-white/60 animate-pulse" />
                                <p className="text-[10px] font-black text-white/60 uppercase tracking-[0.5em]">Critical Priority Node</p>
                            </div>
                            {todayEvents[0] ? (
                                <>
                                    <h3 className="text-5xl font-black text-white tracking-tighter mb-6 leading-[0.9]">{todayEvents[0].title}</h3>
                                    <div className="flex flex-wrap items-center gap-4">
                                        <div className="px-5 py-2.5 bg-white/20 rounded-2xl backdrop-blur-xl border border-white/20 text-xs font-black tracking-widest">{todayEvents[0].time}</div>
                                        {todayEvents[0].location && (
                                            <div className="flex items-center gap-2 text-white/80 text-xs font-bold bg-black/10 px-4 py-2.5 rounded-2xl">
                                                <MapPinIcon className="w-4 h-4" /> {todayEvents[0].location}
                                            </div>
                                        )}
                                    </div>
                                </>
                            ) : (
                                <p className="text-2xl font-bold text-white/80 italic">Clear neural channel for today.</p>
                            )}
                        </div>
                    </div>
                </section>

                <section className="space-y-6">
                    <div className="flex items-center justify-between px-4">
                        <h3 className="text-[11px] font-black text-white/30 uppercase tracking-[0.5em]">Upcoming Sequence</h3>
                        <div className="flex items-center gap-2">
                             <div className="flex gap-1">
                                {[1,1,1,0,0].map((s, i) => (
                                    <div key={i} className={`w-2 h-2 rounded-full ${s ? 'bg-emerald-500' : 'bg-white/10'}`} />
                                ))}
                             </div>
                             <span className="text-[9px] font-black text-emerald-400 uppercase tracking-widest">3 Day Streak</span>
                        </div>
                    </div>
                    <div className="space-y-6">
                        {todayEvents.length > 0 ? todayEvents.map(renderEventCard) : (
                            <div className="py-24 text-center opacity-20 flex flex-col items-center gap-4">
                                <BoltIcon className="w-12 h-12" />
                                <p className="text-sm font-black uppercase tracking-widest">No Active Nodes</p>
                            </div>
                        )}
                    </div>
                </section>
            </motion.div>
        );
    };

    const renderMonth = () => {
        const daysInMonth = new Date(year, month + 1, 0).getDate();
        const firstDay = new Date(year, month, 1).getDay();
        const days = Array.from({ length: daysInMonth }, (_, i) => i + 1);

        return (
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex-1 flex flex-col gap-10">
                 <div className="flex items-center justify-between px-2">
                    <h2 className="text-3xl font-black italic tracking-tighter uppercase">{MONTHS[month]} <span className="text-white/20">{year}</span></h2>
                    <div className="flex gap-2">
                        <button onClick={() => setCurrentDate(new Date(year, month - 1, 1))} className="p-3 bg-white/5 rounded-2xl"><ChevronLeftIcon className="w-4 h-4" /></button>
                        <button onClick={() => setCurrentDate(new Date(year, month + 1, 1))} className="p-3 bg-white/5 rounded-2xl"><ChevronRightIcon className="w-4 h-4" /></button>
                    </div>
                </div>

                <div className="grid grid-cols-7 gap-2">
                    {DAYS_SHORT.map(d => (
                        <div key={d} className="text-center text-[10px] font-black text-white/10 uppercase tracking-widest mb-4">{d}</div>
                    ))}
                    {[...Array(firstDay)].map((_, i) => <div key={`empty-${i}`} />)}
                    {days.map(day => {
                        const dStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
                        const dayEvents = events.filter(e => e.date === dStr);
                        const isToday = todayStr === dStr;

                        return (
                            <button 
                                key={day}
                                onClick={() => { setCurrentDate(new Date(year, month, day)); setViewMode('day'); }}
                                className={`aspect-square rounded-[1.8rem] flex flex-col items-center justify-center relative transition-all border-2 ${
                                    isToday ? 'bg-indigo-600 border-indigo-400 shadow-[0_0_30px_rgba(99,102,241,0.5)] scale-110 z-10' : 
                                    dayEvents.length > 0 ? 'bg-white/5 border-white/5' : 'border-transparent hover:bg-white/[0.03]'
                                }`}
                            >
                                <span className={`text-base font-black ${isToday ? 'text-white' : 'text-white/60'}`}>{day}</span>
                                <div className="flex gap-0.5 mt-1">
                                    {dayEvents.slice(0, 3).map((e, idx) => (
                                        <div key={idx} className={`w-1 h-1 rounded-full ${e.color?.replace('bg-', 'bg-opacity-100 bg-') || 'bg-indigo-400'}`} />
                                    ))}
                                </div>
                            </button>
                        );
                    })}
                </div>

                <section className="space-y-4 pt-10">
                     <h3 className="text-[10px] font-black text-white/30 uppercase tracking-[0.4em] px-2">Month Highlights</h3>
                     <div className="grid grid-cols-2 gap-4">
                        <div className="p-6 bg-white/5 rounded-3xl border border-white/5">
                            <p className="text-[9px] font-black text-emerald-400 uppercase mb-1">Total Tasks</p>
                            <p className="text-2xl font-black">{events.filter(e => e.type === 'task' && e.date.includes(`${year}-${String(month + 1).padStart(2, '0')}`)).length}</p>
                        </div>
                        <div className="p-6 bg-white/5 rounded-3xl border border-white/5">
                            <p className="text-[9px] font-black text-indigo-400 uppercase mb-1">Meets Scheduled</p>
                            <p className="text-2xl font-black">{events.filter(e => e.type === 'meet' && e.date.includes(`${year}-${String(month + 1).padStart(2, '0')}`)).length}</p>
                        </div>
                     </div>
                </section>
            </motion.div>
        );
    };

    const renderWeek = () => {
        const startOfWeek = new Date(currentDate);
        startOfWeek.setDate(currentDate.getDate() - currentDate.getDay());

        const days = Array.from({ length: 7 }, (_, i) => {
            const d = new Date(startOfWeek);
            d.setDate(startOfWeek.getDate() + i);
            return d;
        });

        return (
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex-1 flex flex-col gap-8 h-full">
                <div className="flex items-center justify-between px-2">
                    <h2 className="text-2xl font-black tracking-tighter uppercase italic">Week Cluster</h2>
                    <div className="p-1 bg-white/5 rounded-full border border-white/10 flex gap-2">
                         <button onClick={() => setCurrentDate(new Date(currentDate.setDate(currentDate.getDate() - 7)))} className="p-2 text-white/40"><ChevronLeftIcon className="w-4 h-4" /></button>
                         <button onClick={() => setCurrentDate(new Date(currentDate.setDate(currentDate.getDate() + 7)))} className="p-2 text-white/40"><ChevronRightIcon className="w-4 h-4" /></button>
                    </div>
                </div>

                <div className="flex-1 overflow-y-auto premium-scroll space-y-8 pb-32">
                    {days.map((d, i) => {
                        const dStr = formatDateStr(d);
                        const dayEvents = filteredEvents.filter(e => e.date === dStr);
                        const isToday = todayStr === dStr;

                        return (
                            <div key={i} className="flex gap-4 items-start">
                                <div className="w-14 flex-none flex flex-col items-center">
                                    <span className={`text-[10px] font-black uppercase tracking-widest ${isToday ? 'text-indigo-400' : 'text-white/20'}`}>{DAYS_SHORT[i]}</span>
                                    <span className={`text-2xl font-black mt-1 ${isToday ? 'text-white drop-shadow-[0_0_10px_rgba(99,102,241,0.5)]' : 'text-white/40'}`}>{d.getDate()}</span>
                                </div>
                                <div className="flex-1 space-y-3 pt-4">
                                    {dayEvents.length > 0 ? dayEvents.map(renderEventCard) : (
                                        <div className="h-1 bg-white/[0.03] rounded-full w-full" />
                                    )}
                                </div>
                            </div>
                        );
                    })}
                </div>
            </motion.div>
        );
    };

    const renderDay = () => {
        const dStr = formatDateStr(currentDate);
        const dayEvents = filteredEvents.filter(e => e.date === dStr);
        const hours = Array.from({ length: 24 }, (_, i) => i);
        const currentHour = new Date().getHours();

        return (
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex-1 flex flex-col h-full overflow-hidden">
                <div className="px-2 mb-6">
                    <h2 className="text-2xl font-black tracking-tighter uppercase italic">{currentDate.toLocaleDateString('en-US', { weekday: 'long', day: 'numeric', month: 'long' })}</h2>
                </div>
                <div className="flex-1 overflow-y-auto premium-scroll relative pr-2">
                    {hours.map(h => (
                        <div key={h} className="h-28 border-t border-white/[0.03] flex group relative">
                            <div className="w-20 flex-none flex justify-center pt-3">
                                <span className={`text-[11px] font-black tracking-tighter uppercase ${h === currentHour ? 'text-indigo-400' : 'text-white/10 group-hover:text-white/30'} transition-colors`}>
                                    {h.toString().padStart(2, '0')}:00
                                </span>
                            </div>
                            <div className="flex-1 relative pt-2">
                                {dayEvents.filter(e => parseInt(e.time.split(':')[0]) === h).map(evt => (
                                    <motion.div 
                                        layoutId={evt.id}
                                        key={evt.id} 
                                        onClick={() => setEditEvent(evt)}
                                        className={`p-4 rounded-3xl border border-white/10 backdrop-blur-2xl shadow-xl ${evt.color || 'bg-indigo-600/20'} cursor-pointer active:scale-95 transition-all mb-2`}
                                    >
                                        <h5 className="text-sm font-bold text-white tracking-tight truncate">{evt.title}</h5>
                                        <p className="text-[10px] text-white/40 uppercase font-black tracking-widest">{evt.time}</p>
                                    </motion.div>
                                ))}
                                {h === currentHour && todayStr === dStr && (
                                    <div className="absolute top-0 left-0 w-full h-[2px] bg-rose-500/50 z-[5] pointer-events-none">
                                        <div className="w-3 h-3 rounded-full bg-rose-500 absolute -left-1.5 -top-1 shadow-[0_0_15px_#f43f5e]" />
                                    </div>
                                )}
                            </div>
                        </div>
                    ))}
                    <div className="h-40" />
                </div>
            </motion.div>
        );
    };

    return (
        <div className="fixed inset-0 z-[250] bg-[#0F1115] text-white flex flex-col font-sans overflow-hidden selection:bg-indigo-500/30">
            {/* AMBIENT AURAS */}
            <div className="absolute inset-0 pointer-events-none opacity-40">
                <div className="absolute top-0 left-0 w-full h-[60vh] bg-gradient-to-b from-indigo-900/40 via-purple-900/20 to-transparent" />
                <div className="absolute bottom-[-10%] right-[-10%] w-[50%] h-[50%] bg-blue-600/10 blur-[120px] rounded-full" />
                <div className="absolute inset-0 bg-[url('https://grainy-gradients.vercel.app/noise.svg')] opacity-10 contrast-150 brightness-50" />
            </div>

            {/* TOP NAVIGATION */}
            <header className="p-8 pb-4 relative z-[260] space-y-10 backdrop-blur-3xl bg-[#0F1115]/60 border-b border-white/5">
                <div className="flex items-center justify-between">
                    <button onClick={onClose} className="p-4 bg-white/5 rounded-3xl border border-white/10 hover:bg-white/10 transition-all active:scale-90 shadow-inner">
                        <ArrowLeftIcon className="w-7 h-7 text-white/60" />
                    </button>
                    <div className="flex items-center gap-1.5 p-1.5 bg-white/5 rounded-3xl border border-white/10">
                        {(['today', 'day', 'week', 'month', 'agenda'] as CalendarViewMode[]).map(m => (
                            <button 
                                key={m}
                                onClick={() => setViewMode(m)}
                                className={`px-5 py-2.5 rounded-2xl text-[9px] font-black uppercase tracking-[0.2em] transition-all ${viewMode === m ? 'bg-indigo-600 text-white shadow-[0_10px_20px_rgba(99,102,241,0.3)]' : 'text-gray-400 hover:text-white'}`}
                            >
                                {m}
                            </button>
                        ))}
                    </div>
                    <button onClick={() => setShowCreate(true)} className="p-4 bg-indigo-600 rounded-3xl shadow-2xl shadow-indigo-600/30 active:scale-90 hover:bg-indigo-500 transition-all">
                        <PlusCircleIcon className="w-7 h-7" />
                    </button>
                </div>

                <div className="relative group px-2">
                    <div className={`absolute inset-y-0 left-8 flex items-center ${isParsing ? 'animate-spin' : ''}`}>
                        {isParsing ? <BoltIcon className="w-5 h-5 text-indigo-400" /> : <MicrophoneIcon className="w-5 h-5 text-gray-500" />}
                    </div>
                    <input 
                        type="text" 
                        value={quickAddText}
                        onChange={e => setQuickAddText(e.target.value)}
                        onKeyDown={e => e.key === 'Enter' && handleQuickAdd()}
                        placeholder="Neural Quick Sync: 'Meeting tomorrow 5pm'"
                        className="w-full bg-white/5 border border-white/10 rounded-[2.5rem] py-6 pl-16 pr-14 text-sm font-medium outline-none focus:bg-white/10 focus:border-indigo-500/50 transition-all shadow-2xl"
                    />
                    <button onClick={handleQuickAdd} className="absolute inset-y-0 right-8 flex items-center text-indigo-400 hover:text-white transition-colors">
                        <SparklesIcon className="w-6 h-6" />
                    </button>
                </div>
            </header>

            {/* MAIN CONTENT AREA */}
            <main className="flex-1 overflow-y-auto premium-scroll px-8 pt-10 relative z-10 pb-48">
                <AnimatePresence mode="wait">
                    {viewMode === 'today' && renderToday()}
                    {viewMode === 'month' && renderMonth()}
                    {viewMode === 'week' && renderWeek()}
                    {viewMode === 'day' && renderDay()}
                    {viewMode === 'agenda' && (
                        <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="space-y-12">
                            {filteredEvents.length > 0 ? (
                                filteredEvents.reduce((acc: any[], evt) => {
                                    const last = acc[acc.length - 1];
                                    if (last && last.date === evt.date) last.items.push(evt);
                                    else acc.push({ date: evt.date, items: [evt] });
                                    return acc;
                                }, []).map((group, i) => (
                                    <div key={i} className="space-y-6">
                                        <div className="flex items-center gap-4">
                                             <h3 className="text-[11px] font-black text-indigo-400 uppercase tracking-[0.5em]">{group.date === todayStr ? 'Today Sequence' : `Node ${group.date}`}</h3>
                                             <div className="h-[1px] flex-1 bg-white/5" />
                                        </div>
                                        <div className="space-y-6">{group.items.map(renderEventCard)}</div>
                                    </div>
                                ))
                            ) : (
                                <div className="py-32 text-center opacity-10 flex flex-col items-center gap-4">
                                    <CalendarIcon className="w-20 h-20" />
                                    <p className="text-xl font-black uppercase tracking-[0.4em]">Matrix Empty</p>
                                </div>
                            )}
                        </motion.div>
                    )}
                    {viewMode === 'tasks' && (
                        <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="space-y-8">
                             <div className="flex items-center justify-between px-2">
                                <h2 className="text-3xl font-black tracking-tighter uppercase italic">Pending Tasks</h2>
                                <div className="p-2 bg-emerald-500/10 rounded-2xl border border-emerald-500/20 text-emerald-400 text-[10px] font-black uppercase tracking-widest">Active Ops</div>
                             </div>
                             <div className="space-y-4">
                                {events.filter(e => e.type === 'task').length > 0 ? events.filter(e => e.type === 'task').map(renderEventCard) : (
                                    <div className="py-24 text-center opacity-20 italic">No tasks assigned to matrix.</div>
                                )}
                             </div>
                        </motion.div>
                    )}
                </AnimatePresence>
            </main>

            {/* BOTTOM BAR (NAV + HABITS) */}
            <footer className="fixed bottom-0 left-0 w-full h-40 bg-gradient-to-t from-black via-[#0F1115] to-transparent pointer-events-none z-[300]">
                <div className="absolute bottom-10 left-1/2 -translate-x-1/2 w-[92%] max-w-sm h-20 bg-white/[0.03] backdrop-blur-3xl border border-white/10 rounded-full flex items-center justify-evenly px-6 pointer-events-auto shadow-[0_20px_50px_rgba(0,0,0,0.5)]">
                    <button onClick={() => setViewMode('today')} className={`p-3 rounded-2xl transition-all ${viewMode === 'today' ? 'bg-indigo-600 text-white shadow-2xl scale-110' : 'text-white/20'}`}><HomeIcon className="w-6 h-6" /></button>
                    <button onClick={() => setViewMode('month')} className={`p-3 rounded-2xl transition-all ${viewMode === 'month' ? 'bg-indigo-600 text-white shadow-2xl scale-110' : 'text-white/20'}`}><CalendarIcon className="w-6 h-6" /></button>
                    <button onClick={() => setViewMode('tasks')} className={`p-3 rounded-2xl transition-all ${viewMode === 'tasks' ? 'bg-indigo-600 text-white shadow-2xl scale-110' : 'text-white/20'}`}><CheckCircleIcon className="w-6 h-6" /></button>
                    <button onClick={() => setFocusMode(!focusMode)} className={`p-3 rounded-2xl transition-all ${focusMode ? 'bg-rose-600 text-white shadow-2xl scale-110' : 'text-white/20'}`}><BriefcaseIcon className="w-6 h-6" /></button>
                </div>
            </footer>

            {/* CREATE/EDIT MODAL (ADVANCED BOTTOM SHEET) */}
            <AnimatePresence>
                {(showCreate || editEvent) && (
                    <div className="fixed inset-0 z-[500] flex items-end justify-center p-0">
                        <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onClick={() => { setShowCreate(false); setEditEvent(null); }} className="absolute inset-0 bg-black/80 backdrop-blur-2xl" />
                        <motion.div 
                            initial={{ y: '100%' }} animate={{ y: 0 }} exit={{ y: '100%' }}
                            transition={{ type: "spring", damping: 30, stiffness: 250 }}
                            className="relative w-full max-w-lg bg-[#14161B] border-t border-white/10 rounded-t-[4rem] p-10 flex flex-col gap-10 max-h-[95vh] overflow-y-auto premium-scroll shadow-[0_-20px_60px_rgba(0,0,0,0.5)]"
                        >
                            <div className="flex items-center justify-between mb-2">
                                <div>
                                    <h2 className="text-3xl font-black italic tracking-tighter uppercase leading-none">{editEvent?.id ? 'Adjust Node' : 'Initialize Node'}</h2>
                                    <p className="text-[10px] font-black text-indigo-400 uppercase tracking-[0.4em] mt-2">Neural Link Calibration</p>
                                </div>
                                <button onClick={() => { setShowCreate(false); setEditEvent(null); }} className="p-4 bg-white/5 rounded-3xl border border-white/10"><XMarkIcon className="w-6 h-6" /></button>
                            </div>

                            <form onSubmit={handleSaveEvent} className="space-y-8 pb-10">
                                <div className="space-y-4">
                                    <label className="text-[11px] font-black text-white/30 uppercase tracking-[0.3em] ml-6">Node Title</label>
                                    <input 
                                        name="title"
                                        required
                                        defaultValue={editEvent?.title}
                                        className="w-full bg-white/5 border border-white/10 rounded-[2.5rem] p-8 text-xl font-bold outline-none focus:border-indigo-500 focus:bg-white/10 transition-all shadow-inner" 
                                        placeholder="Identify the Event..." 
                                    />
                                </div>

                                <div className="grid grid-cols-2 gap-6">
                                    <div className="space-y-4">
                                        <label className="text-[11px] font-black text-white/30 uppercase tracking-[0.3em] ml-6">Launch Date</label>
                                        <input type="date" name="date" required defaultValue={editEvent?.date || todayStr} className="w-full bg-white/5 border border-white/10 rounded-[2.5rem] p-6 text-sm outline-none font-bold shadow-inner" />
                                    </div>
                                    <div className="space-y-4">
                                        <label className="text-[11px] font-black text-white/30 uppercase tracking-[0.3em] ml-6">Start Time</label>
                                        <input type="time" name="time" required defaultValue={editEvent?.time || '12:00'} className="w-full bg-white/5 border border-white/10 rounded-[2.5rem] p-6 text-sm outline-none font-bold shadow-inner" />
                                    </div>
                                </div>

                                <div className="space-y-4">
                                    <label className="text-[11px] font-black text-white/30 uppercase tracking-[0.3em] ml-6">Node Classification</label>
                                    <div className="grid grid-cols-3 gap-3">
                                        {(['event', 'task', 'meet'] as EventType[]).map(t => (
                                            <label key={t} className="cursor-pointer">
                                                <input type="radio" name="type" value={t} defaultChecked={(editEvent?.type || 'event') === t} className="hidden peer" />
                                                <div className="w-full py-4 text-center rounded-2xl border-2 border-white/5 bg-white/5 text-[10px] font-black uppercase tracking-widest peer-checked:border-indigo-500 peer-checked:bg-indigo-500/20 peer-checked:text-indigo-400 transition-all">{t}</div>
                                            </label>
                                        ))}
                                    </div>
                                </div>

                                <div className="space-y-4">
                                    <label className="text-[11px] font-black text-white/30 uppercase tracking-[0.3em] ml-6">Coordinate Location</label>
                                    <input name="location" defaultValue={editEvent?.location} className="w-full bg-white/5 border border-white/10 rounded-[2.5rem] p-6 text-sm font-bold outline-none focus:border-indigo-500 shadow-inner" placeholder="Physical or Virtual Room..." />
                                </div>

                                <div className="space-y-4">
                                    <label className="text-[11px] font-black text-white/30 uppercase tracking-[0.3em] ml-6">Link Stream</label>
                                    <input name="meetingLink" defaultValue={editEvent?.meetingLink} className="w-full bg-white/5 border border-white/10 rounded-[2.5rem] p-6 text-sm font-bold outline-none focus:border-indigo-500 shadow-inner" placeholder="Zoom/Google Meet Link..." />
                                </div>

                                <div className="space-y-4">
                                    <label className="text-[11px] font-black text-white/30 uppercase tracking-[0.3em] ml-6">Visual Spectrum</label>
                                    <div className="flex gap-4 px-4 overflow-x-auto no-scrollbar pb-2">
                                        {PRESET_COLORS.map(c => (
                                            <button 
                                                key={c.name} 
                                                type="button"
                                                onClick={() => setEditEvent(prev => ({ ...prev, color: c.bg }))}
                                                className={`w-12 h-12 flex-none rounded-full ${c.bg} border-4 transition-all shadow-xl ${editEvent?.color === c.bg ? 'border-white scale-125' : 'border-transparent'}`} 
                                            />
                                        ))}
                                    </div>
                                </div>

                                <div className="pt-10 flex flex-col gap-4">
                                    <button 
                                        type="submit"
                                        className="w-full py-8 bg-gradient-to-r from-indigo-600 to-blue-600 rounded-[3rem] font-black text-lg uppercase tracking-[0.3em] shadow-2xl shadow-indigo-600/40 active:scale-95 transition-all"
                                    >
                                        Synchronize Node
                                    </button>

                                    {editEvent?.id && (
                                        <button 
                                            type="button"
                                            onClick={() => {
                                                setEvents(prev => prev.filter(e => e.id !== editEvent.id));
                                                setEditEvent(null);
                                            }}
                                            className="w-full py-6 bg-rose-500/10 border border-rose-500/20 text-rose-500 rounded-[2.5rem] font-black text-xs uppercase tracking-widest active:bg-rose-500/20 transition-all"
                                        >
                                            Purge Node Log
                                        </button>
                                    )}
                                </div>
                            </form>
                        </motion.div>
                    </div>
                )}
            </AnimatePresence>

            <style>{`
                .premium-scroll::-webkit-scrollbar { display: none; }
                .premium-scroll { -ms-overflow-style: none; scrollbar-width: none; }
                .no-scrollbar::-webkit-scrollbar { display: none; }
            `}</style>
        </div>
    );
};

