const PersonalCalendarView: React.FC<{ userProfile: UserProfile; onClose: () => void }> = ({ userProfile, onClose }) => {
    // Navigation State
    const [activeTab, setActiveTab] = useState<CalendarViewMode>('today');
    const [viewMode, setViewMode] = useState<'day' | 'week' | 'month' | 'agenda'>('month');

    // Core Data
    const [currentDate, setCurrentDate] = useState(new Date());
    const [events, setEvents] = useLocalStorage<CalendarNote[]>(`sifra_calendar_v3_${userProfile.userId}`, []);
    const [habits, setHabits] = useLocalStorage<HabitStreak[]>(`sifra_habits_${userProfile.userId}`, [
        { id: '1', name: 'Neural Focus', completedDates: [], color: 'bg-indigo-500' },
        { id: '2', name: 'Hydration Link', completedDates: [], color: 'bg-sky-500' }
    ]);

    // UI Control
    const [showAssistant, setShowAssistant] = useState(false);
    const [assistantText, setAssistantText] = useState('');
    const [isAssistantProcessing, setIsAssistantProcessing] = useState(false);
    const [showEventEditor, setShowEventEditor] = useState<Partial<CalendarNote> | null>(null);
    const [focusMode, setFocusMode] = useState(false);

    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();
    const todayStr = new Date().toISOString().split('T')[0];

    const filteredEvents = useMemo(() => {
        let evs = [...events].sort((a, b) => a.time.localeCompare(b.time));
        if (focusMode) evs = evs.filter(e => e.type === 'meet' || e.isSpecial);
        return evs;
    }, [events, focusMode]);

    // AI VOICE ASSISTANT LOGIC
    const handleAssistantSync = async () => {
        if (!assistantText.trim()) return;
        setIsAssistantProcessing(true);
        try {
            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
            const response = await ai.models.generateContent({
                model: 'gemini-3-flash-preview',
                contents: `Create a calendar task from this: "${assistantText}". Respond in JSON. Date context: Today is ${new Date().toDateString()}.`,
                config: {
                    responseMimeType: 'application/json',
                    responseSchema: {
                        type: Type.OBJECT,
                        properties: {
                            title: { type: Type.STRING },
                            date: { type: Type.STRING },
                            time: { type: Type.STRING },
                            type: { type: Type.STRING, description: 'event, task, or meet' }
                        },
                        required: ['title', 'date', 'time', 'type']
                    }
                }
            });
            const data = JSON.parse(response.text);
            const newNode: CalendarNote = {
                id: `node-${Date.now()}`,
                title: data.title,
                date: data.date,
                time: data.time,
                type: data.type as EventType,
                content: '',
                isSpecial: false,
                color: PRESET_COLORS[Math.floor(Math.random() * PRESET_COLORS.length)].bg,
                participants: []
            };
            setEvents([...events, newNode]);
            setAssistantText('');
            setShowAssistant(false);
        } catch (e) {
            alert('Calibration Error: Matrix could not resolve speech.');
        } finally {
            setIsAssistantProcessing(false);
        }
    };

    const toggleHabit = (habitId: string, date: string) => {
        setHabits(prev => prev.map(h => {
            if (h.id === habitId) {
                const dates = h.completedDates.includes(date) 
                    ? h.completedDates.filter(d => d !== date) 
                    : [...h.completedDates, date];
                return { ...h, completedDates: dates };
            }
            return h;
        }));
    };

    // RENDER HELPERS
    const renderEventCard = (evt: CalendarNote) => (
        <motion.div 
            layout
            key={evt.id}
            initial={{ opacity: 0, scale: 0.98 }}
            animate={{ opacity: 1, scale: 1 }}
            className="w-full relative group cursor-pointer active:scale-95 transition-transform"
            onClick={() => setShowEventEditor(evt)}
        >
            <div className="relative bg-white/[0.03] border border-white/10 backdrop-blur-3xl rounded-[2.5rem] p-6 flex flex-col gap-4 shadow-2xl group-hover:bg-white/[0.06] transition-all">
                <div className="flex justify-between items-start">
                    <div className="flex items-center gap-4">
                        <div className={`w-2 h-10 rounded-full ${evt.color || 'bg-indigo-500'} shadow-lg shadow-indigo-500/20`} />
                        <div>
                            <p className="text-[10px] font-black text-white/30 uppercase tracking-[0.3em] mb-1">{evt.time} {evt.endTime ? `— ${evt.endTime}` : ''}</p>
                            <h4 className="text-lg font-bold text-white tracking-tight leading-tight">{evt.title}</h4>
                        </div>
                    </div>
                    <div className={`px-4 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest ${evt.type === 'meet' ? 'bg-indigo-500/30 text-indigo-400 border border-indigo-500/20' : evt.type === 'task' ? 'bg-emerald-500/30 text-emerald-400 border border-emerald-500/20' : 'bg-sky-500/30 text-sky-400 border border-sky-500/20'}`}>
                        {evt.type}
                    </div>
                </div>

                <div className="flex items-center justify-between">
                    <div className="flex -space-x-2.5">
                        {(evt.participants || []).slice(0, 3).map((p, i) => (
                            <div key={i} className={`w-8 h-8 rounded-full border-2 border-[#0F1115] bg-slate-800 flex items-center justify-center text-[10px] font-bold shadow-lg overflow-hidden ${p.status === 'accepted' ? 'ring-2 ring-emerald-500' : 'ring-2 ring-amber-500'}`}>
                                {p.avatar ? <img src={p.avatar} className="w-full h-full object-cover" /> : p.name[0]}
                            </div>
                        ))}
                    </div>
                    {evt.meetingLink && (
                        <button onClick={(e) => { e.stopPropagation(); window.open(evt.meetingLink, '_blank'); }} className="px-6 py-2.5 bg-gradient-to-r from-indigo-600 to-blue-600 rounded-2xl flex items-center gap-2 text-[10px] font-black uppercase tracking-widest shadow-xl active:scale-90 transition-transform">
                            <VideoCameraIcon className="w-4 h-4" /> Join
                        </button>
                    )}
                </div>
            </div>
        </motion.div>
    );

    const renderTodayDashboard = () => {
        const todayEvents = filteredEvents.filter(e => e.date === todayStr);
        return (
            <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="flex-1 flex flex-col gap-10">
                <section className="px-2">
                    <div className="flex justify-between items-end mb-8">
                         <div>
                            <h2 className="text-4xl font-black italic tracking-tighter uppercase leading-none mb-1">Timeline</h2>
                            <p className="text-[10px] font-black text-white/20 uppercase tracking-[0.4em]">Neural Grid Visualization</p>
                         </div>
                         <div className="text-right">
                             <span className="text-xs font-black text-rose-500 uppercase tracking-widest block">{MONTHS[month]}</span>
                             <span className="text-2xl font-black text-white tracking-tighter">{new Date().getDate()}</span>
                         </div>
                    </div>

                    <div className="p-10 rounded-[3.5rem] bg-gradient-to-br from-[#6366F1] to-[#A855F7] shadow-[0_30px_60px_-15px_rgba(99,102,241,0.4)] relative overflow-hidden group">
                        <div className="absolute top-0 right-0 w-48 h-48 bg-white/10 blur-[80px] rounded-full translate-x-10 -translate-y-10 group-hover:scale-125 transition-transform duration-1000" />
                        <div className="relative z-10">
                            <div className="flex items-center gap-2 mb-4">
                                <SparklesIcon className="w-4 h-4 text-white/60 animate-pulse" />
                                <p className="text-[10px] font-black text-white/60 uppercase tracking-[0.5em]">Upcoming Priority</p>
                            </div>
                            {todayEvents[0] ? (
                                <>
                                    <h3 className="text-5xl font-black text-white tracking-tighter mb-8 leading-[0.9]">{todayEvents[0].title}</h3>
                                    <div className="flex flex-wrap items-center gap-4">
                                        <div className="px-5 py-2.5 bg-white/20 rounded-2xl backdrop-blur-xl border border-white/20 text-xs font-black tracking-widest">{todayEvents[0].time}</div>
                                        <div className="flex items-center gap-2 text-white/80 text-xs font-bold bg-black/10 px-4 py-2.5 rounded-2xl"><CloudIcon className="w-4 h-4" /> 28°C</div>
                                    </div>
                                </>
                            ) : (
                                <p className="text-2xl font-bold text-white/80 italic">Clear Neural Channel.</p>
                            )}
                        </div>
                    </div>
                </section>

                <section className="space-y-6">
                    <div className="flex items-center justify-between px-4">
                        <h3 className="text-[11px] font-black text-white/30 uppercase tracking-[0.4em]">Next Sequences</h3>
                        <div className="flex gap-1.5">
                            {habits.map(h => (
                                <button key={h.id} onClick={() => toggleHabit(h.id, todayStr)} className={`w-8 h-8 rounded-full border-2 transition-all flex items-center justify-center ${h.completedDates.includes(todayStr) ? `${h.color} border-white/20 shadow-lg` : 'bg-white/5 border-white/5 opacity-40'}`}>
                                    <CheckCircleIcon className="w-4 h-4" />
                                </button>
                            ))}
                        </div>
                    </div>
                    <div className="space-y-6">
                        {todayEvents.slice(0, 3).map(renderEventCard)}
                        {todayEvents.length === 0 && <div className="py-24 text-center opacity-10 flex flex-col items-center gap-4"><BoltIcon className="w-12 h-12" /><p className="text-xl font-black uppercase tracking-widest">No Active Nodes</p></div>}
                    </div>
                </section>
            </motion.div>
        );
    };

    const renderMonthGrid = () => {
        const daysInMonth = new Date(year, month + 1, 0).getDate();
        const firstDay = new Date(year, month, 1).getDay();
        const days = Array.from({ length: daysInMonth }, (_, i) => i + 1);

        return (
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex-1 flex flex-col gap-10">
                <div className="flex items-center justify-between px-2">
                    <h2 className="text-3xl font-black italic tracking-tighter uppercase">{MONTHS[month]} <span className="text-white/20">{year}</span></h2>
                    <div className="flex gap-2">
                        <button onClick={() => setCurrentDate(new Date(year, month - 1, 1))} className="p-3 bg-white/5 rounded-2xl active:scale-90 transition-all"><ChevronLeftIcon className="w-4 h-4" /></button>
                        <button onClick={() => setCurrentDate(new Date(year, month + 1, 1))} className="p-3 bg-white/5 rounded-2xl active:scale-90 transition-all"><ChevronRightIcon className="w-4 h-4" /></button>
                    </div>
                </div>

                <div className="grid grid-cols-7 gap-2">
                    {DAYS_SHORT.map(d => <div key={d} className="text-center text-[10px] font-black text-white/10 uppercase tracking-widest mb-4">{d}</div>)}
                    {[...Array(firstDay)].map((_, i) => <div key={`empty-${i}`} />)}
                    {days.map(day => {
                        const dStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
                        const dayEvents = events.filter(e => e.date === dStr);
                        const isToday = todayStr === dStr;
                        return (
                            <button 
                                key={day}
                                onClick={() => { setCurrentDate(new Date(year, month, day)); setViewMode('day'); setActiveTab('day'); }}
                                className={`aspect-square rounded-[1.8rem] flex flex-col items-center justify-center relative transition-all border-2 ${isToday ? 'bg-indigo-600 border-indigo-400 shadow-[0_0_30px_rgba(99,102,241,0.5)] scale-110 z-10' : dayEvents.length > 0 ? 'bg-white/5 border-white/5' : 'border-transparent hover:bg-white/[0.03]'}`}
                            >
                                <span className={`text-base font-black ${isToday ? 'text-white' : 'text-white/60'}`}>{day}</span>
                                <div className="flex gap-0.5 mt-1">
                                    {dayEvents.slice(0, 3).map((e, idx) => <div key={idx} className={`w-1 h-1 rounded-full ${e.color || 'bg-indigo-500'}`} />)}
                                </div>
                            </button>
                        );
                    })}
                </div>
            </motion.div>
        );
    };

    const renderDayTimeline = () => {
        const dStr = currentDate.toISOString().split('T')[0];
        const dayEvents = filteredEvents.filter(e => e.date === dStr);
        const hours = Array.from({ length: 24 }, (_, i) => i);
        const currentHour = new Date().getHours();
        const currentMinutes = new Date().getMinutes();

        return (
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex-1 flex flex-col h-full overflow-hidden">
                <div className="px-2 mb-6">
                    <h2 className="text-2xl font-black tracking-tighter uppercase italic">{currentDate.toLocaleDateString('en-US', { weekday: 'long', day: 'numeric', month: 'long' })}</h2>
                </div>
                <div className="flex-1 overflow-y-auto premium-scroll relative pr-2">
                    {hours.map(h => (
                        <div key={h} className="h-32 border-t border-white/[0.03] flex group relative">
                            <div className="w-20 flex-none flex justify-center pt-3">
                                <span className={`text-[11px] font-black tracking-tighter uppercase ${h === currentHour ? 'text-indigo-400' : 'text-white/10'} transition-colors`}>
                                    {h.toString().padStart(2, '0')}:00
                                </span>
                            </div>
                            <div className="flex-1 relative pt-2">
                                {dayEvents.filter(e => parseInt(e.time.split(':')[0]) === h).map(evt => (
                                    <div 
                                        key={evt.id} 
                                        onClick={() => setShowEventEditor(evt)}
                                        className={`p-4 rounded-3xl border border-white/10 backdrop-blur-2xl shadow-xl ${evt.color || 'bg-indigo-600/20'} cursor-pointer active:scale-95 transition-all mb-2`}
                                    >
                                        <h5 className="text-sm font-bold text-white tracking-tight truncate">{evt.title}</h5>
                                        <p className="text-[10px] text-white/40 font-black uppercase">{evt.time}</p>
                                    </div>
                                ))}
                                {h === currentHour && todayStr === dStr && (
                                    <div className="absolute left-0 w-full h-[2px] bg-rose-500/50 z-[5]" style={{ top: `${(currentMinutes / 60) * 100}%` }}>
                                        <div className="w-3 h-3 rounded-full bg-rose-500 absolute -left-1.5 -top-1 shadow-[0_0_15px_#f43f5e]" />
                                    </div>
                                )}
                            </div>
                        </div>
                    ))}
                    <div className="h-40" />
                </div>
            </motion.div>
        );
    };

    return (
        <div className="fixed inset-0 z-[250] bg-[#0F1115] text-white flex flex-col font-sans overflow-hidden selection:bg-indigo-500/30">
            {/* AMBIENT BACKGROUND */}
            <div className="absolute inset-0 pointer-events-none opacity-40">
                <div className="absolute top-0 left-0 w-full h-[60vh] bg-gradient-to-b from-indigo-900/40 via-purple-900/20 to-transparent" />
                <div className="absolute bottom-[-10%] right-[-10%] w-[50%] h-[50%] bg-blue-600/10 blur-[120px] rounded-full" />
                <div className="absolute inset-0 bg-[url('https://grainy-gradients.vercel.app/noise.svg')] opacity-10 contrast-150 brightness-50" />
            </div>

            {/* TOP NAVIGATION */}
            <header className="p-8 pb-4 relative z-[260] space-y-10 backdrop-blur-3xl bg-[#0F1115]/60 border-b border-white/5">
                <div className="flex items-center justify-between">
                    <button onClick={onClose} className="p-4 bg-white/5 rounded-3xl border border-white/10 active:scale-90 shadow-inner">
                        <ArrowLeftIcon className="w-7 h-7 text-white/60" />
                    </button>
                    <div className="flex items-center gap-1.5 p-1.5 bg-white/5 rounded-3xl border border-white/10">
                        {(['today', 'calendar', 'tasks'] as CalendarViewMode[]).map(m => (
                            <button 
                                key={m}
                                onClick={() => setActiveTab(m)}
                                className={`px-6 py-2.5 rounded-2xl text-[9px] font-black uppercase tracking-[0.2em] transition-all ${activeTab === m ? 'bg-indigo-600 text-white shadow-xl' : 'text-gray-400 hover:text-white'}`}
                            >
                                {m}
                            </button>
                        ))}
                    </div>
                    <button onClick={() => setShowAssistant(true)} className="p-4 bg-indigo-600 rounded-3xl shadow-2xl active:scale-90 hover:bg-indigo-500 transition-all">
                        <MicrophoneIcon className="w-7 h-7" />
                    </button>
                </div>
            </header>

            {/* MAIN AREA */}
            <main className="flex-1 overflow-y-auto premium-scroll px-8 pt-10 relative z-10 pb-48">
                <AnimatePresence mode="wait">
                    {activeTab === 'today' && renderTodayDashboard()}
                    {activeTab === 'calendar' && (
                        <div className="flex flex-col h-full gap-8">
                            <div className="flex gap-2 self-center bg-white/5 p-1 rounded-2xl">
                                {(['month', 'day', 'week', 'agenda'] as const).map(v => (
                                    <button key={v} onClick={() => setViewMode(v)} className={`px-4 py-1.5 rounded-xl text-[8px] font-black uppercase tracking-widest ${viewMode === v ? 'bg-white text-black' : 'text-white/40'}`}>{v}</button>
                                ))}
                            </div>
                            {viewMode === 'month' && renderMonthGrid()}
                            {viewMode === 'day' && renderDayTimeline()}
                        </div>
                    )}
                    {activeTab === 'tasks' && (
                        <div className="space-y-8">
                             <div className="flex items-center justify-between px-2">
                                <h2 className="text-3xl font-black tracking-tighter uppercase italic">Nodes Queue</h2>
                                <div className="p-2 bg-emerald-500/10 rounded-2xl border border-emerald-500/20 text-emerald-400 text-[10px] font-black uppercase tracking-widest">Active Matrix</div>
                             </div>
                             <div className="space-y-4">
                                {events.filter(e => e.type === 'task').length > 0 ? events.filter(e => e.type === 'task').map(renderEventCard) : (
                                    <div className="py-24 text-center opacity-20 italic">No tasks assigned to matrix.</div>
                                )}
                             </div>
                        </div>
                    )}
                </AnimatePresence>
            </main>

            {/* BOTTOM BAR */}
            <footer className="fixed bottom-0 left-0 w-full h-40 bg-gradient-to-t from-black via-[#0F1115] to-transparent pointer-events-none z-[300]">
                <div className="absolute bottom-10 left-1/2 -translate-x-1/2 w-[92%] max-w-sm h-20 bg-white/[0.03] backdrop-blur-3xl border border-white/10 rounded-full flex items-center justify-evenly px-6 pointer-events-auto shadow-[0_20px_50px_rgba(0,0,0,0.5)]">
                    <button onClick={() => setActiveTab('today')} className={`p-3 rounded-2xl transition-all ${activeTab === 'today' ? 'bg-indigo-600 text-white shadow-2xl scale-110' : 'text-white/20'}`}><HomeIcon className="w-6 h-6" /></button>
                    <button onClick={() => setActiveTab('calendar')} className={`p-3 rounded-2xl transition-all ${activeTab === 'calendar' ? 'bg-indigo-600 text-white shadow-2xl scale-110' : 'text-white/20'}`}><CalendarIcon className="w-6 h-6" /></button>
                    <button onClick={() => setActiveTab('tasks')} className={`p-3 rounded-2xl transition-all ${activeTab === 'tasks' ? 'bg-indigo-600 text-white shadow-2xl scale-110' : 'text-white/20'}`}><CheckCircleIcon className="w-6 h-6" /></button>
                    <button onClick={() => setFocusMode(!focusMode)} className={`p-3 rounded-2xl transition-all ${focusMode ? 'bg-rose-600 text-white shadow-2xl scale-110' : 'text-white/20'}`}><BriefcaseIcon className="w-6 h-6" /></button>
                </div>
            </footer>

            {/* AI ASSISTANT OVERLAY */}
            <AnimatePresence>
                {showAssistant && (
                    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 z-[600] flex items-center justify-center p-6 bg-black/90 backdrop-blur-2xl">
                        <motion.div initial={{ scale: 0.8, y: 50 }} animate={{ scale: 1, y: 0 }} className="w-full max-w-md bg-[#14161B] border border-white/10 rounded-[3.5rem] p-10 shadow-2xl">
                            <div className="flex justify-between items-center mb-10">
                                <div>
                                    <h2 className="text-3xl font-black text-white italic tracking-tighter uppercase leading-none">AI Sync</h2>
                                    <p className="text-[10px] font-black text-indigo-400 uppercase tracking-[0.4em] mt-2">Matrix Listening...</p>
                                </div>
                                <button onClick={() => setShowAssistant(false)} className="p-3 bg-white/5 rounded-2xl"><XMarkIcon className="w-6 h-6" /></button>
                            </div>
                            <div className="space-y-8">
                                <div className="relative">
                                    <textarea 
                                        autoFocus
                                        value={assistantText}
                                        onChange={e => setAssistantText(e.target.value)}
                                        placeholder="How can I help you today? Speak or type your request..."
                                        className="w-full h-48 bg-white/5 border border-white/10 rounded-3xl p-6 text-lg font-bold outline-none focus:border-indigo-500 transition-all resize-none"
                                    />
                                    <button className="absolute bottom-5 right-5 w-12 h-12 bg-white/10 rounded-full flex items-center justify-center animate-pulse"><MicrophoneIcon className="w-6 h-6 text-indigo-400" /></button>
                                </div>
                                <button 
                                    onClick={handleAssistantSync}
                                    disabled={isAssistantProcessing || !assistantText.trim()}
                                    className="w-full py-6 bg-gradient-to-r from-indigo-600 to-blue-600 rounded-3xl font-black text-sm uppercase tracking-widest shadow-2xl flex items-center justify-center gap-3 disabled:opacity-30"
                                >
                                    {isAssistantProcessing ? <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" /> : <><SendIcon className="w-5 h-5" /> Commit Log</>}
                                </button>
                            </div>
                        </motion.div>
                    </motion.div>
                )}
            </AnimatePresence>

            {/* EVENT EDITOR / CREATOR */}
            <AnimatePresence>
                {showEventEditor && (
                    <div className="fixed inset-0 z-[500] flex items-end justify-center p-0">
                        <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onClick={() => setShowEventEditor(null)} className="absolute inset-0 bg-black/80 backdrop-blur-2xl" />
                        <motion.div 
                            initial={{ y: '100%' }} animate={{ y: 0 }} exit={{ y: '100%' }}
                            transition={{ type: "spring", damping: 30, stiffness: 250 }}
                            className="relative w-full max-w-lg bg-[#14161B] border-t border-white/10 rounded-t-[4rem] p-10 flex flex-col gap-10 max-h-[95vh] overflow-y-auto premium-scroll shadow-[0_-20px_60px_rgba(0,0,0,0.5)]"
                        >
                            <div className="flex items-center justify-between">
                                <h2 className="text-3xl font-black italic tracking-tighter uppercase leading-none">{showEventEditor.id ? 'Adjust Node' : 'Initialize Node'}</h2>
                                <button onClick={() => setShowEventEditor(null)} className="p-4 bg-white/5 rounded-3xl border border-white/10"><XMarkIcon className="w-6 h-6" /></button>
                            </div>

                            <form onSubmit={(e) => {
                                e.preventDefault();
                                const form = e.target as HTMLFormElement;
                                const fd = new FormData(form);
                                const newEvt: CalendarNote = {
                                    id: showEventEditor.id || `evt-${Date.now()}`,
                                    title: fd.get('title') as string,
                                    date: fd.get('date') as string,
                                    time: fd.get('time') as string,
                                    type: fd.get('type') as EventType,
                                    content: fd.get('content') as string,
                                    location: fd.get('location') as string,
                                    meetingLink: fd.get('meetingLink') as string,
                                    isSpecial: fd.get('isSpecial') === 'on',
                                    color: showEventEditor.color || PRESET_COLORS[0].bg,
                                    participants: showEventEditor.participants || []
                                };
                                setEvents(prev => showEventEditor.id ? prev.map(ev => ev.id === showEventEditor.id ? newEvt : ev) : [...prev, newEvt]);
                                setShowEventEditor(null);
                            }} className="space-y-8 pb-10">
                                <div className="space-y-4">
                                    <label className="text-[11px] font-black text-white/30 uppercase tracking-[0.3em] ml-6">Node Title</label>
                                    <input name="title" required defaultValue={showEventEditor.title} className="w-full bg-white/5 border border-white/10 rounded-[2.5rem] p-8 text-xl font-bold outline-none focus:border-indigo-500" placeholder="Identify the Event..." />
                                </div>
                                <div className="grid grid-cols-2 gap-6">
                                    <div className="space-y-4">
                                        <label className="text-[11px] font-black text-white/30 uppercase tracking-[0.3em] ml-6">Launch Date</label>
                                        <input type="date" name="date" required defaultValue={showEventEditor.date || todayStr} className="w-full bg-white/5 border border-white/10 rounded-[2.5rem] p-6 text-sm outline-none font-bold" />
                                    </div>
                                    <div className="space-y-4">
                                        <label className="text-[11px] font-black text-white/30 uppercase tracking-[0.3em] ml-6">Start Time</label>
                                        <input type="time" name="time" required defaultValue={showEventEditor.time || '12:00'} className="w-full bg-white/5 border border-white/10 rounded-[2.5rem] p-6 text-sm outline-none font-bold" />
                                    </div>
                                </div>
                                <div className="space-y-4">
                                    <label className="text-[11px] font-black text-white/30 uppercase tracking-[0.3em] ml-6">Classification</label>
                                    <div className="grid grid-cols-3 gap-3">
                                        {(['event', 'task', 'meet'] as EventType[]).map(t => (
                                            <label key={t} className="cursor-pointer">
                                                <input type="radio" name="type" value={t} defaultChecked={(showEventEditor.type || 'event') === t} className="hidden peer" />
                                                <div className="w-full py-4 text-center rounded-2xl border-2 border-white/5 bg-white/5 text-[10px] font-black uppercase tracking-widest peer-checked:border-indigo-500 peer-checked:bg-indigo-500/20 peer-checked:text-indigo-400 transition-all">{t}</div>
                                            </label>
                                        ))}
                                    </div>
                                </div>
                                <div className="space-y-4">
                                    <label className="text-[11px] font-black text-white/30 uppercase tracking-[0.3em] ml-6">Coordinates</label>
                                    <input name="location" defaultValue={showEventEditor.location} className="w-full bg-white/5 border border-white/10 rounded-[2.5rem] p-6 text-sm font-bold outline-none focus:border-indigo-500" placeholder="Physical or Virtual Location..." />
                                </div>
                                <button type="submit" className="w-full py-8 bg-gradient-to-r from-indigo-600 to-blue-600 rounded-[3rem] font-black text-lg uppercase tracking-[0.3em] shadow-2xl active:scale-95 transition-all">Synchronize Log</button>
                                {showEventEditor.id && (
                                    <button type="button" onClick={() => { setEvents(prev => prev.filter(e => e.id !== showEventEditor.id)); setShowEventEditor(null); }} className="w-full py-6 bg-rose-500/10 border border-rose-500/20 text-rose-500 rounded-[2.5rem] font-black text-xs uppercase tracking-widest">Purge Log</button>
                                )}
                            </form>
                        </motion.div>
                    </div>
                )}
            </AnimatePresence>

            <style>{`
                .premium-scroll::-webkit-scrollbar { display: none; }
                .premium-scroll { -ms-overflow-style: none; scrollbar-width: none; }
            `}</style>
        </div>
    );
};

