                    {userText && (
                        <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0 }} className="max-w-xs bg-white/5 backdrop-blur-md p-4 rounded-2xl border border-white/10">
                            <p className="text-[9px] uppercase font-black tracking-widest text-white/40 mb-1">You said</p>
                            <p className="text-sm text-white italic">"{userText}"</p>
                        </motion.div>
                    )}
                    {aiText && (
                        <motion.div initial={{ opacity: 0, scale: 0.9 }} animate={{ scale: 1, opacity: 1 }} exit={{ opacity: 0 }} className="max-w-md bg-[#ff2a6d]/10 backdrop-blur-xl p-6 rounded-[2.5rem] border border-[#ff2a6d]/30 shadow-[0_0_50px_rgba(255,42,109,0.2)]">
                            <p className="text-[10px] uppercase font-black tracking-widest text-[#ff2a6d] mb-2">{setupData?.wifeName || 'My Love'}</p>
                            <p className="text-xl text-white font-bold leading-tight">{aiText}</p>
