const PersonalCalendarView: React.FC<{ userProfile: UserProfile; onClose: () => void }> = ({ userProfile, onClose }) => {
    // Navigation State
    const [activeTab, setActiveTab] = useState<CalendarViewMode>('today');
    const [viewMode, setViewMode] = useState<'day' | 'week' | 'month' | 'agenda'>('month');

    // Core Data
    const [currentDate, setCurrentDate] = useState(new Date());
    const [events, setEvents] = useLocalStorage<CalendarNote[]>(`sifra_calendar_v3_${userProfile.userId}`, []);
    const [habits, setHabits] = useLocalStorage<HabitStreak[]>(`sifra_habits_${userProfile.userId}`, [
        { id: '1', name: 'Neural Focus', completedDates: [], color: 'bg-indigo-500' },
        { id: '2', name: 'Hydration Link', completedDates: [], color: 'bg-sky-500' }
    ]);

    // UI Control
    const [showAssistant, setShowAssistant] = useState(false);
    const [assistantText, setAssistantText] = useState('');
    const [isAssistantProcessing, setIsAssistantProcessing] = useState(false);
    const [showEventEditor, setShowEventEditor] = useState<Partial<CalendarNote> | null>(null);
    const [focusMode, setFocusMode] = useState(false);

    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();
    const todayStr = new Date().toISOString().split('T')[0];

    const filteredEvents = useMemo(() => {
        let evs = [...events].sort((a, b) => a.time.localeCompare(b.time));
        if (focusMode) evs = evs.filter(e => e.type === 'meet' || e.isSpecial);
        return evs;
    }, [events, focusMode]);

    // AI VOICE ASSISTANT LOGIC
    const handleAssistantSync = async () => {
        if (!assistantText.trim()) return;
        setIsAssistantProcessing(true);
        try {
            // Fix: Initializing GoogleGenAI right before use to ensure up-to-date API key from environment, following naming requirements.
            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
            const response = await ai.models.generateContent({
                model: 'gemini-3-flash-preview',
                contents: `Create a calendar task from this: "${assistantText}". Respond in JSON. Date context: Today is ${new Date().toDateString()}.`,
                config: {
                    responseMimeType: 'application/json',
                    responseSchema: {
                        type: Type.OBJECT,
                        properties: {
                            title: { type: Type.STRING },
                            date: { type: Type.STRING },
                            time: { type: Type.STRING },
                            type: { type: Type.STRING, description: 'event, task, or meet' }
                        },
                        required: ['title', 'date', 'time', 'type']
                    }
                }
            });
            const data = JSON.parse(response.text);
            const newNode: CalendarNote = {
                id: `node-${Date.now()}`,
                title: data.title,
                date: data.date,
                time: data.time,
                type: data.type as EventType,
                content: '',
                isSpecial: false,
                color: PRESET_COLORS[Math.floor(Math.random() * PRESET_COLORS.length)].bg,
                participants: []
            };
            setEvents([...events, newNode]);
            setAssistantText('');
            setShowAssistant(false);
        } catch (e) {
            alert('Calibration Error: Matrix could not resolve speech.');
        } finally {
            setIsAssistantProcessing(false);
        }
    };

    const toggleHabit = (habitId: string, date: string) => {
        setHabits(prev => prev.map(h => {
            if (h.id === habitId) {
                const dates = h.completedDates.includes(date) 
                    ? h.completedDates.filter(d => d !== date) 
                    : [...h.completedDates, date];
                return { ...h, completedDates: dates };
