                            <p className="text-[10px] font-black text-white/30 uppercase tracking-[0.3em] mb-1">{evt.time} {evt.endTime ? `— ${evt.endTime}` : ''}</p>
                            <h4 className="text-lg font-bold text-white tracking-tight leading-tight">{evt.title}</h4>
                        </div>
                    </div>
                    <div className={`px-4 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest ${evt.type === 'meet' ? 'bg-indigo-500/30 text-indigo-400 border border-indigo-500/20' : evt.type === 'task' ? 'bg-emerald-500/30 text-emerald-400 border border-emerald-500/20' : 'bg-sky-500/30 text-sky-400 border border-sky-500/20'}`}>
                        {evt.type}
