                    <div className="flex -space-x-2.5">
                        {(evt.participants || []).slice(0, 3).map((p, i) => (
                            <div key={i} className={`w-8 h-8 rounded-full border-2 border-[#0F1115] bg-slate-800 flex items-center justify-center text-[10px] font-bold shadow-lg overflow-hidden ${p.status === 'accepted' ? 'ring-2 ring-emerald-500' : 'ring-2 ring-amber-500'}`}>
