import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GoogleGenAI, LiveSession, Modality, LiveServerMessage, Blob } from '@google/genai';
import { motion, AnimatePresence } from 'framer-motion';
import { UserProfile } from '../types';
import { decode, decodeAudioData, encode } from '../utils/audioUtils';
import XMarkIcon from '../components/icons/XMarkIcon';
import ArrowLeftIcon from '../components/icons/ArrowLeftIcon';

if (!process.env.API_KEY) {
    throw new Error("API_KEY environment variable is not set");
}

const THEME = {
    bg: '#08090F', // Premium AMOLED Dark
    primary: '#FFFFFF',
    accent: '#3BB7FF',
    orbGlow: 'rgba(59, 183, 255, 0.4)',
};

const createBlob = (data: Float32Array): Blob => {
    const l = data.length;
    const int16 = new Int16Array(l);
    for (let i = 0; i < l; i++) {
        const s = Math.max(-1, Math.min(1, data[i]));
        int16[i] = s * 32767;
    }
    return {
        data: encode(new Uint8Array(int16.buffer)),
        mimeType: 'audio/pcm;rate=16000',
    };
};

type SessionState = 'idle' | 'connecting' | 'active' | 'error' | 'closing';

const GalaxyVoiceView: React.FC<{ userProfile: UserProfile; onClose: () => void; }> = ({ userProfile, onClose }) => {
    const [sessionState, setSessionState] = useState<SessionState>('idle');
    const [statusText, setStatusText] = useState('Listening...');
    const [isShipraSpeaking, setIsShipraSpeaking] = useState(false);

    const aiRef = useRef<GoogleGenAI | null>(null);
    const sessionPromiseRef = useRef<Promise<LiveSession> | null>(null);
    const streamRef = useRef<MediaStream | null>(null);
    const inputAudioContextRef = useRef<AudioContext | null>(null);
    const outputAudioContextRef = useRef<AudioContext | null>(null);
    const audioQueueRef = useRef(new Set<AudioBufferSourceNode>());
    const nextAudioStartTimeRef = useRef(0);
    const cleanedUpRef = useRef(false);
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const animationFrameRef = useRef<number>();
    const micEnergyRef = useRef(0);

    // Auto-timeout Logic (5 Seconds)
    const lastActivityRef = useRef<number>(Date.now());
    const silenceTimeoutRef = useRef<ReturnType<typeof setInterval> | null>(null);

    const cleanup = useCallback(() => {
        if (cleanedUpRef.current) return;
        cleanedUpRef.current = true;
        if (silenceTimeoutRef.current) clearInterval(silenceTimeoutRef.current);

        sessionPromiseRef.current?.then(session => session.close()).catch(console.error);
        sessionPromiseRef.current = null;

        if (streamRef.current) {
            streamRef.current.getTracks().forEach(track => track.stop());
            streamRef.current = null;
        }

        if (inputAudioContextRef.current && inputAudioContextRef.current.state !== 'closed') {
            inputAudioContextRef.current.close().catch(() => {});
        }
        inputAudioContextRef.current = null;

        if (outputAudioContextRef.current && outputAudioContextRef.current.state !== 'closed') {
            outputAudioContextRef.current.close().catch(() => {});
        }
        outputAudioContextRef.current = null;

        if (animationFrameRef.current) cancelAnimationFrame(animationFrameRef.current);
    }, []);

    const startSession = async () => {
        cleanup();
        cleanedUpRef.current = false;
        setSessionState('connecting');
        setStatusText('Initializing...');
        lastActivityRef.current = Date.now();

        try {
            streamRef.current = await navigator.mediaDevices.getUserMedia({ 
                audio: { echoCancellation: true, noiseSuppression: true, autoGainControl: true, sampleRate: 16000 } 
            });
        } catch (err) {
            setSessionState('error');
            setStatusText('Mic Blocked');
            return;
        }

        try {
            // Fix: Initializing GoogleGenAI with API key from environment strictly.
            aiRef.current = new GoogleGenAI({ apiKey: process.env.API_KEY });

            // JARVIS/SIRI LEVEL INSTRUCTIONS
            const systemInstruction = `
                You are SIFRA, a high-end personal AI assistant like Jarvis or Siri.
                User: ${userProfile.nickname || userProfile.name}.
                Tone: Smart, helpful, concise, and professional.

                CORE DIRECTIVES:
                1. You manage the user's "Personal Calendar" and "Memory Log."
                2. If the user asks to save something, acknowledge you've noted it for their tools.
                3. Reply instantly. Do not use filler words unless necessary for personality.
                4. Creator: Rizwan RR.
            `;

            sessionPromiseRef.current = aiRef.current.live.connect({
                model: 'gemini-2.5-flash-native-audio-preview-09-2025',
                callbacks: {
                    onopen: () => {
                        setSessionState('active');
                        setStatusText('Listening...');
                        if (!streamRef.current) return;
                        inputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
                        const ctx = inputAudioContextRef.current!;
                        const source = ctx.createMediaStreamSource(streamRef.current);
                        const processor = ctx.createScriptProcessor(2048, 1, 1);
                        source.connect(processor);
                        processor.connect(ctx.destination);

                        processor.onaudioprocess = (e) => {
                            const inputData = e.inputBuffer.getChannelData(0);
                            let sum = 0;
                            for (let i = 0; i < inputData.length; i++) sum += inputData[i] * inputData[i];
                            const energy = Math.sqrt(sum / inputData.length);
                            micEnergyRef.current = energy;

                            // Reset activity timer if user speaks (threshold 0.015)
                            if (energy > 0.015) lastActivityRef.current = Date.now();

                            sessionPromiseRef.current?.then(s => s.sendRealtimeInput({ media: createBlob(inputData) }));
                        };

                        // PRO ACTIVE WATCHDOG: Check for 5-second silence
                        silenceTimeoutRef.current = setInterval(() => {
                            const now = Date.now();
                            if (now - lastActivityRef.current > 5000 && !isShipraSpeaking) {
                                cleanup();
                                onClose();
                            }
                        }, 1000);
                    },
                    onmessage: async (msg: LiveServerMessage) => {
                        lastActivityRef.current = Date.now(); // Activity detected on msg
                        const audioData = msg.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
                        if (audioData) {
                            setIsShipraSpeaking(true);
                            setStatusText('Sifra is speaking...');
                            if (!outputAudioContextRef.current) {
                                outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
                            }
                            const ctx = outputAudioContextRef.current!;
                            const buffer = await decodeAudioData(decode(audioData), ctx, 24000, 1);
                            const source = ctx.createBufferSource();
                            source.buffer = buffer;
                            source.connect(ctx.destination);
                            const startTime = Math.max(ctx.currentTime, nextAudioStartTimeRef.current);
                            source.start(startTime);
                            nextAudioStartTimeRef.current = startTime + buffer.duration;
                            audioQueueRef.current.add(source);
                            source.onended = () => {
                                audioQueueRef.current.delete(source);
                                if (audioQueueRef.current.size === 0) {
                                    setIsShipraSpeaking(false);
                                    setStatusText('Listening...');
                                    lastActivityRef.current = Date.now(); // Start silence timer now
                                }
                            };
                        }
                    }
                },
                config: {
                    responseModalities: [Modality.AUDIO],
                    speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
                    systemInstruction
                }
            });
        } catch (e) { setSessionState('error'); }
    };

    useEffect(() => {
        startSession();
        return cleanup;
    }, []);

    // PREMIUM ORB ANIMATION
    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;
        canvas.width = window.innerWidth;
        canvas.height = window.innerHeight;
        const render = () => {
            ctx.fillStyle = THEME.bg;
            ctx.fillRect(0, 0, canvas.width, canvas.height);
            const cx = canvas.width / 2;
            const cy = canvas.height / 2 - 50;
            let energy = (isShipraSpeaking ? 0.3 : micEnergyRef.current) * 5;
            const time = Date.now() / 1000;
            const pulse = isShipraSpeaking ? Math.sin(time * 10) * 0.15 : Math.sin(time * 2) * 0.05;
            const radius = 80 * (1 + pulse + energy);

            // Glow
            const glowGradient = ctx.createRadialGradient(cx, cy, radius * 0.8, cx, cy, radius * 2.5);
            glowGradient.addColorStop(0, THEME.orbGlow);
            glowGradient.addColorStop(1, 'transparent');
            ctx.fillStyle = glowGradient;
            ctx.beginPath(); ctx.arc(cx, cy, radius * 2.5, 0, Math.PI * 2); ctx.fill();

            // Core Orb
            const orbGradient = ctx.createRadialGradient(cx - radius * 0.3, cy - radius * 0.3, radius * 0.1, cx, cy, radius);
            orbGradient.addColorStop(0, '#FFFFFF');
            orbGradient.addColorStop(1, '#1A1A1A');
            ctx.fillStyle = orbGradient;
            ctx.beginPath(); ctx.arc(cx, cy, radius, 0, Math.PI * 2); ctx.fill();

            animationFrameRef.current = requestAnimationFrame(render);
        };
        render();
    }, [sessionState, isShipraSpeaking]);

    return (
        <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 z-50 flex flex-col font-sans bg-[#08090F]">
            <canvas ref={canvasRef} className="absolute inset-0 w-full h-full" />
            <div className="relative z-10 flex items-center justify-between p-6">
                <button onClick={() => { cleanup(); onClose(); }} className="p-3 bg-white/5 rounded-2xl border border-white/10">
                    <ArrowLeftIcon className="w-6 h-6 text-white" />
                </button>
                <div className="text-center">
                    <span className="text-[10px] font-black tracking-[0.4em] text-white/40 uppercase">PRO-MATRIX</span>
                    <p className="text-xs text-blue-400 font-bold animate-pulse mt-1">{statusText}</p>
                </div>
                <div className="w-12" />
            </div>
            <div className="flex-1" />
            <div className="p-10 pb-16 flex flex-col items-center gap-6 relative z-10">
                <p className="text-[10px] font-black text-white/20 uppercase tracking-[0.2em]">Auto-off in 5s silence</p>
                <button onClick={() => { cleanup(); onClose(); }} className="w-20 h-20 bg-red-500 rounded-full flex items-center justify-center text-white shadow-xl shadow-red-500/20 active:scale-95 transition-transform">
                    <XMarkIcon className="w-8 h-8" />
                </button>
            </div>
        </motion.div>
    );
};

