const MONTHS = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
const DAYS_SHORT = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];

type CalendarViewMode = 'today' | 'day' | 'week' | 'month' | 'tasks';

const PRESET_COLORS = [
    { name: 'Indigo', bg: 'bg-indigo-500', shadow: 'shadow-indigo-500/20' },
    { name: 'Rose', bg: 'bg-rose-500', shadow: 'shadow-rose-500/20' },
    { name: 'Emerald', bg: 'bg-emerald-500', shadow: 'shadow-emerald-500/20' },
    { name: 'Amber', bg: 'bg-amber-500', shadow: 'shadow-amber-500/20' },
    { name: 'Sky', bg: 'bg-sky-500', shadow: 'shadow-sky-500/20' },
    { name: 'Purple', bg: 'bg-purple-500', shadow: 'shadow-purple-500/20' },
];

const PersonalCalendarView: React.FC<{ userProfile: UserProfile; onClose: () => void }> = ({ userProfile, onClose }) => {
    // Navigation Control
    const [activeTab, setActiveTab] = useState<CalendarViewMode>('today');
    const [currentDate, setCurrentDate] = useState(new Date());
    const [events, setEvents] = useLocalStorage<CalendarNote[]>(`sifra_calendar_v4_${userProfile.userId}`, []);

    // AI Assistant States
    const [assistantInput, setAssistantInput] = useState('');
    const [isAiProcessing, setIsAiProcessing] = useState(false);
    const [syncSuccess, setSyncSuccess] = useState(false);

    // Timeline Pulse State
    const [currentTime, setCurrentTime] = useState(new Date());

    useEffect(() => {
        const timer = setInterval(() => setCurrentTime(new Date()), 60000);
        return () => clearInterval(timer);
    }, []);

    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();
    const todayStr = new Date().toISOString().split('T')[0];

    // GET NEXT 3 DAYS STRING ARRAY
    const nextThreeDays = useMemo(() => {
        return [0, 1, 2].map(offset => {
            const d = new Date();
            d.setDate(d.getDate() + offset);
            return d.toISOString().split('T')[0];
        });
    }, []);

    // FILTERED VIEWS
    const dashboardEvents = useMemo(() => {
        return events
            .filter(e => nextThreeDays.includes(e.date))
            .sort((a, b) => (a.date + a.time).localeCompare(b.date + b.time));
    }, [events, nextThreeDays]);

    const pendingTasks = useMemo(() => {
        return events.filter(e => e.type === 'task' && !e.isCompleted);
    }, [events]);

    // CORE AI SYNC HANDLER
    const handleAiSync = async () => {
        if (!assistantInput.trim()) return;
        setIsAiProcessing(true);
        try {
            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
            const response = await ai.models.generateContent({
                model: 'gemini-3-flash-preview',
                contents: `Context: Sifra Calendar Assistant. Today: ${new Date().toDateString()}.
                          Task: Extract event/task from: "${assistantInput}". 
                          Return JSON object with fields: title, date (YYYY-MM-DD), time (HH:mm), type (event/task/meet), location.`,
                config: {
                    responseMimeType: 'application/json',
                    responseSchema: {
                        type: Type.OBJECT,
                        properties: {
                            title: { type: Type.STRING },
                            date: { type: Type.STRING },
                            time: { type: Type.STRING },
                            type: { type: Type.STRING },
                            location: { type: Type.STRING }
                        },
                        required: ['title', 'date', 'time', 'type']
                    }
                }
            });

            const data = JSON.parse(response.text);
            const newNode: CalendarNote = {
                id: `node-${Date.now()}`,
                title: data.title,
                date: data.date || todayStr,
                time: data.time || '12:00',
                type: data.type as EventType,
                content: assistantInput,
                isSpecial: false,
                color: PRESET_COLORS[Math.floor(Math.random() * PRESET_COLORS.length)].bg,
                participants: []
            };

            setEvents(prev => [...prev, newNode]);
            setAssistantInput('');
            setSyncSuccess(true);
            setTimeout(() => setSyncSuccess(false), 3000);
        } catch (e) {
            alert("Neural connection unstable. Please use standard entry.");
        } finally {
            setIsAiProcessing(false);
        }
    };

    const renderEventCard = (evt: CalendarNote, showDate: boolean = false) => (
        <motion.div 
            layout
            key={evt.id}
            initial={{ opacity: 0, x: -10 }}
            animate={{ opacity: 1, x: 0 }}
            className="w-full relative group cursor-pointer"
        >
            <div className="relative bg-white/[0.04] border border-white/10 backdrop-blur-3xl rounded-[2rem] p-6 flex flex-col gap-4 shadow-xl hover:bg-white/[0.08] transition-all">
                <div className="flex justify-between items-start">
                    <div className="flex items-center gap-4">
                        <div className={`w-1.5 h-10 rounded-full ${evt.color || 'bg-indigo-500'} shadow-lg`} />
                        <div>
                            {showDate && <p className="text-[8px] font-black text-indigo-400 uppercase tracking-widest mb-0.5">{evt.date}</p>}
                            <p className="text-[10px] font-black text-white/30 uppercase tracking-[0.3em] mb-1">{evt.time}</p>
                            <h4 className="text-lg font-bold text-white tracking-tight leading-tight">{evt.title}</h4>
                        </div>
                    </div>
                    <div className={`px-4 py-1.5 rounded-full text-[8px] font-black uppercase tracking-widest ${evt.type === 'meet' ? 'bg-indigo-500/30 text-indigo-400' : evt.type === 'task' ? 'bg-emerald-500/30 text-emerald-400' : 'bg-sky-500/30 text-sky-400'}`}>
                        {evt.type}
                    </div>
                </div>
                {evt.location && (
                    <div className="flex items-center gap-2 text-white/40 text-xs px-2">
                        <MapPinIcon className="w-3.5 h-3.5" />
                        <span className="truncate">{evt.location}</span>
                    </div>
                )}
            </div>
        </motion.div>
    );

    const renderTodayDashboard = () => (
        <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex-1 flex flex-col gap-10">
            {/* GREETING & DATE */}
            <div className="flex justify-between items-end px-2">
                 <div>
                    <h2 className="text-4xl font-black italic tracking-tighter uppercase leading-none mb-1">Timeline</h2>
                    <p className="text-[10px] font-black text-white/20 uppercase tracking-[0.4em]">Personal Node Hub</p>
                 </div>
                 <div className="text-right">
                     <span className="text-xs font-black text-rose-500 uppercase tracking-widest block">{MONTHS[month]}</span>
                     <span className="text-3xl font-black text-white tracking-tighter">{new Date().getDate()}</span>
                 </div>
            </div>

            {/* "HOW CAN I HELP YOU" AI HUB */}
            <div className="relative group">
                <div className="absolute -inset-1 bg-gradient-to-r from-indigo-500 via-purple-500 to-pink-500 rounded-[2.5rem] blur opacity-20 group-focus-within:opacity-100 transition duration-1000"></div>
                <div className="relative bg-[#1A1C22]/90 backdrop-blur-2xl border border-white/10 rounded-[2.5rem] p-6 shadow-2xl flex flex-col gap-4">
                    <div className="flex items-center justify-between">
                        <div className="flex items-center gap-3">
                            <SparklesIcon className="w-5 h-5 text-indigo-400" />
                            <h3 className="text-xs font-black text-white/80 uppercase tracking-widest">How can I help you?</h3>
                        </div>
                        {syncSuccess && <span className="text-[10px] font-black text-emerald-400 uppercase tracking-widest animate-pulse">Sync Complete</span>}
                    </div>
                    <div className="flex items-center gap-3">
                        <input 
                            value={assistantInput}
                            onChange={e => setAssistantInput(e.target.value)}
                            onKeyDown={e => e.key === 'Enter' && handleAiSync()}
                            placeholder="Add node... (e.g. 'Gym tomorrow at 6am')"
                            className="flex-1 bg-transparent text-lg font-bold text-white placeholder:text-white/10 outline-none"
                        />
                        <button 
                            onClick={handleAiSync}
                            disabled={isAiProcessing || !assistantInput.trim()}
                            className={`p-4 rounded-3xl transition-all shadow-xl flex items-center justify-center gap-2 ${isAiProcessing ? 'bg-indigo-600/50' : 'bg-indigo-600 active:scale-90 hover:bg-indigo-500'}`}
                        >
                            {isAiProcessing ? (
                                <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                            ) : (
                                <><PlusCircleIcon className="w-5 h-5" /> <span className="text-[9px] font-black uppercase tracking-widest pr-1">Commit Sync</span></>
                            )}
                        </button>
                    </div>
                </div>
            </div>

            {/* NEXT 3 DAYS SEQUENCE */}
            <section className="space-y-6">
                <div className="flex items-center justify-between px-4">
                    <h3 className="text-[11px] font-black text-white/30 uppercase tracking-[0.5em]">72H Sequence</h3>
                    <span className="text-[9px] font-black text-indigo-400 uppercase tracking-widest">Upcoming Matrix</span>
                </div>
                <div className="space-y-4">
                    {dashboardEvents.length > 0 ? (
                        dashboardEvents.map(e => renderEventCard(e, e.date !== todayStr))
                    ) : (
                        <div className="py-20 text-center opacity-10 flex flex-col items-center gap-4">
                            <CalendarIcon className="w-12 h-12" />
                            <p className="text-sm font-black uppercase tracking-widest">No nodes in the next 72h</p>
                        </div>
                    )}
                </div>
            </section>
        </motion.div>
    );

    const renderDayTimeline = () => {
        const dStr = currentDate.toISOString().split('T')[0];
        const dayEvents = events.filter(e => e.date === dStr).sort((a,b) => a.time.localeCompare(b.time));
        const hours = Array.from({ length: 24 }, (_, i) => i);

        // Calculate blue line position
        const isSelectedToday = dStr === todayStr;
        const currentHour = currentTime.getHours();
        const currentMinutes = currentTime.getMinutes();
        const linePos = ((currentHour * 60 + currentMinutes) / 1440) * 100;

        return (
