                <div className="flex-1 overflow-y-auto premium-scroll relative pr-2">
                    {/* THE TIME GRID */}
                    <div className="relative">
                        {hours.map(h => (
                            <div key={h} className="h-28 border-t border-white/[0.03] flex group relative">
                                <div className="w-20 flex-none flex justify-center pt-3">
                                    <span className={`text-[11px] font-black tracking-tighter uppercase ${h === currentHour && isSelectedToday ? 'text-blue-400' : 'text-white/10'}`}>
                                        {h.toString().padStart(2, '0')}:00
                                    </span>
                                </div>
                                <div className="flex-1 relative pt-2">
                                    {dayEvents.filter(e => parseInt(e.time.split(':')[0]) === h).map(evt => (
                                        <div key={evt.id} className={`p-4 rounded-3xl border border-white/10 backdrop-blur-2xl shadow-xl ${evt.color || 'bg-indigo-600/20'} cursor-pointer mb-2`}>
                                            <h5 className="text-sm font-bold text-white truncate">{evt.title}</h5>
                                            <p className="text-[10px] text-white/40 font-black uppercase">{evt.time}</p>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        ))}

                        {/* THE BLUE PULSE LINE */}
                        {isSelectedToday && (
                            <motion.div 
                                initial={false}
                                animate={{ top: `${linePos}%` }}
                                className="absolute left-20 right-0 h-[2px] bg-blue-500/80 z-[20] pointer-events-none"
                            >
                                <div className="w-4 h-4 rounded-full bg-blue-500 absolute -left-2 -top-1.5 shadow-[0_0_20px_#3b82f6] border-2 border-white/20 animate-pulse" />
                                <div className="absolute right-4 -top-3 bg-blue-500 text-[8px] font-black px-2 py-0.5 rounded-full shadow-lg">LIVE FLUX</div>
                            </motion.div>
                        )}
                    </div>
                    <div className="h-40" />
                </div>
            </motion.div>
        );
    };

    const renderTasksView = () => (
        <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="flex-1 flex flex-col gap-8">
            <div className="flex items-center justify-between px-2">
                <h2 className="text-3xl font-black tracking-tighter uppercase italic leading-none">Task Queue</h2>
                <div className="p-2.5 bg-emerald-500/10 rounded-2xl border border-emerald-500/20 text-emerald-400 text-[10px] font-black uppercase tracking-widest">Active Stack</div>
            </div>

            <div className="space-y-4">
                {pendingTasks.length > 0 ? (
                    pendingTasks.map(t => (
                        <div key={t.id} className="p-6 rounded-[2.5rem] bg-white/[0.03] border border-white/10 flex items-center justify-between group">
                            <div className="flex items-center gap-5">
                                <button 
                                    onClick={() => setEvents(prev => prev.map(ev => ev.id === t.id ? {...ev, isCompleted: true} : ev))}
                                    className="w-10 h-10 rounded-2xl border-2 border-emerald-500/30 flex items-center justify-center text-transparent hover:text-emerald-400 transition-all"
                                >
                                    <CheckCircleIcon className="w-6 h-6" />
                                </button>
                                <div>
                                    <h4 className="text-lg font-bold text-white">{t.title}</h4>
                                    <p className="text-[10px] font-black text-white/20 uppercase tracking-widest mt-0.5">{t.date} @ {t.time}</p>
                                </div>
                            </div>
                            <button onClick={() => setEvents(prev => prev.filter(ev => ev.id !== t.id))} className="p-3 bg-rose-500/10 rounded-2xl text-rose-500 opacity-0 group-hover:opacity-100 transition-opacity"><TrashIcon className="w-4 h-4" /></button>
                        </div>
                    ))
                ) : (
                    <div className="py-32 text-center opacity-10 flex flex-col items-center gap-4">
                        <CheckCircleIcon className="w-16 h-16" />
                        <p className="text-xl font-black uppercase tracking-widest">All Tasks Synchronized</p>
                    </div>
                )}
            </div>
        </motion.div>
    );

    return (
        <div className="fixed inset-0 z-[250] bg-[#0F1115] text-white flex flex-col font-sans overflow-hidden selection:bg-indigo-500/30">
            {/* AMBIENT AURAS */}
            <div className="absolute inset-0 pointer-events-none opacity-40">
                <div className="absolute top-0 left-0 w-full h-[60vh] bg-gradient-to-b from-indigo-900/30 to-transparent" />
