                <div className="absolute inset-0 bg-[url('https://grainy-gradients.vercel.app/noise.svg')] opacity-10 contrast-150 brightness-50" />
            </div>

            {/* TOP NAVIGATION */}
            <header className="p-8 pb-4 relative z-[260] space-y-10 backdrop-blur-3xl bg-[#0F1115]/60 border-b border-white/5">
                <div className="flex items-center justify-between">
                    <button onClick={onClose} className="p-4 bg-white/5 rounded-3xl border border-white/10 active:scale-90 shadow-inner">
                        <ArrowLeftIcon className="w-7 h-7 text-white/60" />
                    </button>
                    <div className="flex items-center gap-1.5 p-1.5 bg-white/5 rounded-[1.8rem] border border-white/10 shadow-inner">
                        {(['today', 'day', 'month', 'tasks'] as CalendarViewMode[]).map(m => (
                            <button 
                                key={m}
                                onClick={() => setActiveTab(m)}
                                className={`px-6 py-2.5 rounded-2xl text-[9px] font-black uppercase tracking-[0.2em] transition-all ${activeTab === m ? 'bg-indigo-600 text-white shadow-xl' : 'text-gray-400 hover:text-white'}`}
                            >
                                {m}
                            </button>
                        ))}
                    </div>
                    <button className="p-4 bg-white/5 rounded-3xl border border-white/10 active:scale-90">
                         <BellIcon className="w-7 h-7 text-white/20" />
                    </button>
                </div>
            </header>

            {/* MAIN AREA */}
            <main className="flex-1 overflow-y-auto premium-scroll px-8 pt-10 relative z-10 pb-48">
                <AnimatePresence mode="wait">
                    {activeTab === 'today' && renderTodayDashboard()}
                    {activeTab === 'day' && renderDayTimeline()}
                    {activeTab === 'tasks' && renderTasksView()}
                    {activeTab === 'month' && (
                        <div className="flex flex-col gap-8 animate-fade-in">
                            <h2 className="text-3xl font-black italic uppercase tracking-tighter text-center">{MONTHS[month]} {year}</h2>
                            <div className="grid grid-cols-7 gap-3">
                                {DAYS_SHORT.map(d => <div key={d} className="text-center text-[10px] font-black text-white/10 uppercase tracking-widest">{d}</div>)}
                                {Array.from({ length: 31 }, (_, i) => i + 1).map(day => (
                                    <button 
                                        key={day} 
                                        onClick={() => { setCurrentDate(new Date(year, month, day)); setActiveTab('day'); }}
                                        className={`aspect-square rounded-2xl flex flex-col items-center justify-center border ${day === new Date().getDate() ? 'bg-indigo-600 border-indigo-400 shadow-xl' : 'bg-white/5 border-white/5 hover:bg-white/10'}`}
                                    >
                                        <span className="text-sm font-black">{day}</span>
                                    </button>
                                ))}
                            </div>
                        </div>
                    )}
                </AnimatePresence>
            </main>

            {/* NAVIGATION BAR */}
            <footer className="fixed bottom-0 left-0 w-full h-40 bg-gradient-to-t from-black via-[#0F1115] to-transparent pointer-events-none z-[300]">
                <div className="absolute bottom-10 left-1/2 -translate-x-1/2 w-[92%] max-w-sm h-20 bg-[#1A1C22]/95 backdrop-blur-3xl border border-white/10 rounded-full flex items-center justify-evenly px-6 pointer-events-auto shadow-[0_30px_60px_rgba(0,0,0,1)]">
                    <button onClick={() => setActiveTab('today')} className={`p-4 rounded-2xl transition-all ${activeTab === 'today' ? 'bg-indigo-600 text-white shadow-2xl scale-110' : 'text-white/20'}`}><HomeIcon className="w-6 h-6" /></button>
                    <button onClick={() => setActiveTab('day')} className={`p-4 rounded-2xl transition-all ${activeTab === 'day' ? 'bg-indigo-600 text-white shadow-2xl scale-110' : 'text-white/20'}`}><CalendarIcon className="w-6 h-6" /></button>
                    <button onClick={() => setActiveTab('tasks')} className={`p-4 rounded-2xl transition-all ${activeTab === 'tasks' ? 'bg-indigo-600 text-white shadow-2xl scale-110' : 'text-white/20'}`}><CheckCircleIcon className="w-6 h-6" /></button>
                    <button onClick={onClose} className="p-4 text-white/10"><UserIcon className="w-6 h-6" /></button>
                </div>
            </footer>

            <style>{`
                .premium-scroll::-webkit-scrollbar { display: none; }
                .premium-scroll { -ms-overflow-style: none; scrollbar-width: none; }
            `}</style>
        </div>
    );
};

