import React, { useState, useEffect, useRef, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { UserProfile } from '../types';
import ArrowLeftIcon from '../components/icons/ArrowLeftIcon';
import XMarkIcon from '../components/icons/XMarkIcon';
import CameraIcon from '../components/icons/CameraIcon';
import SparklesIcon from '../components/icons/SparklesIcon';
import BoltIcon from '../components/icons/BoltIcon';
import SifraLogo from '../components/SifraLogo';

type CameraMode = 'PHOTO' | 'VIDEO' | 'PORTRAIT' | 'PRO' | 'DUAL';

const SifraCameraView: React.FC<{ userProfile: UserProfile; onClose: () => void }> = ({ userProfile, onClose }) => {
    const [mode, setMode] = useState<CameraMode>('PHOTO');
    const [isFrontCamera, setIsFrontCamera] = useState(false);
    const [isFlashActive, setIsFlashActive] = useState(false);
    const [isCapturing, setIsCapturing] = useState(false);
    const [lastCapture, setLastCapture] = useState<string | null>(null);
    const [permissionError, setPermissionError] = useState<string | null>(null);
    const [isActivating, setIsActivating] = useState(false);

    const videoRef = useRef<HTMLVideoElement>(null);
    const streamRef = useRef<MediaStream | null>(null);

    const stopStreams = useCallback(() => {
        if (streamRef.current) {
            streamRef.current.getTracks().forEach(t => {
                t.stop();
                t.enabled = false;
            });
            streamRef.current = null;
        }
        if (videoRef.current) {
            videoRef.current.srcObject = null;
        }
    }, []);

    const startCamera = useCallback(async (isFront: boolean) => {
        stopStreams();
        setPermissionError(null);
        setIsActivating(true);

        try {
            // First attempt with preferred constraints
            const constraints = {
                video: {
                    facingMode: isFront ? 'user' : 'environment',
                    width: { ideal: 1920 },
                    height: { ideal: 1080 }
                },
                audio: mode === 'VIDEO'
            };

            let stream: MediaStream;
            try {
                stream = await navigator.mediaDevices.getUserMedia(constraints);
            } catch (initialErr) {
                console.warn("Initial lens link failed, trying fallback constraints...", initialErr);
                // Fallback to basic constraints if advanced ones fail
                stream = await navigator.mediaDevices.getUserMedia({ 
                    video: true, 
                    audio: mode === 'VIDEO' 
                });
            }

            streamRef.current = stream;
            if (videoRef.current) {
                videoRef.current.srcObject = stream;
            }
        } catch (err: any) {
            console.error("Lens Initialization Error:", err);
            if (err.name === 'NotAllowedError' || err.name === 'PermissionDeniedError') {
                setPermissionError("Access Denied. Please grant camera permissions in your browser settings and try again.");
            } else if (err.name === 'NotFoundError' || err.name === 'DevicesNotFoundError') {
                setPermissionError("No camera hardware detected on this device.");
            } else {
                setPermissionError("Neural link to lens failed. " + (err.message || "Unknown hardware error."));
            }
        } finally {
            setIsActivating(false);
        }
    }, [mode, stopStreams]);

    useEffect(() => {
        startCamera(isFrontCamera);
        return () => stopStreams();
    }, [isFrontCamera, mode, startCamera, stopStreams]);

    const capturePhoto = () => {
        if (!videoRef.current || isCapturing || !!permissionError) return;
        setIsCapturing(true);

        const canvas = document.createElement('canvas');
        canvas.width = videoRef.current.videoWidth;
        canvas.height = videoRef.current.videoHeight;
        const ctx = canvas.getContext('2d');
        if (ctx) {
            if (isFrontCamera) {
                ctx.translate(canvas.width, 0);
                ctx.scale(-1, 1);
            }
            ctx.drawImage(videoRef.current, 0, 0);
            setLastCapture(canvas.toDataURL('image/jpeg', 0.9));
        }

        // Shutter feedback
        const shutter = new Audio('https://assets.mixkit.co/sfx/preview/mixkit-camera-shutter-click-1133.mp3');
        shutter.volume = 0.5;
        shutter.play().catch(() => {});

        setTimeout(() => setIsCapturing(false), 150);
    };

    return (
        <div className="fixed inset-0 z-[250] bg-black text-white flex flex-col font-sans overflow-hidden">
            <AnimatePresence>
                {permissionError && (
                    <motion.div 
                        initial={{ opacity: 0 }} 
                        animate={{ opacity: 1 }} 
                        exit={{ opacity: 0 }}
                        className="absolute inset-0 z-[100] bg-black/95 backdrop-blur-3xl flex flex-col items-center justify-center p-10 text-center"
                    >
                        <div className="w-20 h-20 bg-rose-500/10 rounded-full flex items-center justify-center mb-8 border border-rose-500/30">
                            <XMarkIcon className="w-10 h-10 text-rose-500" />
                        </div>
                        <h2 className="text-xl font-black uppercase italic tracking-widest text-rose-400">Hardware Blocked</h2>
                        <p className="text-sm text-white/60 mt-4 leading-relaxed max-w-xs">{permissionError}</p>
                        <div className="flex flex-col gap-3 w-full max-w-xs mt-10">
                            <button 
                                onClick={() => startCamera(isFrontCamera)} 
                                className="px-10 py-5 bg-white text-black rounded-[2rem] font-black uppercase tracking-widest active:scale-95 transition-all shadow-xl"
                            >
                                Retry Link
                            </button>
                            <button 
                                onClick={onClose} 
                                className="py-4 text-xs font-bold text-white/30 uppercase tracking-widest hover:text-white transition-colors"
                            >
                                Dismiss Matrix
                            </button>
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>

            <header className="absolute top-0 left-0 w-full p-6 flex items-center justify-between z-30 bg-gradient-to-b from-black/80 to-transparent">
                <button onClick={onClose} className="p-3 bg-white/10 rounded-2xl backdrop-blur-md border border-white/10 active:scale-90 transition-all"><XMarkIcon className="w-6 h-6" /></button>
                <div className="flex items-center gap-4 bg-white/10 backdrop-blur-md px-5 py-2.5 rounded-full border border-white/10">
                    <button onClick={() => setIsFlashActive(!isFlashActive)} className={`p-1 transition-all ${isFlashActive ? 'text-yellow-400 drop-shadow-[0_0_8px_#facc15]' : 'text-white/40'}`}><BoltIcon className="w-5 h-5" /></button>
                    <div className="h-4 w-[1px] bg-white/20 mx-1" />
                    <span className="text-[10px] font-black uppercase tracking-[0.2em] text-white/90">{mode}</span>
                </div>
                <button onClick={() => setIsFrontCamera(!isFrontCamera)} className="p-3 bg-white/10 rounded-2xl backdrop-blur-md border border-white/10 active:scale-90 transition-all">
                    <svg className="w-6 h-6 text-white/80" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" /></svg>
                </button>
            </header>

            <main className="flex-1 relative bg-[#020202] overflow-hidden flex items-center justify-center">
                <video 
                    ref={videoRef} 
                    autoPlay 
                    playsInline 
                    muted
                    className={`w-full h-full object-cover transition-all duration-700 ${isFrontCamera ? 'scale-x-[-1]' : ''} ${isCapturing ? 'brightness-150 scale-[1.02]' : 'brightness-100'}`} 
                />
                <AnimatePresence>
                    {isActivating && (
                        <motion.div 
                            initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
                            className="absolute inset-0 flex flex-col items-center justify-center bg-black/60 backdrop-blur-sm z-20"
                        >
                            <div className="w-12 h-12 border-[3px] border-indigo-500/30 border-t-indigo-500 rounded-full animate-spin" />
                            <p className="mt-4 text-[10px] font-black uppercase tracking-[0.3em] text-indigo-400">Syncing Lens...</p>
                        </motion.div>
                    )}
                </AnimatePresence>
            </main>

            <footer className="h-64 bg-black flex flex-col items-center justify-between pb-12 shrink-0 border-t border-white/5 relative z-30">
                <div className="w-full flex justify-center pt-8 pb-4 overflow-x-auto no-scrollbar scroll-smooth">
                    <div className="flex gap-10 px-32">
                        {(['PHOTO', 'VIDEO', 'PORTRAIT', 'DUAL', 'PRO'] as CameraMode[]).map(m => (
                            <button 
                                key={m} 
                                onClick={() => setMode(m)} 
                                className={`text-[12px] font-black uppercase tracking-[0.3em] transition-all whitespace-nowrap active:opacity-60 ${mode === m ? 'text-indigo-400 scale-110 drop-shadow-[0_0_12px_rgba(129,140,248,0.5)]' : 'text-white/20 hover:text-white/40'}`}
                            >
                                {m}
                            </button>
                        ))}
                    </div>
                </div>
                <div className="w-full flex items-center justify-between max-w-sm px-10">
                    <button className="w-16 h-16 rounded-[1.5rem] bg-white/5 border border-white/10 overflow-hidden active:scale-90 transition-transform">
                        {lastCapture ? <img src={lastCapture} className="w-full h-full object-cover" /> : <div className="w-full h-full flex items-center justify-center opacity-10"><CameraIcon className="w-7 h-7" /></div>}
                    </button>
                    <motion.button 
                        whileTap={{ scale: 0.9 }} 
                        onClick={capturePhoto} 
                        className="w-24 h-24 rounded-full border-[5px] border-white/20 flex items-center justify-center transition-all shadow-[0_0_30px_rgba(255,255,255,0.1)]"
                    >
                        <div className="w-18 h-18 rounded-full bg-white shadow-xl" />
                    </motion.button>
                    <button className="w-16 h-16 rounded-[1.5rem] bg-indigo-500/10 border border-indigo-500/20 flex items-center justify-center text-indigo-400 active:scale-90 transition-transform">
                        <SparklesIcon className="w-7 h-7" />
                    </button>
                </div>
            </footer>
        </div>
    );
};

