import React, { useState } from 'react';
import { useLocalStorage } from '../hooks/useLocalStorage';
import { UserProfile } from '../types';
import BoltIcon from '../components/icons/BoltIcon';
import UserIcon from '../components/icons/UserIcon';

interface LoginViewProps {
    onLoginSuccess: (user: UserProfile) => void;
}

const LoginView: React.FC<LoginViewProps> = ({ onLoginSuccess }) => {
    const [view, setView] = useState<'login' | 'register'>('login');
    const [name, setName] = useState('');
    const [email, setEmail] = useState('');
    const [info, setInfo] = useState<{ type: 'success' | 'error' | 'info'; message: string } | null>(null);
    const [allUsers, setAllUsers] = useLocalStorage<UserProfile[]>('sifra_all_users', []);

    const generateSifraId = (): string => {
        const digits = '0123456789';
        const letters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
        return `${digits[Math.floor(Math.random() * 10)]}${digits[Math.floor(Math.random() * 10)]}${letters[Math.floor(Math.random() * 26)]}${digits[Math.floor(Math.random() * 10)]}${digits[Math.floor(Math.random() * 10)]}`;
    };

    const handleLogin = (e: React.FormEvent) => {
        e.preventDefault();
        const foundUser = allUsers.find(u => u.email?.toLowerCase() === email.toLowerCase() && u.name === name);
        if (foundUser) {
            onLoginSuccess(foundUser);
        } else {
            setInfo({ type: 'error', message: 'No account found. Check details or register.' });
        }
    };

    const handleGuestLogin = () => {
        const guestUser: UserProfile = {
            name: 'Guest User',
            nickname: 'Guest',
            email: 'guest@sifra.local',
            avatar: null,
            themeId: 'default',
            sifraAvatarId: 'cute',
            saveHistory: false,
            userId: 'GUEST-' + generateSifraId(),
            joinDate: new Date().toISOString(),
            status: 'active',
            lastLogin: new Date().toISOString(),
            moodAmbienceEnabled: false,
        };
        onLoginSuccess(guestUser);
    };

    const handleRegister = (e: React.FormEvent) => {
        e.preventDefault();
        if (allUsers.some(u => u.email?.toLowerCase() === email.toLowerCase())) {
            setInfo({ type: 'error', message: 'Email already registered.' });
            return;
        }
        const newUser: UserProfile = {
            name: name.trim(),
            nickname: null,
            email: email.trim().toLowerCase(),
            avatar: null,
            themeId: 'default',
            sifraAvatarId: 'cute',
            saveHistory: true,
            userId: generateSifraId(),
            joinDate: new Date().toISOString(),
            status: 'active',
            lastLogin: new Date().toISOString(),
            moodAmbienceEnabled: false,
        };
        setAllUsers([...allUsers, newUser]);
        onLoginSuccess(newUser);
    };

    return (
        <div className="w-screen h-screen bg-gradient-to-br from-indigo-900 via-slate-900 to-black flex items-center justify-center p-4 font-sans selection:bg-cyan-500/30">
            <div className="w-full max-w-md bg-white/5 backdrop-blur-3xl p-10 rounded-[3rem] border border-white/10 shadow-2xl transition-all duration-500 animate-fade-in-up relative overflow-hidden">
                <div className="absolute top-0 right-0 p-8 opacity-10">
                    <BoltIcon className="w-20 h-20 text-cyan-400" />
                </div>

                <div className="text-center mb-10 relative z-10">
                    <h1 className="text-5xl font-black text-white italic tracking-tighter mb-2">SIFRA</h1>
                    <p className="text-[10px] font-black text-cyan-500 uppercase tracking-[0.6em]">Neural Engine v3.0</p>
                </div>

                {view === 'login' ? (
                    <form onSubmit={handleLogin} className="space-y-4 relative z-10">
                        <input type="text" value={name} onChange={e => setName(e.target.value)} placeholder="Neural Carrier Name" className="w-full p-4 bg-white/5 border border-white/10 rounded-2xl text-white outline-none focus:border-cyan-500 transition-all placeholder:text-white/20" required />
                        <input type="email" value={email} onChange={e => setEmail(e.target.value)} placeholder="Frequency Identifier (Email)" className="w-full p-4 bg-white/5 border border-white/10 rounded-2xl text-white outline-none focus:border-cyan-500 transition-all placeholder:text-white/20" required />
                        <button type="submit" className="w-full py-4 bg-white text-black font-black uppercase tracking-widest rounded-2xl shadow-xl hover:scale-105 active:scale-95 transition-all">Link Session</button>

                        <div className="pt-4 flex flex-col gap-3">
                            <button type="button" onClick={handleGuestLogin} className="w-full py-3 bg-cyan-500/10 border border-cyan-500/30 text-cyan-400 font-bold uppercase tracking-widest rounded-xl flex items-center justify-center gap-2 hover:bg-cyan-500/20 transition-all">
                                <UserIcon className="w-4 h-4" /> Guest Mode
                            </button>
                            <button type="button" onClick={() => setView('register')} className="text-[10px] text-white/40 font-bold uppercase tracking-widest hover:text-cyan-400 text-center">Initialize New Link</button>
                        </div>
                    </form>
                ) : (
                     <form onSubmit={handleRegister} className="space-y-4 relative z-10">
                        <input type="text" value={name} onChange={e => setName(e.target.value)} placeholder="Choose Identity" className="w-full p-4 bg-white/5 border border-white/10 rounded-2xl text-white outline-none focus:border-cyan-500 transition-all placeholder:text-white/20" required />
                        <input type="email" value={email} onChange={e => setEmail(e.target.value)} placeholder="Email Vector" className="w-full p-4 bg-white/5 border border-white/10 rounded-2xl text-white outline-none focus:border-cyan-500 transition-all placeholder:text-white/20" required />
                        <button type="submit" className="w-full py-4 bg-cyan-500 text-black font-black uppercase tracking-widest rounded-2xl shadow-xl hover:scale-105 transition-all">Deploy Account</button>
                        <div className="text-center text-[10px] text-white/40 font-bold uppercase tracking-widest pt-4">
                             <button type="button" onClick={() => setView('login')} className="hover:text-cyan-400">Return to Link</button>
                        </div>
                    </form>
                )}
                {info && <p className={`text-xs text-center mt-6 font-bold uppercase tracking-widest ${info.type === 'error' ? 'text-rose-500' : 'text-emerald-400'}`}>{info.message}</p>}
            </div>
        </div>
    );
};

