import React, { useState } from 'react';
import { useLocalStorage } from '../hooks/useLocalStorage';
import { UserProfile } from '../types';
import BoltIcon from '../components/icons/BoltIcon';
import UserIcon from '../components/icons/UserIcon';
import SparklesIcon from '../components/icons/SparklesIcon';

interface LoginViewProps {
    onLoginSuccess: (user: UserProfile) => void;
}

const LoginView: React.FC<LoginViewProps> = ({ onLoginSuccess }) => {
    const [view, setView] = useState<'login' | 'register'>('login');
    const [name, setName] = useState('');
    const [email, setEmail] = useState('');
    const [info, setInfo] = useState<{ type: 'success' | 'error' | 'info'; message: string } | null>(null);
    const [allUsers, setAllUsers] = useLocalStorage<UserProfile[]>('sifra_all_users', []);

    const generateSifraId = (prefix: string = ''): string => {
        const digits = '0123456789';
        const letters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
        const suffix = `${digits[Math.floor(Math.random() * 10)]}${digits[Math.floor(Math.random() * 10)]}${letters[Math.floor(Math.random() * 26)]}${digits[Math.floor(Math.random() * 10)]}${digits[Math.floor(Math.random() * 10)]}`;
        return prefix ? `${prefix}-${suffix}` : suffix;
    };

    const handleLogin = (e: React.FormEvent) => {
        e.preventDefault();
        const foundUser = allUsers.find(u => u.email?.toLowerCase() === email.toLowerCase() && u.name === name);
        if (foundUser) {
            onLoginSuccess(foundUser);
        } else {
            setInfo({ type: 'error', message: 'No account found. Check details or register.' });
        }
    };

    const handleGuestEntry = () => {
        const guestUser: UserProfile = {
            name: 'Guest User',
            nickname: 'Guest',
            email: 'guest@sifra.local',
            avatar: null,
            themeId: 'default',
            sifraAvatarId: 'cute',
            saveHistory: false,
            userId: generateSifraId('GUEST'),
            joinDate: new Date().toISOString(),
            status: 'active',
            lastLogin: new Date().toISOString(),
            moodAmbienceEnabled: false,
        };
        onLoginSuccess(guestUser);
    };

    const handleRegister = (e: React.FormEvent) => {
        e.preventDefault();
        if (allUsers.some(u => u.email?.toLowerCase() === email.toLowerCase())) {
            setInfo({ type: 'error', message: 'Email already registered.' });
            return;
        }
        const newUser: UserProfile = {
            name: name.trim(),
            nickname: null,
            email: email.trim().toLowerCase(),
            avatar: null,
            themeId: 'default',
            sifraAvatarId: 'cute',
            saveHistory: true,
            userId: generateSifraId(),
            joinDate: new Date().toISOString(),
            status: 'active',
            lastLogin: new Date().toISOString(),
            moodAmbienceEnabled: false,
        };
        setAllUsers([...allUsers, newUser]);
        onLoginSuccess(newUser);
    };

    return (
        <div className="w-screen h-screen bg-gradient-to-br from-indigo-900 via-slate-900 to-black flex items-center justify-center p-4 font-sans selection:bg-cyan-500/30">
            <div className="w-full max-w-md bg-white/5 backdrop-blur-3xl p-10 rounded-[3rem] border border-white/10 shadow-2xl transition-all duration-500 animate-fade-in-up relative overflow-hidden">
                <div className="absolute top-0 right-0 p-8 opacity-10">
                    <BoltIcon className="w-20 h-20 text-cyan-400" />
                </div>

                <div className="text-center mb-10 relative z-10">
                    <h1 className="text-5xl font-black text-white italic tracking-tighter mb-2">SIFRA</h1>
                    <p className="text-[10px] font-black text-cyan-500 uppercase tracking-[0.6em]">Neural Engine v3.0</p>
                </div>

                {view === 'login' ? (
                    <div className="space-y-4 relative z-10">
                        <form onSubmit={handleLogin} className="space-y-4">
                            <input type="text" value={name} onChange={e => setName(e.target.value)} placeholder="Neural Carrier Name" className="w-full p-4 bg-white/5 border border-white/10 rounded-2xl text-white outline-none focus:border-cyan-500 transition-all placeholder:text-white/20" required />
                            <input type="email" value={email} onChange={e => setEmail(e.target.value)} placeholder="Frequency Identifier (Email)" className="w-full p-4 bg-white/5 border border-white/10 rounded-2xl text-white outline-none focus:border-cyan-500 transition-all placeholder:text-white/20" required />
                            <button type="submit" className="w-full py-4 bg-white text-black font-black uppercase tracking-widest rounded-2xl shadow-xl hover:scale-105 active:scale-95 transition-all">Link Session</button>
                        </form>

                        <div className="pt-2 flex flex-col gap-3">
                            <button 
                                onClick={handleGuestEntry}
                                className="group w-full py-4 bg-cyan-500/10 border border-cyan-500/20 rounded-2xl flex items-center justify-center gap-3 hover:bg-cyan-500/20 transition-all active:scale-95 shadow-lg"
                            >
                                <SparklesIcon className="w-4 h-4 text-cyan-400 group-hover:animate-spin" />
                                <span className="text-xs font-black text-cyan-400 uppercase tracking-widest">Enter Guest Mode</span>
                            </button>
                            <button 
                                type="button" 
                                onClick={() => setView('register')} 
                                className="text-[10px] text-white/40 font-bold uppercase tracking-widest hover:text-cyan-400 text-center transition-colors"
                            >
                                Initialize New Link
                            </button>
                        </div>
                    </div>
                ) : (
                     <form onSubmit={handleRegister} className="space-y-4 relative z-10">
                        <input type="text" value={name} onChange={e => setName(e.target.value)} placeholder="Choose Identity" className="w-full p-4 bg-white/5 border border-white/10 rounded-2xl text-white outline-none focus:border-cyan-500 transition-all placeholder:text-white/20" required />
                        <input type="email" value={email} onChange={e => setEmail(e.target.value)} placeholder="Email Vector" className="w-full p-4 bg-white/5 border border-white/10 rounded-2xl text-white outline-none focus:border-cyan-500 transition-all placeholder:text-white/20" required />
                        <button type="submit" className="w-full py-4 bg-cyan-500 text-black font-black uppercase tracking-widest rounded-2xl shadow-xl hover:scale-105 transition-all">Deploy Account</button>
                        <div className="text-center text-[10px] text-white/40 font-bold uppercase tracking-widest pt-4">
                             <button type="button" onClick={() => setView('login')} className="hover:text-cyan-400 transition-colors">Return to Link</button>
                        </div>
                    </form>
                )}
                {info && (
                    <motion.p 
                        initial={{ opacity: 0 }} 
                        animate={{ opacity: 1 }} 
                        className={`text-xs text-center mt-6 font-bold uppercase tracking-widest ${info.type === 'error' ? 'text-rose-500' : 'text-emerald-400'}`}
                    >
                        {info.message}
                    </motion.p>
                )}
            </div>
        </div>
    );
};

export default LoginView;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GoogleGenAI, Chat } from '@google/genai';
import { AppFlow, View, UserProfile, Theme, THEMES, SIFRA_AVATARS, Message, Role, Mood, CalendarNote } from './types';
import { useLocalStorage } from './hooks/useLocalStorage';
import { AnimatePresence, motion } from 'framer-motion';

// Import Services & Utils
import { detectMood, generateSpeech } from './services/geminiService';
import { decode, decodeAudioData } from './utils/audioUtils';

// Import Views
import SplashView from './views/SplashView';
import LoginView from './views/LoginView';
import HomeView from './views/HomeView';
import ProfileView from './views/ProfileView';
import HistoryView from './views/HistoryView';
import MobileControlView from './views/MobileControlView';
import GalaxyVoiceView from './views/GalaxyVoiceView';
import YourCardView from './views/YourCardView';
import AccountDetailsView from './views/AccountDetailsView';
import MeetSifraView from './views/MeetSifraView';
import SifraToolsView from './views/SifraToolsView';
import PersonalCalendarView from './views/PersonalCalendarView';
import SifraClockView from './views/SifraClockView';
import SifraRecorderView from './views/SifraRecorderView';
import SifraCalculatorView from './views/SifraCalculatorView';
import SifraVaultView from './views/SifraVaultView';
import SifraMusicView from './views/SifraMusicView';
import SifraBrowserView from './views/SifraBrowserView';
import SifraFileView from './views/SifraFileView';
import SifraCameraView from './views/SifraCameraView';
import SifraWeatherView from './views/SifraWeatherView';
import DualModeView from './views/DualModeView';
import SifraProView from './views/SifraProView';
import SifraPremiumPlusView from './views/SifraPremiumPlusView';
import MonerDanaView from './views/MonerDanaView';
import SifraSaveView from './views/SifraSaveView';
import DiaryEditorView from './views/DiaryEditorView';
import TutorView from './views/TutorView';
import TravelGuideView from './views/TravelGuideView';
import CallsSifraView from './views/CallsSifraView';

// Import Components
import Header from './components/Header';
import Sidebar from './components/Sidebar';
import ChatMessage from './components/ChatMessage';
import ChatInput from './components/ChatInput';
import ArrowLeftIcon from '../components/icons/ArrowLeftIcon';
import Avatar from './components/Avatar';
import SifraQueenAnimation from './components/SifraQueenAnimation';

const App: React.FC = () => {
    const [allUsers, setAllUsers] = useLocalStorage<UserProfile[]>('sifra_all_users', []);
    const [currentUser, setCurrentUser] = useLocalStorage<UserProfile | null>('sifra_current_user', null);

    const [appFlow, setAppFlow] = useState<AppFlow>(AppFlow.SPLASH);
    const [currentView, setCurrentView] = useState<View>(View.HOME);
    const [activeDiaryEntryId, setActiveDiaryEntryId] = useState<string | null>(null);

    const [chatHistory, setChatHistory] = useLocalStorage<Message[]>(`sifra_chat_history_${currentUser?.userId || ''}`, []);
    const [sifraVoice, setSifraVoice] = useLocalStorage<string>(`sifra_voice_${currentUser?.userId || ''}`, 'Kore');

    const [isLoading, setIsLoading] = useState(false);
    const [isSidebarOpen, setIsSidebarOpen] = useState(false);
    const [isQueenLockdown, setIsQueenLockdown] = useState(false);
    const [theme, setTheme] = useState(THEMES[0]);
    const [currentMood, setCurrentMood] = useState<Mood>('neutral');
    const [currentlyPlayingAudioId, setCurrentlyPlayingAudioId] = useState<string | null>(null);

    const handleSplashComplete = useCallback(() => {
        if (currentUser) {
            setAppFlow(AppFlow.MAIN_APP);
            setCurrentView(View.HOME);
        } else {
            setAppFlow(AppFlow.LOGIN);
        }
    }, [currentUser]);

    const chatRef = useRef<Chat | null>(null);
    const audioContextRef = useRef<AudioContext | null>(null);
    const audioSourceRef = useRef<AudioBufferSourceNode | null>(null);

    useEffect(() => {
        const handlePopState = (event: PopStateEvent) => {
            if (event.state && typeof event.state.view === 'number') setCurrentView(event.state.view);
            else setCurrentView(View.HOME);
        };
        window.addEventListener('popstate', handlePopState);
        return () => window.history.back();
    }, []);

    // Instant Navigation Handler
    const handleNavigation = (view: View, params: any = null) => {
        if (view === View.DIARY_EDITOR) setActiveDiaryEntryId(params?.entryId || null);
        window.history.pushState({ view }, '', '');
        setCurrentView(view);
    };

    const handleBack = () => window.history.back();

    const handleLoginSuccess = (user: UserProfile) => {
        setCurrentUser(user);
        setAppFlow(AppFlow.MAIN_APP);
        setCurrentView(View.HOME);
        window.history.replaceState({ view: View.HOME }, '', '');
    };

    const handleLogout = () => {
        setCurrentUser(null);
        setChatHistory([]);
        setAppFlow(AppFlow.LOGIN);
        setCurrentView(View.HOME);
    };

    const handleUserProfileChange = (newProfile: UserProfile) => {
        setCurrentUser(newProfile);
        setAllUsers(users => users.map(u => u.userId === newProfile.userId ? newProfile : u));
    };

    useEffect(() => {
        if (currentUser) {
            const userTheme = THEMES.find(t => t.id === currentUser.themeId) || THEMES[0];
            setTheme(userTheme);
        }
    }, [currentUser]);

    const playAudio = useCallback(async (text: string, messageId: string) => {
        if (audioSourceRef.current) audioSourceRef.current.stop();
        setCurrentlyPlayingAudioId(messageId);
        try {
            if (!audioContextRef.current) {
                audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
            }
            const audioData = await generateSpeech(text, sifraVoice);
            if (audioData && audioContextRef.current) {
                const audioBuffer = await decodeAudioData(decode(audioData), audioContextRef.current, 24000, 1);
                const source = audioContextRef.current.createBufferSource();
                source.buffer = audioBuffer;
                source.connect(audioContextRef.current.destination);
                source.start();
                audioSourceRef.current = source;
                source.onended = () => { if (audioSourceRef.current === source) setCurrentlyPlayingAudioId(null); };
            }
        } catch (error) { setCurrentlyPlayingAudioId(null); }
    }, [sifraVoice]);

    const handleSendMessage = async (text: string, imageData?: { data: string, mimeType: string }) => {
        if ((!text.trim() && !imageData) || isLoading || !currentUser) return;
        const parts = [];
        if (text.trim()) parts.push({ text });
        if (imageData) parts.push({ inlineData: imageData });
        const userMessage: Message = { messageId: `msg-user-${Date.now()}`, role: Role.USER, parts };
        const currentChatHistory = [...chatHistory, userMessage];
        setChatHistory(currentChatHistory);
        setIsLoading(true);

        try {
            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
            if (!chatRef.current) {
                chatRef.current = ai.chats.create({ 
                    model: 'gemini-3-flash-preview', 
                    history: chatHistory.map(({role, parts}) => ({role, parts})),
                    config: { systemInstruction: "You are SIFRA AI. A professional assistant." } 
                });
            }
            const stream = await chatRef.current.sendMessageStream({ message: parts.length > 1 ? parts : (text.trim() || "Image") });
            let fullText = '';
            const modelMessageId = `msg-model-${Date.now()}`;
            setChatHistory([...currentChatHistory, { messageId: modelMessageId, role: Role.MODEL, parts: [{ text: '' }] }]);
            for await (const chunk of stream) {
                fullText += chunk.text || '';
                setChatHistory(prev => prev.map(msg => msg.messageId === modelMessageId ? { ...msg, parts: [{ text: fullText }] } : msg));
            }
        } catch (error) {
            setChatHistory([...chatHistory, { messageId: `err-${Date.now()}`, role: Role.MODEL, parts: [{ text: "Error." }] }]);
        } finally { setIsLoading(false); }
    };

    // Helper to determine if we should hide the main application header for a specific view
    const isFullScreenActive = [
        View.SIFRA_CALCULATOR,
        View.PERSONAL_CALENDAR,
        View.SIFRA_CLOCK,
        View.SIFRA_RECORDER,
        View.SIFRA_TOOLS,
        View.GALAXY_VOICE,
        View.DUAL_MODE,
        View.SIFRA_PRO,
        View.SIFRA_PREMIUM_PLUS,
        View.MONER_DANA,
        View.SIFRA_SAVE,
        View.DIARY_EDITOR,
        View.MEET_SIFRA,
        View.YOUR_CARD,
        View.ACCOUNT_DETAILS,
        View.TUTOR,
        View.TRAVEL_GUIDE,
        View.CALLS_SIFRA,
        View.SIFRA_VAULT,
        View.SIFRA_MUSIC,
        View.SIFRA_BROWSER,
        View.SIFRA_FILE,
        View.SIFRA_CAMERA,
        View.SIFRA_WEATHER
    ].includes(currentView);

    const renderMainView = () => {
        if (!currentUser) return null;
        const sifraAvatar = SIFRA_AVATARS.find(a => a.id === currentUser.sifraAvatarId) || SIFRA_AVATARS[0];

        return (
            <AnimatePresence mode="wait" initial={false}>
                <motion.div
                    key={currentView}
                    initial={{ opacity: 0, x: 5 }}
                    animate={{ opacity: 1, x: 0 }}
                    exit={{ opacity: 0, x: -5 }}
                    transition={{ duration: 0.15, ease: "easeOut" }}
                    className="h-full w-full overflow-hidden gpu-layer"
                >
                    {(() => {
                        switch (currentView) {
                            case View.HOME: return <HomeView userProfile={currentUser} onNavigate={handleNavigation} onUserProfileChange={handleUserProfileChange} />;
                            case View.PROFILE: return <ProfileView userProfile={currentUser} onUserProfileChange={handleUserProfileChange} sifraVoice={sifraVoice} onSifraVoiceChange={setSifraVoice} onClose={handleBack} onNavigate={handleNavigation} onLogout={handleLogout} onClearAllData={() => {}} />;
                            case View.HISTORY: return <HistoryView chatHistory={chatHistory} setChatHistory={setChatHistory} onClose={handleBack} />;
                            case View.GALAXY_VOICE: return <GalaxyVoiceView userProfile={currentUser} onClose={handleBack} />;
                            case View.SIFRA_TOOLS: return <SifraToolsView userProfile={currentUser} onNavigate={handleNavigation} onClose={handleBack} />;
                            case View.PERSONAL_CALENDAR: return <PersonalCalendarView userProfile={currentUser} onClose={handleBack} />;
                            case View.SIFRA_CLOCK: return <SifraClockView userProfile={currentUser} onClose={handleBack} />;
                            case View.SIFRA_RECORDER: return <SifraRecorderView userProfile={currentUser} onClose={handleBack} />;
                            case View.SIFRA_CALCULATOR: return <SifraCalculatorView userProfile={currentUser} onClose={handleBack} />;
                            case View.SIFRA_VAULT: return <SifraVaultView userProfile={currentUser} onClose={handleBack} />;
                            case View.SIFRA_MUSIC: return <SifraMusicView userProfile={currentUser} onClose={handleBack} />;
                            case View.SIFRA_BROWSER: return <SifraBrowserView userProfile={currentUser} onClose={handleBack} />;
                            case View.SIFRA_FILE: return <SifraFileView userProfile={currentUser} onClose={handleBack} />;
                            case View.SIFRA_CAMERA: return <SifraCameraView userProfile={currentUser} onClose={handleBack} />;
                            case View.SIFRA_WEATHER: return <SifraWeatherView userProfile={currentUser} onClose={handleBack} />;
                            case View.DUAL_MODE: return <DualModeView userProfile={currentUser} onUpdateProfile={handleUserProfileChange} onClose={handleBack} />;
                            case View.SIFRA_PRO: return <SifraProView userProfile={currentUser} onUpdateProfile={handleUserProfileChange} onClose={handleBack} />;
                            case View.SIFRA_PREMIUM_PLUS: return <SifraPremiumPlusView userProfile={currentUser} onClose={handleBack} />;
                            case View.MONER_DANA: return <MonerDanaView userProfile={currentUser} onClose={handleBack} onNavigate={handleNavigation} />;
                            case View.SIFRA_SAVE: return <SifraSaveView userProfile={currentUser} onClose={handleBack} />;
                            case View.DIARY_EDITOR: return <DiaryEditorView userProfile={currentUser} onClose={handleBack} entryId={activeDiaryEntryId} />;
                            case View.TUTOR: return <TutorView userProfile={currentUser} onClose={handleBack} />;
                            case View.TRAVEL_GUIDE: return <TravelGuideView userProfile={currentUser} onClose={handleBack} />;
                            case View.CALLS_SIFRA: return <CallsSifraView userProfile={currentUser} onClose={handleBack} />;
                            case View.ACCOUNT_DETAILS: return <AccountDetailsView userProfile={currentUser} onNavigate={handleNavigation} onClose={handleBack} />;
                            case View.YOUR_CARD: return <YourCardView userProfile={currentUser} onClose={handleBack} />;
                            case View.MEET_SIFRA: return <MeetSifraView onClose={handleBack} />;
                            case View.CHAT:
                            default:
                                return (
                                    <div className="h-full flex flex-col bg-white premium-scroll">
                                        <header className="p-4 flex items-center justify-between border-b border-gray-100 bg-white/80 backdrop-blur-md sticky top-0 z-10">
                                             <div className="flex items-center gap-4">
                                                <button onClick={handleBack} className="p-2 -ml-2 rounded-full active:bg-black/5"><ArrowLeftIcon /></button>
                                                <h1 className="text-lg font-bold">Chat</h1>
                                             </div>
                                             {sifraAvatar && <Avatar src={sifraAvatar.url} isSifra />}
                                        </header>
                                        <div className="flex-1 overflow-y-auto space-y-4 p-4 premium-scroll">
                                            {chatHistory.map((msg, idx) => (
                                                <ChatMessage key={msg.messageId || idx} message={msg} isPlayingAudio={currentlyPlayingAudioId === msg.messageId} onReplayAudio={playAudio} userAvatar={currentUser?.avatar || null} userName={currentUser?.name || null} sifraAvatarUrl={sifraAvatar.url} isLoading={isLoading} isLastMessage={idx === chatHistory.length - 1} />
                                            ))}
                                        </div>
                                        <div className="p-4 bg-white/80 backdrop-blur-md border-t border-gray-50"><ChatInput onSendMessage={handleSendMessage} isLoading={isLoading} onVoiceClick={() => handleNavigation(View.GALAXY_VOICE)} /></div>
                                    </div>
                                );
                        }
                    })()}
                </motion.div>
            </AnimatePresence>
        );
    };

    if (appFlow === AppFlow.SPLASH) return <SplashView onComplete={handleSplashComplete} />;

    if (appFlow === AppFlow.LOGIN) {
        return (
            <LoginView 
                onLoginSuccess={handleLoginSuccess} 
            />
        );
    }

    return (
        <main className={`w-screen h-screen font-sans bg-gradient-to-br ${theme.gradient} flex flex-col overflow-hidden relative selection:bg-pink-500/20`}>
             <AnimatePresence>
                {isQueenLockdown && <SifraQueenAnimation onComplete={() => setIsQueenLockdown(false)} />}
             </AnimatePresence>
             <motion.div animate={{ opacity: isQueenLockdown ? 0 : 1 }} className="flex-1 flex flex-col h-full overflow-hidden gpu-layer">
                {!isFullScreenActive && currentUser && (
                    <Header 
                        userName={currentUser.nickname || currentUser.name} 
                        onProfileClick={() => handleNavigation(View.PROFILE)} 
                        onMenuClick={() => setIsSidebarOpen(true)} 
                        onLogoClick={() => setIsQueenLockdown(true)} 
                        theme={theme} 
                        moodAmbienceEnabled={currentUser.moodAmbienceEnabled} 
                        currentMood={currentMood} 
                    />
                )}
                {!isFullScreenActive && currentUser && (
                    <Sidebar 
                        isOpen={isSidebarOpen} 
                        onClose={() => setIsSidebarOpen(false)} 
                        onNavigate={(v) => { handleNavigation(v); setIsSidebarOpen(false); }} 
                        onLogout={handleLogout} 
                        onNewChat={() => { setChatHistory([]); setIsSidebarOpen(false); }} 
                        userProfile={currentUser} 
                    />
                )}
                <div className="flex-1 overflow-hidden relative h-full">
                    {renderMainView()}
                </div>
             </motion.div>
        </main>
    );
};

export default App;

import React, { useState } from 'react';
// Fix: Added missing motion import from framer-motion
import { motion } from 'framer-motion';
import { useLocalStorage } from '../hooks/useLocalStorage';
import { UserProfile } from '../types';
import BoltIcon from '../components/icons/BoltIcon';
import UserIcon from '../components/icons/UserIcon';
import SparklesIcon from '../components/icons/SparklesIcon';

interface LoginViewProps {
    onLoginSuccess: (user: UserProfile) => void;
}

const LoginView: React.FC<LoginViewProps> = ({ onLoginSuccess }) => {
    const [view, setView] = useState<'login' | 'register'>('login');
    const [name, setName] = useState('');
    const [email, setEmail] = useState('');
    const [info, setInfo] = useState<{ type: 'success' | 'error' | 'info'; message: string } | null>(null);
    const [allUsers, setAllUsers] = useLocalStorage<UserProfile[]>('sifra_all_users', []);

    const generateSifraId = (prefix: string = ''): string => {
        const digits = '0123456789';
        const letters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
        const suffix = `${digits[Math.floor(Math.random() * 10)]}${digits[Math.floor(Math.random() * 10)]}${letters[Math.floor(Math.random() * 26)]}${digits[Math.floor(Math.random() * 10)]}${digits[Math.floor(Math.random() * 10)]}`;
        return prefix ? `${prefix}-${suffix}` : suffix;
    };

    const handleLogin = (e: React.FormEvent) => {
        e.preventDefault();
        const foundUser = allUsers.find(u => u.email?.toLowerCase() === email.toLowerCase() && u.name === name);
        if (foundUser) {
            onLoginSuccess(foundUser);
        } else {
            setInfo({ type: 'error', message: 'No account found. Check details or register.' });
        }
    };

    const handleGuestEntry = () => {
        const guestUser: UserProfile = {
            name: 'Guest User',
            nickname: 'Guest',
            email: 'guest@sifra.local',
            avatar: null,
            themeId: 'default',
            sifraAvatarId: 'cute',
            saveHistory: false,
            userId: generateSifraId('GUEST'),
            joinDate: new Date().toISOString(),
            status: 'active',
            lastLogin: new Date().toISOString(),
            moodAmbienceEnabled: false,
        };
        onLoginSuccess(guestUser);
    };

    const handleRegister = (e: React.FormEvent) => {
        e.preventDefault();
        if (allUsers.some(u => u.email?.toLowerCase() === email.toLowerCase())) {
            setInfo({ type: 'error', message: 'Email already registered.' });
            return;
        }
        const newUser: UserProfile = {
            name: name.trim(),
            nickname: null,
            email: email.trim().toLowerCase(),
            avatar: null,
            themeId: 'default',
            sifraAvatarId: 'cute',
            saveHistory: true,
            userId: generateSifraId(),
            joinDate: new Date().toISOString(),
            status: 'active',
            lastLogin: new Date().toISOString(),
            moodAmbienceEnabled: false,
        };
        setAllUsers([...allUsers, newUser]);
        onLoginSuccess(newUser);
    };

    return (
        <div className="w-screen h-screen bg-gradient-to-br from-indigo-900 via-slate-900 to-black flex items-center justify-center p-4 font-sans selection:bg-cyan-500/30">
            <div className="w-full max-w-md bg-white/5 backdrop-blur-3xl p-10 rounded-[3rem] border border-white/10 shadow-2xl transition-all duration-500 animate-fade-in-up relative overflow-hidden">
                <div className="absolute top-0 right-0 p-8 opacity-10">
                    <BoltIcon className="w-20 h-20 text-cyan-400" />
                </div>

                <div className="text-center mb-10 relative z-10">
                    <h1 className="text-5xl font-black text-white italic tracking-tighter mb-2">SIFRA</h1>
                    <p className="text-[10px] font-black text-cyan-500 uppercase tracking-[0.6em]">Neural Engine v3.0</p>
                </div>

                {view === 'login' ? (
                    <div className="space-y-4 relative z-10">
                        <form onSubmit={handleLogin} className="space-y-4">
                            <input type="text" value={name} onChange={e => setName(e.target.value)} placeholder="Neural Carrier Name" className="w-full p-4 bg-white/5 border border-white/10 rounded-2xl text-white outline-none focus:border-cyan-500 transition-all placeholder:text-white/20" required />
                            <input type="email" value={email} onChange={e => setEmail(e.target.value)} placeholder="Frequency Identifier (Email)" className="w-full p-4 bg-white/5 border border-white/10 rounded-2xl text-white outline-none focus:border-cyan-500 transition-all placeholder:text-white/20" required />
                            <button type="submit" className="w-full py-4 bg-white text-black font-black uppercase tracking-widest rounded-2xl shadow-xl hover:scale-105 active:scale-95 transition-all">Link Session</button>
                        </form>

                        <div className="pt-2 flex flex-col gap-3">
                            <button 
                                onClick={handleGuestEntry}
                                className="group w-full py-4 bg-cyan-500/10 border border-cyan-500/20 rounded-2xl flex items-center justify-center gap-3 hover:bg-cyan-500/20 transition-all active:scale-95 shadow-lg"
                            >
                                <SparklesIcon className="w-4 h-4 text-cyan-400 group-hover:animate-spin" />
                                <span className="text-xs font-black text-cyan-400 uppercase tracking-widest">Enter Guest Mode</span>
                            </button>
                            <button 
                                type="button" 
                                onClick={() => setView('register')} 
                                className="text-[10px] text-white/40 font-bold uppercase tracking-widest hover:text-cyan-400 text-center transition-colors"
                            >
                                Initialize New Link
                            </button>
                        </div>
                    </div>
                ) : (
                     <form onSubmit={handleRegister} className="space-y-4 relative z-10">
                        <input type="text" value={name} onChange={e => setName(e.target.value)} placeholder="Choose Identity" className="w-full p-4 bg-white/5 border border-white/10 rounded-2xl text-white outline-none focus:border-cyan-500 transition-all placeholder:text-white/20" required />
                        <input type="email" value={email} onChange={e => setEmail(e.target.value)} placeholder="Email Vector" className="w-full p-4 bg-white/5 border border-white/10 rounded-2xl text-white outline-none focus:border-cyan-500 transition-all placeholder:text-white/20" required />
                        <button type="submit" className="w-full py-4 bg-cyan-500 text-black font-black uppercase tracking-widest rounded-2xl shadow-xl hover:scale-105 transition-all">Deploy Account</button>
                        <div className="text-center text-[10px] text-white/40 font-bold uppercase tracking-widest pt-4">
                             <button type="button" onClick={() => setView('login')} className="hover:text-cyan-400 transition-colors">Return to Link</button>
                        </div>
                    </form>
                )}
                {info && (
                    <motion.p 
                        initial={{ opacity: 0 }} 
                        animate={{ opacity: 1 }} 
                        className={`text-xs text-center mt-6 font-bold uppercase tracking-widest ${info.type === 'error' ? 'text-rose-500' : 'text-emerald-400'}`}
                    >
                        {info.message}
                    </motion.p>
                )}
            </div>
        </div>
    );
};

export default LoginView;

import React, { memo } from 'react';
import { UserProfile, View } from '../types';
import { motion } from 'framer-motion';
import SparklesIcon from '../components/icons/SparklesIcon';
import MicrophoneIcon from '../components/icons/MicrophoneIcon';
import ChatBubbleLeftRightIcon from '../components/icons/ChatBubbleLeftRightIcon';
import CubeTransparentIcon from '../components/icons/CubeTransparentIcon';
import GlobeAltIcon from '../components/icons/GlobeAltIcon';
import BookOpenIcon from '../components/icons/BookOpenIcon';
import ArrowRightIcon from '../components/icons/ArrowRightIcon';
import CalendarIcon from '../components/icons/CalendarIcon';
import ClockIcon from '../components/icons/ClockIcon';
import UserIcon from '../components/icons/UserIcon';
import CalculatorIcon from '../components/icons/CalculatorIcon';
import CameraIcon from '../components/icons/CameraIcon';
import FolderIcon from '../components/icons/FolderIcon';
import CloudIcon from '../components/icons/CloudIcon';
import SifraLiveLogo from '../components/SifraLiveLogo';

interface HomeViewProps {
    userProfile: UserProfile;
    onNavigate: (view: View) => void;
    onUserProfileChange: (profile: UserProfile) => void;
}

const SMOOTH_SPRING = { type: "spring", stiffness: 450, damping: 40, mass: 1 };
const STAGGER_DELAY = 0.03;

const containerVariants = {
    hidden: { opacity: 0 },
    show: { opacity: 1, transition: { staggerChildren: STAGGER_DELAY } }
};

const itemVariants = {
    hidden: { opacity: 0, y: 10 },
    show: { opacity: 1, y: 0, transition: SMOOTH_SPRING }
};

const ActionBox = memo(({ icon, title, subtitle, color, onClick }: { icon: React.ReactNode, title: string, subtitle: string, color: string, onClick: () => void }) => (
    <motion.button 
        variants={itemVariants}
        whileTap={{ scale: 0.96 }}
        onClick={onClick}
        className="relative group w-full h-28 rounded-[2.2rem] p-5 flex flex-col justify-between text-left shadow-lg backdrop-blur-3xl border border-white/20 bg-white/10 overflow-hidden gpu-layer"
    >
        <div className={`absolute -right-4 -bottom-4 w-20 h-20 rounded-full blur-[30px] opacity-20 ${color} pointer-events-none`} />
        <div className={`w-10 h-10 rounded-2xl flex items-center justify-center text-white shadow-lg ${color}`}>
            {React.cloneElement(icon as React.ReactElement, { className: "w-6 h-6" })}
        </div>
        <div>
            <h3 className="font-black text-gray-900 text-[13px] tracking-tight">{title}</h3>
            <p className="text-[8px] font-black text-gray-500 uppercase tracking-[0.2em]">{subtitle}</p>
        </div>
    </motion.button>
));

const PremiumModule = memo(({ icon, label, onClick, color, comingSoon }: { icon: React.ReactNode, label: string, onClick: () => void, color: string, comingSoon?: boolean }) => (
    <motion.button 
        variants={itemVariants}
        whileTap={{ scale: 0.95 }}
        onClick={onClick}
        className="flex-1 min-w-[100px] h-24 rounded-[2rem] bg-white/40 backdrop-blur-md border border-white/40 flex flex-col items-center justify-center gap-2 shadow-sm relative overflow-hidden group"
    >
        {comingSoon && <div className="absolute top-1 right-1 px-1.5 py-0.5 rounded-full bg-amber-500 text-[6px] font-black text-white uppercase tracking-tighter">SOON</div>}
        <div className={`transition-transform duration-300 group-hover:scale-110 ${color}`}>
