        </div>
        <span className="text-[10px] font-black text-gray-800 uppercase tracking-widest">{label}</span>
    </motion.button>
));

const UtilityMiniIcon = memo(({ icon, label, onClick, color }: { icon: React.ReactNode, label: string, onClick: () => void, color: string }) => (
    <motion.button 
        variants={itemVariants}
        whileTap={{ scale: 0.92 }}
        onClick={onClick}
        className="flex flex-col items-center justify-center gap-1.5 p-2 transition-all group"
    >
        <div className={`w-12 h-12 rounded-2xl bg-white/5 border border-white/10 backdrop-blur-sm flex items-center justify-center transition-all group-hover:bg-white/20 group-hover:border-white/30 ${color}`}>
            {React.cloneElement(icon as React.ReactElement, { className: "w-5 h-5" })}
        </div>
        <span className="text-[8px] font-bold text-gray-600 uppercase tracking-tighter text-center">{label}</span>
    </motion.button>
));

