                >
                    <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,_rgba(255,95,175,0.1)_0%,_transparent_70%)]" />
                    <div className="relative z-10">
                        <span className="px-2 py-0.5 rounded-full bg-pink-500 text-white text-[7px] font-black uppercase tracking-widest">Global Assist</span>
                        <h2 className="text-2xl font-black text-white tracking-tighter italic leading-tight mt-1">Discover Sifra</h2>
                        <button className="text-[8px] font-black text-pink-400 uppercase tracking-widest flex items-center gap-2 mt-3 group-hover:translate-x-1 transition-all">Documentation <ArrowRightIcon className="w-3 h-3" /></button>
