            </div>

            <div className="h-40 shrink-0" />
        </motion.div>
    );

    const renderCategoryView = () => (
        <motion.div 
            initial={{ opacity: 0, x: 20 }} animate={{ opacity: 1, x: 0 }}
            className="flex-1 flex flex-col bg-[#05070A] h-full"
        >
