            </header>

            <div className="flex-1 p-8 overflow-y-auto premium-scroll">
                <div className="grid grid-cols-2 sm:grid-cols-3 gap-6">
                    {!isFakeVault && [...Array(CATEGORIES.find(c => c.name === selectedCat)?.count || 0)].map((_, i) => (
