                 <button className="w-full p-8 rounded-[2.5rem] bg-white/5 border border-white/10 flex items-center justify-between group active:scale-95 transition-all">
                    <div className="flex items-center gap-6">
                        <div className="w-12 h-12 rounded-2xl bg-indigo-500/10 flex items-center justify-center text-indigo-400 border border-indigo-500/20"><GlobeAltIcon className="w-6 h-6" /></div>
                        <div className="text-left">
                            <h4 className="text-lg font-black text-white">System Backup</h4>
                            <p className="text-[10px] font-black text-white/20 uppercase">Export carrier matrix</p>
                        </div>
                    </div>
                    <ChevronRightIcon />
                </button>

                <button 
                    onClick={wipeMatrix}
                    className="w-full p-8 rounded-[2.5rem] bg-rose-500/10 border border-rose-500/20 flex items-center justify-between group hover:bg-rose-500/20 active:scale-95 transition-all"
                >
                    <div className="flex items-center gap-6">
                        <div className="w-12 h-12 rounded-2xl bg-rose-500/20 flex items-center justify-center text-rose-500 border border-rose-500/30"><TrashIcon className="w-6 h-6" /></div>
                        <div className="text-left">
                            <h4 className="text-lg font-black text-rose-500">Neural Wipe</h4>
                            <p className="text-[10px] font-black text-rose-500/40 uppercase">Factory matrix reset</p>
                        </div>
                    </div>
                    <XMarkIcon className="text-rose-500/40" />
                </button>
            </div>
        </div>
    );

    return (
        <div className="fixed inset-0 z-[2000] bg-[#050505] text-white flex font-sans selection:bg-cyan-500/30 overflow-hidden">

            {/* AMBIENT OVERLAY */}
            <div className="absolute inset-0 pointer-events-none">
                <div className="absolute top-[-10%] right-[-10%] w-[50%] h-[50%] bg-cyan-600/10 blur-[120px] rounded-full" />
                <div className="absolute bottom-[-10%] left-[-10%] w-[50%] h-[50%] bg-indigo-600/10 blur-[120px] rounded-full" />
                <div className="absolute inset-0 bg-[url('https://grainy-gradients.vercel.app/noise.svg')] opacity-[0.03] mix-blend-screen" />
            </div>

            {/* Sidebar */}
            <aside className="w-80 border-r border-white/5 flex flex-col p-10 bg-[#080808]/80 backdrop-blur-3xl relative z-20">
                <div className="flex items-center gap-4 mb-20 group">
                    <div className="w-12 h-12 rounded-2xl bg-gradient-to-tr from-cyan-500 to-indigo-600 flex items-center justify-center shadow-xl shadow-cyan-500/20 group-hover:rotate-12 transition-transform">
                        <ShieldCheckIcon className="w-6 h-6 text-white" />
                    </div>
                    <div className="flex flex-col">
                        <h2 className="text-2xl font-black italic tracking-tighter leading-none">OVERSEER</h2>
                        <span className="text-[9px] font-black text-cyan-400 uppercase tracking-[0.4em] mt-1.5">Node Center</span>
                    </div>
                </div>

                <nav className="flex-1 space-y-3">
                    {[
                        { id: 'overview', label: 'Dashboard', icon: <GlobeAltIcon /> },
                        { id: 'carriers', label: 'Neural Matrix', icon: <UsersIcon /> },
                        { id: 'broadcast', label: 'Broadcaster', icon: <BellIcon /> },
                        { id: 'security', label: 'Security Protocols', icon: <ShieldCheckIcon /> },
                    ].map(item => (
                        <button 
                            key={item.id}
                            onClick={() => setActiveTab(item.id as AdminTab)}
                            className={`w-full flex items-center gap-5 px-8 py-5 rounded-[1.8rem] transition-all duration-300 group ${activeTab === item.id ? 'bg-white/10 text-cyan-400 shadow-2xl border border-white/10' : 'text-white/40 hover:text-white hover:bg-white/5'}`}
                        >
                            {React.cloneElement(item.icon as React.ReactElement, { className: "w-5 h-5" })}
                            <span className="text-xs font-black uppercase tracking-[0.2em]">{item.label}</span>
                            {activeTab === item.id && <motion.div layoutId="activeInd" className="w-1.5 h-1.5 rounded-full bg-cyan-400 ml-auto shadow-[0_0_8px_#22d3ee]" />}
                        </button>
                    ))}
                </nav>

                <div className="mt-auto space-y-4">
                    <div className="p-6 rounded-3xl bg-white/5 border border-white/5 text-center">
                        <p className="text-[10px] font-black text-white/20 uppercase tracking-widest mb-1">Matrix Core</p>
                        <p className="text-sm font-bold text-white/60">{APP_VERSION}</p>
                    </div>
                    <button onClick={onClose} className="w-full flex items-center justify-center gap-4 py-6 text-rose-500/60 hover:text-rose-500 transition-all font-black uppercase tracking-widest text-[10px]">
                        <LogoutIcon className="w-4 h-4" />
                        Disconnect Matrix
                    </button>
                </div>
            </aside>

            {/* Main Content Area */}
            <main className="flex-1 flex flex-col overflow-hidden relative z-10">
                <header className="p-12 pb-6 flex justify-between items-end">
                    <div className="space-y-1">
                        <h2 className="text-5xl font-black tracking-tighter uppercase italic leading-none">{activeTab}</h2>
                        <div className="flex items-center gap-3">
                             <div className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse" />
                             <p className="text-[10px] font-bold text-white/30 uppercase tracking-[0.4em]">Overseer Terminal Active</p>
                        </div>
                    </div>
                    <div className="flex items-center gap-4">
                        <div className="px-8 py-4 bg-white/5 border border-white/10 rounded-2xl flex items-center gap-4 shadow-inner">
                            <SparklesIcon className="w-5 h-5 text-cyan-400" />
                            <span className="text-[10px] font-black uppercase tracking-[0.2em] text-cyan-500">Live Sync Engaged</span>
                        </div>
                    </div>
                </header>

                <div className="flex-1 overflow-y-auto premium-scroll p-12 pt-6">
                    <AnimatePresence mode="wait">
                        <motion.div
                            key={activeTab}
                            initial={{ opacity: 0, x: 20 }}
                            animate={{ opacity: 1, x: 0 }}
                            exit={{ opacity: 0, x: -20 }}
                            transition={{ duration: 0.3 }}
                        >
                            {activeTab === 'overview' && renderOverview()}
                            {activeTab === 'carriers' && renderCarriers()}
                            {activeTab === 'broadcast' && renderBroadcast()}
                            {activeTab === 'security' && renderSecurity()}
                        </motion.div>
                    </AnimatePresence>
                </div>
            </main>

            <style>{`
                .premium-scroll::-webkit-scrollbar { display: none; }
                .premium-scroll { -ms-overflow-style: none; scrollbar-width: none; }
            `}</style>
        </div>
    );
};

export default AdminDashboardView;

